export const OUR_TAKES: OurTake[] = [{"id": 2841, "title": "1-Minute Gratitude Journal", "url": "https://store.ignatiusbookfairs.com/1-minute-gratitude-journal-ibc-1612/", "take": "One minute a day of prompted thankfulness, built for actual kids. A simple habit with outsized effects on attitude — great family devotional supplement or lunchbox surprise."}, {"id": 1360, "title": "100 Activities Based on the Catechism of the Catholic Church", "url": "https://store.ignatiusbookfairs.com/100-activities-based-on-the-catechism-of-the-catholic-church/", "take": "A teacher's and catechist's workhorse: worksheets, puzzles, Bible studies, and games organized around the Catechism's four pillars, updated in this second edition with new lessons on the Mass, adoration, and Divine Mercy. Endlessly practical."}, {"id": 2169, "title": "1000 Bilingual Words Nature/English-Spanish", "url": "https://store.ignatiusbookfairs.com/1000-bilingual-words-nature-english-spanish/", "take": "A picture-packed vocabulary builder: 1000 nature words in English and Spanish, from the parts of a plant to animal habitats. Clear labels encourage picture-and-word association in both languages. Genuinely useful for bilingual classrooms and curious kids alike."}, {"id": 1131, "title": "24 Christmas Stories for Little Ones", "url": "https://store.ignatiusbookfairs.com/24-christmas-stories-for-little-ones/", "take": "Twenty-four read-aloud stories that walk little ones through Advent - the wreath, the tree, traditions from around the world, and the Bible's own account of Christ's birth. Gentle, colorful, and built for one-a-night December reading."}, {"id": 1130, "title": "24 Christmas Stories to Welcome Jesus", "url": "https://store.ignatiusbookfairs.com/24-christmas-stories-to-welcome-jesus/", "take": "An Advent calendar in book form: one story per day from December 1 through Christmas, mixing Gospel accounts, Advent customs, and original tales. A lovely way to pace the whole family toward the manger."}, {"id": 2128, "title": "26 Fairmont Avenue: The 26 Fairmont Avenue Series #1", "url": "https://store.ignatiusbookfairs.com/26-fairmont-avenue-the-26-fairmont-avenue-series-1/", "take": "Tomie dePaola's autobiographical series opens in 1938 with a hurricane, a new house, and the infamous chocolate-laxative incident with Nana Upstairs. Short, funny, true-life chapters that make wonderful early independent reading."}, {"id": 1787, "title": "3 Adventures from Deckawoo Drive", "url": "https://store.ignatiusbookfairs.com/3-adventures-from-deckawoo-drive/", "take": "Three Kate DiCamillo tales in one affordable bind-up — Leroy Ninker's first horse, Francine Poulet's raccoon wrangling, Baby Lincoln striking out on her own. A Mercy Watson spin-off that early chapter-book readers slide into happily."}, {"id": 1895, "title": "A Bloody Habit", "url": "https://store.ignatiusbookfairs.com/a-bloody-habit/", "take": "London, 1900: a sensible lawyer reads the new novel Dracula, meets an eccentric Dominican friar, and finds his predictable life catapulted into the bizarre and violent. A clever, atmospheric vampire tale with a Catholic spine. Great fun for adults."}, {"id": 1340, "title": "A Catholic Child's Baptismal Bible", "url": "https://store.ignatiusbookfairs.com/a-catholic-childs-baptismal-bible/", "take": "A gift-boxed baptismal Bible that pairs the major Old and New Testament stories with colorful illustrations and scripture references, plus presentation, sacrament, and family record pages. Made to be kept, not just read."}, {"id": 2194, "title": "A Child's Garden of Verses", "url": "https://store.ignatiusbookfairs.com/a-childs-garden-of-verses/", "take": "Stevenson's 1885 verses about swings, shadows, and small joys, paired with Robinson's illustrations from the first illustrated edition. Still the poetry collection that best remembers what being little actually feels like. An essential home-library staple."}, {"id": 1341, "title": "A Continual Feast: A Cookbook to Celebrate the Joys of Family and Faith throughout the Christian Year", "url": "https://store.ignatiusbookfairs.com/a-continual-feast-a-cookbook-to-celebrate-the-joys-of-family-and-faith-throughout-the-christian-year/", "take": "More than 275 recipes tied to the feasts and seasons of the Christian year, with the when and why behind each dish. A cookbook that turns the liturgical calendar into family memory - a wonderful gift."}, {"id": 2762, "title": "A Dark and Desperate Race", "url": "https://store.ignatiusbookfairs.com/a-dark-and-desperate-race-ibc-1570/", "take": "Will Pennington runs from a hard home straight into an enemy kingdom's plot, a would-be assassin, and a race to save the people he loves. Adventure with animals, loyalty, and real stakes at its heart."}, {"id": 2221, "title": "A Foal Called Storm (Jasmine Green Rescue series)", "url": "https://store.ignatiusbookfairs.com/a-foal-called-storm-jasmine-green-rescue-series/", "take": "Jasmine finds a tiny injured foal alone in a field and takes on nursing him back to health, fluffy rabbits and animal-hating great-aunt notwithstanding. Sweet animal-rescue chapter fiction made for horse-loving kids."}, {"id": 1095, "title": "A Hiker's Guide to Purgatory", "url": "https://store.ignatiusbookfairs.com/a-hikers-guide-to-purgatory/", "take": "Seventy-seven-year-old attorney Dan Geary wakes in the afterlife — and finds a trailhead, not a cloud. A hiking pack, a vivid rolling landscape, and purgatory reimagined as a journey. An inventive premise for Catholic fiction readers."}, {"id": 1931, "title": "A Landscape with Dragons", "url": "https://store.ignatiusbookfairs.com/a-landscape-with-dragons/", "take": "Michael O'Brien's provocative examination of modern children's literature, asking which stories feed the soul and which quietly starve it. Written before the Harry Potter debates yet anticipating them — useful for parents who want to choose books with discernment."}, {"id": 926, "title": "A Lion for the Emperor", "url": "https://store.ignatiusbookfairs.com/a-lion-for-the-emperor/", "take": "Volume 2 of In the Shadows of Rome: a lion hunt in North Africa, a perilous voyage home, and the constant danger of being Christian in ancient Rome. Historical adventure with real stakes for readers 10 and up."}, {"id": 1343, "title": "A Little Book about Confession for Children", "url": "https://store.ignatiusbookfairs.com/a-little-book-about-confession-for-children/", "take": "A patient, step-by-step explanation of Confession - the hows and the whys - for children preparing for their first time, and honestly for the parents beside them. Takes the overwhelm out of a beautiful sacrament."}, {"id": 1345, "title": "A Little Prairie House", "url": "https://store.ignatiusbookfairs.com/a-little-prairie-house/", "take": "An illustrated My First Little House adaptation that brings Laura Ingalls Wilder's prairie to the youngest readers: the covered wagon, the tall grass, and Pa building a snug little house with a neighbor's help."}, {"id": 1347, "title": "A Missal for Children", "url": "https://store.ignatiusbookfairs.com/a-missal-for-children/", "take": "A numbered missal that puts the prayers of the Mass on one page and their explanations on the facing page, so children can follow along and understand at the same time. Practical, lovely, and genuinely useful at Mass."}, {"id": 1348, "title": "A Missal for Little Ones", "url": "https://store.ignatiusbookfairs.com/a-missal-for-little-ones/", "take": "A boy and a girl walk through the Mass step by step - what they say, what they do, what the priest does - so young children can enter the mystery little by little. Simple and charming."}, {"id": 1349, "title": "A Missal for Toddlers", "url": "https://store.ignatiusbookfairs.com/a-missal-for-toddlers/", "take": "A durable, sweetly illustrated missal that lets the youngest children follow the Mass alongside a boy and girl and their parents. Sturdy enough for the pew, gentle enough to open the mystery bit by bit."}, {"id": 1099, "title": "A Most Dangerous Innocence", "url": "https://store.ignatiusbookfairs.com/a-most-dangerous-innocence/", "take": "1940, the Phoney War, an isolated English girls' boarding school — and Judy Randall: Catholic, of Jewish heritage, autistic, and a misfit where conformity is prized. A wartime novel with an unusually compelling heroine."}, {"id": 2472, "title": "A Place to Hang the Moon", "url": "https://store.ignatiusbookfairs.com/a-place-to-hang-the-moon/", "take": "Three London siblings, evacuated during World War II, search the countryside for something rarer than safety: a real family. A New York Public Library Best Book of the Year, warm and quietly moving — lovely for middle-grade readers."}, {"id": 2876, "title": "A Pocket Guide to Sacramental Reconciliation", "url": "https://store.ignatiusbookfairs.com/a-pocket-guide-to-sacramental-reconciliation/", "take": "Lego-style Catholic friends Fulton and Cynthia walk kids through the Sacrament of Reconciliation - mortal versus venial sin, preparing for a good Confession, and the mercy waiting on the other side. Catechesis kids will pick up on their own."}, {"id": 1410, "title": "A Raisin in the Sun", "url": "https://store.ignatiusbookfairs.com/a-raisin-in-the-sun/", "take": "Hansberry's landmark 1959 drama of a Black working-class family's hopes on Chicago's South Side, here in the fully restored, uncut text. Essential American theater for high school classrooms and book lists."}, {"id": 1942, "title": "A Song for Nagasaki", "url": "https://store.ignatiusbookfairs.com/a-song-for-nagasaki/", "take": "The true story of Takashi Nagai, radiologist and Catholic convert who survived the Nagasaki bomb and, dying of leukemia in the rubble, spent his remaining years bringing healing to others. Sobering, luminous reading for teens and adults."}, {"id": 2195, "title": "A Symphony of Whales", "url": "https://store.ignatiusbookfairs.com/a-symphony-of-whales/", "take": "Glashka discovers thousands of whales trapped in a rapidly freezing inlet and must rally her whole town to save them. Based on an actual event, this is an inspiring story about responsibility and the importance of all life."}, {"id": 1879, "title": "A Tale of Two Cities", "url": "https://store.ignatiusbookfairs.com/a-tale-of-two-cities/", "take": "Dickens on the French Revolution, sympathetic to the downtrodden poor but no friend of the vengeful mob and its guillotine. Madame Defarge alone is worth the price of admission. One of the most gripping classics you can hand a teenager."}, {"id": 2770, "title": "A to Z Mysteries: The Absent Author", "url": "https://store.ignatiusbookfairs.com/a-to-z-mysteries-the-absent-author-ibc-1571/", "take": "The series that has hooked chapter book readers on mysteries for years, with over 8 million copies in print. Dink, Josh, and Ruth Rose investigate a famous author who never shows up. An easy yes for emerging readers."}, {"id": 1108, "title": "A Treasury of Curious George", "url": "https://store.ignatiusbookfairs.com/a-treasury-of-curious-george/", "take": "Eight Curious George stories in one hefty 192-page hardcover, all in Rey's original watercolor-and-charcoal style. Trains, toy stores, dump trucks — a generous treasury for households where demand for the good little monkey runs high."}, {"id": 2482, "title": "A Very Happy Easter", "url": "https://store.ignatiusbookfairs.com/a-very-happy-easter/", "take": "An Easter retelling with a clever twist: children copy the facial expressions of Jesus's friends as the story unfolds, from sorrow to joy. A genuinely engaging way to help little ones feel the weight and wonder of the Resurrection."}, {"id": 2497, "title": "A Very Noisy Christmas", "url": "https://store.ignatiusbookfairs.com/a-very-noisy-christmas/", "take": "Was it really a silent night? This playful retelling argues the first Christmas was gloriously noisy — and invites kids to shout and sing along. A fresh, joyful read-aloud that still lands the heart of the story."}, {"id": 2804, "title": "A Visitor for Bear", "url": "https://store.ignatiusbookfairs.com/a-visitor-for-bear-ibc-1545/", "take": "Bear does not like visitors - he has a sign. The mouse disagrees, repeatedly and adorably. A wry comedy of manners the New York Times called cozy enough to read aloud every night, and they're right."}, {"id": 2495, "title": "A Wolf Called Wander", "url": "https://store.ignatiusbookfairs.com/a-wolf-called-wander/", "take": "A New York Times bestselling survival novel based on the real journey of a wolf searching for home, illustrated throughout. Hand this to fans of Pax or The One and Only Ivan — it grips from the first page."}, {"id": 1112, "title": "A World Full of Dickens Stories", "url": "https://store.ignatiusbookfairs.com/a-world-full-of-dickens-stories/", "take": "Eight of Dickens's greatest works — Oliver Twist, A Christmas Carol, David Copperfield, Great Expectations — retold accessibly for children with colorful illustrations and a timeline. A friendly first handshake with a great novelist."}, {"id": 2243, "title": "A Wrinkle in Time", "url": "https://store.ignatiusbookfairs.com/a-wrinkle-in-time/", "take": "It was a dark and stormy night, a strange visitor mentioned a tesseract, and children's fantasy was never the same. Meg Murry's journey opens the Time Quintet — a classic worth handing to every curious young reader."}, {"id": 1957, "title": "A Year of Daily Offerings", "url": "https://store.ignatiusbookfairs.com/a-year-of-daily-offerings/", "take": "Fr. James Kubicki of Relevant Radio offers a full 366 days of brief morning offerings, tied to the liturgical calendar and Ignatian spirituality. Built for busy laypeople — a realistic way to start each day by handing it to God."}, {"id": 2210, "title": "Abandon Ship! The True WWII Story about the Sinking of the Laconia", "url": "https://store.ignatiusbookfairs.com/abandon-ship-the-true-wwii-story-about-the-sinking-of-the-laconia/", "take": "The RMS Laconia, torpedoed off West Africa at the height of WWII, and the unprecedented events that followed involving allies and enemies alike. Suspenseful narrative nonfiction for Steve Sheinkin fans; the survival-at-sea stakes hook middle schoolers fast."}, {"id": 2092, "title": "Abigail and Big Start Over", "url": "https://store.ignatiusbookfairs.com/abigail-and-big-start-over/", "take": "Nine-year-old Abigail lands in a new house, new school, and a string of new messes. A wholesome, funny story that shows kids what faith looks like in everyday situations — including learning how Jesus forgives."}, {"id": 2096, "title": "Abigail and the Career Day Catastrophe", "url": "https://store.ignatiusbookfairs.com/abigail-and-the-career-day-catastrophe/", "take": "A funny, warm chapter book that gently untangles works-versus-grace for the 7+ crowd. Abigail's Career Day scheming goes delightfully wrong, and the Bible teaching that follows is genuinely kid-clear."}, {"id": 2100, "title": "Abigail Gets Left Out", "url": "https://store.ignatiusbookfairs.com/abigail-gets-left-out/", "take": "Abigail can't sing or dance, so the class musical leaves her painfully on the outside — until Psalm 139 reframes everything. An honest, absorbing story for ages 7 and up about being wonderfully made just as you are."}, {"id": 1880, "title": "Adventures of Huckleberry Finn", "url": "https://store.ignatiusbookfairs.com/adventures-of-huckleberry-finn/", "take": "Twain's novel is, by many accounts, the great American novel, full of vibrant characters, regional dialects, and down-home humor, while pressing hard on America's ongoing sore spot of race. This critical edition helps students engage it honestly."}, {"id": 2281, "title": "Aesop's Fables: A Little Apple Classic", "url": "https://store.ignatiusbookfairs.com/aesops-fables-a-little-apple-classic/", "take": "Aesop's trickster deeds and age-old morals, dressed in Charles Santore's breathtaking original artwork. An exquisite edition of the fables for cuddled-up read-alouds — the kind of book that gets kept and handed down."}, {"id": 2794, "title": "Airborn", "url": "https://store.ignatiusbookfairs.com/airborn-reprints-done-in-4-6-weeks-ibc-1560/", "take": "Airships, sky pirates, and a cabin boy who believes he's lighter than air. Oppel's adventure classic is pure wind-in-your-hair storytelling for 10-14s — the kind of book that creates readers."}, {"id": 2769, "title": "Alcatraz vs. the Evil Librarians", "url": "https://store.ignatiusbookfairs.com/alcatraz-vs-the-evil-librarians-ibc-1619/", "take": "A boy whose talent is breaking things versus a cult of evil librarians suppressing the truth. Sanderson's middle-grade series is clever, fast, and very funny — hand it to 9-13s who like their fantasy with a wink."}, {"id": 2849, "title": "All Aboard the London Bus", "url": "https://store.ignatiusbookfairs.com/all-aboard-the-london-bus-ibc-1597/", "take": "A family of four rides the London bus past Buckingham Palace, Big Ben, and the London Eye in bouncy, child-friendly rhyme. A delightful armchair tour of the capital - and a fine primer before any real trip."}, {"id": 1837, "title": "All About Advent & Christmas", "url": "https://store.ignatiusbookfairs.com/all-about-advent-christmas/", "take": "A family resource for the whole season — Scripture and salvation history, December saints, and the stories behind treasured Advent and Christmas customs. Substantial enough for classroom use, warm enough for the living room."}, {"id": 2488, "title": "All About Lent & Holy Week", "url": "https://store.ignatiusbookfairs.com/all-about-lent-holy-week/", "take": "Katherine Bogner and Shari Van Vranken walk Catholic families through Lent and Holy Week — biblical roots, liturgical rites, prayers, and traditions. A genuinely useful guide for making the holiest weeks of the year rich at home."}, {"id": 2802, "title": "All Hallows Eve", "url": "https://store.ignatiusbookfairs.com/all-hallows-eve-ibc-1608/", "take": "DeStefano takes children into Halloween's true spiritual roots through a spooky-but-lighthearted tale of a mysterious woman praying in a cemetery. Suspense, Catholic teaching on prayer and penance, and a satisfying shiver."}, {"id": 1405, "title": "All the Light We Cannot See", "url": "https://store.ignatiusbookfairs.com/all-the-light-we-cannot-see/", "take": "Doerr's Pulitzer winner interweaves a blind French girl and a German boy in occupied France, both trying to survive the war. Gorgeous, humane, and widely beloved - best for mature teens and adults."}, {"id": 1045, "title": "All-of-a-Kind Family", "url": "https://store.ignatiusbookfairs.com/all-of-a-kind-family/", "take": "Ella, Henny, Sarah, Charlotte, and Gertie share small adventures — hunting hidden buttons while dusting, rainy days among the peddlers in Papa's shop — in turn-of-the-century New York. Cozy, episodic family storytelling with a big surprise at the end."}, {"id": 2012, "title": "Alphabet Saints Poster/Boys", "url": "https://store.ignatiusbookfairs.com/alphabet-saints-poster-boys/", "take": "Twenty-six saintly men from A to Z in charming peg-doll style. This boys' edition puts real heroes on the bedroom wall — a 16x20 matte print with a featured-saints card to help kids learn each one."}, {"id": 2010, "title": "Alphabet Saints Poster/Gender Neutral", "url": "https://store.ignatiusbookfairs.com/alphabet-saints-poster-gender-neutral/", "take": "Twenty-six of the most popular saints, A to Z, in Kortnee Senn's cheerful peg-doll style. A 16x20 matte print that makes the communion of saints feel friendly and familiar, with a featured-saints card included."}, {"id": 2011, "title": "Alphabet Saints Poster/Girls", "url": "https://store.ignatiusbookfairs.com/alphabet-saints-poster-girls/", "take": "The alphabet, taught by twenty-six holy women. This girls' edition of the peg-doll saints poster gives daughters a wall full of heroines of faith, hope, and love — 16x20 on matte paper, featured-saints card included."}, {"id": 984, "title": "Amelia Bedelia I Can Read Box Set #1: Amelia Bedelia Hit the Books Collection (5 books)", "url": "https://store.ignatiusbookfairs.com/amelia-bedelia-i-can-read-box-set-1-amelia-bedelia-hit-the-books-collection-5-books/", "take": "Five Level 2 Amelia Bedelia stories in a little Velcro-tabbed suitcase with a carry handle. The literal-minded maid's mix-ups are a proven giggle-generator for kids reading on their own with a little help."}, {"id": 985, "title": "Amelia Bedelia Makes a Friend", "url": "https://store.ignatiusbookfairs.com/amelia-bedelia-makes-a-friend/", "take": "Young Amelia Bedelia's best friend moves away, and the new neighbor is not what she expects. A Level 1 I Can Read that keeps newly independent readers laughing while quietly stretching their vocabularies."}, {"id": 1353, "title": "American Indians", "url": "https://store.ignatiusbookfairs.com/american-indians/", "take": "A Fandex field guide introducing fifty North American tribes through people, history, myth, and culture - Sitting Bull, Pontiac, the Navajo code talkers, the Trail of Tears. A browsable format that pulls kids into real history."}, {"id": 916, "title": "An American Little Flower", "url": "https://store.ignatiusbookfairs.com/an-american-little-flower/", "take": "The story of Blessed Miriam Teresa Demjanovich of Bayonne, New Jersey - the first Beatification ever held on American soil. A young American holy life set against automobiles, movies, and World War I. Sanctity in a recognizably American key."}, {"id": 999, "title": "Angel in the Waters", "url": "https://store.ignatiusbookfairs.com/angel-in-the-waters/", "take": "A simple, gentle story of a baby in the womb and the angel who watches over him. Sold widely in Catholic bookstores for years, it plants a quiet reverence for life in young hearts without a single confrontational word."}, {"id": 1355, "title": "Angel Stories from the Bible", "url": "https://store.ignatiusbookfairs.com/angel-stories-from-the-bible/", "take": "Five angel stories straight from the Bible - Jacob's ladder, Raphael and Tobias, Gabriel's good news, Joseph's dreams, the angel at the tomb - beautifully illustrated to give children confidence in God's protecting care."}, {"id": 1412, "title": "Angle of Repose", "url": "https://store.ignatiusbookfairs.com/angle-of-repose/", "take": "Wallace Stegner's Pulitzer-winning novel of a retired historian writing his grandmother's frontier biography amid 1970s chaos. A deeply moving meditation on marriage, tradition, and the American West for adult readers."}, {"id": 2478, "title": "Animal Showdown: Round 2", "url": "https://store.ignatiusbookfairs.com/animal-showdown-round-2/", "take": "Great white shark versus saltwater crocodile; elephant versus dolphin in a battle of smarts. This animal-matchup sequel hands kids the full lowdown on each contender before they pick a winner — irresistible for fact-hungry readers."}, {"id": 1793, "title": "Anna Hibiscus", "url": "https://store.ignatiusbookfairs.com/anna-hibiscus/", "take": "Anna Hibiscus lives in amazing Africa with twin baby brothers named Double and Trouble and a compound full of cousins and aunties. Atinuke's warm series opener brims with family, mischief, and a contemporary West African setting most young readers haven't met."}, {"id": 2460, "title": "Anne of Green Gables", "url": "https://store.ignatiusbookfairs.com/anne-of-green-gables/", "take": "The Cuthberts asked the orphanage for a boy to help on the farm; they got talkative, imaginative Anne Shirley instead. Mishap by mishap, she wins them over — and readers too. An enduring classic every shelf should hold."}, {"id": 1030, "title": "Anne of Green Gables Library (Books 1-4)", "url": "https://store.ignatiusbookfairs.com/anne-of-green-gables-library-books-1-4/", "take": "The first four Anne of Green Gables books in a handsomely designed boxed set. Red-headed, big-hearted Anne Shirley remains one of literature's most beloved characters, and this makes a genuinely lovely gift or keepsake."}, {"id": 2513, "title": "Any Time, Any Place, Any Prayer Storybook: A True Story of How You Can Talk to God", "url": "https://store.ignatiusbookfairs.com/any-time-any-place-any-prayer-storybook-a-true-story-of-how-you-can-talk-to-god/", "take": "From the million-selling Tales That Tell the Truth series and a Christianity Today award winner: a beautifully illustrated storybook teaching kids they can talk to God any time, any place, about anything. Warm, biblical, and genuinely useful."}, {"id": 1124, "title": "Are You Ready to Play Outside?", "url": "https://store.ignatiusbookfairs.com/are-you-ready-to-play-outside/", "take": "Piggie wants sunshine; the sky has other plans. Another Elephant and Piggie gem with vocabulary pitched right at novice readers, and reviewers are right that these books practically teach kids to read with expression."}, {"id": 2278, "title": "Around New York (Young Explorers)", "url": "https://store.ignatiusbookfairs.com/around-new-york-young-explorers/", "take": "The Statue of Liberty, the Empire State Building, the Met — this kid-sized travel guide breaks New York into itineraries with facts at every stop. A fun way to feed curiosity, whether the trip is real or imagined."}, {"id": 2277, "title": "Around Paris (Young Explorers)", "url": "https://store.ignatiusbookfairs.com/around-paris-young-explorers/", "take": "A travel guide to Paris made just for kids, with itineraries covering the Louvre, the Eiffel Tower, Notre-Dame, and more, plus facts about each stop. Equally good for dreaming about a trip or taking along on one."}, {"id": 1792, "title": "Around Rome: Young Explorers", "url": "https://store.ignatiusbookfairs.com/around-rome-young-explorers/", "take": "A travel guide to Rome written just for kids — the Colosseum, the Pantheon, the Trevi Fountain, arranged as itineraries with facts about each iconic stop. Good for dreaming from home or tucking into a real suitcase."}, {"id": 1085, "title": "Art for Kids: Drawing", "url": "https://store.ignatiusbookfairs.com/art-for-kids-drawing/", "take": "Contour drawing, hands-on lessons, and plenty of exercises — a genuinely instructive guide for kids who want their drawings to look like what they actually see. \"A gold mine of information,\" says Library Media Connection."}, {"id": 2225, "title": "Astro Girl", "url": "https://store.ignatiusbookfairs.com/astro-girl/", "take": "Astrid wants to be an astronaut, and while Mama is away she and Papa act out zero gravity, tube food, and science experiments at home. A sweet, playful launchpad for little dreamers who love the stars."}, {"id": 2245, "title": "Attacked at Sea", "url": "https://store.ignatiusbookfairs.com/attacked-at-sea/", "take": "May 1942: a U-boat stalks the freighter Heredia fifty miles from New Orleans, with the Downs family asleep aboard. Tougias delivers another riveting, true WWII survival-at-sea account for young readers who devour real history."}, {"id": 1830, "title": "Auspice Maria Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/auspice-maria-vinyl-sticker/", "take": "The Auspice Maria monogram — \"under the protection of Mary\" — as a vinyl sticker. Classic Marian devotion in an elegant, everyday format, and a lovely small gift for a Catholic student."}, {"id": 1799, "title": "Baby Goes to Market", "url": "https://store.ignatiusbookfairs.com/baby-goes-to-market/", "take": "Baby charms his way through a bustling southwest Nigerian marketplace, collecting bananas and oranges while busy Mama never notices. A bright, bouncy read-aloud that sneaks in gentle counting practice — and a market setting full of life."}, {"id": 1362, "title": "Baby Island", "url": "https://store.ignatiusbookfairs.com/baby-island/", "take": "Two sisters shipwrecked on a deserted island - with four babies to care for. A Newbery Medalist author's classic tale of pluck and dedication that turns babysitting into a survival adventure."}, {"id": 979, "title": "Backpack Explorer: On the Nature Trail", "url": "https://store.ignatiusbookfairs.com/backpack-explorer-on-the-nature-trail/", "take": "A take-along field guide for ages 4 and up, with seek-and-find lists, trail art projects, and a real pull-out magnifying glass. Works in a nature preserve or a suburban backyard — curiosity travels well."}, {"id": 2461, "title": "Bake through the Bible", "url": "https://store.ignatiusbookfairs.com/bake-through-the-bible/", "take": "Twenty simply told Bible stories spanning the whole of scripture, each paired with a cooking activity, discussion questions, and a recap to share over the finished treat. A genuinely fun way for parents and young children to explore the Bible together."}, {"id": 1363, "title": "Baking Class: 50 Fun Recipes Kids Will Love to Bake!", "url": "https://store.ignatiusbookfairs.com/baking-class-50-fun-recipes-kids-will-love-to-bake/", "take": "Fifty kid-friendly recipes with step-by-step photos that teach real skills - kneading dough, decorating cookies, producing an actual pie - for ages 8 to 12. The follow-up to Cooking Class builds bakers, not just messes."}, {"id": 1042, "title": "Ballet Shoes", "url": "https://store.ignatiusbookfairs.com/ballet-shoes/", "take": "Three orphan sisters join a stage academy to help pay the family bills, each chasing a different dream — movies, dance, and something else entirely. A theater-hearted classic generations of readers have pressed on their friends."}, {"id": 2179, "title": "Bambinelli Sunday", "url": "https://store.ignatiusbookfairs.com/bambinelli-sunday/", "take": "On the Third Sunday of Advent, children fill Saint Peter's Square so the pope can bless the Baby Jesus figures from their Nativity scenes. Alessandro's story introduces this real tradition, plus a tender lesson about love that overcomes anything."}, {"id": 1364, "title": "Baptism Day", "url": "https://store.ignatiusbookfairs.com/baptism-day/", "take": "Leo is baptized today, and his whole family is filled with joy. Maite Roche's warm illustrations make this a gentle first introduction to the sacrament for very young children - lovely for godparents to give."}, {"id": 949, "title": "Bard of Avon: The Story of William Shakespeare", "url": "https://store.ignatiusbookfairs.com/bard-of-avon-the-story-of-william-shakespeare/", "take": "Diane Stanley's award-winning picture-book biography of Shakespeare, from Stratford boyhood to London fame. A handsome introduction to the playwright whose words people quote daily without knowing it - well suited to classroom Shakespeare units."}, {"id": 2757, "title": "Barker's Dog House: Leave It", "url": "https://store.ignatiusbookfairs.com/barkers-dog-house-leave-it-ibc-1539/", "take": "Gio can talk to puppies, the doghouse dogs are horrified by the new foster pup, and early middle grade readers get the joke on every page. A funny, warmhearted series pick for kids finding their footing somewhere new."}, {"id": 977, "title": "Barnyard Games & Puzzles", "url": "https://store.ignatiusbookfairs.com/barnyard-games-puzzles/", "take": "Word games, mazes, jokes, and brain teasers with a barnyard theme, pitched at ages six and up. Cheerful puzzle-book fun — the Rhode Island Red crossword alone is worth the price of admission."}, {"id": 2022, "title": "Bartolome de las Casas", "url": "https://store.ignatiusbookfairs.com/bartolome-de-las-casas/", "take": "Award-winning Spanish novelist Jose Luis Olaizola takes on one of colonization's most contested figures, telling Las Casas's story in his own voice — defender of the natives to some, controversial to others. Thoughtful historical fiction for older readers."}, {"id": 1889, "title": "Be a Man!", "url": "https://store.ignatiusbookfairs.com/be-a-man/", "take": "Father Larry Richards writes for men as men, drawing on decades of ministry and his own hard-won lessons in true manhood. Direct, inspiring, and practical. A reliable pick for fathers, and for parishes trying to reach them."}, {"id": 1096, "title": "Before Austen Comes Aesop", "url": "https://store.ignatiusbookfairs.com/before-austen-comes-aesop/", "take": "A guided tour of the Children's Great Books — a chronological list from ancient times to the present, plus practical help for parents and students reading them at home. A thoughtful roadmap for building a real literary childhood."}, {"id": 1764, "title": "Before I Was Me", "url": "https://store.ignatiusbookfairs.com/before-i-was-me/", "take": "An imagined conversation between God and an unborn child, beautifully illustrated: I have great plans for you. A gentle, affirming read-aloud about being loved and chosen from the very first moment of life."}, {"id": 1365, "title": "Before You Were Born: A Lift-the-Flap Book", "url": "https://store.ignatiusbookfairs.com/before-you-were-born-a-lift-the-flap-book/", "take": "A lighthearted lift-the-flap answer to the question curious kids always ask: what happened before I was born? Month by month, in verse and comical pictures, a mother tells the story of waiting to meet her child."}, {"id": 1892, "title": "Being Catholic: What Every Catholic Should Know", "url": "https://store.ignatiusbookfairs.com/being-catholic-what-every-catholic-should-know/", "take": "Suzie Andres surveys Catholic customs, traditions, and culture for the average faithful Catholic who wants to know more, in a friendly, panoramic style. A welcoming entry in the What Every Catholic Should Know series, no theology degree required."}, {"id": 1016, "title": "Beorn the Proud", "url": "https://store.ignatiusbookfairs.com/beorn-the-proud/", "take": "Madeleine Polland's adventure of 9th-century Viking raids on Ireland, where proud young Beorn learns Christian humility from his Irish captive Ness. Battles and shipwrecks for the kids; a genuine clash of faiths underneath."}, {"id": 2462, "title": "Berenstain Bears Kindness Counts", "url": "https://store.ignatiusbookfairs.com/berenstain-bears-kindness-counts/", "take": "The Berenstain Bears learn that kindness counts in this Living Lights story that weaves God's goodness into everyday cub life. An easy conversation-starter about treating others well, pitched just right for readers ages 4-8."}, {"id": 1367, "title": "Bernadette: Our Lady's Little Servant", "url": "https://store.ignatiusbookfairs.com/bernadette-our-ladys-little-servant/", "take": "The story of the poor girl of Lourdes who studied her catechism, minded her siblings, gathered firewood - and met the Blessed Virgin. A classic saint biography that shows holiness hiding in ordinary faithfulness."}, {"id": 1368, "title": "Bernadette: The Little Girl from Lourdes", "url": "https://store.ignatiusbookfairs.com/bernadette-the-little-girl-from-lourdes/", "take": "Bernadette's story told for young readers, beginning with Lourdes as it was: a tiny village, and a simple girl of fourteen whose encounters with the Blessed Virgin Mary changed everything. Accessible and reverent."}, {"id": 2211, "title": "Berry Song", "url": "https://store.ignatiusbookfairs.com/berry-song/", "take": "Caldecott Medalist Michaela Goade's first self-authored picture book follows a girl and her grandmother gathering salmon, herring eggs, and berries on a wild island. A Caldecott Honor book with gorgeous art and the quiet wisdom of elders."}, {"id": 1761, "title": "Best Hair Book Ever!", "url": "https://store.ignatiusbookfairs.com/best-hair-book-ever/", "take": "Faithgirlz tips and tricks for up-dos, uncooperative curls, and picture-day styling, pitched to preteens and tweens ages 8-12. Cheerful, practical, and encouraging about embracing your own unique style on any hair day."}, {"id": 1029, "title": "Betsy-Tacy Treasury", "url": "https://store.ignatiusbookfairs.com/betsy-tacy-treasury/", "take": "The first four Betsy-Tacy books in one volume, with forewords by Judy Blume, Ann M. Martin, and Johanna Hurwitz. Blume says these characters became friends for life — plenty of grown readers agree."}, {"id": 2279, "title": "Beyond Mulberry Glen", "url": "https://store.ignatiusbookfairs.com/beyond-mulberry-glen/", "take": "Lydia Green is happy in Mulberry Glen with her wonderfully mismatched family — until rumors of The Darkness and a foolish choice by the twins push her into the strange magical Valleylands. A cozy-then-brave fantasy for middle readers."}, {"id": 971, "title": "Big Tracks Little Tracks: Following Animals", "url": "https://store.ignatiusbookfairs.com/big-tracks-little-tracks-following-animals/", "take": "Millicent Selsam's gentle classic teaches children to read footprints and other clues animals leave behind. A perfect first book for a budding naturalist, with a new hands-on activities page included."}, {"id": 1370, "title": "Biggest Riddle Book in the World", "url": "https://store.ignatiusbookfairs.com/biggest-riddle-book-in-the-world/", "take": "Over 2,000 riddles from simple to groan-worthy, compiled by a children's librarian, with an index for finding specific zingers. A boost for budding comedians and a reliable pick for reluctant readers who love a punchline."}, {"id": 1000, "title": "Billy and Blaze", "url": "https://store.ignatiusbookfairs.com/billy-and-blaze/", "take": "Billy loves horses more than anything, and for his birthday he gets his own pony. C.W. Anderson's classic series opener about a boy and his horse learning to trust each other — timeless in the best sense."}, {"id": 1001, "title": "Blaze and the Forest Fire", "url": "https://store.ignatiusbookfairs.com/blaze-and-the-forest-fire/", "take": "Billy and Blaze spot smoke in the brush and race to sound the alarm. A classic adventure in the beloved series, rewarded at day's end with carrots, chocolate cake, and a special present to share."}, {"id": 2780, "title": "Blood and Water: The Life and Martyrdom of Shahbaz Bhatti", "url": "https://store.ignatiusbookfairs.com/blood-and-water-graphic-novel-the-life-and-martyrdom-of-shahbaz-bhatti-ibc-6bwh/", "take": "The life and martyrdom of Shahbaz Bhatti, told in powerful graphic-novel form alongside the Gospel scenes his life echoed. A sobering, inspiring portrait of modern courage for teens — one of the most affecting books we carry."}, {"id": 2255, "title": "Blueberries for Sal", "url": "https://store.ignatiusbookfairs.com/blueberries-for-sal/", "take": "Kuplink, kuplank, kuplunk! Sal and her mother pick blueberries for winter, a bear cub and his mother do the same, and the little ones get delightfully mixed up. A Caldecott Honor classic with expressive, timeless line drawings."}, {"id": 2832, "title": "Bluey At the Beach: A Coloring Book", "url": "https://store.ignatiusbookfairs.com/bluey-at-the-beach-a-coloring-book-ibc-1580/", "take": "Bluey, Bingo, and 32 pages of beach to color. Simple, sunny, and exactly what the road trip ordered for the Disney+ generation's favorite heeler family."}, {"id": 2032, "title": "Bluey Big Backyard: A Coloring Book", "url": "https://store.ignatiusbookfairs.com/bluey-big-backyard-a-coloring-book/", "take": "Sixty-four high-quality coloring pages of Bluey, Bingo, Bob Bilby, and friends. Works with crayons, markers, or paint, and earns its keep on road trips and rainy days. Exactly what young Bluey fans hope to find at the fair."}, {"id": 2164, "title": "Bluey: La Piscina The Pool", "url": "https://store.ignatiusbookfairs.com/bluey-la-piscina-the-pool/", "take": "Bluey, Bingo, and Dad head to the pool, in English and Spanish in one storybook. A bilingual picture book from the beloved animated series that lets families read together in either language. Easy fun for the youngest fans."}, {"id": 2117, "title": "Book Scavenger #1", "url": "https://store.ignatiusbookfairs.com/book-scavenger-1/", "take": "Twelve-year-old Emily moves to San Francisco, home of the Book Scavenger game, and lands in a cipher-filled mystery Publishers Weekly likened to The Westing Game. Catnip for puzzle-minded middle graders who like their adventures bookish."}, {"id": 960, "title": "Boys of Steel", "url": "https://store.ignatiusbookfairs.com/boys-of-steel/", "take": "The true story of Jerry Siegel and Joe Shuster, two Depression-era misfits who created Superman the summer they finished high school. A quietly encouraging tale for any kid who escapes into stories and drawings."}, {"id": 2218, "title": "Brambley Hedge: Autumn Story", "url": "https://store.ignatiusbookfairs.com/brambley-hedge-autumn-story/", "take": "Autumn storms are coming, the harvest isn't in, and Primrose has daydreamed her way into being thoroughly lost. Cozy, richly detailed mouse-world storytelling celebrating its 40th anniversary. Perfect fireside fare for little listeners."}, {"id": 2201, "title": "Brambley Hedge: Spring Story", "url": "https://store.ignatiusbookfairs.com/brambley-hedge-spring-story/", "take": "Wilfred's birthday brings a secret celebration picnic, a mysteriously heavy hamper, and a surprise inside it. The mice of Brambly Hedge in springtime: miniature, detailed, and utterly cozy. A lovely quiet read-aloud for little ones."}, {"id": 2190, "title": "Brambley Hedge: Winter Story", "url": "https://store.ignatiusbookfairs.com/brambley-hedge-winter-story/", "take": "The mice of Brambly Hedge wake to deep snowdrifts and declare a Snow Ball, building an Ice Hall in the time-honoured way. Forty years on, this miniature world remains one of the coziest in children's books. Rich, detailed winter comfort."}, {"id": 2466, "title": "Brave Irene", "url": "https://store.ignatiusbookfairs.com/brave-irene/", "take": "William Steig's plucky dressmaker's daughter battles a fierce snowstorm to deliver a ball gown for her ailing mother. Children genuinely cheer Irene on — it's a classic about grit, love, and finishing what you start."}, {"id": 2254, "title": "Bringing the Rain to Kapiti Plain", "url": "https://store.ignatiusbookfairs.com/bringing-the-rain-to-kapiti-plain/", "take": "A cumulative rhyme with the rhythm of The House That Jack Built, telling how Ki-pat brought rain to the drought-stricken Kapiti Plain. Verna Aardema's refrain begs to be chanted aloud — story time gold."}, {"id": 905, "title": "Brother Francis of Assisi", "url": "https://store.ignatiusbookfairs.com/brother-francis-of-assisi/", "take": "DePaola's lifelong ambition realized: the story of St. Francis, built on primary sources and two trips to Assisi. Aimed at children five and up but genuinely satisfying for all ages - a labor of love, and it shows."}, {"id": 879, "title": "Brother Rafael and the Rainy Day Devils", "url": "https://store.ignatiusbookfairs.com/brother-rafael-and-the-rainy-day-devils/", "take": "A monastery kitchen, a pile of turnips, cackling red devils of gloom, and a gentle voice asking Brother Rafael why he does what he does. A playful, surprisingly deep little story about finding God in ordinary chores."}, {"id": 2869, "title": "Brother Wolf Plush", "url": "https://store.ignatiusbookfairs.com/brother-wolf-plush/", "take": "The Wolf of Gubbio - Loupio's faithful companion through all eight Adventures of Loupio books - as a 6-inch plush. Pairs perfectly with the Loupio doll and the series itself for young St. Francis fans."}, {"id": 2489, "title": "Buster's Trip to Victory Lane - board book", "url": "https://store.ignatiusbookfairs.com/buster-s-trip-to-victory-lane-board-book/", "take": "Dale Earnhardt Jr. writes what he knows: race day nerves and not giving up. Now in a sturdy board book, Buster's story gives anxious little ones a cheerful vocabulary for trying again. Bright, loud, and encouraging."}, {"id": 1387, "title": "Butterflies of the World", "url": "https://store.ignatiusbookfairs.com/butterflies-of-the-world/", "take": "A Fandex field guide to fifty butterflies, from the Great Egg-fly that crosses 1,400 miles of ocean to the fingernail-sized Pygmy Blue. Die-cut, full-color cards make identification - and browsing - genuinely fun."}, {"id": 1898, "title": "By the Rivers of Babylon", "url": "https://store.ignatiusbookfairs.com/by-the-rivers-of-babylon/", "take": "A vivid novel of the prophet Ezekiel's early life, from timid bricklayer to exile by the River Chebar, before his visions begin. Biblical fiction that takes the Babylonian Captivity seriously as lived experience. Absorbing for teen and adult readers."}, {"id": 2759, "title": "Caddie Woodlawn", "url": "https://store.ignatiusbookfairs.com/caddie-woodlawn-ibc-1633/", "take": "Carol Ryrie Brink's frontier story won the Newbery Medal in 1936 and has never really left the shelf since. A dependable historical fiction pick with classroom staying power and genuine, unforced charm."}, {"id": 1389, "title": "Calico Bush", "url": "https://store.ignatiusbookfairs.com/calico-bush/", "take": "In 1743, thirteen-year-old Marguerite arrives in Maine as an indentured servant to a family that barely regards her - until her courage and quick thinking surprise them all. A sturdy historical novel with a heroine worth meeting."}, {"id": 2182, "title": "California Black Robe", "url": "https://store.ignatiusbookfairs.com/california-black-robe/", "take": "An in-depth biography of Father Joseph Fessio, S.J., founder of Ignatius Press, written by one of his earliest Jesuit mentors. One for the adults on your list: staff, pastors, and parents curious about a consequential American Jesuit."}, {"id": 1040, "title": "Call it Courage", "url": "https://store.ignatiusbookfairs.com/call-it-courage/", "take": "Mafatu, son of a chief in a culture that worships courage, is branded a coward for fearing the sea that took his mother — until he can bear it no longer. A spare, stirring Newbery Medal winner about earning your name."}, {"id": 2008, "title": "Call me Mama", "url": "https://store.ignatiusbookfairs.com/call-me-mama/", "take": "A sturdy, made-in-the-USA board book from artist Kortnee Senn with one tender, clarifying idea: every Marian apparition is still the same Mama Mary. A sweet, simple way to introduce the littlest ones to Our Lady."}, {"id": 1824, "title": "Call Your Mama Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/call-your-mama-vinyl-sticker/", "take": "A vinyl sticker with a grin built in: Call Your Mama. In a Catholic collection the double meaning lands sweetly — a lighthearted Marian wink that also happens to be plain good advice."}, {"id": 1816, "title": "Called Small Accessory Case", "url": "https://store.ignatiusbookfairs.com/called-small-accessory-case/", "take": "A small accessory case bearing a single word: Called. Practical for pencils, earbuds, or little treasures, with a quiet nudge about vocation riding along. Simple, useful, and unobtrusively meaningful."}, {"id": 1088, "title": "Calligraphy for Kids", "url": "https://store.ignatiusbookfairs.com/calligraphy-for-kids/", "take": "Chisel-edged markers, helpful guidelines, and brightly colored examples take kids from simple zigzags to genuinely handsome lettering. A friendly, well-designed introduction to calligraphy for school projects, art class, or rainy-day fun."}, {"id": 1478, "title": "Camp Granny", "url": "https://store.ignatiusbookfairs.com/camp-granny/", "take": "130 nature projects made for grandparents and grandchildren to share — leaf rubbings, jumbo bubbles, Moon Pizzas, firefly lanterns — illustrated with photographs and the author's own watercolors. Less an activity book than a standing invitation to spend real time together."}, {"id": 1082, "title": "Camp Out! The Ultimate Kid's Guide", "url": "https://store.ignatiusbookfairs.com/camp-out-the-ultimate-kids-guide/", "take": "Bear bags, tarp tents, solar oven pizza, creepy campfire stories, and telling the temperature by cricket chirps. Backyard overnight or wilderness weekend, this guide packs in everything a kid needs to feel camp-competent."}, {"id": 1017, "title": "Canadian Summer", "url": "https://store.ignatiusbookfairs.com/canadian-summer/", "take": "The Mitchell family, unable to find a house in Montreal, settles for a rickety summer place in the woods. Dangers, antics, and quarrels bring each child vividly to life against rural 1940s Quebec."}, {"id": 2823, "title": "Cardboardbox Engineering", "url": "https://store.ignatiusbookfairs.com/cardboardbox-engineering-ibc-1629/", "take": "Gadgets, games, inventions, and sculptures - all engineered from cardboard boxes, sheets, and tubes. Aimed at makers aged 9 to 14, it turns recycling-bin material into real projects. Practical, eco-friendly, and screen-free."}, {"id": 1765, "title": "Carlo Acutis: Holiness for the Third Millenium", "url": "https://store.ignatiusbookfairs.com/carlo-acutis-holiness-for-the-third-millenium/", "take": "Carlo loved video games, soccer, and his friends — and Mass, the poor, and stray dogs. This story of the young computer whiz who built websites to share his faith introduces kids to a holy life from their own era."}, {"id": 2487, "title": "Catch That Pass!", "url": "https://store.ignatiusbookfairs.com/catch-that-pass/", "take": "Jim has everything a linebacker needs except the nerve to get tackled. With his friend Chuckie's example of real courage, this Matt Christopher-style sports story gives young readers an honest, encouraging look at facing fears head-on."}, {"id": 2810, "title": "Catechism of the Seven Sacraments", "url": "https://store.ignatiusbookfairs.com/catechism-of-the-seven-sacraments-ibc-1609/", "take": "Covenant theology in comic-book form — and it genuinely works. Fulton and Cynthia walk from creation to the sacraments with depth that surprises adults and clarity that reaches kids. A parish favorite."}, {"id": 967, "title": "Caterpillar to Butterfly", "url": "https://store.ignatiusbookfairs.com/caterpillar-to-butterfly/", "take": "Metamorphosis told through graduated flaps and stunning photographs — each stage of the caterpillar-to-butterfly journey visible at a glance. Simple text keeps it accessible for young nature lovers."}, {"id": 1093, "title": "Catholic All Year Compendium", "url": "https://store.ignatiusbookfairs.com/catholic-all-year-compendium/", "take": "Kendra Tierney's warm, funny guide to living the liturgical year at home, from Advent through Easter and the feasts between. Equally useful whether your family knows the calendar cold or is hearing of it for the first time."}, {"id": 1094, "title": "Catholic All Year Prayer Companion", "url": "https://store.ignatiusbookfairs.com/catholic-all-year-prayer-companion/", "take": "Hundreds of prayers organized around the Church calendar's seasons and feast days — a practical companion to Tierney's bestselling Compendium for busy families who want to pray the year, not just plan it."}, {"id": 1812, "title": "Catholic Church Alpha Wet Water Reveal Cards", "url": "https://store.ignatiusbookfairs.com/catholic-church-alpha-wet-water-reveal-cards/", "take": "Alphabet cards with a water-reveal twist and a Catholic Church theme. The concept is simple by design: add water, watch the picture appear — a mess-light, screen-free activity for little hands."}, {"id": 996, "title": "Chanticleer and the Fox", "url": "https://store.ignatiusbookfairs.com/chanticleer-and-the-fox/", "take": "Chanticleer, king of the barnyard, gets duped by a flattering fox and must think fast to save himself. A classic trickster tale with a satisfying lesson about vanity and quick wits."}, {"id": 1802, "title": "Charis in the World of Wonders", "url": "https://store.ignatiusbookfairs.com/charis-in-the-world-of-wonders/", "take": "A young woman flees flaming arrows and massacre into the wilderness, scouring it for shelter and striving toward a family and place where she can belong. Lyrical, literary survival fiction with a striking first-person voice — one for older readers."}, {"id": 2484, "title": "Charlotte's Web", "url": "https://store.ignatiusbookfairs.com/charlottes-web/", "take": "E.B. White's barnyard masterpiece, called just about perfect for good reason, here with a foreword by Kate DiCamillo. Wilbur, Charlotte, and those miraculous webs remain essential reading — one of America's most-loved novels by any measure."}, {"id": 1682, "title": "Chick Days: An Absolute Beginners Guide to Raising Chickens from Hatching to Laying", "url": "https://store.ignatiusbookfairs.com/chick-days-an-absolute-beginners-guide-to-raising-chickens-from-hatching-to-laying/", "take": "Follow three chickens — Amelia, Honey, and Tilda — from fluffy hatchlings to laying hens while learning feeding, housing, and health care along the way. A friendly, genuinely useful beginner's guide for families considering a backyard flock."}, {"id": 1090, "title": "Choirs of Angels Coloring Book", "url": "https://store.ignatiusbookfairs.com/choirs-of-angels-coloring-book/", "take": "Line drawings based on paintings by the great masters, each paired with a quotation from Scripture about the angels. Children color their way through Old and New Testament scenes while quietly learning who the angels are."}, {"id": 1136, "title": "Christina's Carol", "url": "https://store.ignatiusbookfairs.com/christinas-carol/", "take": "Tomie dePaola sets Christina Rossetti's carol In the Bleak Midwinter to wintry, reverent pictures: the humble stable, the gathered shepherds and angels, the holy night itself. A quiet, beautiful addition to the Christmas shelf."}, {"id": 995, "title": "Christmas in the Big Woods", "url": "https://store.ignatiusbookfairs.com/christmas-in-the-big-woods/", "take": "Cousins arrive, sweets are eaten, snow is played in — a full-color hardcover introduction to the Little House series built around a holiday of simple joys. A lovely family read-aloud for Christmastime."}, {"id": 906, "title": "Christopher, the Holy Giant", "url": "https://store.ignatiusbookfairs.com/christopher-the-holy-giant/", "take": "DePaola preserves the beloved legend of Reprobus, the giant who sought the most powerful king and ended up carrying the Christ Child. A gorgeous retelling of the St. Christopher story generations of travelers have held dear."}, {"id": 2175, "title": "Chronicles of Narnia Box Set", "url": "https://store.ignatiusbookfairs.com/chronicles-of-narnia-box-set/", "take": "All seven Chronicles of Narnia in one paperback box set. Lewis's talking creatures, epic battles between good and evil, and deep magic have held readers for over sixty years. This is the edition that starts lifelong re-readers."}, {"id": 1553, "title": "Citadel of God: A Novel about Saint Benedict", "url": "https://store.ignatiusbookfairs.com/citadel-of-god-a-novel-about-saint-benedict/", "take": "Louis de Wohl brings his historical-novel mastery to St. Benedict, father of Western monasticism, amid the turbulence of sixth-century post-Roman Europe. Love, violence, and piety woven with historical care — for readers who like their saints in full context."}, {"id": 1479, "title": "Civil War", "url": "https://store.ignatiusbookfairs.com/civil-war/", "take": "A Fandex field guide to the Civil War — battles, generals, causes, and outcomes — documented with on-the-spot photographs and full-color prints. The flip-through format suits kids who absorb history in vivid question-and-answer bursts."}, {"id": 2144, "title": "Cloak of the Light (Wars of the Realm, #1)", "url": "https://store.ignatiusbookfairs.com/cloak-of-the-light-wars-of-the-realm-1/", "take": "Drew Carter's accident leaves him seeing a world just beyond ours — one that can reach back. A tense supernatural thriller for teens about tragedy, mystery, and what lies inches past the visible."}, {"id": 1450, "title": "Communion of Saints Coloring Book", "url": "https://store.ignatiusbookfairs.com/communion-of-saints-coloring-book/", "take": "Line drawings after the great masters, arranged chronologically from the companions of Christ and the early martyrs to Therese of Lisieux and Padre Pio, each with a short life of the saint. A coloring book that doubles as a church history lesson."}, {"id": 2763, "title": "Complete Cookbook for Teen Chefs", "url": "https://store.ignatiusbookfairs.com/complete-cookbook-for-teen-chefs-ibc-1618/", "take": "America's Test Kitchen rigor, aimed at teenagers — 70+ recipes tested by thousands of actual teens. The rare cookbook that builds real kitchen independence instead of just filling a shelf."}, {"id": 1956, "title": "Confio; Siguiendo las Huellas de Santa Faustina", "url": "https://store.ignatiusbookfairs.com/confio-siguiendo-las-huellas-de-santa-faustina/", "take": "The Spanish-language telling of St. Faustina's story and the worldwide spread of the Divine Mercy devotion, with photographs and illustrations on every page. A beautiful choice for Spanish-speaking families, parishes, and bilingual school communities."}, {"id": 2465, "title": "Cooking Class: 73 Fun Recipes Kids will love to Make (and Eat!)", "url": "https://store.ignatiusbookfairs.com/cooking-class-73-fun-recipes-kids-will-love-to-make-and-eat/", "take": "The updated tenth-anniversary edition of a classic kids' cooking guide, with dozens of recipes kids can truly make themselves. Step-by-step photographic instructions do the teaching, so children build real skills instead of just watching a grown-up cook."}, {"id": 989, "title": "County Fair", "url": "https://store.ignatiusbookfairs.com/county-fair/", "take": "Almanzo brings his special pumpkin to the county fair in this adaptation from Farmer Boy — contests, races, good things to eat. Jody Wheeler's luminous illustrations capture the excitement of fair day."}, {"id": 1904, "title": "Couples, Awaken Your Love", "url": "https://store.ignatiusbookfairs.com/couples-awaken-your-love/", "take": "Cardinal Sarah's retreat for married couples, preached at Lourdes, now in book form: a path back to the deep source of married love, God himself. Meant for all couples, including those struggling. Serious, luminous spiritual reading for spouses."}, {"id": 1836, "title": "Courage Dear Heart Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/courage-dear-heart-vinyl-sticker/", "take": "\"Courage, dear heart\" in vinyl sticker form — a phrase many book lovers will recognize, and one everybody needs some days. A small, giftable bit of steel for lockers, laptops, and water bottles."}, {"id": 1795, "title": "Courage Under Fire", "url": "https://store.ignatiusbookfairs.com/courage-under-fire/", "take": "The story of Father Willie Doyle, the Irish Jesuit chaplain who sacrificed his life serving wounded soldiers in World War I. A historical novel for young people about a happy childhood, an early priestly call, and heroic self-giving."}, {"id": 1672, "title": "Cozy's Complete Guide to Girls' Hair", "url": "https://store.ignatiusbookfairs.com/cozys-complete-guide-to-girls-hair/", "take": "The owner of a children's hair salon chain shares professional advice for making girls' hair styling trouble-free — and even fun — for parents and grandparents. Practical, cheerful, and genuinely useful before picture day."}, {"id": 1548, "title": "Crazy Dangerous", "url": "https://store.ignatiusbookfairs.com/crazy-dangerous/", "take": "Sam Hopkins is a good kid running with car thieves — until he finds the courage to defend an eccentric classmate named Jennifer. A tense teen thriller about choosing your friends, built on a fine motto: do right, fear nothing."}, {"id": 2855, "title": "Critter Club: Liz Learns a Lesson", "url": "https://store.ignatiusbookfairs.com/critter-clubliz-learns-a-lesson-ibc-1599/", "take": "Liz's summer plans collide with summer school when her math grades fall short. A gentle Critter Club story about responsibility, friendship, and making the best of unexpected news - with plenty of petsitting alongside."}, {"id": 2238, "title": "Crusaders and Pilgrims, the Adventures of Loupio Volume 8", "url": "https://store.ignatiusbookfairs.com/crusaders-and-pilgrims-the-adventures-of-loupio-volume-8/", "take": "Loupio, the orphaned young troubadour, follows Saint Francis toward the Holy Land in this eighth adventure. Knights, danger, and daring encounters carry gentle lessons of faith, hope, and charity — a winning mix for young comic readers."}, {"id": 2189, "title": "Curious Features of Extraordinary Creatures", "url": "https://store.ignatiusbookfairs.com/curious-features-of-extraordinary-creatures/", "take": "Full-page animal portraits meet graphic-novel story panels in this fact-packed tour of the world's strangest creatures. Bite-size text on appearance and behavior makes it browsable for reluctant readers and bottomless for the animal-obsessed."}, {"id": 1717, "title": "Daddy-Long-Legs", "url": "https://store.ignatiusbookfairs.com/daddy-long-legs/", "take": "Jean Webster's 1912 classic, told in letters: orphaned Judy Abbott, whose writing talent catches a trustee's eye, gets an unexpected chance at a future. A plucky, charming coming-of-age story that still wins readers over."}, {"id": 1400, "title": "Daily Lenten Journey - Magnifikid!", "url": "https://store.ignatiusbookfairs.com/daily-lenten-journey-magnifikid/", "take": "A MagnifiKid companion for the forty days of Lent: a daily liturgical reading plus concrete ways to grow through fasting, prayer, and almsgiving. Works for one child alone or the whole family praying together."}, {"id": 990, "title": "Dance at Grandpa's", "url": "https://store.ignatiusbookfairs.com/dance-at-grandpas/", "take": "A picture-book episode from Little House in the Big Woods, following the little pioneer girl whose family crossed the Midwest by covered wagon. An easy, warm entry point to the Wilder stories."}, {"id": 1459, "title": "Daniel's Duck", "url": "https://store.ignatiusbookfairs.com/daniels-duck/", "take": "Everyone at the fair laughs at Daniel's wood carving, and his heartbreak — then the sweet turn — is handled beautifully. A Level 3 I Can Read with short chapters, just right for newly independent readers."}, {"id": 901, "title": "David and Goliath", "url": "https://store.ignatiusbookfairs.com/david-and-goliath/", "take": "Tomie dePaola brings his unmistakable artwork to the shepherd boy who faced a giant with a sling and his trust in God. A powerful Bible story told simply and beautifully - and one children ask for again and again."}, {"id": 1067, "title": "De Colores and Other Latin-American Folk Songs for Children", "url": "https://store.ignatiusbookfairs.com/de-colores-and-other-latin-american-folk-songs-for-children/", "take": "Latin-American folk songs, rhymes, and hand games with simple musical arrangements and lyrics in both English and Spanish. Bursting with color and spirit — ideal for classrooms, multicultural studies, or just plain singing around the house."}, {"id": 1908, "title": "Dear and Glorious Physician", "url": "https://store.ignatiusbookfairs.com/dear-and-glorious-physician/", "take": "Taylor Caldwell's world-famous novel of St. Luke, the Greek physician who knew grief and emptiness before he ever asked what manner of man his Lord was. Sweeping mid-century biblical fiction that still stirs readers. A classic for good reason."}, {"id": 1395, "title": "Death Comes for the Archbishop", "url": "https://store.ignatiusbookfairs.com/death-comes-for-the-archbishop/", "take": "Willa Cather's epic of Father Latour, sent in 1851 to serve the vast New Mexico territory, is one of the great American novels of faith, friendship, and landscape. Quiet, mythic, and worth every unhurried page."}, {"id": 1102, "title": "Death of A Scholar", "url": "https://store.ignatiusbookfairs.com/death-of-a-scholar/", "take": "Father Gabriel's restful Cambridge visit ends abruptly when his friend's brilliant young protegee is found dead in her laboratory — an apparent accident his instincts refuse to accept. A satisfying clerical mystery in the classic style."}, {"id": 1838, "title": "Decade Rosary Popper Keychain - Agave", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-agave/", "take": "A decade rosary reimagined as a popper keychain in agave green. Fidget-friendly prayer that clips right onto a backpack — one bead-pop at a time, wherever the day happens to go."}, {"id": 2535, "title": "Decade Rosary Popper Keychain - Daffodil", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-daffodil/", "take": "A daffodil-colored decade rosary in popper-keychain form — a bright, portable way to keep a decade of prayer close at hand. A cheerful little extra for backpacks and key rings; simple as that."}, {"id": 1757, "title": "Decade Rosary Popper Keychain - Denim Blue", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-denim-blue/", "take": "A denim-blue decade rosary in popper-keychain form — a small, portable way to keep prayer close at hand on a backpack or key ring. A simple, giftable Catholic accessory."}, {"id": 1841, "title": "Decade Rosary Popper Keychain - Rose Pink", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-rose-pink/", "take": "A Catholic pop-it: a decade rosary as a popper keychain in rose pink, designed to delight little hearts and spark faith conversations. Fidget energy redirected toward prayer — clever, and genuinely useful."}, {"id": 1997, "title": "Decade Rosary Popper Keychain: Mauve", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-mauve/", "take": "The decade rosary popper in mauve, keychain-sized: one decade's worth of press-down bubbles that travels on keys or a backpack zipper. A handy little nudge toward prayer in waiting rooms and carpool lines."}, {"id": 1999, "title": "Decade Rosary Popper Keychain: Sky Blue", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-sky-blue/", "take": "The keychain-sized decade popper in sky blue — ten bubbles, one decade, no beads to break or scatter. Clips wherever you will actually see it, which is half the battle of remembering to pray on the go."}, {"id": 1992, "title": "Decade Rosary Popper Keychain: Terracotta", "url": "https://store.ignatiusbookfairs.com/decade-rosary-popper-keychain-terracotta/", "take": "A terracotta decade rosary popper sized for a keychain — a single decade of press-and-pray portability for pockets, backpacks, and key rings. A small, easy way to keep prayer within reach wherever the day takes you."}, {"id": 2113, "title": "Decide and Survive: Agent 355: Can You Win the Revolution (Decide and Survive #3)", "url": "https://store.ignatiusbookfairs.com/decide-and-survive-agent-355-can-you-win-the-revolution-decide-and-survive-3/", "take": "A Junior Library Guild Selection that puts readers inside the American Revolution as Agent 355, one of America's first spies — a woman whose true identity remains unknown. Choose-your-path suspense with genuine history underneath."}, {"id": 2105, "title": "Decide and Survive: The Attack on Pearl Harbor: Can you stop the assault? (Decide and Survive #2)", "url": "https://store.ignatiusbookfairs.com/decide-and-survive-the-attack-on-pearl-harbor-can-you-stop-the-assault-decide-and-survive-2/", "take": "Readers make the decisions in this interactive Pearl Harbor adventure, joining forces on the ground in the hours before the attack and determining their own survival. History that demands engagement instead of just delivering dates."}, {"id": 2109, "title": "Decide and Survive: The Destruction of Pompeii", "url": "https://store.ignatiusbookfairs.com/decide-and-survive-the-destruction-of-pompeii/", "take": "Vesuvius is about to erupt, and the reader's choices determine survival. This interactive adventure drops kids into Pompeii in the days before the most famous disaster in history — a format reluctant readers find hard to put down."}, {"id": 2817, "title": "Detective Stanley and the Mystery at the Museum", "url": "https://store.ignatiusbookfairs.com/detective-stanley-and-the-mystery-at-the-museum-ibc-1577/", "take": "An art heist where nothing was stolen, investigated by a pancake-loving detective dog. Droll, colorful, and pitched perfectly at early readers who want a real mystery of their own."}, {"id": 2248, "title": "Devotion: Young Readers Edition", "url": "https://store.ignatiusbookfairs.com/devotion-young-readers-edition/", "take": "The true story of Navy pilots Tom Hudner and Jesse Brown, adapted for young readers with its heart intact. Friendship, courage, and sacrifice across racial lines in the Korean War — riveting nonfiction for 10+."}, {"id": 1116, "title": "Digital Disciples: Carlo Acutis and the Eucharist", "url": "https://store.ignatiusbookfairs.com/digital-disciples-carlo-acutis-and-the-eucharist/", "take": "An action-packed comic about Blessed Carlo Acutis — a fifteen-year-old computer geek who loved superheroes and video games, but the Eucharist most of all, and built a website sharing its miracles. A relatable modern witness for tech-native kids."}, {"id": 2274, "title": "Dinosaurs Before Dark: Magic Tree House - The Graphic Novel", "url": "https://store.ignatiusbookfairs.com/dinosaurs-before-dark-magic-tree-house-the-graphic-novel/", "take": "Jack and Annie's very first tree house adventure — whisked to the age of dinosaurs and racing to get home before dark — retold as a graphic novel. A smart handoff format for kids who love comics or loved the originals."}, {"id": 2217, "title": "Dinosaurs: Learn, Press-Out & Play", "url": "https://store.ignatiusbookfairs.com/dinosaurs-learn-press-out-play/", "take": "Ten press-out dinosaur models, more than 150 stickers, bite-sized facts, and a pronunciation guide, plus a landscape spread to display the finished herd. Hours of hands-on fun that sneaks in real learning for young dino fans."}, {"id": 2492, "title": "Dirt Bike Racer", "url": "https://store.ignatiusbookfairs.com/dirt-bike-racer/", "take": "Ron pulls a dirt bike from the bottom of a lake and takes a yard-work job to fund his racing dream — a job that leads somewhere he never expected. A fast, satisfying sports read for young racers."}, {"id": 1431, "title": "Discipline that Lasts a Lifetime: The Best Gift You Can Give Your Kids", "url": "https://store.ignatiusbookfairs.com/discipline-that-lasts-a-lifetime-the-best-gift-you-can-give-your-kids/", "take": "Counselor, broadcaster, and dad Dr. Ray Guarendi gives parents practical, no-nonsense advice on discipline that actually forms character - moral responsibility, respect, and the basics of living. Short on theory, long on usefulness."}, {"id": 2259, "title": "DK Super Readers A Day at the Petting Zoo PK", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-a-day-at-the-petting-zoo-pk/", "take": "Guinea pigs, rabbits, and a parade of petting-zoo friends star in this pre-level nonfiction reader. A motivating, gentle on-ramp for children just beginning to read about the real world."}, {"id": 2843, "title": "DK Super Readers A Day at the Petting Zoo PK", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-a-day-at-the-petting-zoo-pk-ibc-1582/", "take": "Meet the petting zoo animals in a carefully leveled DK nonfiction reader built to set beginning readers up to succeed. Simple, engaging, and genuinely useful for building early reading confidence with real-world content."}, {"id": 2258, "title": "DK Super Readers Dinosaur Dinners Level 2", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-dinosaur-dinners-level-2/", "take": "A carefully leveled nonfiction reader about what dinosaurs ate and how they hunted, from T. rex's bone-crushing teeth to gentle Brachiosaurus's greens. Dinosaur enthusiasm doing what it does best: powering up reading skills."}, {"id": 2166, "title": "DK Super Readers: Explore the Coral Reef/Explora el arrecife de coral Level 1", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-explore-the-coral-reef-explora-el-arrecife-de-coral-level-1/", "take": "Beginning readers explore a coral reef in English and Spanish, meeting the fish and sea creatures who live there. Carefully leveled bilingual nonfiction from DK; a reading confidence-builder that doubles as a science lesson."}, {"id": 2167, "title": "DK Super Readers: Meet the Dinosaurs/Conoce los dinosaurios Level Pre-K", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-meet-the-dinosaurs-conoce-los-dinosaurios-level-pre-k/", "take": "Dinosaurs for the Pre-K crowd, in English and Spanish. DK's leveled bilingual nonfiction gives the youngest readers real facts in language sized just for them. An easy win for the dinosaur-obsessed."}, {"id": 2165, "title": "DK Super Readers: Ponies and Horses/ Ponis y caballos  Level 1", "url": "https://store.ignatiusbookfairs.com/dk-super-readers-ponies-and-horses-ponis-y-caballos-level-1/", "take": "A Level 1 English-Spanish reader all about ponies and horses. DK's leveled nonfiction is carefully Lexile-graded so beginning readers succeed rather than struggle, and the subject sells itself. A solid confidence-builder for animal lovers."}, {"id": 2514, "title": "Do Great Things for God: C.S. Lewis: The Boy Who Loved to Ask Big Questions", "url": "https://store.ignatiusbookfairs.com/do-great-things-for-god-c-s-lewis-the-boy-who-loved-to-ask-big-questions/", "take": "A picture-book biography of C.S. Lewis for the Do Great Things for God series, tracing how a curious boy's big questions led to Narnia and a life of faith. Lovely for young readers who already love the wardrobe."}, {"id": 2515, "title": "Do Great Things for God: Queen Elizabeth II: The Queen Who Chose to Serve", "url": "https://store.ignatiusbookfairs.com/do-great-things-for-god-queen-elizabeth-ii-the-queen-who-chose-to-serve/", "take": "This children's biography follows Princess Elizabeth from an unexpected path to the throne through the longest reign in British history, highlighting the Christian faith that underpinned it. An inspiring story of duty and quiet, lifelong service."}, {"id": 1912, "title": "Do No Harm", "url": "https://store.ignatiusbookfairs.com/do-no-harm/", "take": "A British ER doctor saves a woman's life, and stands trial for it, because her Living Will said let her die. A courtroom novel about conscience, medicine, and English law that raises questions worth arguing about. Timely adult fiction."}, {"id": 1591, "title": "DOCAT Study Guide", "url": "https://store.ignatiusbookfairs.com/docat-study-guide/", "take": "A practical companion for working through DOCAT in a classroom, home, or small group — laid out in a youthful, graphic-heavy style designed to spark reflection and real discussion of Catholic Social Teaching. Useful for any group leader."}, {"id": 1612, "title": "DOCAT: What to Do?", "url": "https://store.ignatiusbookfairs.com/docat-what-to-do/", "take": "The practical follow-up to YOUCAT: Catholic Social Teaching for young people in the same popular question-and-answer style, drawing on Scripture and the Catechism. For teens asking what building a civilization of love actually looks like on Monday morning."}, {"id": 970, "title": "Dolphin", "url": "https://store.ignatiusbookfairs.com/dolphin/", "take": "Follows a baby bottle-nosed dolphin through its first six months — what it eats, how it evades sharks and killer whales. Straightforward marine science for kids fascinated by these intelligent mammals."}, {"id": 1736, "title": "Dolphin Adventure: One Diver's Incredible Undersea Experience", "url": "https://store.ignatiusbookfairs.com/dolphin-adventure-one-divers-incredible-undersea-experience/", "take": "A real-life diving story: eighty feet down off Florida, three wild dolphins approach Wayne Grover — and the baby has a fishhook embedded in its back. An irresistible animal-rescue account for young ocean lovers."}, {"id": 974, "title": "Dolphin Talk: Whistles, Clicks, and Clapping", "url": "https://store.ignatiusbookfairs.com/dolphin-talk-whistles-clicks-and-clapping/", "take": "Dolphins whistle, click, and clap to tell each other who they are and where they are. Clear science plus included activities that let kids explore how underwater communication actually works."}, {"id": 1075, "title": "Don't Throw It, Grow It! 68 Window Plants", "url": "https://store.ignatiusbookfairs.com/dont-throw-it-grow-it-68-window-plants/", "take": "Mango pits, gingerroot, pomegranate seeds — 68 kitchen scraps you can coax into thriving window plants, with clear illustrations and step-by-step instructions. A clever, low-cost gateway to gardening hiding in your refrigerator."}, {"id": 2265, "title": "Double Fudge", "url": "https://store.ignatiusbookfairs.com/double-fudge/", "take": "Fudge is printing his own Fudge Bucks and planning to buy the world in this funny, family-centered entry in Judy Blume's classic series. Note: we do advise parents to use their judgment with Blume's wider catalog; this one is lighthearted fun."}, {"id": 2873, "title": "Dr Seuss: Sing the 50 States", "url": "https://store.ignatiusbookfairs.com/dr-seuss-sing-the-50-states/", "take": "A newly discovered, never-before-seen Dr. Seuss picture book that sings through all 50 states with help from the Cat in the Hat, celebrating America's 250th anniversary. Geography, rhyme, and Seuss - an easy crowd-pleaser."}, {"id": 1867, "title": "Dracula", "url": "https://store.ignatiusbookfairs.com/dracula/", "take": "Stoker's 1897 original, told through journals and letters as Jonathan Harker's business trip to Transylvania becomes a vampiric assault on Victorian London. Slower and stranger than the movies, and far better. For mature readers who like a long shiver."}, {"id": 2818, "title": "Dragon Post", "url": "https://store.ignatiusbookfairs.com/dragon-post-ibc-1547/", "take": "Alex finds a dragon under the stairs and writes for help - and readers open real envelopes to read the hilarious replies from the fire brigade, the butcher, and more. Interactive letter-book fun kids will replay often."}, {"id": 2789, "title": "Dragonspell", "url": "https://store.ignatiusbookfairs.com/dragonspell-ibc-1573/", "take": "A slave girl, a dragon egg, and a destiny she doesn't feel ready for. Donita K. Paul's beloved Christian fantasy delivers real adventure with faith woven into its bones — great for Wingfeather graduates."}, {"id": 2455, "title": "Drinking with Your Patron Saints", "url": "https://store.ignatiusbookfairs.com/drinking-with-your-patron-saints/", "take": "Michael Foley pairs a patron saint with a fitting drink — Saint Matthew gets an Income Tax cocktail, naturally. A witty, well-researched gift book for Catholic adults who like their hagiography with a twist. Strictly for the grown-ups' table."}, {"id": 1854, "title": "E-Wallet: $10", "url": "https://store.ignatiusbookfairs.com/e-wallet-10/", "take": "Not a book, but a smart way to shop for them. Load ten dollars of credit, assign it to your children, and they can spend it at any live fair. No cash in backpacks, no lost envelopes."}, {"id": 2016, "title": "E-Wallet: $25", "url": "https://store.ignatiusbookfairs.com/e-wallet-25/", "take": "The practical pick for fair day: load 25 dollars, assign it to one or more children, and they shop the live fair without cash changing hands. Volunteers see the balance instantly, so checkout stays quick."}, {"id": 2017, "title": "E-Wallet: $50", "url": "https://store.ignatiusbookfairs.com/e-wallet-50/", "take": "Fifty dollars of book fair credit, no cash in the backpack. Assign it to one or more children and redeem at any live fair — the checkout volunteer sees the balance instantly. Simple for parents, smooth for coordinators."}, {"id": 1673, "title": "Easy Crossword Puzzles", "url": "https://store.ignatiusbookfairs.com/easy-crossword-puzzles/", "take": "Twenty-four easy crosswords with picture hints and pages to color, built around familiar scenes like in my room and in winter. A quiet, inexpensive way to grow vocabulary and spelling skills — solutions included."}, {"id": 2856, "title": "Easy Knitting for Kids", "url": "https://store.ignatiusbookfairs.com/easy-knitting-for-kids-ibc-1600/", "take": "Thirty-five beginner-friendly knitting projects with step-by-step artwork, difficulty ratings, and a full techniques section covering yarns, needles, and stitches. A genuinely usable craft book that lets kids build skills project by project."}, {"id": 2796, "title": "Echo Mountain", "url": "https://store.ignatiusbookfairs.com/echo-mountain-ibc-1589/", "take": "After the Depression takes everything, Ellie's family starts over on a wild mountain — and Ellie becomes a healer. Lyrical, brave historical fiction that earned every one of its best-of-year nods."}, {"id": 1628, "title": "Edmund Campion: Hero of God's Underground", "url": "https://store.ignatiusbookfairs.com/edmund-campion-hero-of-gods-underground/", "take": "The dramatic Vision Books account of St. Edmund Campion: the most celebrated young scholar of his day, nearly Archbishop of Canterbury, who returned to his Catholic faith and died a martyr in Elizabethan England. Courage rendered vivid for young readers."}, {"id": 2241, "title": "Egyptology: Search for the Tomb of Osiris", "url": "https://store.ignatiusbookfairs.com/egyptology-search-for-the-tomb-of-osiris/", "take": "A New York Times bestseller styled as Miss Emily Sands' 1926 expedition journal up the Nile, with a novelty element on every spread. Fact and fantasy tangle irresistibly for kids caught up in the allure of ancient Egypt."}, {"id": 1871, "title": "Eight Ways of Loving God", "url": "https://store.ignatiusbookfairs.com/eight-ways-of-loving-god/", "take": "If people have love languages, does God? Jeanette Flood answers from the life and teachings of Jesus, with a conversational style, good humor, and stories from her own life. Warm, fresh spiritual reading for adults."}, {"id": 2170, "title": "El Gran Libro de Beginner Books en espanol de Dr. Seuss", "url": "https://store.ignatiusbookfairs.com/el-gran-libro-de-beginner-books-en-espanol-de-dr-seuss/", "take": "Six classic Dr. Seuss Beginner Books, translated into rhyming Spanish and collected in one sturdy hardcover for the first time. Ideal for Spanish speakers ages 3-7 and second-language learners, and the rhymes still bounce."}, {"id": 2493, "title": "Electrical Wizard: How Nikola Tesla Lit Up the World", "url": "https://store.ignatiusbookfairs.com/electrical-wizard-how-nikola-tesla-lit-up-the-world/", "take": "A picture-book biography of Nikola Tesla, from lighting the Chicago World's Fair to harnessing Niagara Falls, rivalry with Edison included. Kirkus praised it for encouraging budding scientists, and it makes the creative process genuinely exciting for kids."}, {"id": 1559, "title": "Elephant Run", "url": "https://store.ignatiusbookfairs.com/elephant-run/", "take": "Bombed out of London in 1941, Nick is sent to the family teak plantation in Burma — just as Japanese soldiers invade and his father is taken prisoner. A high-stakes World War II survival adventure with elephants at its heart."}, {"id": 1884, "title": "Elijah in Jerusalem", "url": "https://store.ignatiusbookfairs.com/elijah-in-jerusalem/", "take": "The sequel to Father Elijah sends the priest into Jerusalem to confront a powerful politician who may be the Antichrist. O'Brien's apocalyptic storytelling, carried by a hero shaped by the Holocaust, Carmel, and conversion. For adult readers."}, {"id": 2459, "title": "Encyclopedia Brown and His Best Cases Ever", "url": "https://store.ignatiusbookfairs.com/encyclopedia-brown-and-his-best-cases-ever/", "take": "Fifteen of Encyclopedia Brown's best mysteries, hand-picked from across the whole series, plus a never-before-published article by Donald Sobol on why he wrote them. Solve-along fun that has hooked young detectives for generations."}, {"id": 1034, "title": "Encyclopedia Brown Box Set (4 books)", "url": "https://store.ignatiusbookfairs.com/encyclopedia-brown-box-set-4-books/", "take": "The first four cases for the boy detective who lets readers crack the mysteries alongside him. Short, clever puzzles that make kids feel smart — a reliable gateway box set for aspiring sleuths and reluctant readers alike."}, {"id": 2813, "title": "Escape from Mr. Lemoncello's Library: The Graphic Novel", "url": "https://store.ignatiusbookfairs.com/escape-from-mr-lemoncellos-library-the-graphic-novel-ibc-1627/", "take": "The bestselling puzzle-filled library escape, now a full-color interactive graphic novel where readers solve the clues alongside the characters. Booklist compared its puzzle-master to Willy Wonka, and the comparison fits."}, {"id": 1467, "title": "Eucharistic Adoration Coloring Book", "url": "https://store.ignatiusbookfairs.com/eucharistic-adoration-coloring-book/", "take": "Katherine Sotnik's detailed drawings cover symbols of the Eucharist, saints devoted to it, and the vessels of the liturgy, with names and terms explained along the way. A coloring book that genuinely catechizes while it occupies busy hands."}, {"id": 1013, "title": "Every Autumn Comes the Bear", "url": "https://store.ignatiusbookfairs.com/every-autumn-comes-the-bear/", "take": "Each autumn, a bear appears in the woodland behind a family farm. The description keeps it simple, and so does the book's premise — a quiet seasonal nature story from Jim Arnosky."}, {"id": 1872, "title": "Exogenesis", "url": "https://store.ignatiusbookfairs.com/exogenesis/", "take": "A dystopian novel set in Lantua, a glittering metropolis of drones, social-credit algorithms, and children grown in artificial wombs, until rebellion stirs. Thoughtful science fiction for older readers who want their thrillers to ask real questions."}, {"id": 2283, "title": "Exploring Space: Learn, Press-Out & Play", "url": "https://store.ignatiusbookfairs.com/exploring-space-learn-press-out-play/", "take": "How big is the universe? What is a space station? This interactive activity book answers in bite-size chunks, then hands kids 150 stickers and ten press-out models — rocket included — to build. Great for hands-on budding astronauts."}, {"id": 1979, "title": "Eyelike Stickers: Baby Animals", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-baby-animals/", "take": "Roly-poly pandas, fluffy bunnies, fuzzy owlets — full-color photographic stickers of baby animals that restick without tearing. Pure, portable cuteness for kids who decorate everything they own, and forgiving enough to survive constant redecorating."}, {"id": 1977, "title": "Eyelike Stickers: Christmas", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-christmas/", "take": "Santa hats, reindeer, ornaments, cookies, and an old-fashioned sleigh — restickable photo-style stickers that survive being peeled and placed again and again. An easy stocking stuffer that keeps little hands happily decorating all through December."}, {"id": 1975, "title": "Eyelike Stickers: Dinosaurs", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-dinosaurs/", "take": "Photorealistic dinosaur stickers — T-rex, triceratops, pterodactyl, and more — that peel off and restick without tearing. Cheerful, screen-free fun for dino-obsessed kids, equally at home on notebooks, windows, and lunch boxes."}, {"id": 1544, "title": "Eyelike Stickers: Horses", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-horses/", "take": "Over 400 reusable photographic stickers of horses in action, plus cowboy hats, horseshoes, and ribbons to round out the scene. For the horse-loving kid, this is hours of mixing, matching, and trading — no reading required."}, {"id": 958, "title": "Eyelike Stickers: Space", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-space/", "take": "Four hundred reusable space stickers with strikingly lifelike detail, built to peel and re-stick without tearing. Less a book than a craft supply — and for sticker-loving kids, that is exactly the appeal."}, {"id": 1978, "title": "Eyelike Stickers: Trucks", "url": "https://store.ignatiusbookfairs.com/eyelike-stickers-trucks/", "take": "Photorealistic trucks, cars, tires, and road signs in restickable form, with glossy illustrated backgrounds inside the covers for staging scenes. Simple, sturdy, screen-free entertainment for vehicle-loving kids — stick, peel, repeat."}, {"id": 1657, "title": "Ezekiel and the Dry Bones", "url": "https://store.ignatiusbookfairs.com/ezekiel-and-the-dry-bones/", "take": "An Arch Book telling Ezekiel's vision of the dry bones in easy-to-read rhyme, with a helpful letter to adults for teaching the story. A trusted, engaging way to put real Scripture into little hands."}, {"id": 1771, "title": "Faelan and the Miracle Machine", "url": "https://store.ignatiusbookfairs.com/faelan-and-the-miracle-machine/", "take": "A runaway slave in ancient Alexandria becomes apprentice to Heron, the real-life mathematician and inventor. Historical fiction that folds science and invention into an adventure about finding a new identity and a brighter future — a setting young readers rarely see."}, {"id": 2773, "title": "Fancy Nancy and the Too Loose Tooth", "url": "https://store.ignatiusbookfairs.com/fancy-nancy-and-the-too-loose-tooth-ibc-1556/", "take": "Nancy's first loose tooth simply must fall out at school - the nurse's special tooth-holder necklace depends on it. O'Connor and Glasser deliver the familiar Fancy Nancy sparkle around a milestone every child knows."}, {"id": 1384, "title": "Fandex Family Field Guides: Bugs", "url": "https://store.ignatiusbookfairs.com/fandex-family-field-guides-bugs/", "take": "Bugs, kids, and the Fandex format - a natural match. Die-cut cards introduce the Hercules Beetle, the misunderstood Black Widow, the Walking Stick, and more, with the kind of jaw-dropping facts kids repeat at dinner."}, {"id": 2186, "title": "Fandex Kids: Dinosaurs", "url": "https://store.ignatiusbookfairs.com/fandex-kids-dinosaurs/", "take": "Fifty-two cards covering 48 dinosaurs, from the airplane-sized Quetzalcoatlus to the turkey-sized Compsognathus. The flip-through fan format is perfect for fact-hungry kids who would rather browse and share than sit with a chapter book."}, {"id": 2185, "title": "Fandex Kids: Ocean", "url": "https://store.ignatiusbookfairs.com/fandex-kids-ocean/", "take": "Forty-nine ocean creatures on boldly illustrated fan-deck cards: a whale that holds its breath nearly four hours, kelp that grows two feet a day, the living-fossil coelacanth. Browsable fact-food for kids who read in bursts."}, {"id": 1881, "title": "Father Brown and the Ten Commandments", "url": "https://store.ignatiusbookfairs.com/father-brown-and-the-ten-commandments/", "take": "Father Brown mysteries paired with the Ten Commandments, with a twist: the criminal is not always the worst sinner in the story. Chesterton's distinction between crime and sin gives these detective tales unusual depth. Great for discussion."}, {"id": 1878, "title": "Father Brown of the Church of Rome", "url": "https://store.ignatiusbookfairs.com/father-brown-of-the-church-of-rome/", "take": "Ten Father Brown mysteries chosen to show how the little priest's Catholic faith actually helps him solve the crimes. Chesterton brought real wickedness, and real judgment, into the detective story. Wonderful for mystery lovers of any stripe."}, {"id": 1887, "title": "Father Elijah", "url": "https://store.ignatiusbookfairs.com/father-elijah/", "take": "O'Brien's acclaimed apocalyptic novel sends Father Elijah, a Carmelite priest and Holocaust survivor, on a secret Vatican mission touching the ultimate destiny of the Church. Gripping, serious fiction for adults. The kind of thriller that stays with you."}, {"id": 1669, "title": "Father Marquette and the Great Rivers", "url": "https://store.ignatiusbookfairs.com/father-marquette-and-the-great-rivers/", "take": "The Vision series takes ages 9-15 down the Mississippi with Father Marquette and explorer Louis Joliet, braving a river no one had survived to map. Real American history with genuine missionary courage at its center."}, {"id": 2859, "title": "Father Michael McGivney and the Knights of Columbus", "url": "https://store.ignatiusbookfairs.com/father-michael-mcgivney-and-the-knights-of-columbus/", "take": "The first children's chapter book to tell the story of Blessed Michael McGivney, the humble parish priest who founded the Knights of Columbus. Carefully researched, written in an easy-to-read style - an inspiring introduction kids rarely get."}, {"id": 2854, "title": "Father of the Fatherless", "url": "https://store.ignatiusbookfairs.com/father-of-the-fatherless-ibc-1616/", "take": "Father Nelson Baker's remarkable life — businessman turned priest turned father to Buffalo's poorest — in a full-color action-style comic. Catholic heroism kids can actually picture themselves imitating."}, {"id": 1875, "title": "Fatima Mysteries", "url": "https://store.ignatiusbookfairs.com/fatima-mysteries/", "take": "A deep dive into the 1917 apparitions at Fatima, which Pope Benedict XVI insisted still speak to our own crisis of faith. Serious, substantive reading on perhaps the most important private revelations in Church history."}, {"id": 2261, "title": "Fenway and the Bone Thieves (Make Way for Fenway #1)", "url": "https://store.ignatiusbookfairs.com/fenway-and-the-bone-thieves-make-way-for-fenway-1/", "take": "A brand-new bone, sneaky squirrels, and a hiding place so good even Fenway might not find it again. This first Make Way for Fenway chapter book gives emerging readers an easy, funny on-ramp to series reading."}, {"id": 2260, "title": "Fenway and the Frisbee Trick (Make Way for Fenway #2)", "url": "https://store.ignatiusbookfairs.com/fenway-and-the-frisbee-trick-make-way-for-fenway-2/", "take": "Fenway the little dog with the giant personality sees a Frisbee-catching dog and simply must try it — and trying is harder than it looks. Easy reading, lively illustrations, and a lesson in persistence emerging readers will lap up."}, {"id": 2193, "title": "Fig Pudding", "url": "https://store.ignatiusbookfairs.com/fig-pudding/", "take": "Eleven-year-old Cliff narrates a year in his big, loud family of six kids, Christmas to Christmas, in chapters that each work as complete short stories. Hilarious, occasionally poignant, and full of the warmth of a close-knit household."}, {"id": 2246, "title": "Finding Narnia", "url": "https://store.ignatiusbookfairs.com/finding-narnia/", "take": "Before Narnia, there were two brothers: Jack dreaming up knights and talking animals, Warnie imagining trains and technology. This captivating picture book biography shows how the Lewis boys' twin imaginations grew into a magical world."}, {"id": 1138, "title": "Finding Providence: The Story of Roger Williams", "url": "https://store.ignatiusbookfairs.com/finding-providence-the-story-of-roger-williams/", "take": "Roger Williams flees the Massachusetts Bay Colony in winter, trusting God's providence and the Narragansett people for survival - told through his daughter Mary's worried eyes. American history with real human stakes for young readers."}, {"id": 1117, "title": "Finnian and the Seven Mountains Volume 1 Issues 1-4", "url": "https://store.ignatiusbookfairs.com/finnian-and-the-seven-mountains-volume-1-issues-1-4/", "take": "After Vikings kill his parents, Finnian leaves his Irish monastic school to seek a legendary sword said to defeat evil. A faith-infused adventure comic beginning on Skellig Michael, drawn by artists with real Marvel credits."}, {"id": 2025, "title": "Fire of Love: A Historical Novel about Saint John of the Cross", "url": "https://store.ignatiusbookfairs.com/fire-of-love-a-historical-novel-about-saint-john-of-the-cross/", "take": "This historical novel about Saint John of the Cross begins a generation early, with a father who chose love over fortune and paid dearly for it. Rich family drama that grounds a great mystic in a very human story."}, {"id": 1489, "title": "First Date", "url": "https://store.ignatiusbookfairs.com/first-date/", "take": "Addy never auditioned for the reality show where the prize is a prom date with the President's son — and she is doing her best to get eliminated. A light, funny YA premise about an ordinary, scholarship-minded girl thrown into the spotlight."}, {"id": 957, "title": "First Flight: The Story of Tom Tate and the Wright Brothers", "url": "https://store.ignatiusbookfairs.com/first-flight-the-story-of-tom-tate-and-the-wright-brothers/", "take": "A boy named Tom Tate wants a ride on the Wright brothers' flying machine, even though his dad calls it dangerous. A friendly way into the Kitty Hawk story, told from a kid's-eye view of history in the making."}, {"id": 1069, "title": "First Team", "url": "https://store.ignatiusbookfairs.com/first-team/", "take": "Brock knows his strong left arm can earn him the first team — but the coaches have plans of their own for kids from the wrong side of the tracks. Tim Green football drama, a natural pick for Lupica and Gutman fans."}, {"id": 1451, "title": "Florence Nightingale's Nuns", "url": "https://store.ignatiusbookfairs.com/florence-nightingales-nuns/", "take": "The true story of the heroic nuns who served alongside Florence Nightingale's nurses in the Crimean War, told for young readers in the Vision Books tradition. Real history, real sacrifice — courage in its unglamorous, hard-working form."}, {"id": 2257, "title": "Flower Fairies Alphabet Coloring Book", "url": "https://store.ignatiusbookfairs.com/flower-fairies-alphabet-coloring-book/", "take": "Twenty-four popular Flower Fairies to color, arranged to teach the alphabet and flower names along the way (no U or X fairy, charmingly enough). A gentle two-birds pick for young colorers learning their letters."}, {"id": 1051, "title": "Fly Boy", "url": "https://store.ignatiusbookfairs.com/fly-boy/", "take": "Seventeen-year-old Robbie lies his way into the Royal Canadian Air Force while his Spitfire-pilot father sits in a POW camp. A World War II flying story with real stakes and real disappointments for readers who love wartime adventure."}, {"id": 1066, "title": "Follow the Drinking Gourd", "url": "https://store.ignatiusbookfairs.com/follow-the-drinking-gourd/", "take": "A peg-leg sailor teaches enslaved workers a song encoding the route north, and one family follows it to freedom. Bold, primitive-style paintings carry this compelling Underground Railroad story with rhythmic, memorable energy."}, {"id": 1057, "title": "Football Genius", "url": "https://store.ignatiusbookfairs.com/football-genius/", "take": "Troy can predict any football play before it happens — and his single mom just landed a job with the Atlanta Falcons. Former NFL player Tim Green delivers insider suspense; an easy handoff for Mike Lupica fans."}, {"id": 1686, "title": "Forget Not Love: The Passion of Maximilian Kolbe", "url": "https://store.ignatiusbookfairs.com/forget-not-love-the-passion-of-maximilian-kolbe/", "take": "Frossard, with Vatican documentation and John Paul II's encouragement, chronicles Maximilian Kolbe — the Polish Franciscan who volunteered to die in a fellow prisoner's place at Auschwitz. Sobering, powerful reading about a martyr of charity."}, {"id": 1603, "title": "Framed!", "url": "https://store.ignatiusbookfairs.com/framed/", "take": "Twelve-year-old Florian Bates and his Theory of All Small Things land him on the FBI Director's speed dial — and several criminals' most-wanted lists. A hilarious start to a middle grade mystery series with genuine deductive fun."}, {"id": 1472, "title": "Francis and Clare: Saints of Assisi", "url": "https://store.ignatiusbookfairs.com/francis-and-clare-saints-of-assisi/", "take": "Helen Homan tells Francis and Clare of Assisi together, from shared childhood streets through radical conversion and the founding of the Franciscans and Poor Clares. Two Gospel-soaked lives, one absorbing Vision Book for young readers."}, {"id": 1541, "title": "Francis: The Poor Man of Assisi", "url": "https://store.ignatiusbookfairs.com/francis-the-poor-man-of-assisi/", "take": "From The Life of a Saint series, this picture-book life of Francis follows him from joyful youth through war, illness, and a dramatic encounter with God into radical poverty. Vivid pictures on every page make him a brother to lepers, the poor, and animals."}, {"id": 1869, "title": "Frankenstein", "url": "https://store.ignatiusbookfairs.com/frankenstein/", "take": "Shelley's novel may be the most misread classic of the nineteenth century, and this edition pushes back on the fashionable misreadings to take the book on its own terms. A strong pick for serious high school literature study."}, {"id": 1018, "title": "Friendly Gables", "url": "https://store.ignatiusbookfairs.com/friendly-gables/", "take": "Two years after Canadian Summer, twins arrive and every Mitchell child must grow in new ways — Joan's first dance, Peter's disastrous fight, Catherine's brush with fire. Family fiction with real charm and real stakes."}, {"id": 894, "title": "Friends Again", "url": "https://store.ignatiusbookfairs.com/friends-again/", "take": "Henry and Emma turn their backs on each other, each carrying a lump of sadness - until forgiveness sets things right. An endearing, beautifully illustrated story that gives children real language for making peace after a quarrel."}, {"id": 1394, "title": "Friendship with Jesus: Pope Benedict XVI Speaks to Children on their First Holy Communion", "url": "https://store.ignatiusbookfairs.com/friendship-with-jesus-pope-benedict-xvi-speaks-to-children-on-their-first-holy-communion/", "take": "Pope Benedict XVI answers real questions from Roman children who had just made their First Communion - profound and simple at once, with Ann Engelhart's lovely illustrations. A beautiful gift for a First Communicant."}, {"id": 2502, "title": "Frindle", "url": "https://store.ignatiusbookfairs.com/frindle/", "take": "Andrew Clements's classic about the boy who renames the pen and starts a word revolution. Frindle is that rare school story that makes kids think about language and creative power — and it's genuinely funny along the way."}, {"id": 2483, "title": "Frog and Toad Together", "url": "https://store.ignatiusbookfairs.com/frog-and-toad-together/", "take": "A Newbery Honor classic about the best kind of friendship. Frog and Toad grow gardens, eat cookies, and are brave together — Arnold Lobel's gentle humor still lands perfectly with early readers, generation after generation."}, {"id": 2779, "title": "Frog and Toad: Four Classic Stories of Friendship", "url": "https://store.ignatiusbookfairs.com/frog-and-toad-four-classic-stories-of-friendship-ibc-1557/", "take": "All four Level 2 Frog and Toad I Can Reads in one volume - Lobel's Caldecott and Newbery Honor-winning duo eating ice cream, finding buttons, waiting for spring. The gentlest, most durable friendship stories in early reading."}, {"id": 1461, "title": "From Caterpillar to Butterfly", "url": "https://store.ignatiusbookfairs.com/from-caterpillar-to-butterfly/", "take": "A caterpillar comes to school in a jar, and the class watches it eat, grow, and emerge as a Painted Lady butterfly. Clear, appealing early-elementary science with research prompts and an identification activity — a classroom natural, in both senses."}, {"id": 2015, "title": "Fuzzy Poster - Jesus", "url": "https://store.ignatiusbookfairs.com/fuzzy-poster-jesus/", "take": "Remember fuzzy posters? This nostalgic 11x14 brings them back with a sacred subject — color it in and Jesus emerges in stained-glass style. A quiet, screen-free activity kids and adults genuinely enjoy."}, {"id": 1440, "title": "Game Over", "url": "https://store.ignatiusbookfairs.com/game-over/", "take": "Rick Dial has survived the MindWar Realm twice; now the terrorist's computerized world has followed him home. Fast-paced techno-thriller action for readers who want stakes, courage, and no easy escapes."}, {"id": 2267, "title": "Gather Round", "url": "https://store.ignatiusbookfairs.com/gather-round/", "take": "Crackle, crinkle, sizzle, pop — a girl and her father build a campfire, and the fire tells its story. A gorgeous, timely picture book from an award-winning illustrator about how gathering together keeps us warm."}, {"id": 2024, "title": "General Escobar's War", "url": "https://store.ignatiusbookfairs.com/general-escobars-war/", "take": "Winner of Spain's Planeta Prize, this historical novel imagines the diary of General Escobar, the Republican Army's highest-ranking officer, as he awaits trial and execution after the Spanish Civil War. Sobering, vivid fiction for mature readers."}, {"id": 1504, "title": "George the Drummer Boy", "url": "https://store.ignatiusbookfairs.com/george-the-drummer-boy/", "take": "The start of the American Revolution from the other side: George is a British drummer boy on the secret night march toward Concord. An I Can Read with vibrant pictures — and a quietly smart way to build historical empathy."}, {"id": 947, "title": "George Washington", "url": "https://store.ignatiusbookfairs.com/george-washington/", "take": "A watercolor-illustrated life of Washington that starts with his ancestors and traces the faith, character, and courage behind the father of our country. A biography for children that treats his trust in God as central rather than incidental."}, {"id": 2485, "title": "Giovanni and the Fava Beans", "url": "https://store.ignatiusbookfairs.com/giovanni-and-the-fava-beans/", "take": "A medieval Sicilian drought, a starving girl, and a boy's change of heart — this picture book tells the origin of the St. Joseph Altar tradition with warmth. A lovely way to connect kids to a beautiful Catholic custom."}, {"id": 2864, "title": "Glitch", "url": "https://store.ignatiusbookfairs.com/glitch/", "take": "Time-traveling enemies Regan and Elliot must break all the rules to set things right in this whirlwind adventure for Gordon Korman fans - with a worthwhile undercurrent about learning from history rather than sanitizing it."}, {"id": 1740, "title": "Glory Stories Coloring Book: Blessed Imelda's First Communion Miracle", "url": "https://store.ignatiusbookfairs.com/glory-stories-coloring-book-blessed-imeldas-first-communion-miracle/", "take": "A coloring-book companion to the Glory Stories audio CD, telling how young Blessed Imelda's First Communion miracle helped lower the age for receiving. A gentle way to catechize little ones on the Real Presence."}, {"id": 2505, "title": "Go Fishes and Loaves Card Game", "url": "https://store.ignatiusbookfairs.com/go-fishes-and-loaves-card-game/", "take": "A card game that teaches the Eucharist through play, with beautifully illustrated cards depicting its key elements and symbols. A clever pick for Catholic classrooms and family game nights — catechesis that doesn't feel like homework."}, {"id": 2767, "title": "Goat Is the G.O.A.T.", "url": "https://store.ignatiusbookfairs.com/goat-is-the-goat-ibc-1634/", "take": "Goat is declared the G.O.A.T. - but he's not the fastest, strongest, or even the best spitter, so what makes him great? A funny, tender story about self-worth that lands its answer just when Goat needs it."}, {"id": 1625, "title": "God's Fire for Elijah", "url": "https://store.ignatiusbookfairs.com/gods-fire-for-elijah/", "take": "Elijah's showdown proving there is but one true God, told in the colorful Arch Books way: a complete Bible story in engaging rhyme for ages 5 to 9. Biblically careful, affordable, and genuinely fun to read aloud."}, {"id": 2750, "title": "God's Great Love", "url": "https://store.ignatiusbookfairs.com/gods-great-love-ibc-1568/", "take": "Glenys Nellist's rhyming bedtime blessing wraps little ones in Ephesians 3:18 — God's love is wide, long, high, and deep, every moment of every day. A lyrical, reassuring last word before lights out."}, {"id": 991, "title": "Going to Town", "url": "https://store.ignatiusbookfairs.com/going-to-town/", "take": "Laura has never been to town, so Pa's surprise trip is everything she imagined and more. A sweet My First Little House adaptation about how big a small adventure can feel."}, {"id": 986, "title": "Going West", "url": "https://store.ignatiusbookfairs.com/going-west/", "take": "The My First Little House series opens with Laura's family packing the covered wagon and leaving the Big Woods. Renee Graef's illustrations, based on Garth Williams' classic art, make this a lovely first taste of Wilder."}, {"id": 1534, "title": "Good Books, Good Times!", "url": "https://store.ignatiusbookfairs.com/good-books-good-times/", "take": "Lee Bennett Hopkins gathers witty, whimsical poems celebrating the joy of reading itself — Prelutsky, Kuskin, and Lobel among the contributors — with Harvey Stevenson's wacky illustrations. A natural read-aloud for library corners and the first week of school."}, {"id": 1055, "title": "Goodbye, Vietnam", "url": "https://store.ignatiusbookfairs.com/goodbye-vietnam/", "take": "When soldiers come for her father and grandmother, Mai's family slips away by night through the Mekong Delta toward the sea. A riveting, haunting refugee story built on determination, hope, love, and courage."}, {"id": 898, "title": "Grandma Taught Me to Love Mary", "url": "https://store.ignatiusbookfairs.com/grandma-taught-me-to-love-mary/", "take": "A charming bilingual English-Spanish book inspired by a real grandmother, Miledys Marte, whose devotion to Mary taught her grandchildren that Our Lady leads us to Jesus. Warm, personal, and a lovely fit for families passing faith between generations."}, {"id": 1014, "title": "Grandma's Best Stories", "url": "https://store.ignatiusbookfairs.com/grandmas-best-stories/", "take": "Seven gentle stories for family reading — a deer who reads to forest animals, a bear making his first friends, a giant carrying his house. Warm-hearted bedtime fare about kindness and friendship."}, {"id": 1874, "title": "Great Expectations", "url": "https://store.ignatiusbookfairs.com/great-expectations/", "take": "Pip gains a fortune and loses illusions, trading improved fortunes for hard-won wisdom. This edition reads Dickens the way Pope John Paul I did, as books filled with love for the poor and warm with humanity. A rich classroom choice."}, {"id": 1506, "title": "Great Men of the New Testament", "url": "https://store.ignatiusbookfairs.com/great-men-of-the-new-testament/", "take": "Fr. Jude Winkler introduces the significant men of the New Testament — Joseph, John the Baptist, and Jesus himself among them — in short explanations with vibrant full-color art. A sturdy St. Joseph Picture Book for parish and classroom shelves."}, {"id": 890, "title": "Great Missionaries Throughout the Ages", "url": "https://store.ignatiusbookfairs.com/great-missionaries-throughout-the-ages/", "take": "Fifteen missionaries from Paul the Apostle to Junipero Serra to Lucille Mathevon, with maps, historical notes, and handsome illustrations. Adventure stories that happen to be true - people who crossed the world, often at real risk, to share the Gospel."}, {"id": 1111, "title": "Green Eggs and Ham", "url": "https://store.ignatiusbookfairs.com/green-eggs-and-ham/", "take": "Sam-I-Am's relentless breakfast campaign, in signature Seuss rhyme. Few books do more with fewer words — beginning readers chant it, memorize it, and before long are reading it entirely by themselves."}, {"id": 2129, "title": "Green Ember II: Ember Falls", "url": "https://store.ignatiusbookfairs.com/green-ember-ii-ember-falls/", "take": "War comes to the rabbit resistance as Morbin Blackhawk threatens everything, and Heather and Picket are thrust into pivotal roles. The second Green Ember book raises the stakes while keeping the series' earnest, hopeful heart."}, {"id": 2132, "title": "Green Ember III: Ember Rising", "url": "https://store.ignatiusbookfairs.com/green-ember-iii-ember-rising/", "take": "Heather and Picket go into enemy territory, carrying the flame of the cause through the darkness of Morbin's shadow. The third Green Ember book is the series at its most harrowing — and its most stirring."}, {"id": 2136, "title": "Green Ember IV: Ember's End", "url": "https://store.ignatiusbookfairs.com/green-ember-iv-embers-end/", "take": "The finale: Heather and Picket face their tyrannical foes one last time as the rabbits of Natalia battle for survival and the hope of the Mended Wood. A conclusion that honors everything the series promised."}, {"id": 1571, "title": "Greg's Microscope", "url": "https://store.ignatiusbookfairs.com/gregs-microscope/", "take": "Greg turns his new microscope on ordinary things around the house and makes genuinely fascinating discoveries. An accurate, entertaining pick for beginning independent readers — the kind of science book that sends kids off to investigate for themselves."}, {"id": 2504, "title": "Grimm's Fairy Tales: The Illustrated Just-for-Kids", "url": "https://store.ignatiusbookfairs.com/grimm-s-fairy-tales-the-illustrated-just-for-kids/", "take": "The Brothers Grimm retold just for kids: abridged, freshly illustrated, and just the right amount of scary while staying true to the originals. A handsome way to hand children the fairy tales everything else is built on."}, {"id": 1825, "title": "Guadalupe and Juan Diego Mini Puzzle", "url": "https://store.ignatiusbookfairs.com/guadalupe-and-juan-diego-mini-puzzle/", "take": "A mini puzzle picturing Our Lady of Guadalupe and St. Juan Diego. Small enough for a quiet-time basket or a travel bag, and a gentle way to keep a beloved story in little hands."}, {"id": 1899, "title": "Guadalupe Mysteries", "url": "https://store.ignatiusbookfairs.com/guadalupe-mysteries/", "take": "Our Lady of Guadalupe draws millions of pilgrims a year and has intrigued scientists across many disciplines. This substantive volume explores the apparitions, the devotion, and the mystery. Rich reading for anyone drawn to her story."}, {"id": 1877, "title": "Gulliver's Travels", "url": "https://store.ignatiusbookfairs.com/gullivers-travels/", "take": "Swift's great satire follows hopelessly modern Gulliver through misadventures that skewer the Enlightenment's worship of science and neglect of philosophy and theology. Funnier and sharper than its reputation as a children's story suggests. Ideal for older students."}, {"id": 1910, "title": "Habits for a Healthy Marraige", "url": "https://store.ignatiusbookfairs.com/habits-for-a-healthy-marraige/", "take": "A psychiatrist with forty years of experience names twelve common marital conflicts and pairs each with a virtue-building habit, drawing on positive psychology. Practical, structured help for Catholic couples who want to work on it, not just talk about it."}, {"id": 1507, "title": "Half Magic", "url": "https://store.ignatiusbookfairs.com/half-magic/", "take": "Jane's found coin grants wishes — but only by half, with gloriously complicated results for four bored siblings. Book one of a classic fantasy series praised by Newbery winner Jack Gantos; witty, inventive, and wonderful read-aloud material for middle graders."}, {"id": 1883, "title": "Hamlet", "url": "https://store.ignatiusbookfairs.com/hamlet/", "take": "Arguably Shakespeare's finest play, and one of the most misunderstood. This critical edition digs into what \"to be\" actually means, with essays from serious scholars. A strong companion for students tackling Hamlet for the first time."}, {"id": 1721, "title": "Hand, Hand, Fingers, Thumb", "url": "https://store.ignatiusbookfairs.com/hand-hand-fingers-thumb/", "take": "Al Perkins' drumming monkeys, in sturdy board-book form, teach babies and toddlers their hands, fingers, and thumbs in rollicking rhyme. Fair warning: parents end up drumming and humming along too."}, {"id": 1529, "title": "Heart of a Shepherd", "url": "https://store.ignatiusbookfairs.com/heart-of-a-shepherd/", "take": "When his father's reserve unit ships to Iraq, Brother must help his grandparents keep the ranch exactly as Dad left it. Rosanne Parry's tender coming-of-age story about duty, hope, and discovering a true calling — quiet in the best way."}, {"id": 1803, "title": "Hearts of the Holy Family Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/hearts-of-the-holy-family-vinyl-sticker/", "take": "A vinyl sticker honoring the hearts of Jesus, Mary, and Joseph. A small devotional image for a notebook or water bottle — an easy way to keep the Holy Family in view through an ordinary day."}, {"id": 2778, "title": "Heir to the Empire: Star Wars Legends (The Thrawn Trilogy): V 1", "url": "https://store.ignatiusbookfairs.com/heir-to-the-empire-star-wars-legends-the-thrawn-trilogy-v-1-ibc-1572/", "take": "The novel that revived Star Wars and introduced Grand Admiral Thrawn — still the gold standard of the Legends era. For teen (and parent) fans, this is where the post-trilogy story truly begins."}, {"id": 1025, "title": "Henry and Ribsy", "url": "https://store.ignatiusbookfairs.com/henry-and-ribsy/", "take": "Henry vows to stick up for Ribsy, even as the mutt terrorizes the garbage man and gobbles Ramona's ice cream cone. Cleary's humor and heart, built on the sturdy bond between a boy and his troublesome dog."}, {"id": 1026, "title": "Henry Huggins", "url": "https://store.ignatiusbookfairs.com/henry-huggins/", "take": "Beverly Cleary's very first novel: an average boy, a stray dog with a nose for mischief, and the question of what happens when Ribsy's original owner turns up. Still instantly charming after all these years."}, {"id": 1428, "title": "Here Comes McBroom!", "url": "https://store.ignatiusbookfairs.com/here-comes-mcbroom/", "take": "More tall-tale adventures of Josh McBroom, where corn grows so fast you had better step aside and words freeze solid in midair. Sid Fleischman-style farm exaggeration that makes young readers laugh out loud."}, {"id": 2133, "title": "Here We All Are (26 Fairmount Avenue Series #2)", "url": "https://store.ignatiusbookfairs.com/here-we-all-are-26-fairmount-avenue-series-2/", "take": "The follow-up to a Newbery Honor book finds young Tomie and family settling into the new house on Fairmount Avenue. Charming, lively, and illustrated in dePaola's trademark style — gentle autobiographical storytelling for young readers."}, {"id": 2227, "title": "Hike", "url": "https://store.ignatiusbookfairs.com/hike/", "take": "A father and child wake before dawn, head into the mountains, and come home feeling alive and closer than ever. Told in detail-rich panels, this quiet celebration of nature makes you want to lace up your boots."}, {"id": 2863, "title": "Hilo Book 1: The Boy Who Crashed to Earth", "url": "https://store.ignatiusbookfairs.com/hilo-book-1-the-boy-who-crashed-to-earth/", "take": "D.J. and Gina are totally ordinary kids; Hilo fell from space. A hilarious graphic novel series about friendship, acceptance, and space robots - the New York Times bestseller even Dav Pilkey cheers for. Start reluctant readers here."}, {"id": 1755, "title": "His Grace is Enough", "url": "https://store.ignatiusbookfairs.com/his-grace-is-enough/", "take": "A rhyming, illustrated way to explain grace: Jesus offers forgiveness, and our mistakes are not the end of the story. A tender read-aloud for helping children run to God rather than hide when they mess up."}, {"id": 2394, "title": "History Smashers: Titanic", "url": "https://store.ignatiusbookfairs.com/history-smashers-titanic/", "take": "Was the Titanic ever really called unsinkable? Kate Messner smashes the myths with sidebars, photos, and graphic panels in this fun, fact-checking history. A natural pick for I Survived and Hazardous Tales fans."}, {"id": 2212, "title": "Hold This!", "url": "https://store.ignatiusbookfairs.com/hold-this/", "take": "Mika keeps handing her father every treasure she finds on their woodland walk; he keeps urging her to carry what she can. A tender father-daughter picture book about nature, small stumbles, and what the real treasure turns out to be."}, {"id": 1484, "title": "Holy Family Coloring Book", "url": "https://store.ignatiusbookfairs.com/holy-family-coloring-book/", "take": "Line drawings based on great masters' paintings of Jesus, Mary, and Joseph, each paired with a quotation from Scripture. A quiet-time activity that introduces children to the Holy Family through genuinely beautiful art."}, {"id": 2508, "title": "Holy Family Hearts Mini Puzzle", "url": "https://store.ignatiusbookfairs.com/holy-family-hearts-mini-puzzle/", "take": "A 48-piece mini puzzle celebrating the love and unity of the Holy Family. Challenging enough to reward young puzzlers, and a simple, sweet way to bring a devotion into playtime. Handy for quiet bags and rainy afternoons."}, {"id": 2161, "title": "Holy Family Magnetic Bookmarks", "url": "https://store.ignatiusbookfairs.com/holy-family-magnetic-bookmarks/", "take": "Magnetic bookmarks featuring the Holy Family: a simple, useful little Catholic gift for the readers in your life. The kind of small, sweet extra that ends up marking pages in every book in the house."}, {"id": 2160, "title": "Holy Men Magnetic Bookmarks", "url": "https://store.ignatiusbookfairs.com/holy-men-magnetic-bookmarks/", "take": "Six magnetic bookmarks featuring custom Catholic art of inspiring male saints. Practical, sturdy, and a painless way to keep holy company tucked into schoolbooks and novels. An easy gift for the boys and men on your list."}, {"id": 889, "title": "Holy Mysteries", "url": "https://store.ignatiusbookfairs.com/holy-mysteries/", "take": "Twelve inexplicable cases from Catholic history - the dancing sun at Fatima, Eucharistic miracles, the Shroud of Turin - investigated with curiosity rather than credulity. Exactly the kind of intriguing book that hooks kids who love a good mystery."}, {"id": 1517, "title": "Holy Name of Jesus Coloring Book", "url": "https://store.ignatiusbookfairs.com/holy-name-of-jesus-coloring-book/", "take": "Classic images of Christ drawn from famous artworks, each paired with one of his Holy Names — King of Glory, Author of Life, Strength of Martyrs. A devotional coloring book with unusual richness in its captions."}, {"id": 2230, "title": "Home of the Brave", "url": "https://store.ignatiusbookfairs.com/home-of-the-brave/", "take": "Katherine Applegate tells the story of Kek, who arrives from Africa having lost nearly everything, and meets American snow, ice, and uncertainty. A beautifully wrought middle grade novel about an immigrant's road from hardship to hope."}, {"id": 1437, "title": "Homeless Bird", "url": "https://store.ignatiusbookfairs.com/homeless-bird/", "take": "Gloria Whelan's National Book Award winner follows thirteen-year-old Koly, betrayed by her arranged marriage in India, as she dares to forge her own future. Hand it to middle schoolers who loved A Long Walk to Water."}, {"id": 1525, "title": "Honey for a Child's Heart", "url": "https://store.ignatiusbookfairs.com/honey-for-a-childs-heart/", "take": "Gladys Hunt's modern classic — over 250,000 copies sold — guides parents in choosing the best books for children ages 0-12 and raising genuine readers. Less a list than a whole philosophy of family reading, with the lists included too."}, {"id": 2284, "title": "Hooray for Anna Hibiscus!", "url": "https://store.ignatiusbookfairs.com/hooray-for-anna-hibiscus/", "take": "Anna Hibiscus lives in amazing Africa with more family than she can count, and this second illustrated chapter book follows her through solos, hair-braiding day escapes, and hide-and-seek. Atinuke's modern Nigeria setting is warm and engaging."}, {"id": 2099, "title": "Horse Diaries #1: Elska", "url": "https://store.ignatiusbookfairs.com/horse-diaries-1-elska/", "take": "Elska, a silver dapple Icelandic filly, tells her own story — carefree summers, farmyard winters, and the powerful neighbor whose attention changes everything. A gentle entry point to the Horse Diaries series for young horse lovers."}, {"id": 2103, "title": "Horse Diaries #2: Bell's Star", "url": "https://store.ignatiusbookfairs.com/horse-diaries-2-bells-star/", "take": "Vermont, the 1850s: Bell's Star, a Morgan colt bred for hard work, longs to run free — until helping rescue a runaway slave girl changes what freedom means to him. Horse story and history lesson in one."}, {"id": 2107, "title": "Horse Diaries #3: Koda", "url": "https://store.ignatiusbookfairs.com/horse-diaries-3-koda/", "take": "Koda, a bay quarter horse, narrates his own journey west on the Oregon Trail in 1846, leaving beloved Missouri countryside behind with his girl Jasmine's family. Moving text and black-and-white art from real horse people."}, {"id": 2110, "title": "Horse Diaries #4: Maestro Petra", "url": "https://store.ignatiusbookfairs.com/horse-diaries-4-maestro-petra/", "take": "Vienna, 1938: Maestoso Petra, a world-famous Lipizzaner stallion trained in the Spanish Riding School's airs above the ground, must learn survival when World War II erupts. An unusual, affecting window on history through a horse's eyes."}, {"id": 2114, "title": "Horse Diaries #5: Golden Sun", "url": "https://store.ignatiusbookfairs.com/horse-diaries-5-golden-sun/", "take": "Oregon, 1790: Golden Sun, a chestnut snowflake Appaloosa, gathers healing plants with his Nez Perce rider Little Turtle — and finds his true calling when the boy's best friend falls ill. Written by a mother-daughter team of horse experts."}, {"id": 1579, "title": "Horse Play! 25 Crafts, Party Ideas and Activities for Horse-Crazy Kids", "url": "https://store.ignatiusbookfairs.com/horse-play-25-crafts-party-ideas-and-activities-for-horse-crazy-kids/", "take": "Twenty-five crafts and activities for horse-crazy kids: sew a pony pillow, build a mini barn, design your dream horse, and test your breed knowledge with quizzes. Stickers, stencils, and pop-out cards included — a kit-in-a-book that earns its shelf space."}, {"id": 1607, "title": "Horses in Action! A Poster Book", "url": "https://store.ignatiusbookfairs.com/horses-in-action-a-poster-book/", "take": "Thirty pull-out posters of horses galloping, jumping, bucking, and thundering down the stretch, with fun facts and kid-friendly histories of equine sports alongside. For the young horse lover, this is bedroom-wall gold."}, {"id": 1674, "title": "Hostage Run", "url": "https://store.ignatiusbookfairs.com/hostage-run/", "take": "The MindWar Realm sequel raises the stakes: Rick Dial must choose between saving his best friend Molly and stopping a high-tech terrorist attack on America. Fast, cinematic suspense for teen thriller readers."}, {"id": 962, "title": "How Deep is the Ocean?", "url": "https://store.ignatiusbookfairs.com/how-deep-is-the-ocean/", "take": "A dive from the shallows to the ocean's deepest trenches, meeting glowing animals and creatures that live without sunlight along the way. Clear text and lovely illustrations for young readers full of \"how deep?\" questions."}, {"id": 1903, "title": "How I Became a Man", "url": "https://store.ignatiusbookfairs.com/how-i-became-a-man/", "take": "Growing up as an underground Catholic in the Soviet Union, Alexander Krylov never entered a church until his teens. These short vignettes show faith surviving where God was outlawed, with humor, irony, and a keen eye for human goodness."}, {"id": 1916, "title": "How Saints Die: 100 Stories of Hope", "url": "https://store.ignatiusbookfairs.com/how-saints-die-100-stories-of-hope/", "take": "Carmelite biographer Antonio Maria Sicari turns to the hardest hour in a Christian's life, the hour of death, and finds in the saints not desolation but inexplicable joy. One hundred brief stories of hope. Consoling, sturdy spiritual reading."}, {"id": 1768, "title": "How the Angels Got Their Wings", "url": "https://store.ignatiusbookfairs.com/how-the-angels-got-their-wings/", "take": "A charming rhyming introduction to the angels that reads aloud beautifully. DeStefano answers the questions little ones actually ask — and lands on the joyful truth that the God who made the angels made them too. Lovely for ages 4-8."}, {"id": 1919, "title": "How to Be Holy", "url": "https://store.ignatiusbookfairs.com/how-to-be-holy/", "take": "Peter Kreeft calls holiness the most important question he has ever written about, and he tackles it as a self-confessed beginner writing for fellow novices. Engaging, encouraging, and typically quotable. A fine on-ramp to the spiritual life."}, {"id": 2188, "title": "How to Draw Cute Stuff", "url": "https://store.ignatiusbookfairs.com/how-to-draw-cute-stuff/", "take": "Step-by-step sequences teach kids the basics of Japanese kawaii: simple rounded shapes, big sweet-faced eyes, even personified objects. Pick-up-and-go drawing instruction that works with whatever pencils, crayons, or markers are already on hand."}, {"id": 2766, "title": "How to Find a Unicorn", "url": "https://store.ignatiusbookfairs.com/how-to-find-a-unicorn-ibc-1603/", "take": "Part story, part invitation to go outside: kids gather daisies, ferns, and apples to craft a gift that might just summon a unicorn. Sweet, gentle magic that ends in real-world nature play."}, {"id": 932, "title": "How to Handle My Emotions: Anger", "url": "https://store.ignatiusbookfairs.com/how-to-handle-my-emotions-anger/", "take": "Anger gets the honest treatment here: the most powerful emotion we have, harmful when it boils over, a powerhouse for good when channeled. Three stories and guided steps help children do the channeling, with Christian virtues as the toolkit."}, {"id": 931, "title": "How to Handle My Emotions: Fear", "url": "https://store.ignatiusbookfairs.com/how-to-handle-my-emotions-fear/", "take": "Three engaging stories help children spot fear's early warning signs and keep from being overwhelmed, with guided steps rooted in Christian virtue. A practical emotions series - Charlotte and Elliot make it feel like story time, not therapy."}, {"id": 2858, "title": "How to Trap a Leprechaun", "url": "https://store.ignatiusbookfairs.com/how-to-trap-a-leprechaun/", "take": "Catch a leprechaun and he'll grant you a wish - but you'll need a clever trap. Sue Fliess's read-aloud rhyme comes with a craft included, so the fun keeps going after the story ends. St. Patrick's Day gold."}, {"id": 917, "title": "Hugh O'Flaherty", "url": "https://store.ignatiusbookfairs.com/hugh-oflaherty/", "take": "Monsignor Hugh O'Flaherty, the witty, fearless Irish priest who hid escaped POWs and persecuted Jews in Nazi-occupied Rome - the real man behind The Scarlet and the Black. A true story as gripping as any spy thriller for young readers."}, {"id": 1896, "title": "Humility Rules", "url": "https://store.ignatiusbookfairs.com/humility-rules/", "take": "Saint Benedict's fifth-century wisdom on humility, translated for stressed and anxious modern young adults by Father Augustine, a high school teacher and coach. Candid, funny, and genuinely useful. An unexpected antidote that actually works."}, {"id": 2500, "title": "I am Earth's Keeper", "url": "https://store.ignatiusbookfairs.com/i-am-earth-s-keeper/", "take": "Lisa M. Hendey's rhyming story follows one child's pre-dawn kayak ride into wonder at God's creation, with lovely artwork by Giuliano Ferri. A gentle invitation for young readers to become caretakers of the natural world."}, {"id": 2792, "title": "I am Invited to a Party", "url": "https://store.ignatiusbookfairs.com/i-am-invited-to-a-party-ibc-1588/", "take": "Piggie's invited to a party; Gerald's advice is absurd; early readers cackle. Mo Willems remains the most reliable laugh-per-page ratio in beginning reading."}, {"id": 2787, "title": "I Am Rebel", "url": "https://store.ignatiusbookfairs.com/i-am-rebel-ibc-1544/", "take": "A farm dog narrates his rescue mission when war takes his boy — The Incredible Journey by way of a rebellion. Big-hearted, exciting, and clean; a read-aloud that will wreck the whole family in a good way."}, {"id": 2171, "title": "I Learn About Jesus/Aprendo acerca de Jesus Coloring and Activity Book", "url": "https://store.ignatiusbookfairs.com/i-learn-about-jesus-aprendo-acerca-de-jesus-coloring-and-activity-book/", "take": "A simple coloring and activity book on the life of Jesus, with English and Spanish text on every page. Inexpensive, useful, and bilingual; good for religious ed classrooms, quiet Mass bags, and Sunday afternoons."}, {"id": 2007, "title": "I Was Born to be a Saint, too", "url": "https://store.ignatiusbookfairs.com/i-was-born-to-be-a-saint-too/", "take": "The sequel picks up the happy premise — you were born to be a saint — and shows through pairs of saints that the journey goes better together. Mini biographies in the back and a free audiobook via QR code sweeten the deal."}, {"id": 1488, "title": "I'll Be There", "url": "https://store.ignatiusbookfairs.com/ill-be-there/", "take": "Emily first sees Sam while singing a church choir solo; Sam and his little brother have spent their lives uprooted by an unstable father. A tender YA story about connection and belonging — best for older readers, given the heavier family material."}, {"id": 1624, "title": "I, Juan de Pareja", "url": "https://store.ignatiusbookfairs.com/i-juan-de-pareja/", "take": "Elizabeth Borton de Trevino's vibrant novel of Juan de Pareja, born a slave in Velazquez's Spain, who prepared the master's canvases and died a respected artist himself. Both the beauty and the cruelty of the age, rendered unforgettably."}, {"id": 1408, "title": "Ida Elisabeth", "url": "https://store.ignatiusbookfairs.com/ida-elisabeth/", "take": "Nobel laureate Sigrid Undset's drama of a young wife whose charming husband cannot support the family - and what fidelity, sorrow, and forgiveness cost her. Serious, rewarding fiction for adult readers."}, {"id": 1574, "title": "If We Survive", "url": "https://store.ignatiusbookfairs.com/if-we-survive/", "take": "Will Peterson and his friends came to Central America to rebuild a school — then revolution sweeps the country and Americans become targets. A propulsive survival thriller for teens where kindness and courage get tested under real fire."}, {"id": 1101, "title": "If You Can Get It", "url": "https://store.ignatiusbookfairs.com/if-you-can-get-it/", "take": "Silicon Valley marketing climber Jen has the MBA, the condo, and the fast track — until her chaotic, newly graduated sister lands on her just-swept floor. A wry contemporary novel about career, family, and what actually matters."}, {"id": 1798, "title": "If You Had Your Birthday Party on the Moon", "url": "https://store.ignatiusbookfairs.com/if-you-had-your-birthday-party-on-the-moon/", "take": "What would a lunar birthday be like? Candles behaving weirdly, a low-gravity playground, a day that lasts a month — this picture book smuggles real outer-space facts into an irresistible party premise. Fun and learning in equal measure."}, {"id": 1743, "title": "Ignatius Bible (RSV), 2nd Edition", "url": "https://store.ignatiusbookfairs.com/ignatius-bible-rsv-2nd-edition/", "take": "The Ignatius RSV Catholic Edition in a completely new design and typesetting, with the first edition's archaic language lightly revised. A clear, dignified contemporary translation — a dependable choice for study, school, or gift."}, {"id": 1842, "title": "Illustrated Lives of the Saints", "url": "https://store.ignatiusbookfairs.com/illustrated-lives-of-the-saints/", "take": "Over 80 full-color illustrations, large easy-to-read type, and a ribbon marker: a saint-a-day treasury of short, inspiring biographies covering familiar and lesser-known holy men and women alike. A handsome family shelf staple."}, {"id": 1996, "title": "Immaculate Heart Popper", "url": "https://store.ignatiusbookfairs.com/immaculate-heart-popper/", "take": "A popper modeled on the Immaculate Heart of Mary — tactile, kid-friendly, and quietly devotional. Pairs naturally with the Sacred Heart version as a small gift for Catholic families, classrooms, and prayer corners."}, {"id": 2229, "title": "In Harm's Way (Young Readers Edition): the sinking of the USS Indianapolis and the Story of Its Survivors", "url": "https://store.ignatiusbookfairs.com/in-harms-way-young-readers-edition-the-sinking-of-the-uss-indianapolis-and-the-story-of-its-survivors/", "take": "The young readers edition of the bestselling account of the USS Indianapolis, torpedoed in 1945 in the worst maritime disaster in US naval history. Gripping, sobering World War II nonfiction for readers ready for a true survival story."}, {"id": 1402, "title": "In This House of Brede", "url": "https://store.ignatiusbookfairs.com/in-this-house-of-brede/", "take": "Rumer Godden follows Philippa Talbot from a gleaming career into the enclosed life of Brede Abbey - unceasing work, prayer, disappointment, and a peace the world cannot give. A rich, grown-up novel of vocation."}, {"id": 1704, "title": "Inside, Outside, Upside Down", "url": "https://store.ignatiusbookfairs.com/inside-outside-upside-down/", "take": "A bear rides a carton onto a truck and back again, teaching inside, outside, and upside down along the way. Minimal words, maximum concept — a dependable early book for the very youngest readers."}, {"id": 1805, "title": "Interrupting Chicken", "url": "https://store.ignatiusbookfairs.com/interrupting-chicken/", "take": "The little red chicken cannot help leaping into Papa's bedtime stories to rescue Hansel and Gretel and Little Red Riding Hood from their fates. A read-aloud that gets both generations laughing — with a sly turnabout ending for sleepy papas."}, {"id": 1852, "title": "Interrupting Chicken and the Elephant of Surprise", "url": "https://store.ignatiusbookfairs.com/interrupting-chicken-and-the-elephant-of-surprise/", "take": "The little red chicken from the Caldecott Honor book returns, sparring with Papa over whether stories need an element, or an elephant, of surprise. Read-aloud silliness with a sly wink at how storytelling works."}, {"id": 1901, "title": "Into the Deep: An Unlikely Catholic Conversion", "url": "https://store.ignatiusbookfairs.com/into-the-deep-an-unlikely-catholic-conversion/", "take": "Abigail Favale's memoir of an unlikely road from evangelicalism through postmodern feminism to the brink of atheism, and then into the Catholic Church. Written with humor and real insight. A conversion story for readers who like their honesty unvarnished."}, {"id": 1617, "title": "Invincible Louisa", "url": "https://store.ignatiusbookfairs.com/invincible-louisa/", "take": "A biography tracing Louisa May Alcott from her happy childhood in Pennsylvania and Boston to her success as the author of classics like Little Women. A natural handoff for young readers who have just fallen for the March sisters."}, {"id": 1132, "title": "Ishmael: The Shepherd Boy of Bethlehem", "url": "https://store.ignatiusbookfairs.com/ishmael-the-shepherd-boy-of-bethlehem/", "take": "A thirteen-year-old shepherd - gentle with his sheep, quick with his fists when they need defending - arrives in crowded Bethlehem during the census. An adventurous way into the Nativity story through the eyes of a boy on its edges."}, {"id": 1905, "title": "Island of the World", "url": "https://store.ignatiusbookfairs.com/island-of-the-world/", "take": "Josip Lasta is born in 1933 in a remote Bosnian mountain village, and O'Brien traces his life through Yugoslavia's wars into the third millennium. A sweeping, demanding, deeply rewarding novel for adult readers with time to give it."}, {"id": 1810, "title": "Jabari Jumps", "url": "https://store.ignatiusbookfairs.com/jabari-jumps/", "take": "Jabari has passed his swim test and is definitely, almost, absolutely ready for the diving board. A tender portrait of everyday courage, with a dad who knows exactly when to squeeze a hand. A gentle companion for any child facing a nervous first."}, {"id": 1653, "title": "Jacob Have I Loved", "url": "https://store.ignatiusbookfairs.com/jacob-have-i-loved/", "take": "Katherine Paterson's Newbery Medal winner about sibling rivalry and a sister fighting to become her own person. Honest, sometimes painful, and widely taught — a serious coming-of-age novel for mature independent readers."}, {"id": 1972, "title": "Jane Eyre: Ignatius Critical Edition", "url": "https://store.ignatiusbookfairs.com/jane-eyre-ignatius-critical-edition/", "take": "Jane Eyre with a critical apparatus that takes Charlotte Bronte's deep Christian faith seriously, reading the novel through its semi-autobiographical and moral dimensions rather than passing critical fashions. A strong choice for high school and homeschool literature study."}, {"id": 1815, "title": "Jasmine Green Rescues: A Collie Called Sky", "url": "https://store.ignatiusbookfairs.com/jasmine-green-rescues-a-collie-called-sky/", "take": "Jasmine finds a starving collie pup hiding under a hedge on the family farm, and with her veterinarian mother's help begins the slow work of healing and trust. Warm animal-rescue fiction for kids who dream of being vets."}, {"id": 1393, "title": "Jayber Crow", "url": "https://store.ignatiusbookfairs.com/jayber-crow/", "take": "Wendell Berry's barber of Port William narrates a lifetime of loneliness, patience, and grace in a small Kentucky town. A slow, deep novel about heaven, membership, and love for adult and mature high-school readers."}, {"id": 2005, "title": "Jesse Tree Window Clings (with O Antiphons) and Book", "url": "https://store.ignatiusbookfairs.com/jesse-tree-window-clings-with-o-antiphons-and-book/", "take": "Twenty-four window clings plus a short companion book, The Tree of Jesse, with daily readings for Advent — the final eight days covering the O Antiphons. Low-effort, low-space, and genuinely lovely for families new to the tradition."}, {"id": 1475, "title": "Jesus Feeds the Multitude (Jesus Alimenta a la Multitud)", "url": "https://store.ignatiusbookfairs.com/jesus-feeds-the-multitude-jesus-alimenta-a-la-multitud/", "take": "The feeding of the multitude in Arch Books rhyme, now in a bilingual English-Spanish edition with the series' bright, kid-pleasing illustrations. A natural for bilingual families, Spanish classes, and parishes serving both languages — ages 5-9."}, {"id": 1127, "title": "Jesus I Love You board book", "url": "https://store.ignatiusbookfairs.com/jesus-i-love-you-board-book/", "take": "A tender first prayer book for toddlers, with lift-open windows and the simplest possible words: hello, thank you, sorry, I love you. A sweet way to show a small child that talking to Jesus is easy."}, {"id": 1640, "title": "Jesus Stories from the Bible", "url": "https://store.ignatiusbookfairs.com/jesus-stories-from-the-bible/", "take": "Five New Testament stories — from the Birth of Jesus to the calling of the disciples to resurrection — imaginatively told and illustrated by three different artists. A warm way to stir a child's desire to know the Savior better."}, {"id": 1398, "title": "Jesus, I Adore You", "url": "https://store.ignatiusbookfairs.com/jesus-i-adore-you/", "take": "A gentle child's introduction to Eucharistic Adoration: what it is, how to draw near the tabernacle, and prayers to use once there. Drawing on Scripture, it makes a profound practice feel simple - just telling Jesus we love him."}, {"id": 1808, "title": "JMJ Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/jmj-vinyl-sticker/", "take": "Three letters, one holy household: Jesus, Mary, and Joseph. A simple vinyl sticker of the classic JMJ monogram — an old-school Catholic touch for a brand-new notebook or laptop lid."}, {"id": 1909, "title": "Joan of Arc", "url": "https://store.ignatiusbookfairs.com/joan-of-arc/", "take": "Few people know Mark Twain wrote a major work on Joan of Arc, or that he considered it his best. Twelve years of research, including French archives, went into it. A fascinating meeting of America's great humorist and a great saint."}, {"id": 2233, "title": "Joan of Arc by Josephine Poole", "url": "https://store.ignatiusbookfairs.com/joan-of-arc-by-josephine-poole/", "take": "The true story of Saint Joan of Arc, the peasant girl who led the French army to victory in 1429. Poole's beautiful prose and charming illustrations let her courage, purity, and devotion shine on every page."}, {"id": 2847, "title": "Joan of Arc: The Girl Soldier", "url": "https://store.ignatiusbookfairs.com/joan-of-arc-the-girl-soldier-louis-de-wohl-ip-sjgsp/", "take": "Louis de Wohl gives young readers the real Joan — visions, armor, trial, and grace — with the narrative drive of a novelist. The Vision Books series at its thrilling best; superb for 9-14s."}, {"id": 1600, "title": "John Mary Vianney: The Holy Cure of Ars", "url": "https://store.ignatiusbookfairs.com/john-mary-vianney-the-holy-cure-of-ars/", "take": "A tenderly illustrated life of John Vianney, the humble Cure of Ars and patron of parish priests — his compassion for the poor, his long hours in the confessional, his heartfelt Masses. A quiet portrait of faithfulness children can absorb."}, {"id": 1620, "title": "John Paul II: The Journey of a Saint", "url": "https://store.ignatiusbookfairs.com/john-paul-ii-the-journey-of-a-saint/", "take": "A richly illustrated hardcover life of John Paul II: the athletic Polish student who defied Nazi occupiers in an underground seminary, stood up to the communists as priest and bishop, and became a saint. Genuinely dramatic material, handsomely presented."}, {"id": 1811, "title": "Jonah's Voyage to Atlantis", "url": "https://store.ignatiusbookfairs.com/jonahs-voyage-to-atlantis/", "take": "The prophet Jonah's flight from Nineveh retold as an epic fantasy-adventure comic — a soul-thirsting demon, a violent storm, and a divine quest he cannot outrun. Biblical truth in a format built for kids who devour graphic novels."}, {"id": 1642, "title": "Jonah: The Runaway Prophet", "url": "https://store.ignatiusbookfairs.com/jonah-the-runaway-prophet/", "take": "Jonah the runaway prophet in classic Arch Books style: easy-to-read rhyme, engaging illustrations, and a letter to adults with background and teaching suggestions. A trusted series that has taught Bible stories to generations of children, and this entry shows why."}, {"id": 1831, "title": "Joseph and Child Jesus Mini Puzzle", "url": "https://store.ignatiusbookfairs.com/joseph-and-child-jesus-mini-puzzle/", "take": "A mini puzzle of St. Joseph with the child Jesus. A small, sweet quiet-time activity that puts fatherly tenderness front and center — handy for travel bags, classroom corners, and St. Joseph devotees of any age."}, {"id": 2232, "title": "Joseph Had a Little Overcoat", "url": "https://store.ignatiusbookfairs.com/joseph-had-a-little-overcoat/", "take": "Joseph's shabby overcoat becomes a jacket, then something smaller, then smaller still — and die-cut holes let children guess each step. A cheerful classic with a sturdy moral: you can always make something, even out of nothing."}, {"id": 2184, "title": "Joy Accessory Case", "url": "https://store.ignatiusbookfairs.com/joy-accessory-case/", "take": "A cheerful accessory case for stashing pencils, trinkets, and small treasures. Not a book, we'll admit, but a fun little extra that rounds out a book fair haul without promising more than it is."}, {"id": 1133, "title": "Joy to the World", "url": "https://store.ignatiusbookfairs.com/joy-to-the-world/", "take": "Three of Tomie dePaola's beloved Christmas stories - Las Posadas, the Three Wise Kings, and the Legend of the Poinsettia - gathered into one handsome volume. A dependable family read-aloud for the whole season."}, {"id": 2163, "title": "Juana & Lucas", "url": "https://store.ignatiusbookfairs.com/juana-lucas/", "take": "Spunky Juana loves drawing, Bogota, and her dog Lucas, the best amigo ever; she does not love her itchy school uniform. A playful, abundantly illustrated series with vivid Colombian flavor. A natural next step for Judy Moody and Clarice Bean fans."}, {"id": 881, "title": "Julia Greeley", "url": "https://store.ignatiusbookfairs.com/julia-greeley/", "take": "The true story of Julia Greeley, born into slavery, mostly illiterate, desperately poor - and Denver's tireless angel of mercy who gave away whatever she begged. A powerful, joyful American witness that children will not forget."}, {"id": 1885, "title": "Julius Caesar", "url": "https://store.ignatiusbookfairs.com/julius-caesar/", "take": "A high school staple that is anything but simple: fate and free will, ambition and public service, all drawn from Plutarch. The questions it asks about what kind of man rises to power never go out of date."}, {"id": 1730, "title": "Junipero Serra: Founder of the California Missions", "url": "https://store.ignatiusbookfairs.com/junipero-serra-founder-of-the-california-missions/", "take": "The story of the Franciscan friar who left Spain for the New World and founded the California missions, canonized by Pope Francis in 2015. A solid pick for saints' biographies and California history alike."}, {"id": 2198, "title": "Kate In Between", "url": "https://store.ignatiusbookfairs.com/kate-in-between/", "take": "After a bullying incident goes viral, twelve-year-old Kate must face what she did and who she wants to be. Claire Swinarski's timely middle-grade novel takes popularity, guilt, and truth-telling seriously without preaching. A good discussion-starter."}, {"id": 1609, "title": "Kateri Tekakwitha: Mohawk Maiden", "url": "https://store.ignatiusbookfairs.com/kateri-tekakwitha-mohawk-maiden/", "take": "The inspiring Vision Books story of St. Kateri Tekakwitha, the young Mohawk woman who embraced Christianity through the French missionaries of the 1600s despite losing her family to smallpox and facing real opposition. A moving account of quiet, costly conviction."}, {"id": 1460, "title": "Keep Out! Build Your Own Backyard Clubhouse", "url": "https://store.ignatiusbookfairs.com/keep-out-build-your-own-backyard-clubhouse/", "take": "Lee Mothes gives families step-by-step instructions for building a real backyard clubhouse, with ideas for keeping kids involved at every stage. A project book that trades screens for sawdust and ends with something to play in for years."}, {"id": 2756, "title": "Keeping the Light", "url": "https://store.ignatiusbookfairs.com/keeping-the-light-ibc-1617/", "take": "A lighthouse keeper's son learns the light shines for everyone, deserving or not — a coastal tale of humor and heart from Ali Gilkeson and bestselling illustrator Lee Wildish. The generous message sneaks in while kids enjoy the hijinks."}, {"id": 1888, "title": "King Lear", "url": "https://store.ignatiusbookfairs.com/king-lear/", "take": "One of Shakespeare's most thought-provoking plays, read here through Cordelia's refusal to render unto Caesar what belongs to God. The essays give students a genuinely fresh angle on a play they may think they already know."}, {"id": 1019, "title": "Kitchen Madonna", "url": "https://store.ignatiusbookfairs.com/kitchen-madonna/", "take": "Marta, the Ukrainian housekeeper who anchors two lonely children's home, is quietly unhappy — so nine-year-old Gregory sets out to make her kitchen a \"good place.\" Rumer Godden-style tenderness about love expressed through effort."}, {"id": 1539, "title": "Knight's Castle", "url": "https://store.ignatiusbookfairs.com/knights-castle/", "take": "An old toy soldier comes to life, and Roger, his sister Ann, and their bossy cousins tumble into magic during an anxious summer. Book two of the series Half Magic began — same wit, new enchantment."}, {"id": 2838, "title": "Knights: Discover: Press out and Play DK", "url": "https://store.ignatiusbookfairs.com/knights-discover-press-out-and-play-dk-ibc-1581/", "take": "Made in collaboration with The Metropolitan Museum of Art: real answers about armor, castles, and battle, then a press-out jousting tournament to build. Facts up front, play in the back - a smart gift for knight-obsessed kids."}, {"id": 2219, "title": "Knock-Knock Jokes for Kids", "url": "https://store.ignatiusbookfairs.com/knock-knock-jokes-for-kids/", "take": "Rob Elliott's clean, kid-pleasing knock-knock jokes. Expect relentless repetition at the dinner table; that's rather the point. Reliable lighthearted humor that parents and teachers don't have to screen first."}, {"id": 1615, "title": "Knots (Collins Discover)", "url": "https://store.ignatiusbookfairs.com/knots-collins-discover/", "take": "An authoritative, user-friendly knot guide from the cofounder of the International Guild of Knot Tyers — boating knots, home and hobby knots, life-support knots, all with full-color step-by-step illustrations. Handy for scouts, sailors, and the incurably practical."}, {"id": 2866, "title": "Lady of Guadalupe Plush", "url": "https://store.ignatiusbookfairs.com/lady-of-guadalupe-plush/", "take": "An 8-inch plush of Our Lady of Guadalupe, blue starred mantle and roses included. A soft, huggable way for little ones to connect with the story of her appearance to Juan Diego. A sweet first Marian devotion."}, {"id": 2029, "title": "Lady of Lourdes Plush", "url": "https://store.ignatiusbookfairs.com/lady-of-lourdes-plush/", "take": "Mary as she appeared to Bernadette at the grotto — white dress, blue sash — in soft eight-inch plush form. A comforting companion for teaching little ones about Lourdes, healing, and Our Lady's call to prayer."}, {"id": 2853, "title": "Laugh out loud: Puns, jokes and Riddles for Kids", "url": "https://store.ignatiusbookfairs.com/laugh-out-loud-puns-jokes-and-riddles-for-kids-rob-elliot-ibc-1598/", "take": "400+ road-tested jokes, puns, and riddles from the bestselling king of kid comedy. The antidote to long car rides; milk-out-the-nose incidents are the reader's responsibility."}, {"id": 1660, "title": "Lay Siege to Heaven: A Novel about St. Catherine of Siena", "url": "https://store.ignatiusbookfairs.com/lay-siege-to-heaven-a-novel-about-st-catherine-of-siena/", "take": "Louis de Wohl turns his novelist's gifts on Catherine of Siena, the dyer's daughter who refused marriage to give her life wholly to God. Rich historical fiction that makes a formidable saint feel vividly human."}, {"id": 980, "title": "Learn to Read with Tug the Pup Box Set 1", "url": "https://store.ignatiusbookfairs.com/learn-to-read-with-tug-the-pup-box-set-1/", "take": "Eleven simple storybooks by reading specialist Dr. Julie M. Wood, plus a parent guide and reward stickers. Tug the Pup gives brand-new readers sight words, strong picture support, and a reason to keep going."}, {"id": 981, "title": "Learn to Read with Tug the Pup Box Set 2", "url": "https://store.ignatiusbookfairs.com/learn-to-read-with-tug-the-pup-box-set-2/", "take": "The second Tug the Pup set: eleven more storybooks from reading specialist Dr. Julie M. Wood, with a parent guide and reward stickers. A steady, structured next step for beginning readers building confidence."}, {"id": 982, "title": "Learn to Read with Tug the Pup Box Set 3", "url": "https://store.ignatiusbookfairs.com/learn-to-read-with-tug-the-pup-box-set-3/", "take": "The third Tug the Pup set rounds out the program — eleven storybooks, parent guide, and reward stickers from reading specialist Dr. Julie M. Wood. Sight words and simple text carry new readers forward."}, {"id": 1863, "title": "Learning to Pray", "url": "https://store.ignatiusbookfairs.com/learning-to-pray/", "take": "A practical, cheerful introduction to daily prayer for children, covering traditional prayers like the Rosary alongside do-it-yourself projects and simple ways to just talk with God. The kind of book that starts a lifelong habit."}, {"id": 2108, "title": "Legends of Zita the Space Girl (Zita the Spacegirl #2)", "url": "https://store.ignatiusbookfairs.com/legends-of-zita-the-space-girl-zita-the-spacegirl-2/", "take": "Zita's heroics made her an intergalactic megastar, and fame turns out to have a price. Ben Hatke's second outing asks who you can trust when your public persona starts eclipsing your true self — smart stuff wrapped in delightful adventure."}, {"id": 2821, "title": "Lego Cute Ideas -with Owlicorn minifigure", "url": "https://store.ignatiusbookfairs.com/lego-cute-ideas-with-owlicorn-minifigure-ibc-1578/", "take": "More than 50 kawaii-style LEGO build ideas - unicorns, hotdogs, cacti, cupcakes - plus an exclusive Owlicorn model. Exactly the kind of idea book that keeps brick-obsessed kids building instead of asking what to build."}, {"id": 2828, "title": "Lego Epic History Includes Four Exclusive LEGO Mini Models", "url": "https://store.ignatiusbookfairs.com/lego-epic-history-includes-four-exclusive-lego-mini-models-ibc-1579/", "take": "World history told in LEGO — with bricks included for four mini-builds. The book equivalent of a museum gift shop's best item; history-averse kids don't stand a chance."}, {"id": 1753, "title": "Lego Super Nature", "url": "https://store.ignatiusbookfairs.com/lego-super-nature/", "take": "Fascinating natural-world facts — insect-eating plants, flying mammals — all illustrated with LEGO builds, from flowers and trees to deepwater fish. A clever hook that gets brick-minded kids reading nonfiction happily."}, {"id": 1745, "title": "Lenten Adventure Activity Book 1", "url": "https://store.ignatiusbookfairs.com/lenten-adventure-activity-book-1/", "take": "A 112-page book of daily Lenten activities — fun, challenging, and catechetical — with pages pitched for the whole 5-12 age range. A practical way to keep the season in front of kids every single day."}, {"id": 2538, "title": "Leo XIV: The Pope from Both Americas", "url": "https://store.ignatiusbookfairs.com/leo-xiv-the-pope-from-both-americas/", "take": "Pope Leo XIV's story told by his guardian angel — a genuinely charming narrative device that carries kids from Robert's humble beginnings to the Chair of Peter with warmth and humor. Timely, playful, and reverent all at once."}, {"id": 1922, "title": "Lepanto", "url": "https://store.ignatiusbookfairs.com/lepanto/", "take": "Belloc called Lepanto the greatest poem of Chesterton's generation, yet both the poem and the battle behind it get skipped in class. This volume restores both: annotated poem, riveting battle history, and the consequences that followed. A splendid package."}, {"id": 1856, "title": "Let Your Light Shine Small Accessory Case: Marigold", "url": "https://store.ignatiusbookfairs.com/let-your-light-shine-small-accessory-case-marigold/", "take": "A cheerful marigold zipper case trimmed with pink pom-poms and patterned with the Fruit of the Spirit from Galatians. Coordinates with the Let Your Light Shine totes, and just the right size to stow and go."}, {"id": 2226, "title": "Library Lion", "url": "https://store.ignatiusbookfairs.com/library-lion/", "take": "Miss Merriweather runs a tidy, rule-abiding library — until a lion strolls in and turns out to be very good at library visiting. A gentle, affectionate storybook about rules, kindness, and why we love libraries."}, {"id": 1091, "title": "Life of Jesus Coloring Book", "url": "https://store.ignatiusbookfairs.com/life-of-jesus-coloring-book/", "take": "Classic images from Christ's Birth through the Ascension — Cana, the loaves and fishes, Lazarus, the Last Supper — each with a phrase from Scripture. A coloring book that doubles as a gentle walk through the Gospels."}, {"id": 963, "title": "Light Is All Around Us", "url": "https://store.ignatiusbookfairs.com/light-is-all-around-us/", "take": "Sunlight, firelight, electric lights, even glowing sea animals — this Level 2 Let's-Read-and-Find-Out title gives early elementary kids a clear, cheerful introduction to light in all its forms, with helpful diagrams."}, {"id": 2148, "title": "Light of the Last (Wars of the Realm, #3)", "url": "https://store.ignatiusbookfairs.com/light-of-the-last-wars-of-the-realm-3/", "take": "Drew Carter regained his sight after an accident, and now sees the spiritual battle raging beyond it. This series installment mixes CIA intrigue, romance, and angelic warfare; a solid pick for teens who like their thrillers with a supernatural Christian edge."}, {"id": 1627, "title": "Lights in a Dark Town: A Story about John Henry Newman", "url": "https://store.ignatiusbookfairs.com/lights-in-a-dark-town-a-story-about-john-henry-newman/", "take": "In 1849 Birmingham — a town of progress and poverty, tolerance and prejudice — young Emmeline Erle and her widowed mother start over. A historical novel about John Henry Newman's world for readers who like their faith stories with texture."}, {"id": 2820, "title": "Lightseekers Book 1 - Kingdom of Shadows", "url": "https://store.ignatiusbookfairs.com/lightseekers-book-1-a-kingdom-of-shadows-ibc-1594/", "take": "Light itself is dying in Wildfel, and a thief, his friend, and his little sister get caught up in the fight against the dark. A promising fantasy start in the Narnia/Wingfeather lineage — clean, exciting, meaningful."}, {"id": 1817, "title": "Lily of the Mohawks: Saint Kateri Tekakwitha", "url": "https://store.ignatiusbookfairs.com/lily-of-the-mohawks-saint-kateri-tekakwitha/", "take": "Kateri Tekakwitha, caught between her Mohawk community's traditions and her newfound Christian faith, must make a radical choice. This historical graphic novel tells her story with real dramatic tension — a saint's life that reads like the page-turner it was."}, {"id": 1575, "title": "Listening for Lions", "url": "https://store.ignatiusbookfairs.com/listening-for-lions/", "take": "From the National Book Award-winning author of Homeless Bird: Rachel, raised in Africa by missionary parents, is orphaned by influenza and forced into a life of deception in England. A critically acclaimed historical novel with patience and steel at its core."}, {"id": 1924, "title": "Literary Converts", "url": "https://store.ignatiusbookfairs.com/literary-converts/", "take": "Joseph Pearce traces the spiritual lives of Wilde, Waugh, Lewis, Chesterton, Sayers, Eliot, Tolkien, and more, with Shaw and Wells stirring the debate from outside. A fascinating map of the great religious current running through modern English letters."}, {"id": 1929, "title": "Literature: What Every Catholic Should Know", "url": "https://store.ignatiusbookfairs.com/literature-what-every-catholic-should-know/", "take": "A friendly, panoramic tour of literature — Greek epics, Shakespeare, Tolkien — written for the ordinary Catholic reader, no English degree required. A solid pick for parents and teachers who want a map of the whole tradition."}, {"id": 2486, "title": "Little Bear", "url": "https://store.ignatiusbookfairs.com/little-bear/", "take": "The very first I Can Read book, from Else Holmelund Minarik with Maurice Sendak's art. Little Bear's adventures always circle back to Mother Bear's steady love — a tender, timeless choice for children just starting to read."}, {"id": 997, "title": "Little Bear Box Set (3 books)", "url": "https://store.ignatiusbookfairs.com/little-bear-box-set-3-books/", "take": "Three paperback Little Bear books in a gift box — Minarik's tender stories with Maurice Sendak's art. Mother Bear is always there when Little Bear needs her, which is exactly what early readers need too."}, {"id": 1819, "title": "Little Beasts Mini Puzzle", "url": "https://store.ignatiusbookfairs.com/little-beasts-mini-puzzle/", "take": "A mini puzzle from the Little Beasts line. Small format and pocket-sized ambitions — the kind of compact quiet-time activity that suits travel bags, classroom corners, and stocking stuffers alike."}, {"id": 2477, "title": "Little Cities: New York City", "url": "https://store.ignatiusbookfairs.com/little-cities-new-york-city/", "take": "A picture-book travel guide that walks little urbanites through New York City: the Statue of Liberty, taxis, Broadway and more. Bold illustrations and simple read-aloud text make it a fun armchair field trip for young explorers."}, {"id": 2475, "title": "Little House on the Prairie", "url": "https://store.ignatiusbookfairs.com/little-house-on-the-prairie/", "take": "The third Little House book follows the Ingalls family by covered wagon from Wisconsin to Kansas, with Garth Williams's classic artwork intact. Laura Ingalls Wilder's real-life pioneer childhood still captivates generation after generation of readers."}, {"id": 1003, "title": "Little Red Riding Hood", "url": "https://store.ignatiusbookfairs.com/little-red-riding-hood/", "take": "A Caldecott Honor edition of the classic fairy tale, rich with wildflowers, mushrooms, and one wicked wolf urging Elisabeth off the path. A stunning version of the story, with all its old warning intact."}, {"id": 1048, "title": "Little Women", "url": "https://store.ignatiusbookfairs.com/little-women/", "take": "The four March sisters — sweet Meg, smart Jo, shy Beth, sassy Amy — hold together while Father is away at war. The beloved classic of sisterly squabbles, hard times, and growing up, in an edition with a new introduction."}, {"id": 1754, "title": "Look and Learn: First Words for Catholic Kids", "url": "https://store.ignatiusbookfairs.com/look-and-learn-first-words-for-catholic-kids/", "take": "A bright board-book treasure hunt through the colors, sights, and sounds of a parish church, written by a mom to engage her own toddler during Mass. First faith words for the very youngest Catholics."}, {"id": 1890, "title": "Loss and Gain", "url": "https://store.ignatiusbookfairs.com/loss-and-gain/", "take": "Newman's first book after entering the Catholic Church in 1845: a novel of a young Oxford man wrestling through doubt and controversy toward Rome. Autobiographical in spirit, and a rewarding read for thoughtful older students and adults."}, {"id": 2496, "title": "Lots of Animal Jokes for Kids", "url": "https://store.ignatiusbookfairs.com/lots-of-animal-jokes-for-kids/", "take": "More than 250 clean, kid-friendly animal jokes, riddles, and tongue twisters. What do you call a sleeping bull? A bull-dozer. Perfect ammunition for road trips and family gatherings — groans and giggles guaranteed in equal measure."}, {"id": 1784, "title": "Loupio coloring book", "url": "https://store.ignatiusbookfairs.com/loupio-coloring-book/", "take": "A coloring book from the world of Loupio. If your kids already know the character, this is an easy companion purchase; if not, it is simply pleasant, screen-free coloring time — no more promised, none needed."}, {"id": 2868, "title": "Loupio Plush", "url": "https://store.ignatiusbookfairs.com/loupio-plush/", "take": "Loupio, the young orphaned poet and musician befriended by St. Francis of Assisi in the beloved 8-book adventure series, now in plush form. A natural companion gift for young readers working through the books."}, {"id": 2272, "title": "Lunch Lady and the Cyborg Substitute", "url": "https://store.ignatiusbookfairs.com/lunch-lady-and-the-cyborg-substitute/", "take": "Hector, Terrence, and Dee always wondered what their lunch lady does after the daily special. The answer: she serves justice. A goofy, action-packed school comic that turns the cafeteria into a crime-fighting headquarters."}, {"id": 2812, "title": "Lunch Lady and the League of Librarians", "url": "https://store.ignatiusbookfairs.com/lunch-lady-and-the-league-of-librarians-ibc-1576/", "take": "Something rotten is going on in the library - the usually friendly librarians have turned cold and secretive, and Lunch Lady is on the case. From the author of Hey, Kiddo, a graphic novel romp kids happily devour."}, {"id": 1558, "title": "Mac and Cheese", "url": "https://store.ignatiusbookfairs.com/mac-and-cheese/", "take": "An alley-cat odd couple in the spirit of Big Dog... Little Dog: Mac loves to run, Cheese loves to lounge, and a runaway hat forces the issue. Level One I Can Read — short sentences, familiar words, real charm."}, {"id": 1543, "title": "Mac and Cheese and the Perfect Plan", "url": "https://store.ignatiusbookfairs.com/mac-and-cheese-and-the-perfect-plan/", "take": "Mac wants the beach; Cheese wants bed. Sarah Weeks turns that standoff into a genuinely funny friendship story at Level One I Can Read — short sentences and familiar words for kids just learning to sound things out."}, {"id": 1897, "title": "Macbeth", "url": "https://store.ignatiusbookfairs.com/macbeth/", "take": "The darkest of Shakespeare's plays: nihilistic despair, or a cautionary tale about Machiavellianism that points to light beyond the darkness? This critical edition puts the question squarely to students, with essays worth arguing over."}, {"id": 1814, "title": "Made for Greatness Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/made-for-greatness-vinyl-sticker/", "take": "A vinyl sticker with a bracing reminder: made for greatness. An easy encouragement for a student's binder, locker, or laptop — a small purchase carrying a genuinely good message."}, {"id": 2269, "title": "Madeline", "url": "https://store.ignatiusbookfairs.com/madeline/", "take": "Twelve little girls in two straight lines, and the smallest one fears nothing — not tigers, not mice. After 75-plus years, Bemelmans' whimsical Paris and his brave little heroine still charm every reader who meets them."}, {"id": 2501, "title": "Madeline: Activity Book with Stickers", "url": "https://store.ignatiusbookfairs.com/madeline-activity-book-with-stickers/", "take": "Madeline, Pepito, and the Bemelmans cast frolic through Paris in reusable vinyl stickers, simple puzzles, and coloring pages, with glossy gatefold scenes to decorate. An easy, screen-free win for fans of the little Parisian."}, {"id": 2530, "title": "Magnifier 2026, Jan-Feb: Cathedrals", "url": "https://store.ignatiusbookfairs.com/magnifier-2026-jan-feb-cathedrals/", "take": "A magazine for ages 7-12 built to spark wonder away from screens — this issue explores cathedrals through stories, comics, great art, games, crafts, and a detachable poster. Thoughtful, beautiful periodical reading for curious kids."}, {"id": 2531, "title": "Magnifier 2026, Mar-Apr: Mountains", "url": "https://store.ignatiusbookfairs.com/magnifier-2026-mar-apr-mountains/", "take": "This issue of the wonder-filled children's magazine for ages 7-12 takes mountains as its theme, explored through stories, comics, art, games, and crafts, poster included. A lovely screen-free habit for curious readers."}, {"id": 2532, "title": "Magnifier 2026, May-June: Bread", "url": "https://store.ignatiusbookfairs.com/magnifier-2026-may-june-bread/", "take": "Bread is the theme of this issue for ages 7-12 — explored through engaging stories, comics, an introduction to great art, games, and crafts, with a detachable poster. Curiosity-feeding, screen-free reading, issue after issue."}, {"id": 1006, "title": "Make Way for Ducklings", "url": "https://store.ignatiusbookfairs.com/make-way-for-ducklings/", "take": "Mrs. Mallard needs to get eight ducklings through busy Boston streets to the Public Garden pond, and the police lend a hand. A Caldecott winner that generations of families have loved for good reason."}, {"id": 1690, "title": "Manalive", "url": "https://store.ignatiusbookfairs.com/manalive/", "take": "Chesterton's rollicking puzzle of a novel: Innocent Smith brings joy to a boarding house, then stands trial for attempted murder. The twists build toward something bigger — that life itself is worth being astonished by. For strong teen and adult readers."}, {"id": 2807, "title": "Manga Carlo Acutis", "url": "https://store.ignatiusbookfairs.com/manga-carlo-acutis-ibc-6mcap/", "take": "Carlo Acutis — soccer, video games, daily Mass, and a website of Eucharistic miracles — in manga form. The saint teens recognize as one of their own; this flies off our fair tables."}, {"id": 1902, "title": "Mansfield Park", "url": "https://store.ignatiusbookfairs.com/mansfield-park/", "take": "Austen's most neglected and misunderstood novel, this edition argues, and one best appreciated in light of her own Christian faith. A story about family, upbringing, and conservative values that rewards patient readers. Ideal for Austen completists and classrooms."}, {"id": 2456, "title": "Manual to Manhood", "url": "https://store.ignatiusbookfairs.com/manual-to-manhood/", "take": "One hundred step-by-step instructions on the things a guy would rather not have to ask about — cologne, credit cards, talking to a girl, planning a date. A practical, judgment-free handbook for growing up capable."}, {"id": 914, "title": "Maria von Trapp and Her Musical Family", "url": "https://store.ignatiusbookfairs.com/maria-von-trapp-and-her-musical-family/", "take": "The true story behind The Sound of Music, told for young readers from Maria's own bestselling account - the postulant, the musical family, the escape from the Third Reich. The real history is every bit as dramatic as the musical."}, {"id": 2134, "title": "Mariel of Redwall: Redwall #4", "url": "https://store.ignatiusbookfairs.com/mariel-of-redwall-redwall-4/", "take": "Cast into the sea by the pirate rat Gabool, Mariel comes back swinging — literally, with her rope-weapon the Gullwhacker. A Redwall tale with a fierce heroine at its center and a father worth avenging."}, {"id": 1920, "title": "Married Saints and Blesseds Through the Centuries", "url": "https://store.ignatiusbookfairs.com/married-saints-and-blesseds-through-the-centuries/", "take": "Fr. Holbock gathers the stories of over 200 married saints and blesseds, from Mary and Joseph to Thomas More to Gianna Molla and the parents of St. Therese. A needed reminder that the vocation of marriage is a call to holiness."}, {"id": 1419, "title": "Marshmallow", "url": "https://store.ignatiusbookfairs.com/marshmallow/", "take": "The true story of Oliver the spotlight-loving tabby and Marshmallow, the baby rabbit he refuses to welcome - at first. Clare Turlay Newberry's elegant drawings make this classic friendship tale a quiet stunner."}, {"id": 2835, "title": "Marty Moose: First Class Mischief", "url": "https://store.ignatiusbookfairs.com/marty-moosefirst-class-mischief-ibc-1631/", "take": "Marty's first day delivering mail for the Little Ditch Post Office turns perilous fast - good thing Great-Aunt Ada taught him that small doesn't mean timid. A silly, encouraging story of bravery, independence, and friendship."}, {"id": 1582, "title": "Marvel Doodles", "url": "https://store.ignatiusbookfairs.com/marvel-doodles/", "take": "Doodle prompts across the Marvel Universe — Avengers, Black Panther, Ms. Marvel, even Loki and Ultron — inviting kids to draw, color, and finish the scenes themselves. Low-pressure creative fun for young superhero fans of all drawing abilities."}, {"id": 2509, "title": "Mary Dress Up Magnet Playset", "url": "https://store.ignatiusbookfairs.com/mary-dress-up-magnet-playset/", "take": "Twenty-eight magnetic pieces let little ones dress Mary and arrange a prayer garden. A gentle, hands-on way to foster devotion to the Blessed Mother — the kind of quiet-time toy that earns its spot in the Mass bag."}, {"id": 1560, "title": "Mary Stories from the Bible", "url": "https://store.ignatiusbookfairs.com/mary-stories-from-the-bible/", "take": "Five touching stories from Mary's life — childhood, Annunciation, Nativity, Cana, and the death and resurrection of Jesus — imaginatively told and beautifully illustrated. Works read aloud to little ones or handed to young readers to manage on their own."}, {"id": 1778, "title": "Mary, Blessed Mother Charm", "url": "https://store.ignatiusbookfairs.com/mary-blessed-mother-charm/", "take": "A charm for the Blessed Mother herself — blessed among women, and the mother Jesus gave to all of us from the Cross. A source of peace, hope, and love, and a sweet first devotion for any Catholic child."}, {"id": 1840, "title": "Mary, Mother of All", "url": "https://store.ignatiusbookfairs.com/mary-mother-of-all/", "take": "Scott Hahn and Emily Stimpson Chapman trace Our Lady's role in salvation from creation and the Fall onward, opening in verse, with Tricia Dugat's attractive illustrations. Real theology scaled for children of all ages — Marian catechesis done gently."}, {"id": 1933, "title": "Mary, Mother of God", "url": "https://store.ignatiusbookfairs.com/mary-mother-of-god/", "take": "Writer Gorny and photographer Rosikon retrace Mary's earthly life across Israel, Egypt, Turkey, and Italy in this richly illustrated, carefully documented volume. Part journalism, part pilgrimage — a beautiful gift book for families and parish libraries."}, {"id": 904, "title": "Mary, The Mother of Jesus", "url": "https://store.ignatiusbookfairs.com/mary-the-mother-of-jesus/", "take": "The book dePaola dreamed of making since seeing Giotto's frescoes as an art student: the life of Mary, drawn from Scripture, tradition, and legend. Splendid, reverent, and a fitting companion for Marian months and family reading."}, {"id": 978, "title": "Mason Jar Science", "url": "https://store.ignatiusbookfairs.com/mason-jar-science/", "take": "Winner of Mom's Choice Gold and a Nautilus Silver, this one turns a humble mason jar into a science lab: forty experiments for ages 8 and up, from tiny tornadoes to homemade slime, using ordinary household items."}, {"id": 2130, "title": "Mattimeo: Redwall #3", "url": "https://store.ignatiusbookfairs.com/mattimeo-redwall-3/", "take": "Slagar the Fox skips the battle plans and simply steals Redwall's children — including Mattimeo, Matthias's headstrong son. A tense, satisfying entry in the saga about rescue, courage, and growing into your father's legacy."}, {"id": 2276, "title": "Max and the Midknights", "url": "https://store.ignatiusbookfairs.com/max-and-the-midknights/", "take": "Max wants to be a knight, which seems about as likely as a friendly dragon — until Uncle Budrick is kidnapped by cruel King Gastley. From the Big Nate author, a laugh-filled bestselling quest with a brave band of Midknights."}, {"id": 1118, "title": "Medal Knight 1: Max and the Robot", "url": "https://store.ignatiusbookfairs.com/medal-knight-1-max-and-the-robot/", "take": "Max's robotics genius is being exploited for illegal ends by his own school's owner — will he keep his head down or refuse? A comic that pits conscience against ambition, made for young tech-minded readers."}, {"id": 2393, "title": "Medal Knight 2: Max: Medal Knight!", "url": "https://store.ignatiusbookfairs.com/medal-knight-2-max-medal-knight/", "take": "Max dons armor salvaged from his old robot and storms Gustave's headquarters to rescue his mom — but now the whole family is in the tyrant's crosshairs. Fast-moving, high-stakes fun for kids who like their heroes scrappy."}, {"id": 2850, "title": "Medal Knight 3:  Attack of the Robots!", "url": "https://store.ignatiusbookfairs.com/medal-knight-3-attack-of-the-robots-ibc-1614/", "take": "Max versus killer robots of his own creation in round three of this Catholic comic series. High-action, clean fun with a hero kids genuinely root for."}, {"id": 1113, "title": "Medal of Honor: Ryan Pitts: Afghanistan", "url": "https://store.ignatiusbookfairs.com/medal-of-honor-ryan-pitts-afghanistan/", "take": "The true story of Staff Sergeant Ryan Pitts, badly wounded at the Battle of Wanat yet helping turn back 200 insurgents — actions that earned the Medal of Honor. Sober, real-life heroism for young readers of this series."}, {"id": 2775, "title": "Mega-Predators of the Past", "url": "https://store.ignatiusbookfairs.com/mega-predators-of-the-past-ibc-1542/", "take": "Beyond T. rex: terror birds, giant ripper lizards, and the prehistoric predators nobody tells kids about. Melissa Stewart's science writing turns dino-obsessed readers into genuine junior paleontologists."}, {"id": 1769, "title": "Memento Mori Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/memento-mori-vinyl-sticker/", "take": "A vinyl sticker carrying the ancient Christian watchword, memento mori — remember your death. Not gloomy but clarifying, a small daily nudge to live for what actually lasts. A simple gift with centuries of wisdom behind it."}, {"id": 1794, "title": "Memory Match Game - Marvelous Men Series 1", "url": "https://store.ignatiusbookfairs.com/memory-match-game-marvelous-men-series-1/", "take": "A memory-match card game from the Marvelous Men series. Classic flip-and-find concentration play — simple to learn, screen-free, and easy to pull out at a family table or in a classroom quiet corner."}, {"id": 2223, "title": "Merci Suarez Changes Gears", "url": "https://store.ignatiusbookfairs.com/merci-suarez-changes-gears/", "take": "Merci Suarez has never quite fit in at her Florida private school, and sixth grade brings changes she didn't see coming. This Newbery Medal winner is warm, funny, and true about family. An easy, confident recommendation."}, {"id": 2220, "title": "Mercy Watson Goes for a Ride", "url": "https://store.ignatiusbookfairs.com/mercy-watson-goes-for-a-ride/", "take": "Mercy the pig loves nothing more than a ride in the convertible, preferably from the driver's seat. The porcine wonder's hilarious adventure delivers reliable laughs for kids just graduating from picture books to chapters."}, {"id": 2765, "title": "Mercy Watson Princess in Disguise", "url": "https://store.ignatiusbookfairs.com/mercy-watson-princess-in-disguise-ibc-1540/", "take": "The Watsons zip their porcine wonder into a princess dress for Halloween; Mercy just wants the treats. The neighbors' cat sets off a hysterical nighttime parade. Reliably silly fun for young readers."}, {"id": 1823, "title": "Mercy Watson to the Rescue", "url": "https://store.ignatiusbookfairs.com/mercy-watson-to-the-rescue/", "take": "Mercy the pig loves buttered toast and snuggling into the Watsons' bed — right up until the bed starts sinking through the floor. Kate DiCamillo's porcine wonder launches a series early readers genuinely adore. Reliable giggles, gentle text."}, {"id": 1458, "title": "Michelangelo", "url": "https://store.ignatiusbookfairs.com/michelangelo/", "take": "Diane Stanley's thoroughly researched picture-book biography captures Michelangelo whole: the towering brilliance in paint, marble, and architecture, and the turbulent, quarrelsome perfectionist behind it. Art history that treats young readers like intelligent people."}, {"id": 2845, "title": "Million Dollar Throw", "url": "https://store.ignatiusbookfairs.com/million-dollar-throw-mike-lupica-ibc-1613/", "take": "Nate 'Brady' Brodie gets one million-dollar throw while his family teeters on losing everything. Lupica at his best: real sports, real stakes, real heart. Reluctant-reader gold for 10-14s."}, {"id": 2396, "title": "Mind Your Manners, Dinosaurs  - board book", "url": "https://store.ignatiusbookfairs.com/mind-your-manners-dinosaurs-board-book/", "take": "Dinnertime for dinosaurs means toys put away and everyone at the table. Lift-the-flaps and die-cut pages let toddlers follow along as each dinosaur shows off mealtime manners — a clever, sturdy way to start the conversation early."}, {"id": 1656, "title": "Mindwar", "url": "https://store.ignatiusbookfairs.com/mindwar/", "take": "A star quarterback loses the ability to walk in a car accident, then discovers his gaming skill might make him a different kind of hero. A high-stakes thriller premise for teens who want action with heart."}, {"id": 2819, "title": "Minecrafter's Cookbook", "url": "https://store.ignatiusbookfairs.com/minecrafters-cookbook-ibc-1628/", "take": "Over 40 Minecraft-themed recipes designed for kids and parents to make together - clearly labeled unofficial, and clearly aimed at what young gamers will actually be excited to cook. A clever hook for family kitchen time."}, {"id": 1770, "title": "Mini St. Michael the Archangel Plush Doll", "url": "https://store.ignatiusbookfairs.com/mini-st-michael-the-archangel-plush-doll/", "take": "A small, huggable version of the great archangel. For the child who loves St. Michael, or the parent who wants the heavenly protector close by at naptime, this mini plush makes the warrior angel approachably soft."}, {"id": 2266, "title": "Miss Rumphius", "url": "https://store.ignatiusbookfairs.com/miss-rumphius/", "take": "Alice Rumphius wants to travel the world, live by the sea, and do something to make the world more beautiful — and the lupines say she succeeds. Barbara Cooney's beloved classic resonates with every new generation."}, {"id": 1038, "title": "Misty of Chincoteague", "url": "https://store.ignatiusbookfairs.com/misty-of-chincoteague/", "take": "Marguerite Henry's Newbery Honor classic about two children determined to win Phantom, the wild mare no one can capture, on Pony Penning Day. Warm, windswept, and beloved for good reason — hand it to any horse-loving child."}, {"id": 1893, "title": "Moby Dick", "url": "https://store.ignatiusbookfairs.com/moby-dick/", "take": "A sea adventure, a study of evil, and a crazed captain hunting the whale that maimed him. This critical edition looks at Melville's tragic tale afresh, with the background to help students navigate its depths. A rewarding challenge."}, {"id": 2526, "title": "Mont-Saint-Michel: Seek and Find Volume 6", "url": "https://store.ignatiusbookfairs.com/mont-saint-michel-seek-and-find-volume-6/", "take": "Seek-and-find fun set at medieval Mont-Saint-Michel: kids hunt for Sarah, Simon, two cats, and a goat while absorbing the story of the famous Benedictine abbey. History, faith, and busy-page searching in one handsome volume."}, {"id": 880, "title": "More Once Upon a Time Saints", "url": "https://store.ignatiusbookfairs.com/more-once-upon-a-time-saints/", "take": "Ethel Pochocki's follow-up collection of wonderfully odd saints - Hyacinth, Zita, Longinus, Kentigern - told with warmth and vivid immediacy. She makes them real people with a \"preposterous\" passion for God, which is exactly what keeps kids reading."}, {"id": 2126, "title": "Mossflower: Redwall #2", "url": "https://store.ignatiusbookfairs.com/mossflower-redwall-2/", "take": "The beloved Redwall saga continues in Mossflower Wood, where gentle creatures face cunning villains in another epic tale full of the series' trademark valor and personality. A natural next step for readers hooked by book one."}, {"id": 1535, "title": "Most Holy Rosary Coloring Book", "url": "https://store.ignatiusbookfairs.com/most-holy-rosary-coloring-book/", "take": "Line drawings after the great masters walk children through the mysteries of the Rosary as they color, adding depth and meaning to a prayer many families already say together. Simple, beautiful, and genuinely useful for family devotion."}, {"id": 1453, "title": "Mother Cabrini: Missionary to the World", "url": "https://store.ignatiusbookfairs.com/mother-cabrini-missionary-to-the-world/", "take": "Frances Cabrini crossed the ocean 37 times, founded the Missionary Sisters of the Sacred Heart, and became the first canonized saint of the United States. This Vision book gives 9-15 year olds her story as the adventure it truly was."}, {"id": 1092, "title": "Mother of God Coloring Book", "url": "https://store.ignatiusbookfairs.com/mother-of-god-coloring-book/", "take": "Thirty-five finely drawn images of Our Lady — Guadalupe, Fatima, Czestochowa, Perpetual Help — each accompanied by a short story of the shrine or miraculous image. Catechesis and crayons in one lovely package."}, {"id": 1514, "title": "Mother Seton and the Sisters of Charity", "url": "https://store.ignatiusbookfairs.com/mother-seton-and-the-sisters-of-charity/", "take": "America's first native-born saint: Elizabeth Bayley Seton's road from a well-to-do Protestant New York family through marriage, five children, and tragedy to founding an order of sisters. A Vision Book true story with more turns than most novels."}, {"id": 1494, "title": "Mother Teresa of Calcutta", "url": "https://store.ignatiusbookfairs.com/mother-teresa-of-calcutta/", "take": "Fr. Leo Maasburg traveled the world for years as Mother Teresa's close companion, and this account draws on what he witnessed at her side. The Albanian girl who became the Angel of the Poor, seen up close — for teens and adults."}, {"id": 1585, "title": "Mother Teresa: Smile of Calcutta", "url": "https://store.ignatiusbookfairs.com/mother-teresa-smile-of-calcutta/", "take": "A beautifully illustrated introduction to Mother Teresa, whose comforting smile and compassionate hands carried the light of Jesus into Calcutta's poorest streets. Part of a series helping children discover holiness as a genuine adventure — this one from our own times."}, {"id": 946, "title": "Mozart: Gift from God", "url": "https://store.ignatiusbookfairs.com/mozart-gift-from-god/", "take": "Demi's lavishly illustrated life of Mozart covers the whole arc - prodigy childhood, family life, and fame as a composer - while taking seriously the Catholic faith that shaped his character. A handsome introduction to perhaps the greatest composer ever."}, {"id": 2271, "title": "Mr. Willowby's Christmas Tree", "url": "https://store.ignatiusbookfairs.com/mr-willowbys-christmas-tree/", "take": "Mr. Willowby's Christmas tree is too tall, so the trimmed top gets passed along — again and again — spreading cheer through a whole forest of critters. A cozy classic about how one tree, shared, becomes many joys."}, {"id": 1483, "title": "Mummies, Gods, and Pharaohs", "url": "https://store.ignatiusbookfairs.com/mummies-gods-and-pharaohs/", "take": "Pharaohs, pyramids, the Book of the Dead, and Howard Carter stepping into Tutankhamun's tomb, illustrated from tomb paintings and museum finds. Irresistible browsing for the kid currently obsessed with mummies — which is most of them, eventually."}, {"id": 2153, "title": "Murder at Penwood Manor (Harwood Mysteries #5)", "url": "https://store.ignatiusbookfairs.com/murder-at-penwood-manor-harwood-mysteries-5/", "take": "A Crusader returns from the Holy Land, a brutal murder follows, and everyone assumes his guilt except Xan. Medieval mystery with genuine moral and spiritual questions underneath the whodunit; a strong installment in this award-winning Catholic series."}, {"id": 1680, "title": "My America: a Poetry Atlas of the United States", "url": "https://store.ignatiusbookfairs.com/my-america-a-poetry-atlas-of-the-united-states/", "take": "Fifty poems arranged by region build a portrait of the whole country, from Northeast seacoast to redwood forest. Lee Bennett Hopkins' anthology pairs naturally with geography lessons — an atlas you can read aloud."}, {"id": 1974, "title": "My Antarctica: True Adventures in the Land of Mummified Seals, Space Robots, and So Much More", "url": "https://store.ignatiusbookfairs.com/my-antarctica-true-adventures-in-the-land-of-mummified-seals-space-robots-and-so-much-more/", "take": "G. Neri finally reaches the continent of his dreams and brings kids along — mummified seals, sea angels, space robots, lava-bomb warnings and all. Lively true-adventure nonfiction that makes the coldest, driest place on Earth feel thrillingly close."}, {"id": 1072, "title": "My Book of Little House Paper Dolls: The Big Woods Collection", "url": "https://store.ignatiusbookfairs.com/my-book-of-little-house-paper-dolls-the-big-woods-collection/", "take": "Laura, Mary, Baby Carrie, Ma, Pa, and Jack the bulldog as sturdy card-stock paper dolls. A simple, screen-free playtime package for young Little House fans who want to step into the Big Woods themselves."}, {"id": 1731, "title": "My Catholic Bible", "url": "https://store.ignatiusbookfairs.com/my-catholic-bible/", "take": "The important stories of both Testaments retold in easy-to-read language with inviting illustrations, plus historical background and key-term definitions. A well-built first Bible for introducing a child to the Word of God."}, {"id": 1015, "title": "My Family and Other Skaters", "url": "https://store.ignatiusbookfairs.com/my-family-and-other-skaters/", "take": "A big, modern English family with six competitive figure skaters and a pet alpaca weathers life's storms with clumsy, believable patience. Realistic, funny, and warm — family fiction with actual texture."}, {"id": 1471, "title": "My First Bedtime Prayers", "url": "https://store.ignatiusbookfairs.com/my-first-bedtime-prayers/", "take": "Opens with the Our Father, then adds tender original prayers meant to be said with a parent at day's end. Sweet full-color pictures and a calm tone make this a gentle way to close the evening near each other and God."}, {"id": 1518, "title": "My First Catechism: The Catholic Faith for Little Ones", "url": "https://store.ignatiusbookfairs.com/my-first-catechism-the-catholic-faith-for-little-ones/", "take": "A board-book catechism for ages 2 and up: basic prayers, holidays, and big ideas like forgiveness, carried by sweet illustrations and genuinely simple text. A first taste of the faith sized for the littlest hands."}, {"id": 1068, "title": "My First Dance Ballet", "url": "https://store.ignatiusbookfairs.com/my-first-dance-ballet/", "take": "From the five basic positions to first steps to performance time, ballet basics told through beautiful photographs of a diverse cast of young dancers. A charming first book for the littlest aspiring dancers."}, {"id": 1411, "title": "My First Easter (board book)", "url": "https://store.ignatiusbookfairs.com/my-first-easter-board-book/", "take": "Tomie dePaola walks little ones through Easter traditions with bright illustrations and easy text, in a board book sized for small hands. A natural for the Easter basket - family and sharing at its heart."}, {"id": 1061, "title": "My First Hockey Book", "url": "https://store.ignatiusbookfairs.com/my-first-hockey-book/", "take": "One word per page, one big photo, and a wonderfully grabbable embossed cover — hockey vocabulary from \"hockey stick\" to \"GOAL!\" A sweet, sturdy first sports book for parents to share with toddlers."}, {"id": 1432, "title": "My First Holy Communion", "url": "https://store.ignatiusbookfairs.com/my-first-holy-communion/", "take": "A First Communion preparation book that is genuinely beautiful: Bible stories, Church history, and the sacraments woven together in gifted writing and vibrant illustration, leading child and parent alike into the mystery of the Eucharist."}, {"id": 2786, "title": "My First Lift and Slide Bible", "url": "https://store.ignatiusbookfairs.com/my-first-lift-and-slide-bible-ibc-6flsbh/", "take": "Eight Bible stories toddlers can move — wheels to slide, flaps to lift, scenes that unfold. A first Bible that gets loved to pieces, in the best way."}, {"id": 2860, "title": "My First Picture Reader", "url": "https://store.ignatiusbookfairs.com/my-first-picture-reader/", "take": "Twenty-two New Testament stories, from Bethlehem to Easter to Pentecost, told with large print and small pictures that help children recognize words. Builds reading confidence and introduces Jesus at the same time - a lovely two-for-one."}, {"id": 1468, "title": "My First Pictures of Mary", "url": "https://store.ignatiusbookfairs.com/my-first-pictures-of-mary/", "take": "A rounded-corner board book walking toddlers through key moments of Mary's life — one large scene per spread, with smaller detail pictures to point at and name together. A lovely, low-pressure way to begin knowing the mother of Jesus."}, {"id": 1433, "title": "My First Prayers for My Family", "url": "https://store.ignatiusbookfairs.com/my-first-prayers-for-my-family/", "take": "Simple prayers celebrating family life for the very young - thanksgiving for parents and baptism, gentle petitions for pardon and for departed loved ones - with charming four-color pictures throughout."}, {"id": 1446, "title": "My First Prayers for the Whole Year", "url": "https://store.ignatiusbookfairs.com/my-first-prayers-for-the-whole-year/", "take": "Twenty-nine simple prayers for morning, bedtime, ordinary days, and holy days, with Maite Roche's sweet illustrations. An easy, warm way to make prayer a daily habit for the littlest members of the family."}, {"id": 1447, "title": "My First Prayers With Mary", "url": "https://store.ignatiusbookfairs.com/my-first-prayers-with-mary/", "take": "Tender first prayers to the Blessed Mother, opening with the Hail Mary and adding sweet original petitions that draw little ones toward Jesus. Soft four-color pictures suit laps and bedtimes — a gentle first Marian book for the very young."}, {"id": 2247, "title": "My First Thanksgiving", "url": "https://store.ignatiusbookfairs.com/my-first-thanksgiving/", "take": "Tomie dePaola's simple text and bright illustrations introduce the traditions and joy of Thanksgiving for the very youngest readers. A sweet, unfussy first look at the holiday."}, {"id": 965, "title": "My Five Senses", "url": "https://store.ignatiusbookfairs.com/my-five-senses/", "take": "Aliki's simple text and warm artwork walk young children through sight, smell, taste, hearing, and touch. A gentle classic that works equally well at home and in an early elementary classroom."}, {"id": 1732, "title": "My Golden Book of Prayers", "url": "https://store.ignatiusbookfairs.com/my-golden-book-of-prayers/", "take": "Twenty-two well-loved prayers set in large, easy-to-read type with vibrant artwork — a simple, beautiful introduction to devotional life for young Catholic children, and a natural gift book."}, {"id": 1821, "title": "My Little Church Magnet Play Set", "url": "https://store.ignatiusbookfairs.com/my-little-church-magnet-play-set/", "take": "A magnet play set on a little-church theme: arrange, rearrange, repeat. Screen-free quiet play that helps make church a familiar, friendly place for young children. Simple concept, easy yes."}, {"id": 1070, "title": "My Little House Crafts Book: 18 Projects from Laura Ingalls Wilder's Little House Stories", "url": "https://store.ignatiusbookfairs.com/my-little-house-crafts-book-18-projects-from-laura-ingalls-wilders-little-house-stories/", "take": "Eighteen pioneer crafts straight from the Little House books — the very things Laura's family made because stores were far and money was short. A hands-on companion that turns beloved stories into a satisfying afternoon's work."}, {"id": 1542, "title": "My Picture Book of the Bible", "url": "https://store.ignatiusbookfairs.com/my-picture-book-of-the-bible/", "take": "A gentle first walk through the Bible for the youngest listeners — essential stories simply told and captivatingly illustrated. A lovely way to let a small child linger over the great stories of faith, one page at a time."}, {"id": 1526, "title": "My Picture Book of the Catholic Faith", "url": "https://store.ignatiusbookfairs.com/my-picture-book-of-the-catholic-faith/", "take": "Maite Roche brings Bible stories, the seven sacraments, and Christian living to little ones in colorful pictures and simple words. Roche has a rare knack for sharing the faith with warmth and imagination — a lovely all-in-one starter."}, {"id": 1828, "title": "My Pop Out Mass Kit", "url": "https://store.ignatiusbookfairs.com/my-pop-out-mass-kit/", "take": "A pop-out Mass kit for pretend play. Children learn the liturgy by doing, and playing Mass at home is an old Catholic tradition worth keeping alive. The imaginative payoff, not the cardboard, is the point."}, {"id": 1844, "title": "My Pop Out Nativity Set", "url": "https://store.ignatiusbookfairs.com/my-pop-out-nativity-set/", "take": "Unfold, assemble, and recreate the first Christmas: sturdy illustrated cardboard pieces, a trifold background, an educational insert, and a vinyl storage bag. For ages 3 and up — a nativity that little hands are actually allowed to touch."}, {"id": 1487, "title": "My Prayer Book", "url": "https://store.ignatiusbookfairs.com/my-prayer-book/", "take": "Prayer presented to children as a heart-to-heart talk with a loving Father — why we pray, how, where, and when — followed by prayers for all occasions and church seasons. A formation book, not just a collection, and a gentle one."}, {"id": 1923, "title": "My Uncle Fulton Sheen", "url": "https://store.ignatiusbookfairs.com/my-uncle-fulton-sheen/", "take": "Joan Sheen Cunningham's memoir of the uncle who became her second father: Bishop Fulton Sheen, who brought her to school in New York and into a lifetime of formative moments, from coat shopping to meeting the governor. Charming firsthand history."}, {"id": 2176, "title": "Mysteries at Gloria Circus", "url": "https://store.ignatiusbookfairs.com/mysteries-at-gloria-circus/", "take": "Garrett, a nine-year-old circus juggler, keeps receiving mysterious riddle-filled notes from someone who knows too much about his parents. Regina Medal winner Sophie de Mullenheim lets readers solve the puzzles right alongside Garrett, Grace, and Jack. Satisfying mystery."}, {"id": 1917, "title": "Mysteries Made Visible: Praying the Rosary With Sacred Art", "url": "https://store.ignatiusbookfairs.com/mysteries-made-visible-praying-the-rosary-with-sacred-art/", "take": "Fr. Lawrence Lew pairs his stunning photographs of sacred art with rich contemplations on all twenty Mysteries of the Rosary. For faithful daily pray-ers and for those still warming up to the Rosary alike, this makes the Mysteries vivid."}, {"id": 2122, "title": "Mysterious Benedict Society", "url": "https://store.ignatiusbookfairs.com/mysterious-benedict-society/", "take": "A peculiar newspaper ad, a gauntlet of mind-bending tests readers get to solve along the way, and four gifted children on an undercover mission. The award-winning series opener remains a reliable hook for clever middle graders."}, {"id": 2131, "title": "Mysterious Benedict Society and the Perilous Journey", "url": "https://store.ignatiusbookfairs.com/mysterious-benedict-society-and-the-perilous-journey/", "take": "The gifted foursome's mind-bending tests and secret missions continue in this Mysterious Benedict Society adventure. More puzzles for readers to work alongside the characters — the series' signature pleasure, delivered again."}, {"id": 2127, "title": "Mysterious Benedict Society and the Prisoner's Dilemma", "url": "https://store.ignatiusbookfairs.com/mysterious-benedict-society-and-the-prisoners-dilemma/", "take": "The quartet reunites — plus a new Society member — to face Mr. Curtain and a telepathic enemy tracking their every move. More dangerous dilemmas and irresistible adventure for readers who loved the earlier missions."}, {"id": 2135, "title": "Mysterious Benedict Society and the Riddle of Ages", "url": "https://store.ignatiusbookfairs.com/mysterious-benedict-society-and-the-riddle-of-ages/", "take": "Reynie, Sticky, Kate, and Constance reunite to welcome a new Society member and face a telepathic enemy — with Mr. Curtain as villainous as ever. Familiar pleasures for fans: dangerous dilemmas, clever kids, irresistible adventure."}, {"id": 910, "title": "Nana Upstairs and Nana Downstairs", "url": "https://store.ignatiusbookfairs.com/nana-upstairs-and-nana-downstairs/", "take": "Four-year-old Tommy loves his Nana Upstairs - and then one day she is gone. DePaola's classic handles a grandparent's death with rare honesty and comfort. One of the best books there is for a child facing this loss."}, {"id": 1532, "title": "Nate the Great", "url": "https://store.ignatiusbookfairs.com/nate-the-great/", "take": "The case that starts it all: Nate the Great takes on the mystery of the lost picture, and beginning readers problem-solve right alongside him. A long-running early chapter series for good reason — logical thinking disguised as fun."}, {"id": 1511, "title": "Nate the Great Goes Undercover", "url": "https://store.ignatiusbookfairs.com/nate-the-great-goes-undercover/", "take": "Someone is raiding Oliver's garbage can nightly, and Nate goes undercover — under the garbage can lid, naturally. Early chapter-book mystery that lets beginning readers deduce right alongside Nate, with fun activities in the back."}, {"id": 2172, "title": "Navidad: !Jesus ha nacido!", "url": "https://store.ignatiusbookfairs.com/navidad-jesus-ha-nacido/", "take": "The story of the first Christmas, told in Spanish with warmth by Sister Marlyn Monge and beautifully illustrated for ages 3-8. A lovely way to keep the birth of Jesus at the heart of the season for Spanish-speaking families."}, {"id": 2473, "title": "Near: Psalm 139", "url": "https://store.ignatiusbookfairs.com/near-psalm-139/", "take": "From Sally Lloyd-Jones of The Jesus Storybook Bible, a lyrical picture book built on Psalm 139. Its gentle refrain — God sees me, knows me, is near me — is exactly the reassurance little explorers need at bedtime."}, {"id": 969, "title": "Nest Full of Eggs", "url": "https://store.ignatiusbookfairs.com/nest-full-of-eggs/", "take": "A full year with a robin family: eggs in spring, fledglings in summer, first flights in fall. Named a best children's science book by Science Books & Films, and it earns the distinction."}, {"id": 1722, "title": "New Kid", "url": "https://store.ignatiusbookfairs.com/new-kid/", "take": "Jerry Craft's award-winning graphic novel follows Jordan Banks, one of the few kids of color at his prestigious new school, drawing cartoons about the struggle to fit in. Timely, honest, and hugely readable for middle schoolers."}, {"id": 1747, "title": "New Testament and Psalms (RSV)", "url": "https://store.ignatiusbookfairs.com/new-testament-and-psalms-rsv/", "take": "The Ignatius RSV New Testament and Psalms in a fresh new design, with archaic language gently updated. A portable, contemporary-English option well suited to backpacks, desks, and daily Scripture reading."}, {"id": 1725, "title": "Night of the Twisters: The Most Dangerous Night of Their Lives", "url": "https://store.ignatiusbookfairs.com/night-of-the-twisters-the-most-dangerous-night-of-their-lives/", "take": "Twelve-year-old Dan and his best friend shrug off another Nebraska tornado watch — until the storm arrives and surviving it is only the beginning. A gripping disaster story pitched just right for middle-grade readers."}, {"id": 1462, "title": "Nightmare City", "url": "https://store.ignatiusbookfairs.com/nightmare-city/", "take": "Tom, a high school newspaper reporter, wakes to empty streets, a strange sea fog, and something evil and hungry moving inside it. A fast, atmospheric thriller for teens who want genuine suspense — save it for readers who can handle the scares."}, {"id": 2031, "title": "Noah and the Ark", "url": "https://store.ignatiusbookfairs.com/noah-and-the-ark/", "take": "Tomie dePaola's imaginative artwork gives the flood story fresh life in this warm retelling — Noah, the ark, the animals two by two, and forty days of rain. A lovely read-aloud from a beloved storyteller."}, {"id": 899, "title": "Noah's Ark", "url": "https://store.ignatiusbookfairs.com/noahs-ark/", "take": "Peter Spier's Caldecott Medal-winning Noah's Ark, in print continuously since 1977 - and deservedly so. His detailed scenes hold both the grandeur of the flood and the comedy of shipboard life. The definitive picture-book edition of this story."}, {"id": 2013, "title": "Noah's Ark Alphabet Poster", "url": "https://store.ignatiusbookfairs.com/noahs-ark-alphabet-poster/", "take": "Alphabet practice meets Noah's ark: each letter gets its matching pair of animals, from alpaca to narwhal, capped with \"All Creatures Great and Small, the Lord God made them all.\" Two lessons on one cheerful poster."}, {"id": 2143, "title": "North! Or be Eaten: The Wingfeather Saga Book #2", "url": "https://store.ignatiusbookfairs.com/north-or-be-eaten-the-wingfeather-saga-book-2/", "take": "Now that the Igibys know they're the Lost Jewels of Anniera, everyone wants them dead. The flight to the Ice Prairies runs through forest monsters and thieving Stranders — book two moves fast and cuts deeper."}, {"id": 1065, "title": "Nothing but Trouble: The Story of Althea Gibson", "url": "https://store.ignatiusbookfairs.com/nothing-but-trouble-the-story-of-althea-gibson/", "take": "Everyone calls Althea nothing but trouble — until a Harlem play leader watches her play paddle tennis and sees pure possibility. The stirring picture-book story of the first African American to compete at and win Wimbledon."}, {"id": 1797, "title": "Nothing is Far from God Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/nothing-is-far-from-god-vinyl-sticker/", "take": "A vinyl sticker with a line worth keeping close: nothing is far from God. A small, giftable reassurance for a locker, a notebook, or wherever a hard day might happen to find it."}, {"id": 912, "title": "Now One Foot, Now the Other", "url": "https://store.ignatiusbookfairs.com/now-one-foot-now-the-other/", "take": "Grandpa Bob teaches Bobby to walk; after a stroke, Bobby teaches him. One of dePaola's most beloved stories, now in a larger full-color edition. A tender, honest book about disability, patience, and what family members do for each other."}, {"id": 2240, "title": "Nuestra Senora de Guadelupe", "url": "https://store.ignatiusbookfairs.com/nuestra-senora-de-guadelupe/", "take": "Tomie dePaola tenderly retells Juan Diego's encounter with Our Lady of Guadalupe, drawn from original sources — the miraculous image on a poor man's cloak and a defining moment in Mexico's history. En espanol, and lovely for sharing aloud."}, {"id": 2831, "title": "Nutcracker Mice", "url": "https://store.ignatiusbookfairs.com/nutcracker-mice-ibc-1549/", "take": "Esmeralda, a young mouse ballerina hidden in the Mariinsky Theater, lands the lead in a Christmas Nutcracker - despite an unruly tail. A charming holiday tale with backstage sparkle, from the author of The Gingerbread Pirates."}, {"id": 1714, "title": "Old Hat New Hat", "url": "https://store.ignatiusbookfairs.com/old-hat-new-hat/", "take": "Brother Bear tries frilly hats, silly hats, bumpy and lumpy hats before landing on the most perfect hat of all — his own. A simple, funny concept book with a quietly good message about contentment."}, {"id": 2137, "title": "On My Way (26 Fairmount Avenue Series #4)", "url": "https://store.ignatiusbookfairs.com/on-my-way-26-fairmount-avenue-series-4/", "take": "Baby sister Maureen finally comes home, there's a dance recital and a trip to the World's Fair, and Tomie counts the days until first grade — when he'll finally learn to read. Cozy, true-life storytelling at its gentlest."}, {"id": 2140, "title": "On the Edge of the Dark Sea of Darkness: Wingfeather Saga #1", "url": "https://store.ignatiusbookfairs.com/on-the-edge-of-the-dark-sea-of-darkness-wingfeather-saga-1/", "take": "Janner, Tink, and Leeli Igiby hold the secret to a lost kingdom — and the venomous Fangs of Dang are hunting them. The Wingfeather Saga opens with rich characters, real menace, and a family worth rooting for."}, {"id": 1790, "title": "On the Way to Santiago de Compostela: Seek and Find Volume 3", "url": "https://store.ignatiusbookfairs.com/on-the-way-to-santiago-de-compostela-seek-and-find-volume-3/", "take": "A seek-and-find journey down the medieval pilgrimage road to Santiago de Compostela, spotting Sara and Simon, a teacher and his daughter, two cats, and Gil the goat along the way. Painless history and long, happy poring over pages."}, {"id": 2803, "title": "Once a Castle", "url": "https://store.ignatiusbookfairs.com/once-upon-a-castle-ibc-1575/", "take": "The sequel to Christy Award finalist Once a Queen: portals to the magical land of Ternival are fraying, and a new generation's discoveries will change two worlds. Rich, wonder-driven fantasy in the classic portal tradition."}, {"id": 2795, "title": "Once A Queen", "url": "https://store.ignatiusbookfairs.com/once-upon-a-queen-ibc-1574/", "take": "A manor house, fading portals, family secrets — Narnia's tradition carried forward with real craft. A Christy finalist we happily hand to Lewis and L'Engle kids, roughly 10-14."}, {"id": 2228, "title": "Once upon a Map Book", "url": "https://store.ignatiusbookfairs.com/once-upon-a-map-book/", "take": "What if fairy tales came with maps? Pore over Neverland, Oz, Wonderland, and the Giant's kingdom atop the beanstalk in charted detail. A clever browse-for-hours book for kids who love both stories and geography."}, {"id": 2805, "title": "One For The Dogs", "url": "https://store.ignatiusbookfairs.com/one-for-the-dogs-ibc-1625/", "take": "When Abuela sprains her ankle, Resa's Brooklyn summer needs a new plan - and she's exactly the kid to make one. A graphic novel series with Baby-Sitters Club appeal and a bright entrepreneurial streak."}, {"id": 2463, "title": "Oscar and the Moth: A Book About Light and Dark", "url": "https://store.ignatiusbookfairs.com/oscar-and-the-moth-a-book-about-light-and-dark/", "take": "Oscar the kitten watches the sunset and wonders about light and dark — and Moth explains stars, fireflies, shadows, and why night comes. A friendly first science book with story appeal and lesson ideas built in."}, {"id": 1911, "title": "Othello", "url": "https://store.ignatiusbookfairs.com/othello/", "take": "Among the darkest of Shakespeare's four great tragedies, a cautionary tale of sin, bad philosophy, and the gloomiest recesses of the human psyche. This critical edition helps students see what Shakespeare was raging against. Strong classroom support."}, {"id": 2816, "title": "Our Family is Growing", "url": "https://store.ignatiusbookfairs.com/our-family-is-growing-ibc-6ofgh/", "take": "Mother Bunny's belly is growing, and young Henry worries about his place in her heart. A gentle, reassuring read for families expecting a new baby - the worry is honest, and the answer is love."}, {"id": 1557, "title": "Our Lady Came to Fatima", "url": "https://store.ignatiusbookfairs.com/our-lady-came-to-fatima/", "take": "The story of Fatima told warmly for young readers: Lucia, Jacinta, and Francisco, the surprised little shepherds of 1917, plus scornful neighbors and puzzled parents. The 27th Vision Books volume keeps the focus on the children who insisted on the truth."}, {"id": 1756, "title": "Our Lady of Guadalupe Charm", "url": "https://store.ignatiusbookfairs.com/our-lady-of-guadalupe-charm/", "take": "A small charm honoring Our Lady of Guadalupe, whose miraculous image appeared on Juan Diego's tilma in 1531 and is enshrined in Mexico City today. A sweet, tangible reminder of a beloved apparition."}, {"id": 1773, "title": "Our Lady's Wardrobe", "url": "https://store.ignatiusbookfairs.com/our-ladys-wardrobe/", "take": "A rhyming introduction to Mary told through her clothes — from her poor life in Nazareth to the dresses, veils, and crowns of her heavenly wardrobe. A playful, kid-sized doorway into the Church's long love for Our Lady."}, {"id": 1734, "title": "Our Parish Church", "url": "https://store.ignatiusbookfairs.com/our-parish-church/", "take": "Father Jude Winkler walks children through everything they see at church — crucifix, tabernacle, altar — with clear explanations and vibrant illustrations. A practical St. Joseph Picture Book that makes Mass more familiar and less mysterious."}, {"id": 966, "title": "Our Solar System", "url": "https://store.ignatiusbookfairs.com/our-solar-system/", "take": "A first tour of the solar system with a clever twist: graduated flaps present the sun and each planet in order, hiding facts underneath. A satisfying format for the youngest astronomers."}, {"id": 1519, "title": "Owls in the Family", "url": "https://store.ignatiusbookfairs.com/owls-in-the-family/", "take": "Farley Mowat's story of a boy whose menagerie — crows, magpies, gophers, a dog — grows by two cantankerous pet owls who turn the town upside down. Warm, funny animal storytelling with real adventure and suspense in it."}, {"id": 2755, "title": "Paddington and the Magic Trick", "url": "https://store.ignatiusbookfairs.com/paddington-and-the-magic-trick-ibc-1553/", "take": "Paddington's birthday magic trick goes predictably, delightfully awry. A Level One I Can Read starring Michael Bond's beloved bear — just right for children sounding out their first words and sentences, with charm to spare."}, {"id": 2748, "title": "Paint By Sticker Outer Space", "url": "https://store.ignatiusbookfairs.com/paint-by-sticker-outer-space-ibc-1536/", "take": "Ten mess-free sticker paintings of rovers, shuttles, and planets — with glow-in-the-dark stickers and a science fact behind every image. Screen-free focus time that ends with art worth hanging up."}, {"id": 1679, "title": "Painters: Masters of Western Art", "url": "https://store.ignatiusbookfairs.com/painters-masters-of-western-art/", "take": "A Fandex field guide to the great painters, Giotto to Frank Stella, full of human stories — Michelangelo resenting the Sistine Chapel, Vermeer languishing in obscurity. Art history in a browsable, flip-through form kids actually enjoy."}, {"id": 2192, "title": "Peek Inside Christmas", "url": "https://store.ignatiusbookfairs.com/peek-inside-christmas/", "take": "Lift the flaps and peek through holes into Santa's workshop, meet the reindeer, and catch Santa snoozing on Christmas morning. Interactive board-book fun for the littlest hands; expect it to be read until the flaps wear soft."}, {"id": 1648, "title": "People on the Go Mazes", "url": "https://store.ignatiusbookfairs.com/people-on-the-go-mazes/", "take": "Kids guide a bus driver to school, a princess to her castle, and a cowboy back to his horse across dozens of lively mazes, with brief captions setting each goal and solutions in the back. Dependable quiet-time fun."}, {"id": 2768, "title": "Pete the Cat and the Mars Mission", "url": "https://store.ignatiusbookfairs.com/pete-the-cat-and-the-mars-mission-ibc-1555/", "take": "Pete stays groovy even on Mars. Short sentences, familiar words, and original Dean-family art make this a confidence-builder for brand-new readers — Level 1 in the best sense."}, {"id": 1424, "title": "Peter, Apostle of Jesus", "url": "https://store.ignatiusbookfairs.com/peter-apostle-of-jesus/", "take": "Peter meant to be a fisherman like his father; then he met Jesus. This beautifully illustrated Life of a Saint picture book brings the apostle's Bible story to life page by page for children."}, {"id": 902, "title": "Petook", "url": "https://store.ignatiusbookfairs.com/petook/", "take": "An unusual and moving Easter book: Petook the rooster watches the child Jesus admire his chicks, then years later senses something momentous on Calvary's hill. A gentle, oblique way into the Passion for young children, with dePaola's warm art."}, {"id": 1739, "title": "Philip and the Ethiopian (Felipe y el etiope)", "url": "https://store.ignatiusbookfairs.com/philip-and-the-ethiopian-felipe-y-el-etiope/", "take": "The Acts story of Philip and the Ethiopian traveler who believed but could not understand the Scripture he was reading — until God sent someone to explain. A simple retelling of one of the Bible's great evangelization moments."}, {"id": 1683, "title": "Philip Hall Likes Me. I Reckon Maybe", "url": "https://store.ignatiusbookfairs.com/philip-hall-likes-me-i-reckon-maybe/", "take": "A Newbery Honor book about Beth Lambert, who realizes the cutest, smartest boy in sixth grade might be best at everything because she is letting him win. Funny, sharp, and quietly wise about growing up."}, {"id": 2523, "title": "Pier Giorgio Frassati: To the Heights", "url": "https://store.ignatiusbookfairs.com/pier-giorgio-frassati-to-the-heights/", "take": "The stirring story of the university student, athlete, and Dominican tertiary who died at 24 after contracting polio while serving the poor. Beatified by John Paul II as a model for young people, Frassati's witness still blazes."}, {"id": 1058, "title": "Pinch Hit", "url": "https://store.ignatiusbookfairs.com/pinch-hit/", "take": "Trevor has the Hollywood mansion, limo, and bowling alley — everything except real baseball. Sam has big-league talent and a struggling dad. Tim Green sets up an irresistible lookalike premise that young sports readers will happily run with."}, {"id": 2761, "title": "Pinkalicious and the Perfect Present", "url": "https://store.ignatiusbookfairs.com/pinkalicious-and-the-perfect-present-ibc-1554/", "take": "Pinkalicious has her own money and a yard sale full of possibilities in this I Can Read story from Victoria Kann. An easy, familiar pick for beginning readers who already love all things pink."}, {"id": 2471, "title": "Pippi Longstocking", "url": "https://store.ignatiusbookfairs.com/pippi-longstocking/", "take": "Astrid Lindgren's red-pigtailed original: no parents, a horse on the porch, and one outrageous escapade after another. Tommy and Annika's unforgettable neighbor has been making young readers laugh for generations, and she has not lost a step."}, {"id": 1928, "title": "Plague Journal", "url": "https://store.ignatiusbookfairs.com/plague-journal/", "take": "Michael O'Brien's third Children of the Last Days novel follows a small-town newspaper editor as North America drifts quietly toward totalitarianism. Near-future fiction with a conscience, best suited to adult readers who like their thrillers thoughtful."}, {"id": 1767, "title": "Play On Like Ludwig van Beethoven", "url": "https://store.ignatiusbookfairs.com/play-on-like-ludwig-van-beethoven/", "take": "Fourth in the Good Guys Agency series: when Gordie wants to give up on math, the trio time-travels to meet Beethoven himself. The prose-plus-comic-panel format keeps reluctant readers moving, and the perseverance lesson lands without preaching."}, {"id": 1081, "title": "Pocket Flyers Paper Airplane Book", "url": "https://store.ignatiusbookfairs.com/pocket-flyers-paper-airplane-book/", "take": "Twelve miniature paper airplane designs — 69 planes in all — from the loop-and-dive Gargoyle to the Concorde 500. Vibrantly colored, pocket-sized entertainment for backyards, parties, and classrooms (don't get caught)."}, {"id": 2191, "title": "Polar Express", "url": "https://store.ignatiusbookfairs.com/polar-express/", "take": "The mysterious train, the city at the top of the world, the boy's Christmas wish. This thirtieth-anniversary edition of the beloved classic belongs in the Christmas Eve read-aloud rotation, if it isn't anchoring yours already."}, {"id": 1681, "title": "Pony Scouts: Pony Crazy", "url": "https://store.ignatiusbookfairs.com/pony-scouts-pony-crazy/", "take": "Meg has pony books, pony toys, pony everything — and on her first day at a new school she finds two friends just as pony crazy. A warm series opener for young horse lovers, with Pony Pointers vocabulary pages included."}, {"id": 1655, "title": "Pony Scouts: Really Riding!", "url": "https://store.ignatiusbookfairs.com/pony-scouts-really-riding/", "take": "A riding lesson, a sleepover, and a big surprise — plus the Pony Pointers vocabulary page that horse-crazy kids actually read. Author Catherine Hapka keeps horses on her own farm, and the authentic detail shows."}, {"id": 2534, "title": "Pope Leo XIV Charm", "url": "https://store.ignatiusbookfairs.com/pope-leo-xiv-charm/", "take": "A special edition Tiny Saints charm of Pope Leo XIV, whose road ran from suburban Chicago to Peru to the Chair of Peter. A sweet, pocket-sized prompt to pray for the pope — and a timely keepsake."}, {"id": 1932, "title": "Practical Theology: Spiritual Direction from St. Thomas Aquinas", "url": "https://store.ignatiusbookfairs.com/practical-theology-spiritual-direction-from-st-thomas-aquinas/", "take": "Peter Kreeft mines the Summa for 358 bite-sized pieces of practical wisdom, pairing each Aquinas quote with his own lively commentary. Deep theology made genuinely usable — a bedside book adults can dip into for years."}, {"id": 987, "title": "Prairie Day", "url": "https://store.ignatiusbookfairs.com/prairie-day/", "take": "Laura's family crosses the Kansas prairie — gophers and rabbits by day, a cozy camp at night. A gentle My First Little House adaptation that introduces the youngest readers to pioneer life."}, {"id": 1701, "title": "Prairie School", "url": "https://store.ignatiusbookfairs.com/prairie-school/", "take": "It is the 1880s on the Colorado prairie, and Noah cannot see the use of reading — until Aunt Dora arrives with schooling that changes his life. A short, satisfying historical story about why learning matters."}, {"id": 2158, "title": "Pray by Sticker: Paint-by-number Sticker Book", "url": "https://store.ignatiusbookfairs.com/pray-by-sticker-paint-by-number-sticker-book/", "take": "Paint-by-number, but with stickers and prayers. Children match numbered stickers while learning their Catholic faith, practicing counting and fine motor skills along the way. A quiet-time activity that actually points somewhere; handy for Mass bags and rainy afternoons."}, {"id": 2537, "title": "Pray by Sticker: Saints", "url": "https://store.ignatiusbookfairs.com/pray-by-sticker-saints/", "take": "Paint-by-number, but with stickers: kids assemble vibrant images of ten saints, five women and five men, from St. Bernadette to St. Patrick. A quiet-time activity that leaves children knowing real saints by name and face."}, {"id": 2159, "title": "Pray by Sticker: Story of the Cross Sticker Book", "url": "https://store.ignatiusbookfairs.com/pray-by-sticker-story-of-the-cross-sticker-book/", "take": "Sticker-by-number pages walk children through Christ's sacrifice and resurrection, one placement at a time. A hands-on way for young Catholics to absorb the story of the Cross while busy fingers stay occupied. Ready-made for Lent and Easter."}, {"id": 1934, "title": "Pray.Think.Act.", "url": "https://store.ignatiusbookfairs.com/pray-think-act/", "take": "Father Augustine Wetta turns to the Desert Fathers to answer the question young people actually ask: how do I make up my mind? Witty, biblical, and surprisingly practical — a strong gift for teens facing big decisions."}, {"id": 1486, "title": "Prayers around the Crib", "url": "https://store.ignatiusbookfairs.com/prayers-around-the-crib/", "take": "The Advent calendar and wreath, the tree, and every figure of the Nativity scene, each explained with a little story and a simple, heartfelt prayer. With sweet four-color pictures throughout, a lovely December rhythm for young children awaiting Christmas."}, {"id": 1107, "title": "Pride and Prejudice", "url": "https://store.ignatiusbookfairs.com/pride-and-prejudice/", "take": "Austen's most popular novel in an edition attentive to the Christian moral vision modern critics too often overlook. The wit, the follies, the family frictions — all intact, with a lens teachers and parents will appreciate."}, {"id": 2814, "title": "Pride and Prejudice", "url": "https://store.ignatiusbookfairs.com/pride-and-prejudice-ibc-1592/", "take": "Austen's classic in the gorgeous Puffin in Bloom edition — Anna Bond's cover art alone converts teens. The right first Austen for a strong reader, and a shelf treasure afterward."}, {"id": 1973, "title": "Pride and Prejudice: Ignatius Critical Edition", "url": "https://store.ignatiusbookfairs.com/pride-and-prejudice-ignatius-critical-edition/", "take": "Austen's most popular novel in an edition attentive to the Christian moral vision modern critics often skip past. The beloved story of follies, foibles, and family life, plus tradition-minded criticism — well suited to high school courses and thoughtful rereaders."}, {"id": 2481, "title": "Princess Charity's Golden Heart", "url": "https://store.ignatiusbookfairs.com/princess-charitys-golden-heart/", "take": "The Parable of the Good Samaritan retold for brand-new readers, as Princess Charity must choose between her father's border rule and a hurt boy who needs help. A Level One I Can Read with real heart."}, {"id": 2830, "title": "Princess in Black and the Mermaid Princess", "url": "https://store.ignatiusbookfairs.com/princess-in-black-and-the-mermaid-princess-ibc-1630/", "take": "The Princess in Black heads underwater to help a mermaid princess protect her very cute sea goats from a greedy kraken. Series fans get everything they came for, plus a new friend and a whole new setting."}, {"id": 2782, "title": "Princess in Black and the Perfect Princess Party", "url": "https://store.ignatiusbookfairs.com/princess-in-black-and-the-perfect-princess-party-ibc-1621/", "take": "It's Princess Magnolia's birthday party, and the monster alarm will not stop ringing. Quick costume changes, defeated monsters, and a secret to protect - the kind of fun that keeps brand-new chapter book readers turning pages."}, {"id": 2470, "title": "Princess Joy's Party", "url": "https://store.ignatiusbookfairs.com/princess-joys-party/", "take": "A Level One I Can Read that retells the Parable of the Great Feast through a princess's birthday party. When no one comes, Joy's father the king shows her God's wider welcome. Sweet faith formation for brand-new readers."}, {"id": 2797, "title": "Project Droid: Science No Fair", "url": "https://store.ignatiusbookfairs.com/project-droid-science-no-fair-ibc-1607/", "take": "Logan's inventor mother builds him a robot cousin, and third grade goes sideways - starting with the science fair. Nancy Krulik and her daughter Amanda make STEM genuinely funny in this lighthearted series."}, {"id": 1930, "title": "Providence Blue", "url": "https://store.ignatiusbookfairs.com/providence-blue/", "take": "A bold literary fantasy imagining pulp legend Robert E. Howard, creator of Conan, on a strange otherworldly journey after his 1936 suicide. Inventive and unusual; given the subject matter, this one is for adult and mature readers."}, {"id": 2754, "title": "Pumpkin Day for Boo and Belle", "url": "https://store.ignatiusbookfairs.com/pumpkin-day-for-boo-and-belle-ibc-1569/", "take": "When wind steals an invitation to Belle's Annual Pumpkin Tea, a friendship wobbles — briefly. A heartwarming autumn story about misunderstanding and making things right, praised by Midwest Book Review as charming and memorable. Cozy fall read-aloud material."}, {"id": 1008, "title": "Puss in Boots", "url": "https://store.ignatiusbookfairs.com/puss-in-boots/", "take": "Fred Marcellino's magnificent illustrations grace a nimble new translation of Perrault's 1697 tale. Yes, there are many editions of Puss — this is the one that earns a spot on the favorites shelf."}, {"id": 900, "title": "Queen Esther", "url": "https://store.ignatiusbookfairs.com/queen-esther/", "take": "Tomie dePaola turns his colorful, delicate artwork to the story of Esther, the queen who risked her life to save her people. A simple, accurate retelling of one of the Bible's bravest women, from a master of the picture-book form."}, {"id": 2785, "title": "Quest for the Golden Apple: Minecraft", "url": "https://store.ignatiusbookfairs.com/quest-for-the-golden-apple-minecraft-ibc-1605/", "take": "Phoenix's quest to un-zombie her brother, told in 750+ Minecraft-world images. For game-obsessed kids, this graphic novel is often the gateway that makes reading feel like playing."}, {"id": 1012, "title": "Rabbits & Raindrops", "url": "https://store.ignatiusbookfairs.com/rabbits-raindrops/", "take": "Five baby rabbits leave the nest for the first time, and a rain shower brings the neighbors visiting. Jim Arnosky's graceful watercolors make this a sweet first nature story for the very young."}, {"id": 1499, "title": "Raccoon on His Own", "url": "https://store.ignatiusbookfairs.com/raccoon-on-his-own/", "take": "A baby raccoon drifts downstream in an abandoned canoe — afraid at first, then curious, then quietly brave. A gentle mirror of a child's first adventure away from home, and a lovely conversation starter about venturing out on your own."}, {"id": 2214, "title": "Rain", "url": "https://store.ignatiusbookfairs.com/rain/", "take": "Newbery Medalist Cynthia Rylant's lyrical tribute to rainy days: the hush before the storm, the cozy ones tucked inside, the joyful ones out splashing. A gentle, vibrantly illustrated picture book for little weather watchers."}, {"id": 2498, "title": "Raising Lumie", "url": "https://store.ignatiusbookfairs.com/raising-lumie/", "take": "Newbery Honor author Joan Bauer pairs newly orphaned Olive with Lumie, a guide dog puppy in training. Discipline, rules, lots of hugs — and a hopeful story about building a new family. Poignant without ever turning heavy."}, {"id": 1023, "title": "Ramona and Her Father", "url": "https://store.ignatiusbookfairs.com/ramona-and-her-father/", "take": "Ramona's father loses his job, and the seven-year-old resolves to help — even trimming her Christmas list. A Newbery Honor book that treats a family's money worries with Cleary's perfect mix of humor and warmth."}, {"id": 1024, "title": "Ramona Quimby Age 8", "url": "https://store.ignatiusbookfairs.com/ramona-quimby-age-8/", "take": "Ramona is old enough to be counted on now — riding the bus, behaving for Mrs. Kemp while Mom works and Dad returns to school. Cleary's classic, reissued with a foreword by Amy Poehler and an interview with Cleary herself."}, {"id": 1536, "title": "Rascal", "url": "https://store.ignatiusbookfairs.com/rascal/", "take": "Young Sterling brings home a baby raccoon, and boy and Rascal share one perfect year of adventure — until a spring day changes everything. A gentle, bittersweet animal story that stays with readers."}, {"id": 1415, "title": "Rechenka's Eggs", "url": "https://store.ignatiusbookfairs.com/rechenkas-eggs/", "take": "Patricia Polacco's tale of Babushka, her beautifully painted Easter eggs, and the injured goose who repays her kindness with a miracle. Warm, folk-art gorgeous, and a lovely springtime read-aloud."}, {"id": 1021, "title": "Red Hugh, Prince of Donegal", "url": "https://store.ignatiusbookfairs.com/red-hugh-prince-of-donegal/", "take": "Red Hugh's capture, escape from Dublin Castle, blizzard survival, and fight for Irish liberty against Queen Elizabeth's reign. One of those keep-reading-one-more-chapter historical adventures — you can see the movie in your head."}, {"id": 1050, "title": "Red Scarf Girl: A Memoir of the Cultural Revolution", "url": "https://store.ignatiusbookfairs.com/red-scarf-girl-a-memoir-of-the-cultural-revolution/", "take": "Ji-li Jiang is twelve, bright, and thriving — until the Cultural Revolution upends everything she trusted. A moving, honest memoir stacked with ALA honors; powerful reading for young adults and unforgettable fuel for classroom discussion."}, {"id": 2123, "title": "Redwall: A Tale from Redwall #1", "url": "https://store.ignatiusbookfairs.com/redwall-a-tale-from-redwall-1/", "take": "Cluny the one-eyed rat and his savage horde are coming for peaceable Redwall Abbey, and the mice's only hope is the lost sword of Martin. The novel that launched the beloved saga — grand, old-fashioned adventure."}, {"id": 1397, "title": "Remains of the Day", "url": "https://store.ignatiusbookfairs.com/remains-of-the-day/", "take": "Ishiguro's Booker Prize winner about Stevens, the perfect English butler, taking a country drive through his own past. A masterclass in restraint and regret for adult readers - devastating precisely because it stays so polite."}, {"id": 1935, "title": "Remembering C.S. Lewis", "url": "https://store.ignatiusbookfairs.com/remembering-c-s-lewis/", "take": "Twenty-four men and women who knew C.S. Lewis as teacher, colleague, and friend share candid memories — Jack sparring with Oxford's atheists one moment, striding up a hill the next. An intimate community portrait for grown-up Lewis admirers."}, {"id": 2800, "title": "Rescue at Lake Wild", "url": "https://store.ignatiusbookfairs.com/rescue-at-lake-wild-ibc-1561/", "take": "Madi can't stop rescuing animals — and two orphaned beaver kits push her luck into a full environmental caper. Funny, warm, and quietly smart about wildlife; perfect for fans of Pax."}, {"id": 2112, "title": "Return of Zita the Space Girl", "url": "https://store.ignatiusbookfairs.com/return-of-zita-the-space-girl/", "take": "Zita is still fighting her way back to Earth, and space keeps making it complicated. More of Ben Hatke's delightful sci-fi adventure for kids who fell for the intrepid spacegirl in the earlier books."}, {"id": 2793, "title": "Revenge of the Zombie Monks", "url": "https://store.ignatiusbookfairs.com/revenge-of-the-zombie-monks-ibc-1623/", "take": "The monks who grow Xenos's healing golden apples - and guard its deepest secrets - have been zombified, leaving the villagers unprotected. A fantasy adventure with a fun hook and clear, kid-friendly stakes."}, {"id": 2450, "title": "Richard Scarry's Please and Thank You book", "url": "https://store.ignatiusbookfairs.com/richard-scarrys-please-and-thank-you-book/", "take": "Huckle Cat, Lowly Worm, and the rest of Richard Scarry's crew model please, thank you, sharing, and school behavior in bright, busy illustrations. Manners lessons that go down easily — with a sticker sheet included."}, {"id": 1465, "title": "Richard Scarry's The Rooster Struts", "url": "https://store.ignatiusbookfairs.com/richard-scarrys-the-rooster-struts/", "take": "Richard Scarry's tall classic board book shows all the ways animals get from here to there — strutting roosters, hopping frogs, flying favorites. Simple, cheerful, and likely to have toddlers acting out every page."}, {"id": 1031, "title": "Rilla of Ingleside", "url": "https://store.ignatiusbookfairs.com/rilla-of-ingleside/", "take": "Rilla, the youngest of Anne's children, meets World War I with irrepressible spirit in the sixth Green Gables book. A coming-of-age story with more weight than readers may expect — and better for it."}, {"id": 2146, "title": "Rise of the Fallen (Wars of the Realm, #2)", "url": "https://store.ignatiusbookfairs.com/rise-of-the-fallen-wars-of-the-realm-2/", "take": "Validus, the last and least of God's angels, rises through millennia of angelic and demonic warfare to command legions. Christian speculative fiction for teens that makes the unseen battle for humanity feel immediate."}, {"id": 1549, "title": "Roller Skates", "url": "https://store.ignatiusbookfairs.com/roller-skates/", "take": "A Newbery Medal winner with real wind in its hair. With her parents in Italy, ten-year-old Lucinda gets a year of glorious freedom, roller-skating through New York City and collecting friends and adventures. Classic, spirited, and joyful."}, {"id": 2021, "title": "Romantic Poets: Blake, Wordsworth, and Coleridge", "url": "https://store.ignatiusbookfairs.com/romantic-poets-blake-wordsworth-and-coleridge/", "take": "The first generation of Romantic poets — Blake, Wordsworth, and Coleridge — gathered in one volume that aims to be both accessible and scholarly. A solid anthology for high school students meeting Romanticism seriously for the first time."}, {"id": 1809, "title": "Rome Sweet Home", "url": "https://store.ignatiusbookfairs.com/rome-sweet-home/", "take": "Scott Hahn was a Presbyterian minister, a brilliant Scripture scholar, and militantly anti-Catholic — until the journey he and Kimberly recount here led them to Rome. Their conversion story, told in their own words, remains a persuasive, very human read."}, {"id": 1870, "title": "Romeo and Juliet", "url": "https://store.ignatiusbookfairs.com/romeo-and-juliet/", "take": "Shakespeare's most famous lovers, in a critical edition built for high school reading lists. The essays take seriously the question the tragedy poses for young readers who know exactly what being in love feels like. Classroom-ready."}, {"id": 1084, "title": "Roots, Shoots, Buckets, and Boots", "url": "https://store.ignatiusbookfairs.com/roots-shoots-buckets-and-boots/", "take": "Twelve theme gardens for parents and kids to grow together — a giant Pizza Patch, bean tunnels — each with a plan, planting recipe, discovery walk, and crafts, all in Sharon Lovejoy's lyrical watercolors. Gardening as wonder, not chore."}, {"id": 1986, "title": "Rosary Popper: Denim Blue", "url": "https://store.ignatiusbookfairs.com/rosary-popper-denim-blue/", "take": "The popper rosary in an easygoing denim blue. Press down a bubble for each prayer and your place keeps itself; the printed mysteries save flipping through a booklet. A sturdy, giftable prayer tool for kids and adults."}, {"id": 1990, "title": "Rosary Popper: Fatima Sun", "url": "https://store.ignatiusbookfairs.com/rosary-popper-fatima-sun/", "take": "In a sunny golden shade, this silicone popper keeps your place through every prayer — press a bubble, pray, repeat. Mysteries printed for easy reference; equally at home in a child's hands or a grandparent's Mass bag."}, {"id": 1987, "title": "Rosary Popper: Forest", "url": "https://store.ignatiusbookfairs.com/rosary-popper-forest/", "take": "Deep forest green, food-grade silicone, and the same simple genius: one bubble per prayer, so distractions never cost you your place. The mysteries are printed on the popper — handy for family rosaries with wiggly participants."}, {"id": 1982, "title": "Rosary Popper: Glow-in-the-dark Green", "url": "https://store.ignatiusbookfairs.com/rosary-popper-glow-in-the-dark-green/", "take": "A silicone pop-it rosary in glow-in-the-dark green: press a bubble for each prayer and never lose your place, with the mysteries printed right on it. Sturdy and quiet for kids learning the Rosary — the glow is a bonus for bedtime prayers."}, {"id": 1984, "title": "Rosary Popper: Mauve", "url": "https://store.ignatiusbookfairs.com/rosary-popper-mauve/", "take": "Press a bubble, say a prayer, see exactly where you left off — this mauve silicone popper makes the Rosary approachable for restless kids and forgetful grown-ups alike. The mysteries are printed right on it for quick reference."}, {"id": 1991, "title": "Rosary Popper: Natural", "url": "https://store.ignatiusbookfairs.com/rosary-popper-natural/", "take": "The natural-toned version of the press-and-pray rosary popper: one bubble per prayer, mysteries printed right on it, no beads to drop or tangle. An unfussy, giftable way to help anyone keep their place in the Rosary."}, {"id": 1988, "title": "Rosary Popper: Rose Pink", "url": "https://store.ignatiusbookfairs.com/rosary-popper-rose-pink/", "take": "In rose pink, this silicone popper turns place-keeping into part of the prayer: press a bubble, move along, never lose count. Printed mysteries included for quick reference. A sweet companion for a young pray-er's first rosaries."}, {"id": 1985, "title": "Rosary Popper: Sky Blue", "url": "https://store.ignatiusbookfairs.com/rosary-popper-sky-blue/", "take": "A soft sky-blue take on the popper rosary: durable food-grade silicone, mysteries printed for easy reference, and a bubble to press for every prayer. Practical for car rides, Mass bags, and children still building the habit."}, {"id": 1989, "title": "Rosary Popper: Terracotta", "url": "https://store.ignatiusbookfairs.com/rosary-popper-terracotta/", "take": "The popper rosary in a warm terracotta shade — tactile, durable, and quiet enough for church. Bubbles track every prayer and the mysteries are printed on the face. A practical addition to the family prayer table or Mass bag."}, {"id": 1007, "title": "Rumpelstiltskin", "url": "https://store.ignatiusbookfairs.com/rumpelstiltskin/", "take": "Zelinsky's richly hued oil paintings give the old tale of spun gold and a mysterious name real gravity. A classic fairy tale retold simply and gracefully — one adults will enjoy rereading too."}, {"id": 2000, "title": "Sacrament Popper Bundle", "url": "https://store.ignatiusbookfairs.com/sacrament-popper-bundle/", "take": "Three pop-its marking the sacramental milestones: a seashell for Baptism, a chalice and host for Holy Communion, a dove for Confirmation. A fun, inexpensive way to celebrate a child's big day — and a cheerful reminder afterward."}, {"id": 2027, "title": "Sacred Heart Plush", "url": "https://store.ignatiusbookfairs.com/sacred-heart-plush/", "take": "An eight-inch plush of Jesus with His Sacred Heart visible — flames, thorns, and all — from Little Drops of Water. A huggable way to start conversations with small children about how personally Christ loves them."}, {"id": 1994, "title": "Sacred Heart Popper", "url": "https://store.ignatiusbookfairs.com/sacred-heart-popper/", "take": "A pop-it in the form of the Sacred Heart — a simple, tactile devotional item that gives busy little hands something faith-shaped to hold. A small gift or basket-stuffer for families who love the devotion."}, {"id": 1693, "title": "Saint Anthony and the Christ Child", "url": "https://store.ignatiusbookfairs.com/saint-anthony-and-the-christ-child/", "take": "Helen Walker Homan's Vision book covers Anthony of Padua's adventurous life — a voyage to Morocco, a shipwreck, meeting Francis at Assisi — plus his powerful preaching and miracles. Lively saint biography for young readers."}, {"id": 877, "title": "Saint Bernadette and the Miracles of Lourdes", "url": "https://store.ignatiusbookfairs.com/saint-bernadette-and-the-miracles-of-lourdes/", "take": "The story of Bernadette, the beautiful lady, and the spring that still draws millions to Lourdes, told with genuinely lovely mixed-media art - watercolor, inks, gold overlays, collage. A saint biography that feels like a treasure, not a lesson."}, {"id": 1748, "title": "Saint Clothilde: The First Christian Queen of France Tells Her Story", "url": "https://store.ignatiusbookfairs.com/saint-clothilde-the-first-christian-queen-of-france-tells-her-story/", "take": "Clothilde's prayers and good example led her husband, the fierce barbarian Clovis, to a miraculous battlefield conversion in 496 — forever changing the destiny of France. A story-driven introduction to the first Christian queen of France."}, {"id": 1456, "title": "Saint Dominic and the Rosary", "url": "https://store.ignatiusbookfairs.com/saint-dominic-and-the-rosary/", "take": "Catherine Beebe's dramatic Vision Books life of St. Dominic opens with an all-night tavern conversation that wins back an embittered innkeeper — and the great preaching career begins. Vivid, fast-moving hagiography for readers 9-15 who like their saints bold."}, {"id": 1509, "title": "Saint Elizabeth's Three Crowns", "url": "https://store.ignatiusbookfairs.com/saint-elizabeths-three-crowns/", "take": "A saint who lived amid incredible wealth: Princess Elizabeth of Hungary, betrothed at four and sent from home to be raised beside her future husband. For ages 9-15, a Vision Book reminder that holiness wears many circumstances."}, {"id": 1530, "title": "Saint Francis of the Seven Seas", "url": "https://store.ignatiusbookfairs.com/saint-francis-of-the-seven-seas/", "take": "St. Francis Xavier for ages 9-15: the sports-loving Paris student who scoffed at Ignatius Loyola before becoming the great missionary to the Far East. A Vision Book conversion story with genuine surprise in its turns."}, {"id": 2028, "title": "Saint Francis Plush", "url": "https://store.ignatiusbookfairs.com/saint-francis-plush/", "take": "The patron of animals and nature, rendered eight inches tall and huggable. Francis in his simple brown habit is a natural favorite for little animal lovers, and a gentle companion come his October 4 feast day."}, {"id": 1002, "title": "Saint George and the Dragon", "url": "https://store.ignatiusbookfairs.com/saint-george-and-the-dragon/", "take": "Winner of the Caldecott Medal, with Trina Schart Hyman's astonishing illustrations. This retelling of the Red Cross Knight's battle from Spenser's Faerie Queene belongs in any collection of folklore worth the name."}, {"id": 1554, "title": "Saint Helena and the True Cross", "url": "https://store.ignatiusbookfairs.com/saint-helena-and-the-true-cross/", "take": "Louis de Wohl tells young readers the story of St. Helena, mother of Constantine, who found the Cross of Christ in Jerusalem. Imperial power struggles, Roman legions, and a remarkably determined woman — the 29th entry in the Vision Books series."}, {"id": 1597, "title": "Saint Ignatius and the Company of Jesus", "url": "https://store.ignatiusbookfairs.com/saint-ignatius-and-the-company-of-jesus/", "take": "The dramatic Vision Books account of Ignatius of Loyola for readers 9 to 15: a soldier's dreams shattered by a battlefield wound, a profound conversion during recovery, and the founding of the Society of Jesus. Adventure redirected, not abandoned."}, {"id": 1614, "title": "Saint Isaac and the Indians", "url": "https://store.ignatiusbookfairs.com/saint-isaac-and-the-indians/", "take": "The story of St. Isaac Jogues, the Jesuit missionary and martyr who came to the St. Lawrence forests three hundred years ago not to take furs and wealth, but to give his life sharing God's love. Dramatic, sobering, and inspiring."}, {"id": 1649, "title": "Saint John Bosco and Saint Dominic Savio", "url": "https://store.ignatiusbookfairs.com/saint-john-bosco-and-saint-dominic-savio/", "take": "A Vision book pairing the great apostle of youth with his best-loved pupil. John Bosco — juggler, magician, tailor, teacher — used every gift, including a wonderful sense of humor, to lead poor children to God. Stirring reading for young Catholics."}, {"id": 913, "title": "Saint Jose, Boy Cristero Martyr", "url": "https://store.ignatiusbookfairs.com/saint-jose-boy-cristero-martyr/", "take": "From the Vision Books saints series for ages 9-15: the true story of St. Jose Sanchez del Rio, the fourteen-year-old who died for his faith in Mexico's Cristero War. Sobering, heroic history that speaks directly to young readers his own age."}, {"id": 2174, "title": "Saint Kevin of Glendalough", "url": "https://store.ignatiusbookfairs.com/saint-kevin-of-glendalough/", "take": "A Vision Book about Saint Kevin, whose 6th-century Irish monastery was a beacon of light for 800 years. Miracles, animal friendships, and thousands inspired to follow Christ; sturdy saint storytelling for kids who loved Patrick and want more of Ireland."}, {"id": 1667, "title": "Saint Louis and the Last Crusade", "url": "https://store.ignatiusbookfairs.com/saint-louis-and-the-last-crusade/", "take": "A Vision book for ages 9-15 about Louis IX of France, who took the throne with one aim — to be a good king — and carried the cross on crusade. History, adventure, and holiness in one stirring package."}, {"id": 1709, "title": "Saint Philip of the Joyous Heart", "url": "https://store.ignatiusbookfairs.com/saint-philip-of-the-joyous-heart/", "take": "A Vision book for ages 9-15 about Philip Neri, the learned saint who never stopped joking, teasing, and playing with his many pets — proof that a joyous heart wins friends to Christ. Young readers take to him quickly."}, {"id": 1719, "title": "Saint Pius X: the Farm Boy Who Became Pope", "url": "https://store.ignatiusbookfairs.com/saint-pius-x-the-farm-boy-who-became-pope/", "take": "The Vision series for ages 9-15 tells the charming story of Giuseppe Sarto, the farm boy who worked and prayed his way through every rank of the Church — reluctantly accepting each promotion — until he became Pope."}, {"id": 1570, "title": "Saint Therese and the Roses", "url": "https://store.ignatiusbookfairs.com/saint-therese-and-the-roses/", "take": "The Little Flower for readers 9 to 15: Therese of Lisieux growing up in France with her four vividly different sisters, where growing up meant growing closer to God. A warm Vision Books telling of the most popular modern saint."}, {"id": 2030, "title": "Saint Therese Plush", "url": "https://store.ignatiusbookfairs.com/saint-therese-plush/", "take": "The Little Flower at her most approachable: an eight-inch plush of Therese in her Carmelite habit with roses. A sweet way to hand small children her big idea — little things, done with great love, make saints."}, {"id": 1827, "title": "Saintly Creatures", "url": "https://store.ignatiusbookfairs.com/saintly-creatures/", "take": "Fourteen tales of animals and the holy men and women they encountered — a huge dog guarding a French priest, a tiger sheltering persecuted Korean Christians, a wolf tamed by an Italian friar. Heroic virtue delivered through animal stories, a pairing young readers take to instantly."}, {"id": 1800, "title": "Saintly Scenes Book #1", "url": "https://store.ignatiusbookfairs.com/saintly-scenes-book-1/", "take": "Six repositionable cling-sticker scenes and six coloring pages drawn from saints' lives, including St. Juan Diego and Our Lady of Guadalupe. Reusable, open-ended, and quietly catechetical — the kind of activity book that survives more than one car ride."}, {"id": 1806, "title": "Saintly Scenes Book #2", "url": "https://store.ignatiusbookfairs.com/saintly-scenes-book-2/", "take": "Six reusable cling-sticker scenes plus six coloring pages, this round featuring saints like Joan of Arc and Jerome. Repositionable stickers mean open-ended play rather than one-and-done — a dependable quiet-time activity with real substance behind it."}, {"id": 1858, "title": "Saintly Scenes Book #3", "url": "https://store.ignatiusbookfairs.com/saintly-scenes-book-3/", "take": "Six reusable cling-sticker scenes plus six coloring pages, all built around saints from across Church history. The stickers reposition endlessly, which means open-ended play instead of a one-and-done activity book. A quiet-time workhorse."}, {"id": 1860, "title": "Saintly Scenes Book #4", "url": "https://store.ignatiusbookfairs.com/saintly-scenes-book-4/", "take": "Another round of saintly sticker play, this one featuring St. Joan of Arc and St. Jerome among its six scenes and six coloring pages. The reusable clings hold up to repeat sessions, which is where these books earn their keep."}, {"id": 1777, "title": "Saints Chronicles: Collection 1", "url": "https://store.ignatiusbookfairs.com/saints-chronicles-collection-1/", "take": "Graphic-novel storytelling meets the lives of the saints: this first volume opens with St. Patrick, captured by Irish pirates as a boy, escaping slavery, then returning to convert his captors' land. Dramatic images and engaging text that genuinely captivate."}, {"id": 2449, "title": "Saints Chronicles: Collection 2", "url": "https://store.ignatiusbookfairs.com/saints-chronicles-collection-2/", "take": "Saint Nicholas, Saint Francis, and more come to life in this handsome graphic novel of daring quests for holiness. Thrilling stories and striking images that make the saints feel like the adventurers they truly were."}, {"id": 2014, "title": "Saints Together Keychain Set", "url": "https://store.ignatiusbookfairs.com/saints-together-keychain-set/", "take": "A faith-forward twist on the best-friends necklace: two keychains and a heart, made for splitting between siblings or friends as a reminder that we help each other get to Heaven. Sized right for backpack zippers."}, {"id": 2138, "title": "Salamandastron: Redwall #5", "url": "https://store.ignatiusbookfairs.com/salamandastron-redwall-5/", "take": "Another epic entry in the beloved Redwall saga, overflowing with the valorous personality that keeps young readers marching through these chronicles of Mossflower's heroes and villains. Reliable, wholesome adventure for series fans."}, {"id": 1481, "title": "Sam the Minuteman", "url": "https://store.ignatiusbookfairs.com/sam-the-minuteman/", "take": "Nathaniel Benchley imagines the Battle of Lexington through a young minuteman's eyes, with Arnold Lobel's vivid pictures grounding the history. An early reader that genuinely pulls in first and second graders — reluctant ones included — for colonial America units."}, {"id": 1524, "title": "Sasquatch", "url": "https://store.ignatiusbookfairs.com/sasquatch/", "take": "Dylan's dad joins a Sasquatch-hunting team on Mount Saint Helens, so Dylan teams up with an aging field biologist to keep watch — and someone is following them, too. Brisk, suspenseful adventure for readers who like their mysteries slightly hairy."}, {"id": 1452, "title": "School Year, Church Year: Customs and Decorations for the Classroom", "url": "https://store.ignatiusbookfairs.com/school-year-church-year-customs-and-decorations-for-the-classroom/", "take": "For the teacher weary of pumpkins-then-snowflakes by default: a walk through the school year paired with the Church's year, with customs and decoration ideas from Advent to Easter for children of all ages. Practical, cheerful, and genuinely different."}, {"id": 961, "title": "Science Experiments you Can Eat", "url": "https://store.ignatiusbookfairs.com/science-experiments-you-can-eat/", "take": "Vicki Cobb's classic turns the kitchen into a laboratory: real chemistry demonstrated through experiments you can eat afterward. Updated for today's food world, it makes scientific principles stick the way only snacks can."}, {"id": 1512, "title": "Sea Animals (Coloring Book)", "url": "https://store.ignatiusbookfairs.com/sea-animals-coloring-book/", "take": "Thirty marine animals — octopus, humpback whale, penguin, great white shark — in simple portraits with easy-to-read captions that sneak in real facts. An informative coloring book that keeps ocean-obsessed kids busy and teaches while it does."}, {"id": 1652, "title": "Sea Life Games and Puzzles: 100 Brainteasers, Word Games, Jokes & Riddles, Picture Puzzles, Matches, and Logic Tests for Ocean-Loving Kids", "url": "https://store.ignatiusbookfairs.com/sea-life-games-and-puzzles-100-brainteasers-word-games-jokes-riddles-picture-puzzles-matches-and-logic-tests-for-ocean-loving-kids/", "take": "One hundred ocean-themed brainteasers, mazes, jokes, and logic puzzles — lead a clownfish through coral, find the pearl-hiding oyster. A smart pick for keeping ocean-loving kids happily busy on car rides and quiet afternoons."}, {"id": 1598, "title": "Sea Life Mazes", "url": "https://store.ignatiusbookfairs.com/sea-life-mazes/", "take": "Forty-six sea-creature mazes with fact-filled captions tucked alongside — kids help ocean animals hunt, hide, and search for food while picking up marine trivia. Solutions included for maze travelers who get thoroughly lost. Solid quiet-time material."}, {"id": 1547, "title": "Second Fiddle", "url": "https://store.ignatiusbookfairs.com/second-fiddle/", "take": "Just after the Berlin Wall falls, thirteen-year-old Jody and her friends rescue a beaten Russian soldier — and end up racing from Berlin to Paris. Rosanne Parry delivers a fast-paced coming-of-age adventure where friend and enemy are hard to tell apart."}, {"id": 1939, "title": "Second Friends", "url": "https://store.ignatiusbookfairs.com/second-friends/", "take": "C.S. Lewis and Ronald Knox were Oxford neighbors and two of the century's great apologists. Milton Walsh sets their writings side by side on God, suffering, miracles, and prayer — a rich conversation for readers who love either man."}, {"id": 1105, "title": "See No Evil", "url": "https://store.ignatiusbookfairs.com/see-no-evil/", "take": "A wealthy family's Christmas party, probably black-market food, an odious reporter who witnessed a wartime massacre — and a body by morning. The third Father Gabriel mystery serves classic whodunit pleasures with a postwar edge."}, {"id": 2774, "title": "See you Later, Alligator", "url": "https://store.ignatiusbookfairs.com/see-you-later-alligator-ibc-1604/", "take": "A tortoise says one more goodbye to every animal friend before his trip — and the rhymes get funnier as he stalls. A joyful read-aloud that toddlers will demand again immediately."}, {"id": 1946, "title": "Seeing Through the Eye", "url": "https://store.ignatiusbookfairs.com/seeing-through-the-eye/", "take": "Selections from Malcolm Muggeridge, the celebrated British journalist whose late-life conversion startled the world. These writings and speeches carry his blunt clarity — \"It is the truth that has died, not God.\" A bracing introduction for adult readers."}, {"id": 2009, "title": "Seek & You will Find Treasures of Our Faith", "url": "https://store.ignatiusbookfairs.com/seek-you-will-find-treasures-of-our-faith/", "take": "Takes the beloved seek-and-find game and fills every nook and cranny with the treasures of Catholic faith. Built around Matthew 7's \"seek and you will find,\" it turns poring over pictures into a small act of discovery."}, {"id": 2494, "title": "Seek and Find: The First Christmas", "url": "https://store.ignatiusbookfairs.com/seek-and-find-the-first-christmas/", "take": "Over 450 hidden things to find, count, and sort in a large-format board book that walks little ones through the Gospel accounts of Jesus's birth. Biblically faithful and busy in the best way — Advent hands stay happily occupied."}, {"id": 1876, "title": "Sense and Sensibility", "url": "https://store.ignatiusbookfairs.com/sense-and-sensibility/", "take": "The Dashwood sisters lose their fortune and fall in love, and Austen does the rest. This edition appreciates her genius as grounded in her deep sense of what it is to be human. A pleasure for students and rereaders alike."}, {"id": 1671, "title": "Set All Afire: A Novel of St. Francis Xavier", "url": "https://store.ignatiusbookfairs.com/set-all-afire-a-novel-of-st-francis-xavier/", "take": "Louis de Wohl follows Francis Xavier from student days in Paris through his meeting with Ignatius and his missionary travels to the Orient. Absorbing historical fiction about one of the first Jesuits, written with deep conviction."}, {"id": 1073, "title": "Sewing School: 21 Sewing Projects Kids Will Love to Make", "url": "https://store.ignatiusbookfairs.com/sewing-school-21-sewing-projects-kids-will-love-to-make/", "take": "Twenty-one kid-tested projects — pillows, potholders, dolls, blankets — with illustrated instructions and cut-out patterns. Simple hand stitches, minimal supervision, no machine required. A genuinely usable craft book for children ages five and up."}, {"id": 2781, "title": "Shadow Fox", "url": "https://store.ignatiusbookfairs.com/shadow-fox-ibc-1543/", "take": "A fox with magic, a girl without it, and an island in peril. This animal fantasy earns its Kirkus praise — atmospheric, kind-hearted, and great for 8-12s who loved A Wolf Called Wander."}, {"id": 2157, "title": "Shadow in the Dark (Harwood Mysteries #1)", "url": "https://store.ignatiusbookfairs.com/shadow-in-the-dark-harwood-mysteries-1/", "take": "A medieval abbey, a boy with no memory, and a mystery worth staying up for — with a shelf of awards to prove it. One of our favorite starts to a series for 10-14s; give it to fans of The Ranger's Apprentice."}, {"id": 1464, "title": "Shakespeare", "url": "https://store.ignatiusbookfairs.com/shakespeare/", "take": "A Fandex guide to Shakespeare — plays, plots, and poetry from Henry VI to The Tempest, taking in Hamlet's hesitation, Iago's evil, and Juliet's passion, illustrated with historic paintings and actor photographs. A browsable way into an intimidating canon."}, {"id": 2222, "title": "Ship of Dolls", "url": "https://store.ignatiusbookfairs.com/ship-of-dolls/", "take": "Portland, 1926: Lexie's class is raising money to send a friendship doll to the children of Japan, and the best letter-writer earns a coveted honor. Tender, funny historical fiction about family and belonging, with a Beverly Cleary flavor."}, {"id": 1123, "title": "Should I Share My Ice Cream?", "url": "https://store.ignatiusbookfairs.com/should-i-share-my-ice-cream/", "take": "Gerald has ice cream and a decision that cannot wait, and Mo Willems wrings real comedy from the struggle to do the right thing. Vocabulary vetted for beginning readers, laughs vetted by every kid we know."}, {"id": 2798, "title": "Sib Squad", "url": "https://store.ignatiusbookfairs.com/sib-squad-ibc-1624/", "take": "Three youngest-of-seven siblings, tired of being told they're too little, form a club of their own. A Junior Library Guild Selection from a Pulitzer Prize-winning cartoonist - gleeful, accessible early graphic novel comedy."}, {"id": 2806, "title": "Sib Squad: Flying High", "url": "https://store.ignatiusbookfairs.com/sib-squad-flying-high-ibc-1626/", "take": "Lucy, Bruce, and Oliver are back for more amazing, mind-blowing adventures without their older siblings. Same gleeful rebellion, same Pulitzer Prize-winning cartoonist, same easy on-ramp for kids just starting graphic novels."}, {"id": 2837, "title": "Sib Squad: Hole Lotta Trouble", "url": "https://store.ignatiusbookfairs.com/sib-squad-hole-lotta-trouble-ibc-1550/", "take": "The three youngest siblings form their own adventure club, and chaos follows. A Pulitzer-winning cartoonist making early graphic novels means every kid in the house will fight over this one."}, {"id": 2527, "title": "Sibling Saints: Twelve Extraordinary Stories", "url": "https://store.ignatiusbookfairs.com/sibling-saints-twelve-extraordinary-stories/", "take": "Twelve stories of holy brothers and sisters — Benedict and Scholastica, Cyril and Methodius, the Martin sisters, and more — told through lively narrative, comic strips, history, and prayers. A fresh angle on the saints: holiness runs in families."}, {"id": 2173, "title": "Siempre Tu", "url": "https://store.ignatiusbookfairs.com/siempre-tu/", "take": "A gentle Spanish-language introduction to the soul and what makes us human, for ages 4-8, with simple prayers, nature-based analogies, and friendly illustrations. Christian formation at its most elemental, in the language of home."}, {"id": 2506, "title": "Sin Squash Card Game", "url": "https://store.ignatiusbookfairs.com/sin-squash-card-game/", "take": "Slap Jack gets a holy twist in this fast, silly card game built around the Sacrament of Reconciliation. A fun fit for families and kids preparing for First Reconciliation — learning about confession while laughing out loud."}, {"id": 1758, "title": "Sister Seraphina: The Curious Christmas Trail", "url": "https://store.ignatiusbookfairs.com/sister-seraphina-the-curious-christmas-trail/", "take": "Christmas Eve at the abbey: a play to stage, a feast to prepare, an elderly nun missing in the falling snow, and curious clues hidden under G. K. Chesterton's floorboards. A cozy Catholic mystery with real charm."}, {"id": 1041, "title": "Skating Shoes", "url": "https://store.ignatiusbookfairs.com/skating-shoes/", "take": "When a doctor prescribes skating to rebuild frail Harriet's health, she meets Lalla, an orphan being raised to be a champion. An unlikely, fast friendship on ice — a warmhearted classic that has captivated generations."}, {"id": 2749, "title": "Sky & Ty Dinomite!", "url": "https://store.ignatiusbookfairs.com/sky-ty-dinomite-ibc-1552/", "take": "A cowgirl and her T. rex running a delivery service: exactly as fun as it sounds. This Pulitzer-winner's graphic series has the Narwhal-and-Jelly magic — silly on the surface, surprisingly warm underneath."}, {"id": 2874, "title": "Skybreaker", "url": "https://store.ignatiusbookfairs.com/skybreaker/", "take": "The airship Hyperion vanished forty years ago with untold riches aboard; Matt Cruse means to recover it at 20,000 feet, with pursuers closing in and deadly high-altitude creatures circling. Rip-roaring aerial adventure for adventure-hungry readers."}, {"id": 2490, "title": "Slam Dunk", "url": "https://store.ignatiusbookfairs.com/slam-dunk/", "take": "Thirteen-year-old Julian is the only returning player from last year's championship basketball team, and the pressure is real. A friend's health crisis restores his perspective in this relatable sports story about what actually matters."}, {"id": 1531, "title": "So Young a Queen: Jadwiga of Poland", "url": "https://store.ignatiusbookfairs.com/so-young-a-queen-jadwiga-of-poland/", "take": "Jadwiga of Poland: crowned monarch at eleven, asked to give up her betrothed and marry Lithuania's pagan prince for the sake of peace and his promised conversion. Absorbing historical fiction about duty and sacrifice for thoughtful young readers."}, {"id": 1862, "title": "Soccer Hero", "url": "https://store.ignatiusbookfairs.com/soccer-hero/", "take": "Rob saves his coach's life and becomes the town hero, but the unearned applause sits wrong with him. A refreshing sports story arguing that doing right should be ordinary, not exceptional. Good conversation fodder for young athletes."}, {"id": 1943, "title": "Something Other Than God", "url": "https://store.ignatiusbookfairs.com/something-other-than-god/", "take": "Jennifer Fulwiler had the tech salary, the condo, the sunset views — and a creeping darkness anyway. Her honest memoir of moving from a happy atheist upbringing toward faith reads like a novel. Great for skeptics and the people who love them."}, {"id": 2457, "title": "Something's Fishy Coloring Book", "url": "https://store.ignatiusbookfairs.com/somethings-fishy-coloring-book/", "take": "Thirty original underwater scenes of fantasy fish, starfish, and shells in wild, psychedelic settings. Full-page designs with busy patterned backgrounds — a fun pick for colorers who like something more imaginative than the usual aquarium."}, {"id": 2834, "title": "Songs of a Warrior", "url": "https://store.ignatiusbookfairs.com/songs-of-a-warrior-ibc-1611/", "take": "Saul, David, Jonathan, and Michal — the whole tangled saga of Israel's first kings, retold for 8-13s with battles, betrayal, and grace intact. Bible engagement that reads like the epic it is."}, {"id": 1941, "title": "Sophia House", "url": "https://store.ignatiusbookfairs.com/sophia-house/", "take": "In Nazi-occupied Warsaw, a Catholic bookseller hides a Jewish teenager in his attic, and their long winter of conversation ranges over good, evil, literature, and redemption. Weighty, serious fiction for adults — O'Brien at his most intimate."}, {"id": 1940, "title": "Soul Garden", "url": "https://store.ignatiusbookfairs.com/soul-garden/", "take": "A generous, screen-free gathering of stories, essays, poems, and even recipes from women around the world, all meant to encourage mothers in their quiet daily work. A lovely, tangible gift book for the women who hold everything together."}, {"id": 1513, "title": "Sounds All Around", "url": "https://store.ignatiusbookfairs.com/sounds-all-around/", "take": "Clap your hands, snap your fingers: Wendy Pfeffer's engaging text and Anna Chernyshova's colorful art show early-elementary kids how sound works and how people and animals use it to communicate. Solid, appealing science for home or classroom."}, {"id": 1983, "title": "Spanish Rosary Popper: Blue", "url": "https://store.ignatiusbookfairs.com/spanish-rosary-popper-blue/", "take": "The clever press-a-bubble rosary tracker with the mysteries printed in Spanish, in a friendly blue. Food-grade silicone, easy to toss in a Mass bag, and kind to fidgety fingers — a thoughtful pick for Spanish-speaking families and bilingual classrooms."}, {"id": 1636, "title": "Splish, Splash!", "url": "https://store.ignatiusbookfairs.com/splish-splash/", "take": "Chub the fish loves to scrub in his tub — until all his friends come to splish and splash too. A bouncy, rhyming early reader built around one pressing question: can a tub so small hold them all?"}, {"id": 1801, "title": "St. Benedict Charm", "url": "https://store.ignatiusbookfairs.com/st-benedict-charm/", "take": "Benedict fled Rome, drew followers, and wrote the Rule that shaped monastic life and changed the world. His charm recalls the raven and the poisoned loaf — and gives students a patron with serious staying power."}, {"id": 1776, "title": "St. Benedict Medal Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/st-benedict-medal-vinyl-sticker/", "take": "The famous St. Benedict medal, rendered as a vinyl sticker. A simple way to put a beloved Catholic symbol of protection on a notebook or water bottle — a small gift carrying a very long tradition."}, {"id": 1998, "title": "St. Benedict Popper", "url": "https://store.ignatiusbookfairs.com/st-benedict-popper/", "take": "A pop-it modeled on the reverse of the St. Benedict medal, with the medal's traditional initials imprinted letter by letter on the bubbles. A tactile conversation-starter that can lead kids and adults into the meaning behind a beloved sacramental."}, {"id": 1706, "title": "St. Benedict: Hero of the Hills", "url": "https://store.ignatiusbookfairs.com/st-benedict-hero-of-the-hills/", "take": "Mary Fabyan Windeatt's Vision book on Benedict, the Father of Western Monasticism, whose monks' life of prayer and work helped convert the godless society of post-Roman Europe. Solid, dramatic saint storytelling for young readers."}, {"id": 2533, "title": "St. Carlo Acutis Charm", "url": "https://store.ignatiusbookfairs.com/st-carlo-acutis-charm/", "take": "A small charm honoring Carlo Acutis, the tech-loving teen who built websites about the Eucharist and offered his suffering for the Church before dying at 15. A tangible little reminder of a very modern path to holiness."}, {"id": 2867, "title": "St. Carlo Acutis Plush", "url": "https://store.ignatiusbookfairs.com/st-carlo-acutis-plush-kce3/", "take": "Saint Carlo Acutis in casual clothes, 8 inches of plush - the patron of the internet and youth in a form today's kids find instantly relatable. A conversation-starting gift about holiness in the digital age."}, {"id": 2521, "title": "St. Carlo Acutis Plush (Khakis)", "url": "https://store.ignatiusbookfairs.com/st-carlo-acutis-plush-khakis/", "take": "The patron saint of the internet as an 8-inch plush in casual khakis — and that's the point. Carlo Acutis shows kids that holiness is possible in the digital age, and this version is instantly relatable."}, {"id": 1716, "title": "St. Catherine Laboure and the Miraculous Medal", "url": "https://store.ignatiusbookfairs.com/st-catherine-laboure-and-the-miraculous-medal/", "take": "The Miraculous Medal is known worldwide; the shy Burgundy farm girl to whom the Blessed Virgin gave it in 1830 is less so. This Vision book for ages 9-16 tells Catherine Laboure's story with warmth and drama."}, {"id": 1762, "title": "St. Francis of Assisi Charm", "url": "https://store.ignatiusbookfairs.com/st-francis-of-assisi-charm/", "take": "A charm honoring Francis of Assisi — the wealthy merchant's son who heard Repair my house while praying before a crucifix and chose radical poverty, drawing the followers who became the Franciscans. A small keepsake with a big story."}, {"id": 2507, "title": "St. George and the Dragon Mini Puzzle", "url": "https://store.ignatiusbookfairs.com/st-george-and-the-dragon-mini-puzzle/", "take": "St. George battles the dragon across 48 custom-shaped pieces in this faith-inspired mini puzzle. Extra challenging for small hands in the best way — a nice screen-free option for Catholic families and classroom quiet time."}, {"id": 1813, "title": "St. George Charm", "url": "https://store.ignatiusbookfairs.com/st-george-charm/", "take": "A charm for the Roman soldier-saint remembered for faith, courage, and — as legend has it — slaying a man-eating dragon. Short on words, long on appeal for any kid who loves a knight-and-dragon story."}, {"id": 1818, "title": "St. Gianna Charm", "url": "https://store.ignatiusbookfairs.com/st-gianna-charm/", "take": "Gianna Beretta Molla was a pediatrician, wife, and mother who knew the rigors of balancing work and family — and who died from a risky surgery that saved her unborn baby's life. A charm honoring a thoroughly modern saint."}, {"id": 1807, "title": "St. Joan of Arc Charm", "url": "https://store.ignatiusbookfairs.com/st-joan-of-arc-charm/", "take": "The peasant girl who heard God's call, led France to pivotal victories, and paid for it with her life. Joan's charm suits brave girls especially — patroness of France, soldiers, and women in the military."}, {"id": 1796, "title": "St. John Paul II Charm", "url": "https://store.ignatiusbookfairs.com/st-john-paul-ii-charm/", "take": "A charm for the pope who told the world \"Do not be afraid.\" John Paul II visited 116 countries and inspired a generation of the faithful — patron of hope and perseverance, and a strong companion for a young Catholic."}, {"id": 1832, "title": "St. John Paul II-Special Edition Charm", "url": "https://store.ignatiusbookfairs.com/st-john-paul-ii-special-edition-charm/", "take": "John Paul II loved skiing his native Poland, and moments after his election quipped he would ski again \"when they let me.\" This special-edition charm, inspired by the poem Pope on a Slope, celebrates the saint's playful side."}, {"id": 1783, "title": "St. Joseph Charm", "url": "https://store.ignatiusbookfairs.com/st-joseph-charm/", "take": "A charm for the quiet hero of the Holy Family — the carpenter God trusted to raise His Son. Patron of workers and fathers, invoked for a happy death, Joseph makes a grounding companion for boys and dads alike."}, {"id": 1826, "title": "St. Kateri Tekakwitha Charm", "url": "https://store.ignatiusbookfairs.com/st-kateri-tekakwitha-charm/", "take": "Smallpox scarred her face; the Eucharist gave her peace. Kateri, the Lily of the Mohawks, crossed the wilderness by foot and canoe to live her faith, dying at just 24. A charm for converts, outcasts, and outdoor enthusiasts — her actual patronages."}, {"id": 1588, "title": "St. Katharine Drexel: Friend of the Oppressed", "url": "https://store.ignatiusbookfairs.com/st-katharine-drexel-friend-of-the-oppressed/", "take": "A Vision book telling the story of St. Katharine Drexel, the Philadelphia heiress who gave her entire inherited fortune to serve the oppressed. An American saint's story that quietly asks young readers what generosity might actually cost."}, {"id": 915, "title": "St. Maximilian Kolbe, Hero of the Holocaust", "url": "https://store.ignatiusbookfairs.com/st-maximilian-kolbe-hero-of-the-holocaust/", "take": "The story of Maximilian Kolbe, the Polish priest who volunteered to die in a condemned man's place at Auschwitz, told for younger readers. One of the twentieth century's greatest accounts of heroism, handled with the seriousness it deserves."}, {"id": 1772, "title": "St. Michael the Archangel Charm", "url": "https://store.ignatiusbookfairs.com/st-michael-the-archangel-charm/", "take": "The warrior archangel of Revelation, whose very name asks \"Who is like God?\" This charm honors the chief protector of the Christian faith — a fitting token for military and police families, or any child who needs a dose of courage."}, {"id": 2520, "title": "St. Michael the Archangel Plush", "url": "https://store.ignatiusbookfairs.com/st-michael-the-archangel-plush/", "take": "An 8-inch plush of heaven's greatest warrior, armor and wings included. A child-friendly way to introduce St. Michael as defender against evil — cuddly courage for bedtime, and a conversation starter about good triumphing over evil."}, {"id": 1766, "title": "St. Nicholas Charm", "url": "https://store.ignatiusbookfairs.com/st-nicholas-charm/", "take": "A charm carrying the real story behind Santa Claus: generous Bishop Nicholas of the third century, tossing bags of gold through windows to families in need. A lovely way to keep the saint himself at the center of the season."}, {"id": 1789, "title": "St. Teresa of Calcutta Charm", "url": "https://store.ignatiusbookfairs.com/st-teresa-of-calcutta-charm/", "take": "Mother Teresa described herself as belonging entirely to the Heart of Jesus — and, by calling, to the world. This charm honors the saint of little acts, the poor, and the marginalized: a beautiful patron for a compassionate child."}, {"id": 1947, "title": "St. Therese of Lisieux", "url": "https://store.ignatiusbookfairs.com/st-therese-of-lisieux/", "take": "Over 150 photographs plus rich text and sidebars open up the daily world of Therese of Lisieux — her history, her relationships, her hidden depth. A gorgeous illustrated introduction to a saint everyone loves but few truly know."}, {"id": 1835, "title": "St. Therese of Lisieux Charm", "url": "https://store.ignatiusbookfairs.com/st-therese-of-lisieux-charm/", "take": "Therese of Lisieux, the Little Flower, found peace in forgetting herself to make others happy — and promised a shower of roses from heaven. A charm for young people, and for anyone who has known anxiety and found grace bigger."}, {"id": 1476, "title": "St. Thomas Aquinas and the Preaching Beggars", "url": "https://store.ignatiusbookfairs.com/st-thomas-aquinas-and-the-preaching-beggars/", "take": "Monte Cassino in flames, an escape from a tower, and quiet young Thomas joining the preaching beggars: this Vision Book gives ages 9-15 the dramatic life behind the Summa Theologica. Saint biography with real narrative pull."}, {"id": 1521, "title": "St. Thomas More of London", "url": "https://store.ignatiusbookfairs.com/st-thomas-more-of-london/", "take": "Elizabeth Ince's Vision Books life of the light-hearted, heroic Chancellor of England — bright page boy, Oxford scholar, lawyer of great repute. For readers 9-16 who deserve heroes with both wit and spine."}, {"id": 2875, "title": "Starclimber", "url": "https://store.ignatiusbookfairs.com/starclimber/", "take": "Matt Cruse boards the Starclimber, a vessel that literally climbs into the cosmos - with a proposal planned and Kate newly engaged to someone else. Space adventure with real heartache stitched in. A strong series continuation."}, {"id": 2511, "title": "STEM Starters for Kids Robotics Activity Book: Packed with Activities and Robotics Facts", "url": "https://store.ignatiusbookfairs.com/stem-starters-for-kids-robotics-activity-book-packed-with-activities-and-robotics-facts/", "take": "Mazes, spot-the-difference, drawing, quizzes — this colorful activity book sneaks real STEM learning in through robots. An easy, engaging introduction to science and technology for kids who like their facts served with puzzles."}, {"id": 1555, "title": "Sticky Facts: Animals", "url": "https://store.ignatiusbookfairs.com/sticky-facts-animals/", "take": "A clever twist on the sticker book: read a question, peel the sticker to reveal the answer underneath, then build your own book of animal facts. Learning and stickers in one sitting, pitched for ages 6 and up."}, {"id": 1587, "title": "Sticky Facts: Construction", "url": "https://store.ignatiusbookfairs.com/sticky-facts-construction/", "take": "The same clever Sticky Facts formula, aimed at construction fans: read a question, peel the sticker to reveal the answer, then build your own fact book on the activity pages. Learning disguised as stickers, for ages 6 and up."}, {"id": 1391, "title": "Stories of the Blessed Sacrament", "url": "https://store.ignatiusbookfairs.com/stories-of-the-blessed-sacrament/", "take": "Twelve true stories of the Real Presence, from the multiplication of the loaves to a brave girl in Nazi-occupied Poland. A lavishly illustrated way to help children know and love Jesus in the Eucharist."}, {"id": 1039, "title": "Stormy, Misty's Foal", "url": "https://store.ignatiusbookfairs.com/stormy-mistys-foal/", "take": "A hurricane slashes across Chincoteague just as Misty is about to give birth, and Paul and Maureen can only wait and worry. Marguerite Henry at her most gripping — the sequel her horse-story fans will race through."}, {"id": 1420, "title": "Strangers and Sojourners", "url": "https://store.ignatiusbookfairs.com/strangers-and-sojourners/", "take": "Michael O'Brien's epic opens a four-generation trilogy in the rugged interior of British Columbia, following an educated Englishwoman and her family from 1900 toward the millennium. Serious, spiritually rich fiction for adults."}, {"id": 2852, "title": "Student of the Cross : Saint Edith Stein", "url": "https://store.ignatiusbookfairs.com/student-of-the-cross-saint-edith-stein-ibc-1615/", "take": "A historical graphic novel tracing St. Edith Stein from her Jewish childhood through her conversion to Catholicism and her martyrdom in a Nazi gas chamber. A serious, truth-hungry saint told in a format that helps her story land."}, {"id": 992, "title": "Sugar Snow", "url": "https://store.ignatiusbookfairs.com/sugar-snow/", "take": "A late spring snow means more maple sap, and maple sap means sugar cakes and sticky fingers. This Little House adaptation, with Doris Ettlinger's full-color art, is pure cozy pioneer sweetness."}, {"id": 1849, "title": "Summer Blast: The Adventures of Nick and Sam", "url": "https://store.ignatiusbookfairs.com/summer-blast-the-adventures-of-nick-and-sam/", "take": "Twins Nick and Sam kick off summer in quirky Hope Springs, where an old family house brings unexpected problems. Likeable, relatable characters whose adventures make the Church's teachings come alive without ever feeling like a lesson."}, {"id": 1851, "title": "Summer Discovery: The Adventures of Nick and Sam", "url": "https://store.ignatiusbookfairs.com/summer-discovery-the-adventures-of-nick-and-sam/", "take": "Summer winds down for the Perry twins, but there is plenty left to do in Hope Springs. A satisfying finish to the season with the same engaging characters who make living the faith feel like an adventure."}, {"id": 1850, "title": "Summer Grace: The Adventures of Nick and Sam", "url": "https://store.ignatiusbookfairs.com/summer-grace-the-adventures-of-nick-and-sam/", "take": "July in Hope Springs means a big Fourth celebration and camp, and both hold surprises for twins Nick and Sam. Another warm, funny installment where Catholic family life and small-town adventure go hand in hand."}, {"id": 994, "title": "Summertime in the Big Woods", "url": "https://store.ignatiusbookfairs.com/summertime-in-the-big-woods/", "take": "Winter is over and Laura and Mary spend summer days in the garden and outdoors. A simple, sunny My First Little House adaptation for the youngest Wilder fans."}, {"id": 2857, "title": "Super Narwhal and Jelly Jolt", "url": "https://store.ignatiusbookfairs.com/super-narwhal-and-jelly-jolt/", "take": "Narwhal and Jelly discover their inner superheroes in three silly, sunny undersea stories. Pilkey called them the most lovable duo since Frog and Toad; we don't argue with that."}, {"id": 2772, "title": "Suppose You Meet a Dinosaur", "url": "https://store.ignatiusbookfairs.com/suppose-you-meet-a-dinosaur-ibc-1586/", "take": "A polite dinosaur in a grocery store teaches please-and-thank-you without a whiff of lecture. Sierra's read-aloud rhyme plus Bowers's art make manners genuinely giggly for preschoolers."}, {"id": 1665, "title": "Surprises: Poems Selected by Lee Bennett Hopkins", "url": "https://store.ignatiusbookfairs.com/surprises-poems-selected-by-lee-bennett-hopkins/", "take": "Thirty-eight short, simple rhyming poems about pets, vehicles, cooking, and space, chosen for beginning readers ages 3 to 7. A gentle, giggle-friendly first poetry anthology that doubles as reading practice."}, {"id": 2811, "title": "Survivor Diaries: Lost", "url": "https://store.ignatiusbookfairs.com/survivor-diaries-lost-ibc-1562/", "take": "Two kids, one Costa Rican jungle, zero trails. Written by a real survival expert, this series gives Hatchet and I Survived fans their next stay-calm-and-think fix."}, {"id": 2480, "title": "Sweet Like Milton Hershey: The Good Guys Academy  #3", "url": "https://store.ignatiusbookfairs.com/sweet-like-milton-hershey-the-good-guys-academy-3/", "take": "Book three in the Good Guys Agency series sends the gang back in time to meet Milton Hershey. Prose plus colorful comic panels keep the pages turning while kindness and generosity get the spotlight — a winning formula."}, {"id": 2751, "title": "Sweet Like Milton Hershey: The Good Guys Academy  #3", "url": "https://store.ignatiusbookfairs.com/sweet-like-milton-hershey-the-good-guys-academy-3-ibc-1537/", "take": "Book three in the Good Guys Agency series sends the trio back in time to meet Milton Hershey, whose chocolate empire came with a generous heart. Prose plus comic panels keep it fast-moving while kindness takes center stage."}, {"id": 2809, "title": "Sweetness at the Bottom of the Pie", "url": "https://store.ignatiusbookfairs.com/sweetness-at-the-bottom-of-the-pie-ibc-1591/", "take": "Eleven-year-old chemist Flavia de Luce solves a murder with poison expertise and acid wit. Technically an adult mystery, beloved by strong teen readers — one of the great heroines of the genre."}, {"id": 1562, "title": "Tag, Toss and Run: 40 Classic Lawn Games", "url": "https://store.ignatiusbookfairs.com/tag-toss-and-run-40-classic-lawn-games/", "take": "Forty time-tested lawn games — capture the flag, croquet, bocce, plus lesser-known finds like kubb and Cherokee marbles — with rules, strategies, and variations. A practical little argument for getting the whole gang outside on a long afternoon."}, {"id": 2199, "title": "Take it From the Top", "url": "https://store.ignatiusbookfairs.com/take-it-from-the-top/", "take": "Six summers of camp, two girls from different backgrounds, and a production of Wicked that surfaces every buried resentment. Swinarski tackles privilege, perspective, and friendship in a puzzle-structured page-turner. A strong pick for theater kids."}, {"id": 2851, "title": "Tales from Wakken Wood", "url": "https://store.ignatiusbookfairs.com/tales-from-wakken-wood-ip-twawp/", "take": "Silver-eyed Peter, his ailing best friend, and an island where the normal surface doesn't add up. An intriguing, faith-friendly mystery-fantasy for middle readers who like their strange with substance."}, {"id": 888, "title": "Tell Me About the Catholic Faith", "url": "https://store.ignatiusbookfairs.com/tell-me-about-the-catholic-faith/", "take": "When the questions start coming - about God, the Bible, the Church - this book gives parents a way to answer with stories instead of lectures. Beautiful illustrations and simple words carry children from Scripture through Christian history and Catholic belief."}, {"id": 1528, "title": "Tell Me about the Catholic Faith for Small Children", "url": "https://store.ignatiusbookfairs.com/tell-me-about-the-catholic-faith-for-small-children/", "take": "The best-selling Tell Me about the Catholic Faith, shortened and simplified for preschoolers and kindergartners, with gorgeous four-color illustrations on every page. A comprehensive sweep from Adam and Eve onward, sized for the youngest listeners."}, {"id": 2525, "title": "Ten Keys to Caring for Our World", "url": "https://store.ignatiusbookfairs.com/ten-keys-to-caring-for-our-world/", "take": "Ten simple, practical keys for caring for the world God has given us — sharing, stewardship, and habits of wonder, gratitude, and joy. Short, doable, and a gentle nudge toward gratitude for the whole family."}, {"id": 2235, "title": "Ten Keys to Good Manners", "url": "https://store.ignatiusbookfairs.com/ten-keys-to-good-manners/", "take": "Ten simple keys — please and thank you, table behavior, receiving gifts graciously — explained in plain language with charming illustrations. A helpful little book for teaching children that good manners are really about respect for others."}, {"id": 2861, "title": "Ten Keys to Happiness", "url": "https://store.ignatiusbookfairs.com/ten-keys-to-happiness/", "take": "Ten simple keys to help children explore what true happiness really means - the kind that grows quietly and hides in everyday moments. A thoughtful little book that invites conversation rather than lecturing."}, {"id": 1953, "title": "Terrapin", "url": "https://store.ignatiusbookfairs.com/terrapin/", "take": "Four childhood friends reunite for a weekend; by the first night one is murdered — or is he? A suspense novel that shuttles between the reunion gone wrong and the boyhood street where it all began. Clever, twisty fiction for adults."}, {"id": 1839, "title": "Thank God Ahead of Time Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/thank-god-ahead-of-time-vinyl-sticker/", "take": "Thank God ahead of time — a vinyl sticker preaching trust before the outcome arrives. A tiny catechesis in gratitude and providence, sized for a notebook, bumper, or water bottle."}, {"id": 2833, "title": "Thank you Lord", "url": "https://store.ignatiusbookfairs.com/thank-you-lord-ibc-6tylh/", "take": "A tender prayer of gratitude for little ones - birdsong, puddles, Daddy's strong arms, Mommy's cuddles - with windows that open on each page. A sweet way to teach small children wonder and thankfulness to the Lord."}, {"id": 1961, "title": "That Was Father Stu", "url": "https://store.ignatiusbookfairs.com/that-was-father-stu/", "take": "Father Stuart Long — former boxer, exuberant priest, fighter to the end against a rare degenerative disease — remembered by Father Bart Tolleson, the close friend ordained alongside him. Inspiring, insightful, and often genuinely funny."}, {"id": 918, "title": "The Adventures of Loupio Volume 1", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-1/", "take": "An orphaned young troubadour in 13th-century Italy falls in with Brother Francis of Assisi and a tamed wolf. This colorful comic-book series wears its faith lightly and its adventure proudly - a reliable handoff for graphic-novel kids."}, {"id": 919, "title": "The Adventures of Loupio Volume 2", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-2/", "take": "Volume 2 of the Loupio comics continues the young troubadour's escapades alongside Brother Francis and the wolf, as he learns to love and be loved. Same colorful comic-book format, same easy blend of medieval adventure and gentle formation."}, {"id": 920, "title": "The Adventures of Loupio Volume 3", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-3/", "take": "A medieval tournament, bigger and better-trained rivals, and some timely help from Brother Wolf - volume 3 sends Loupio into competition. This award-winning comic series keeps delivering full-color knightly adventure with heart."}, {"id": 921, "title": "The Adventures of Loupio Volume 4", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-4/", "take": "Six short comic adventures in one volume - The Inn, The Watchman, The Torrent, The Fog, The Bear, The Puppeteer - with St. Francis guiding Loupio throughout. A good pick for readers who like their stories quick, colorful, and complete."}, {"id": 922, "title": "The Adventures of Loupio Volume 5", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-5/", "take": "In The Cave, volume 5 of this best-selling comic series, Loupio confronts prejudice and burglary and learns what mercy costs. The Loupio books keep proving that a comic can carry real moral weight without losing its sense of adventure."}, {"id": 923, "title": "The Adventures of Loupio Volume 6", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-6/", "take": "Volume 6 sends Loupio on a quest for a bell for his friend St. Francis - a simple errand that turns into a proper adventure. Faith, hope, and charity keep growing through this dependable, colorful comic series."}, {"id": 924, "title": "The Adventures of Loupio Volume 7", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-loupio-volume-7/", "take": "Volume 7 introduces Clare of Assisi - the young woman who made Loupio's red cape - alongside more adventures with Francis and the wolf. A welcome addition for readers who have followed this comic series from the start."}, {"id": 933, "title": "The Adventures of Nick and Sam Book 1", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-1/", "take": "Book 1 of this Catholic family series: twins Nick and Sam pack in end-of-summer fun and promptly find trouble - snooped birthday presents, a stinky hike, a hard lesson about disobedience. Relatable, funny, and gently formative."}, {"id": 934, "title": "The Adventures of Nick and Sam Book 2", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-2/", "take": "Book 2 sends the Perry twins into a new school year full of discoveries: a family mystery, buried treasure, and a secret about guardian angels. Fun, faith-filled stories about the wonder hiding in ordinary life."}, {"id": 935, "title": "The Adventures of Nick and Sam Book 3", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-3/", "take": "Book 3 gives the Perry family its first Advent in Hope Springs: pageant rivalry, a flying-angel ambition, a Christmas-tree hunt gone sideways, and traditions that take on new meaning. A warm seasonal entry in a likeable Catholic series."}, {"id": 936, "title": "The Adventures of Nick and Sam Book 4", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-4/", "take": "In Trouble with Lent, the Perry twins tackle the season at school in quirky Hope Springs, Colorado. This series has a knack for making the Church's teachings come alive through ordinary family scrapes rather than sermons."}, {"id": 937, "title": "The Adventures of Nick and Sam Book 5", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-5/", "take": "A World of Wonder, book five, sends the Perry twins into the Great outdoors-scale adventures the series does well - likeable Catholic family life in quirky Hope Springs, where the faith comes alive through the everyday."}, {"id": 938, "title": "The Adventures of Nick and Sam Book 6", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-nick-and-sam-book-6/", "take": "View from the Top, book six, finds the Perry twins looking ahead to summer with more Hope Springs adventures in store. A dependable continuation for families already invested in this warm, faith-alive series."}, {"id": 2454, "title": "The Adventures of Sophie Mouse: The Great Bake Off", "url": "https://store.ignatiusbookfairs.com/the-adventures-of-sophie-mouse-the-great-bake-off/", "take": "Sophie Mouse and her mom bake more sweets than they can eat — but can they reach the village to share before the treats go bad? Easy language and near-constant illustrations make this fourteenth adventure perfect for beginning readers."}, {"id": 2124, "title": "The Alcatraz Escape: Book Scavenger #3", "url": "https://store.ignatiusbookfairs.com/the-alcatraz-escape-book-scavenger-3/", "take": "Emily and James head to Alcatraz for Unlock the Rock, an epic escape-room game co-designed by a famously reclusive mystery writer. The third Book Scavenger adventure delivers atmosphere, ciphers, and a satisfyingly twisty puzzle."}, {"id": 959, "title": "The Amazing Impossible Erie Canal", "url": "https://store.ignatiusbookfairs.com/the-amazing-impossible-erie-canal/", "take": "Cheryl Harness tells how De Witt Clinton spent eight years proving the doubters wrong and connecting the Hudson to the Great Lakes. American history as an engineering underdog story — fascinating and genuinely fun."}, {"id": 1399, "title": "The Autobiography of Miss Jane Pittman", "url": "https://store.ignatiusbookfairs.com/the-autobiography-of-miss-jane-pittman/", "take": "Ernest Gaines's legendary heroine narrates a century of American history in a voice critics rightly compared to Huckleberry Finn's. A landmark novel for older students studying the African American experience."}, {"id": 2398, "title": "The Awakening of Miss Prim", "url": "https://store.ignatiusbookfairs.com/the-awakening-of-miss-prim/", "take": "Prudencia Prim, accomplished and very sure of herself, takes a librarian post in a remote village and finds her ideas about life and love challenged at every turn. A bookish international bestseller for the adults at the fair table."}, {"id": 2519, "title": "The Awesome Super Fantastic Forever Party", "url": "https://store.ignatiusbookfairs.com/the-awesome-super-fantastic-forever-party/", "take": "Joni Eareckson Tada answers a question kids genuinely ask — what will heaven be like? — with a joyful, biblically faithful picture of the forever party to come. From the million-selling Tales That Tell the Truth series."}, {"id": 1900, "title": "The Ballad of the White Horse", "url": "https://store.ignatiusbookfairs.com/the-ballad-of-the-white-horse/", "take": "Chesterton's epic poem of King Alfred's battle against the Danes in 878, which doubles as a timeless allegory of Christianity against nihilism. Thrilling battles, mystical visions, and rhyme that begs to be read aloud. One of the last great English epics."}, {"id": 1054, "title": "The Bears on Hemlock Mountain", "url": "https://store.ignatiusbookfairs.com/the-bears-on-hemlock-mountain/", "take": "Jonathan isn't afraid to cross Hemlock Mountain alone — everyone says there are no bears there. But people aren't always right. A classic slow-build of wintry suspense with a payoff that delights young readers every single time."}, {"id": 2528, "title": "The Beautiful Life of St. Carlo Acutis", "url": "https://store.ignatiusbookfairs.com/the-beautiful-life-of-st-carlo-acutis/", "take": "Twenty true stories of a soccer-playing, video-gaming Italian teenager whose love for Jesus set him apart. Canonized in 2025, Carlo Acutis is a saint kids can actually see themselves in — relatable, joyful, and real."}, {"id": 887, "title": "The Beautiful Story of the Bible", "url": "https://store.ignatiusbookfairs.com/the-beautiful-story-of-the-bible/", "take": "The essential Bible stories - Creation, Noah, David and Goliath, the life of Jesus, the early Church - with expressive, gorgeous pictures pitched at children as young as three. A solid first Bible storybook for the littlest listeners."}, {"id": 2784, "title": "The Best Christmas Pageant Ever", "url": "https://store.ignatiusbookfairs.com/the-best-christmas-pageant-ever-ibc-1558/", "take": "The Herdmans, \"the worst kids in the history of the world,\" take over the Christmas pageant - and somehow it becomes the best one. Barbara Robinson's hilarious, heartwarming classic still earns its title every December."}, {"id": 2286, "title": "The Best of Sherlock Holmes: Ignatius Press Critical Edition", "url": "https://store.ignatiusbookfairs.com/the-best-of-sherlock-holmes-ignatius-press-critical-edition/", "take": "The twelve stories Conan Doyle himself named as the quintessential Holmes adventures, gathered in an Ignatius Press critical edition. A well-chosen doorway into Baker Street for readers meeting the great detective on the page at last."}, {"id": 2862, "title": "The Bible : Seek and Find series Volume 7", "url": "https://store.ignatiusbookfairs.com/the-bible-seek-and-find-series-volume-7/", "take": "Volume seven of the Seek and Find series sends children hunting for Sarah, Simon, two cats, and Gil the goat through great stories of the Old and New Testaments. Scripture and search-and-find fun on the same page."}, {"id": 1443, "title": "The Bible for Little Ones", "url": "https://store.ignatiusbookfairs.com/the-bible-for-little-ones/", "take": "The main stories from Creation to Pentecost, lovingly told with engaging illustrations and childproof padded pages with rounded corners. A genuinely durable first Bible for ages 2 and up - built to be chewed on and loved."}, {"id": 1855, "title": "The Bible Illustrated and Explained for Children", "url": "https://store.ignatiusbookfairs.com/the-bible-illustrated-and-explained-for-children/", "take": "Simple texts and vivid, detail-rich illustrations carry children from Creation to the early Church, with historical and cultural notes that add real context. A Bible built to grow with young readers rather than be outgrown."}, {"id": 891, "title": "The Big Book of Christians Around the World", "url": "https://store.ignatiusbookfairs.com/the-big-book-of-christians-around-the-world/", "take": "Two young reporters visit Christians in 25 countries - Mass by dugout canoe, icy January plunges, believers who must hide their faith. A genuinely eye-opening tour that shows children how big, varied, and brave the Christian family is."}, {"id": 2476, "title": "The Big Book of Life Skills for Kids", "url": "https://store.ignatiusbookfairs.com/the-big-book-of-life-skills-for-kids/", "take": "Sandy Silverthorne tackles the questions growing kids actually have — making friends, handling anger, even telling a joke — with humor and genuinely useful advice. A friendly, practical handbook for kids figuring out how life works."}, {"id": 1710, "title": "The Big Dipper", "url": "https://store.ignatiusbookfairs.com/the-big-dipper/", "take": "A clear, colorfully illustrated science picture book that helps young stargazers find the Big Dipper — and its companion, the Little Dipper. A fine first step into astronomy for early elementary readers."}, {"id": 1126, "title": "The Big Red Barn board book", "url": "https://store.ignatiusbookfairs.com/the-big-red-barn-board-book/", "take": "Margaret Wise Brown's rhythmic tour of a farm from morning to night, in a toddler-proof board edition. Like Goodnight Moon, it settles little ones down for sleep as gently as any book we stock."}, {"id": 2242, "title": "The Black Cauldron (The Chronicles of Prydain #2)", "url": "https://store.ignatiusbookfairs.com/the-black-cauldron-the-chronicles-of-prydain-2/", "take": "Taran's quest continues as the beloved Prydain cast — Eilonwy, Fflewddur, Gurgi, and grumpy Doli — is drawn into an epic struggle between good and evil. The second chapter of a fantasy series that has enthralled readers since 1964."}, {"id": 1043, "title": "The Black Stallion", "url": "https://store.ignatiusbookfairs.com/the-black-stallion/", "take": "Walter Farley's 1941 classic: a boy, a wild stallion, an ill-fated ship, a desert island, and the bond that forms between them. Still one of the great boy-and-horse adventures for young readers, new and old."}, {"id": 1044, "title": "The Black Stallion Returns", "url": "https://store.ignatiusbookfairs.com/the-black-stallion-returns/", "take": "The Black's claimed rightful owner appears — and so does someone trying to kill the stallion. Alec follows his beloved horse all the way to Arabia in a sequel full of evil, intrigue, and adventure for series fans."}, {"id": 1430, "title": "The Blessing of a Skinned Knee: Using Jewish Teachings to Raise Self-Reliant Children", "url": "https://store.ignatiusbookfairs.com/the-blessing-of-a-skinned-knee-using-jewish-teachings-to-raise-self-reliant-children/", "take": "Dr. Wendy Mogel draws on Jewish teachings to help parents raise self-reliant, grateful, compassionate kids instead of entitled ones. A bestselling parenting book with genuine wisdom about letting children struggle a little."}, {"id": 2231, "title": "The Book of Three (The Chronicles of Prydain #1)", "url": "https://store.ignatiusbookfairs.com/the-book-of-three-the-chronicles-of-prydain-1/", "take": "The 1964 Newbery-winning series opener that launched Taran the Assistant Pig-Keeper on his quest to become a hero, alongside sharp-tongued Princess Eilonwy and the faithful Gurgi. Classic fantasy that still enthralls young readers."}, {"id": 2177, "title": "The Boy who knew Carlo Acutis", "url": "https://store.ignatiusbookfairs.com/the-boy-who-knew-carlo-acutis/", "take": "Daniel, a teenager newly diagnosed with leukemia, reluctantly turns to Carlo Acutis and finds a role model who helps him trust God and find meaning. Corinna Turner weaves fiction and biography into a moving introduction to the young saint of our own era."}, {"id": 2224, "title": "The Camping Trip", "url": "https://store.ignatiusbookfairs.com/the-camping-trip/", "take": "Ernestine packs her new sleeping bag, new flashlight, and homemade snack mix, absolutely certain camping will be wonderful. What actually happens is funnier and truer. A warm first-camping-trip story that new campers and their parents will recognize instantly."}, {"id": 2524, "title": "The Carmelites of Compiegne: Martyrs of the French Revolution", "url": "https://store.ignatiusbookfairs.com/the-carmelites-of-compiegne-martyrs-of-the-french-revolution/", "take": "The sobering, luminous account of sixteen Carmelite nuns who offered their lives for peace during the Reign of Terror, singing as they went to the guillotine. Ten days later the Terror collapsed. A powerful martyrdom story, movingly told."}, {"id": 1110, "title": "The Cat in the Hat", "url": "https://store.ignatiusbookfairs.com/the-cat-in-the-hat/", "take": "A dreary day, two kids, one enormous cat, and Thing 1 and Thing 2. Simple words and bouncing rhyme make this the beloved classic that turns beginning readers into actual readers — mess, cleanup, and all."}, {"id": 2783, "title": "The Cat in the Hat Knows a Lot About That: 5-Minute Stories Colliection", "url": "https://store.ignatiusbookfairs.com/the-cat-in-the-hat-knows-a-lot-about-that-5-minute-stories-colliection-ibc-1587/", "take": "Nick, Sally, and the Cat answer the endless whys of ages 3-7, five minutes at a time. The rare bedtime collection engineered for exactly how long a parent's evening actually is."}, {"id": 1699, "title": "The Catholic Baby Name Book", "url": "https://store.ignatiusbookfairs.com/the-catholic-baby-name-book/", "take": "More than ten thousand saints' and biblical names, each with meaning, origin, a capsule biography, and feast days. A practical, browsable gift for expectant Catholic parents who want a name with a real story behind it."}, {"id": 1822, "title": "The Catholic Cartoon Collection #1", "url": "https://store.ignatiusbookfairs.com/the-catholic-cartoon-collection-1/", "take": "A first collection of Catholic cartoons. Expect light, faith-flavored humor in panel form — an easy pickup for kids who read everything comic-shaped, and a gentle way to mix laughter with the faith."}, {"id": 2499, "title": "The Catholic Cartoon Collection: No. 2", "url": "https://store.ignatiusbookfairs.com/the-catholic-cartoon-collection-no-2/", "take": "Fr. Otto and friends return for a second round of Catholic cartoons — laughs and holy moments side by side, in both color and black-and-white pages. Easy, wholesome fun for the comic-strip lovers in your parish or school."}, {"id": 895, "title": "The Catholic Faith from A to Z", "url": "https://store.ignatiusbookfairs.com/the-catholic-faith-from-a-to-z/", "take": "Fifty-two words, Advent to Zeal, each explained simply and tied to everyday life. Far more inviting than a dictionary has any right to be, with lovely illustrations throughout. A useful, browsable reference for Catholic homes and classrooms."}, {"id": 2023, "title": "The Catholic Home Gallery", "url": "https://store.ignatiusbookfairs.com/the-catholic-home-gallery/", "take": "A handsome answer to the idea that Catholic art belongs to the past. This collection surveys the Church's astonishing artistic patrimony, from catacomb etchings to Baroque exuberance, and makes the case for living with sacred art at home."}, {"id": 1750, "title": "The Childhood of Jesus: Coloring Book", "url": "https://store.ignatiusbookfairs.com/the-childhood-of-jesus-coloring-book/", "take": "Large coloring pages walk through Our Lord's young life as Scripture records it — the Annunciation, the Visitation, the Nativity, the Presentation. A quiet, faith-filled activity for little hands during Advent or any season."}, {"id": 2237, "title": "The Childhood of Jesus: Seek and Find Volume 5", "url": "https://store.ignatiusbookfairs.com/the-childhood-of-jesus-seek-and-find-volume-5/", "take": "In this fifth Seek and Find volume, children watch Jesus grow from baby to wise young boy while hunting for Sara, Simon, two cats, a goat, and a three-legged dog on every busy page. Searching and learning, happily combined."}, {"id": 1046, "title": "The Children of Noisy Village", "url": "https://store.ignatiusbookfairs.com/the-children-of-noisy-village/", "take": "From the author of Pippi Longstocking: a year with six children on three Swedish farms — crayfishing in summer, dipping in the pot at Christmas, nutting at New Year. Gently funny, deeply cozy, and lovely to read aloud."}, {"id": 1662, "title": "The Children's Homer: The Adventures of Odysseus and the Tale of Troy", "url": "https://store.ignatiusbookfairs.com/the-childrens-homer-the-adventures-of-odysseus-and-the-tale-of-troy/", "take": "Padraic Colum, a Newbery Honor storyteller, retells the Iliad and Odyssey for young readers — Achilles at Troy, Odysseus facing Scylla and Circe. Still one of the best doorways into Greek epic for children."}, {"id": 1692, "title": "The Christmas Promise", "url": "https://store.ignatiusbookfairs.com/the-christmas-promise/", "take": "An Arch Book tracing God's promise of a Savior from the Garden of Eden all the way to Bethlehem, in the series' familiar rhyme-and-bright-pictures format. Scripturally sound and easy to remember, for ages 5-9."}, {"id": 1495, "title": "The Christmas Star", "url": "https://store.ignatiusbookfairs.com/the-christmas-star/", "take": "Maite Roche's glorious illustrations carry the very young through the Christmas story — Wise Men following the star, shepherds and angels, and the Baby Jesus in the humble stable. A first Nativity book that is genuinely beautiful to look at."}, {"id": 2216, "title": "The Christmas Story Brick by Brick", "url": "https://store.ignatiusbookfairs.com/the-christmas-story-brick-by-brick/", "take": "The Christmas story retold in faithful rhyme and photographed in real brick builds, with five builds kids can make themselves. A genuinely clever way to get Lego-loving children engaging with who Jesus is and why he came."}, {"id": 2872, "title": "The Christmas Trolls", "url": "https://store.ignatiusbookfairs.com/the-christmas-trolls/", "take": "Presents are vanishing before Christmas, and when Treva spots a small creature making off with the pudding, she chases it into the forest. A cozy holiday adventure with just the right pinch of mischief and wonder."}, {"id": 1028, "title": "The Chronicles of Narnia Set (7 books)", "url": "https://store.ignatiusbookfairs.com/the-chronicles-of-narnia-set-7-books/", "take": "All seven Narnia books in one box, from The Magician's Nephew onward. Four wartime siblings, a wardrobe, and Aslan — a complete set of one of the great read-aloud and read-alone series for families."}, {"id": 1097, "title": "The Chronicles of Transformation", "url": "https://store.ignatiusbookfairs.com/the-chronicles-of-transformation/", "take": "An exploration of the moral and spiritual journey C. S. Lewis built into Narnia — courage tested, character forged, wonder reawakened. For grown readers who suspect the Chronicles were never just for children."}, {"id": 1829, "title": "The Circus Ship", "url": "https://store.ignatiusbookfairs.com/the-circus-ship/", "take": "A circus ship runs aground off the Maine coast, and the animals swim ashore to win over a wary island town — until the greedy circus owner comes back. Rhyming text, stunning artwork from the Mercy Watson illustrator, and a deeply satisfying conspiracy."}, {"id": 2788, "title": "The City of Ember: The Graphic Novel", "url": "https://store.ignatiusbookfairs.com/the-city-of-ember-the-graphic-novel-ibc-1622/", "take": "The modern classic about an underground city doomed to darkness, retold as a graphic novel. Lina and Doon race to decipher a message from the past before Ember's lights go out forever. A striking way into a beloved story."}, {"id": 2826, "title": "The Clockwork Crow", "url": "https://store.ignatiusbookfairs.com/the-clockwork-crow-ibc-1565/", "take": "An orphan, a snowed-in Welsh manor, and a crotchety mechanical crow with opinions. Winter fantasy with classic Aiken/Ibbotson bones — atmospheric bedtime reading for 8-12s."}, {"id": 2206, "title": "The Comic Book Lesson: A Graphic Novel", "url": "https://store.ignatiusbookfairs.com/the-comic-book-lesson-a-graphic-novel/", "take": "Mark Crilley teaches comic-making through an actual graphic novel: an aspiring young creator learns art, design, and storytelling from three mentors. Instruction that practices what it preaches, ideal for the kid always drawing in the margins."}, {"id": 1448, "title": "The Coming of the Holy Spirit", "url": "https://store.ignatiusbookfairs.com/the-coming-of-the-holy-spirit/", "take": "Pentecost — the church's birthday — retold in Arch Books rhyme with bright pictures, straight from Acts 2. A complete Bible story children ages 5-9 can read, remember, and retell, which is exactly what this sturdy series has done well since 1964."}, {"id": 1864, "title": "The Confessions: Saint Augustine of Hippo", "url": "https://store.ignatiusbookfairs.com/the-confessions-saint-augustine-of-hippo/", "take": "Augustine's autobiography is really one long, passionate prayer, confessing his sins and proclaiming God's goodness. Sixteen centuries later his conversion story still reads with startling immediacy. If a student meets one Christian classic, make it this."}, {"id": 1865, "title": "The Consolation of Philosophy", "url": "https://store.ignatiusbookfairs.com/the-consolation-of-philosophy/", "take": "Written by Boethius in prison while awaiting execution, this sixth-century conversation with Lady Philosophy shaped the whole medieval mind. Part prose, part poetry, all wrestling with what life is actually for. Demanding, and worth it."}, {"id": 1053, "title": "The Courage of Sarah Noble", "url": "https://store.ignatiusbookfairs.com/the-courage-of-sarah-noble/", "take": "In 1707, eight-year-old Sarah travels the wilderness with her father to build the family's new home, her mother's words ringing: keep up your courage. A Newbery Honor classic drawn from a true and genuinely inspiring journey."}, {"id": 1668, "title": "The Cure of Ars: The Priest who Out-Talked the Devil", "url": "https://store.ignatiusbookfairs.com/the-cure-of-ars-the-priest-who-out-talked-the-devil/", "take": "Jean-Marie Vianney could not learn Latin, and it seemed the humble, slow-thinking farm boy would never be ordained. This Vision book for ages 9-15 shows how he became the beloved patron of parish priests."}, {"id": 2200, "title": "The Dark Skies Mystery", "url": "https://store.ignatiusbookfairs.com/the-dark-skies-mystery/", "take": "It's 1942, and Henry Hamilton wants to be a reporter, not a soldier. His city's air raid program hands him a scoop far more perilous than he imagined. Home-front WWII mystery with real momentum for middle-grade readers."}, {"id": 988, "title": "The Deer in the Wood", "url": "https://store.ignatiusbookfairs.com/the-deer-in-the-wood/", "take": "The quietest of the Little House adaptations: Laura and Mary listen as Pa describes meeting a mother deer and her fawn in the Big Woods. Tender and simple, well suited to the very youngest listeners."}, {"id": 2152, "title": "The Devil's Ransom (Harwood Mysteries #6)", "url": "https://store.ignatiusbookfairs.com/the-devils-ransom-harwood-mysteries-6/", "take": "The Harwood Mysteries close with their most perilous case: a sea voyage to ransom Uncle William from Moorish pirates at the dawn of the Third Crusade. Medieval adventure where faith and friendship carry real weight, and a satisfying finish for series fans."}, {"id": 1056, "title": "The Disappeared", "url": "https://store.ignatiusbookfairs.com/the-disappeared/", "take": "Silvia will do anything to find her Disappeared brother in 1970s Argentina — even charm the general's foolish son. Gloria Whelan alternates the siblings' voices in a sobering, gripping novel that gives hard history a human face."}, {"id": 1032, "title": "The Door in the Wall", "url": "https://store.ignatiusbookfairs.com/the-door-in-the-wall/", "take": "Robin, a nobleman's son bound for knighthood, loses the use of his legs and is rescued by a monk who teaches him woodcarving, patience, and strength. A moving medieval story about finding another door through."}, {"id": 1630, "title": "The Drinking Gourd: A Story of the Underground Railroad", "url": "https://store.ignatiusbookfairs.com/the-drinking-gourd-a-story-of-the-underground-railroad/", "take": "A Level 3 I Can Read telling of the Underground Railroad through Tommy, a ten-year-old Quaker boy whose family hides a fleeing enslaved family. First-person, historically grounded, and quietly gripping — a strong bridge into American history for young readers."}, {"id": 1637, "title": "The Eagle of the Ninth", "url": "https://store.ignatiusbookfairs.com/the-eagle-of-the-ninth/", "take": "A young Roman centurion, invalided out after his first battle in Britain, sets off to discover what became of the vanished Ninth Legion his father led — and its lost Eagle. Classic historical adventure with real weight behind the swordplay."}, {"id": 1538, "title": "The Edge", "url": "https://store.ignatiusbookfairs.com/the-edge/", "take": "A billionaire's world-uniting peace climb in the Hindu Kush goes very wrong when the remote base camp is attacked. Fifteen-year-old Peak Marcello returns in a gripping, high-stakes climbing adventure — an easy handoff to fans of Peak."}, {"id": 1406, "title": "The Egg Tree", "url": "https://store.ignatiusbookfairs.com/the-egg-tree/", "take": "Katy finds Grandmom's hand-painted eggs in the attic, and a Pennsylvania Dutch Easter tradition is born. This Caldecott Medal winner will have children begging to make an egg tree of their own."}, {"id": 2139, "title": "The Extraordinary Education of Nicholas Benedict", "url": "https://store.ignatiusbookfairs.com/the-extraordinary-education-of-nicholas-benedict/", "take": "Before the Society, there was nine-year-old Nicholas Benedict: orphaned, narcoleptic, saddled with an unfortunate nose, and off to a new orphanage full of bullies. A prequel with real heart about a brilliant boy nobody has claimed yet."}, {"id": 1586, "title": "The Family Butterfly Book: Projects, activities, and a field guide to 40 favorite North American species", "url": "https://store.ignatiusbookfairs.com/the-family-butterfly-book-projects-activities-and-a-field-guide-to-40-favorite-north-american-species/", "take": "Rick Mikula's family guide to butterflies pairs a field guide to 40 North American species with 40 hands-on projects — building habitats, hand-feeding, raising butterflies through their lifecycle. Close-up photography throughout. A lovely backyard-science rabbit hole for the whole family."}, {"id": 1137, "title": "The Family Under the Bridge", "url": "https://store.ignatiusbookfairs.com/the-family-under-the-bridge/", "take": "A Newbery Honor classic about Armand, a Paris tramp who likes his carefree life until three children upend it. Warm without being sugary, and especially good reading at Christmastime. Garth Williams's artwork seals it."}, {"id": 1894, "title": "The Father's Tale", "url": "https://store.ignatiusbookfairs.com/the-fathers-tale/", "take": "A widowed Canadian bookseller's son vanishes, and the father follows the merest thread of a trail out of his safe, orderly world. O'Brien calls it a retelling of the Good Shepherd and the Prodigal Son. A long, absorbing journey."}, {"id": 2162, "title": "The Finest Hours", "url": "https://store.ignatiusbookfairs.com/the-finest-hours/", "take": "The true 1952 Coast Guard rescue off Cape Cod, with two tankers torn in half and four young men in a tiny lifeboat, retold as an illustrated chapter book. Real-life heroism that grips reluctant readers the way fiction often can't."}, {"id": 2155, "title": "The Fire of Eden (Harwood Mysteries #3)", "url": "https://store.ignatiusbookfairs.com/the-fire-of-eden-harwood-mysteries-3/", "take": "A priceless ruby vanishes from Harwood Abbey, and Xan must team up with John, his blinded and bitter enemy. The mystery is good; the slow mending between two orphan rivals is better. Catholic storytelling that earns its lessons."}, {"id": 2252, "title": "The Flower Fairies Coloring Book", "url": "https://store.ignatiusbookfairs.com/the-flower-fairies-coloring-book/", "take": "Cicely Mary Barker's beloved Flower Fairies, ready for crayons and colored pencils. A simple, pretty pick for any young fan of the fairies — or any child who likes their coloring on the enchanting side."}, {"id": 1891, "title": "The Fool of New York City", "url": "https://store.ignatiusbookfairs.com/the-fool-of-new-york-city/", "take": "Two so-called fools in present-day Manhattan, a literal giant and an amnesiac who believes he is Goya, help each other recover lost identity. O'Brien at his most tender and strange. A moving novel for adult readers."}, {"id": 955, "title": "The Fourth of July Story", "url": "https://store.ignatiusbookfairs.com/the-fourth-of-july-story/", "take": "Alice Dalgliesh, a two-time Newbery Honor author, tells the story of America's birthday in a way young readers can actually follow. A solid, full-color starting point for talking about the Fourth beyond fireworks."}, {"id": 1005, "title": "The Fox Went Out on a Chilly Night", "url": "https://store.ignatiusbookfairs.com/the-fox-went-out-on-a-chilly-night/", "take": "Peter Spier's Caldecott Honor take on the classic American folk song, with New England autumn scenes the New York Times called almost startlingly beautiful — and decades later, Spier painted the remaining pages in full color."}, {"id": 2262, "title": "The Friendship War", "url": "https://store.ignatiusbookfairs.com/the-friendship-war/", "take": "Grace accidentally starts a school-wide fad and finally steps out of best-friend Ellie's shadow — and then things get complicated. From the author of Frindle, a sharp, fabulous school story about fads and what friendship can survive."}, {"id": 983, "title": "The Frog and Toad Collection Box Set (3 books)", "url": "https://store.ignatiusbookfairs.com/the-frog-and-toad-collection-box-set-3-books/", "take": "Three classics in one slipcase, including the Caldecott Honor and Newbery Honor titles. Arnold Lobel's gentle stories of friendship through every season remain some of the best early reading ever made."}, {"id": 876, "title": "The Garden of Wonders", "url": "https://store.ignatiusbookfairs.com/the-garden-of-wonders/", "take": "A tender premise handled well: Rica faces surgery, and through her grandmother and an encounter with St. Hildegard of Bingen, learns to see creation as gift. A quiet, consoling meditation for young people going through hard things."}, {"id": 2516, "title": "The Garden, the Curtain and the Cross Storybook: The True Story of Why Jesus Died and Rose Again", "url": "https://store.ignatiusbookfairs.com/the-garden-the-curtain-and-the-cross-storybook-the-true-story-of-why-jesus-died-and-rose-again/", "take": "From the million-selling Tales That Tell the Truth series: a journey from Eden to the new creation, centered on the torn temple curtain. A clear, beautiful gospel presentation for 3-6 year olds — theology at picture-book height."}, {"id": 1414, "title": "The Gift from the Sea", "url": "https://store.ignatiusbookfairs.com/the-gift-from-the-sea/", "take": "Anne Morrow Lindbergh draws quiet wisdom from shells on the shore - meditations on youth, marriage, solitude, and contentment. A slim classic that mothers pass along to each other for good reason."}, {"id": 1843, "title": "The Girl and the Cathedral: The Story of Notre-Dame de Paris", "url": "https://store.ignatiusbookfairs.com/the-girl-and-the-cathedral-the-story-of-notre-dame-de-paris/", "take": "A little girl plants a garden of people — Paris — with a majestic cathedral as its guardian. This beautifully illustrated telling of Notre-Dame's story earned a School Library Journal starred review and a Maxy Award. Moving without being heavy."}, {"id": 1413, "title": "The Golden Egg Book", "url": "https://store.ignatiusbookfairs.com/the-golden-egg-book/", "take": "A little bunny finds a blue egg and wonders what could be inside. Margaret Wise Brown's playful springtime classic, with Caldecott Medalist Leonard Weisgard's illustrations, is just right for the littlest hands at Easter."}, {"id": 1482, "title": "The Golden Goblet", "url": "https://store.ignatiusbookfairs.com/the-golden-goblet/", "take": "A Newbery Honor mystery in ancient Thebes: Ranofer longs to be a master goldsmith like his father, but his cruel half brother stands in the way — until a priceless golden goblet appears in Gebu's room. Historical fiction with genuine suspense."}, {"id": 1497, "title": "The Golden Thread: A Novel About St. Ignatius Loyola", "url": "https://store.ignatiusbookfairs.com/the-golden-thread-a-novel-about-st-ignatius-loyola/", "take": "Louis de Wohl weaves St. Ignatius Loyola's conversion and pilgrimage into the colorful, dangerous world of sixteenth-century Spain and Italy. Considered one of de Wohl's finest novels — for older readers who want their saints full-blooded and human."}, {"id": 1576, "title": "The Good Master", "url": "https://store.ignatiusbookfairs.com/the-good-master/", "take": "A Newbery Honor classic set on the Hungarian plains: Jancsi's summer transforms when headstrong cousin Kate arrives from Budapest, bringing horseback races, country fairs, and real adventure. Vividly detailed, beautifully illustrated, and full of old-world warmth."}, {"id": 1563, "title": "The Gospel for Little Ones", "url": "https://store.ignatiusbookfairs.com/the-gospel-for-little-ones/", "take": "The life of Jesus from Annunciation to Ascension in simple, beautiful language, printed on hard childproof pages with rounded corners. A sturdy, charming first Gospel for the very youngest — built to survive being loved by toddlers."}, {"id": 882, "title": "The Gospel Told by the Animals", "url": "https://store.ignatiusbookfairs.com/the-gospel-told-by-the-animals/", "take": "The Gospel retold by the ox, the fish, the trembling little donkey - twelve animals who wonder aloud who this child, this man, this king really is. Playful and profound at once, with artful illustrations. A genuinely fresh angle on familiar stories."}, {"id": 1556, "title": "The Great Divorce", "url": "https://store.ignatiusbookfairs.com/the-great-divorce/", "take": "A dreamer boards a bus and rides between Hell and Heaven, meeting souls who reveal how everyday choices harden into eternity. A profound, surprisingly readable meditation on good and evil — the kind of book older readers argue about afterward, happily."}, {"id": 2125, "title": "The Green Ember", "url": "https://store.ignatiusbookfairs.com/the-green-ember/", "take": "Heather and Picket are ordinary rabbits until calamity spills them into a world of falling kings and broken roads. An earnest, old-fashioned adventure about courage and loyalty that families have taken to heart."}, {"id": 2249, "title": "The Green Glass Sea", "url": "https://store.ignatiusbookfairs.com/the-green-glass-sea/", "take": "It's 1943 and eleven-year-old Dewey arrives at a town that officially doesn't exist: Los Alamos. A Scott O'Dell Award winner about friendship blooming in the shadow of the biggest secret of the war."}, {"id": 1523, "title": "The Harp and Laurel Wreath", "url": "https://store.ignatiusbookfairs.com/the-harp-and-laurel-wreath/", "take": "Laura Berquist's anthology gathers poetry for grades one through twelve, chosen to enrich language and form a love of the beautiful and true. One volume, every age level — a memorization and recitation backbone worth keeping on the shelf for years."}, {"id": 2156, "title": "The Haunted Cathedral (Harwood Mysteries #2)", "url": "https://store.ignatiusbookfairs.com/the-haunted-cathedral-harwood-mysteries-2/", "take": "Orphaned Xan leaves the abbey to find a long-lost uncle in far-off Lincoln, traveling alongside a prisoner and his cruel guards, drawn all the while to the spirit haunting Lincoln Cathedral. Atmospheric medieval mystery with real heart."}, {"id": 1390, "title": "The Hiding Place", "url": "https://store.ignatiusbookfairs.com/the-hiding-place/", "take": "Corrie ten Boom's account of hiding Jews from the Nazis and surviving the camps is one of the twentieth century's great testimonies of faith under fire. Hard, hopeful, and unforgettable for older readers and adults."}, {"id": 2776, "title": "The Hobbit", "url": "https://store.ignatiusbookfairs.com/the-hobbit-ibc-1635/", "take": "Bilbo Baggins, a comfort-loving hobbit who surprises even himself, dragged into a quest for dragon-guarded gold. Trolls, goblins, Smaug, and the Battle of Five Armies - the adventure story generations of readers started with."}, {"id": 2118, "title": "The Hobbit and Lord of the Rings Box Set", "url": "https://store.ignatiusbookfairs.com/the-hobbit-and-lord-of-the-rings-box-set/", "take": "All four books, one box: Bilbo's unlikely quest with Thorin's dwarves, then the epic of the Ring itself. If a young reader is ready for Tolkien, this is the tidiest way to hand them the whole journey."}, {"id": 1914, "title": "The Holiness of Ordinary People", "url": "https://store.ignatiusbookfairs.com/the-holiness-of-ordinary-people/", "take": "Madeleine Delbrel, French poet and social worker, insisted the ordinary street where God places us is the site of our holiness. A book for people with ordinary jobs and ordinary households who suspect sanctity is still meant for them."}, {"id": 1785, "title": "The Holy Mass: On Earth as it is in Heaven", "url": "https://store.ignatiusbookfairs.com/the-holy-mass-on-earth-as-it-is-in-heaven/", "take": "Fulton and Cynthia return in comic-book format to walk children through the Holy Mass — the Real Presence, God's plan of salvation, and the Old Testament fulfilled in the New. Substantial catechesis in a form kids will actually pick up."}, {"id": 1658, "title": "The Homelanders (4 books in 1)", "url": "https://store.ignatiusbookfairs.com/the-homelanders-4-books-in-1/", "take": "Charlie West went to bed an ordinary high schooler and woke up strapped to a chair, wanted for his best friend's death. All four Homelanders thrillers in one volume — relentless pacing for teen suspense fans."}, {"id": 1595, "title": "The Horse in Harry's Room", "url": "https://store.ignatiusbookfairs.com/the-horse-in-harrys-room/", "take": "Harry keeps a horse in his room — a trusty one only he can see. Then he meets real horses, free to run and kick, and faces a genuinely tender question: does his horse need freedom too? Quietly wise."}, {"id": 928, "title": "The Hound of the Lord", "url": "https://store.ignatiusbookfairs.com/the-hound-of-the-lord/", "take": "The life of St. Dominic, narrated by Torch, his legendary faithful dog - from a village boyhood in Spain to founding the Dominican Order across medieval Europe. The canine narrator is a genuinely clever way into a great saint's story."}, {"id": 1907, "title": "The Hundredfold", "url": "https://store.ignatiusbookfairs.com/the-hundredfold/", "take": "Anthony Esolen, translator of Dante, turns poet himself: hymns, monologues, and lyrics knit into one book-length poem in praise of Christ in all his startling humanity. Formal verse in the tradition of Donne and Milton. For lovers of real poetry."}, {"id": 1621, "title": "The Hunters: Brotherband Chronicles Book 3", "url": "https://store.ignatiusbookfairs.com/the-hunters-brotherband-chronicles-book-3/", "take": "Book three of the Brotherband Chronicles sends Hal and his crew down mighty rivers and terrifying rapids in pursuit of the pirate Zavac and the stolen Andomal. High-momentum seafaring adventure for readers who like their heroes tested hard."}, {"id": 886, "title": "The Illustrated Acts of the Apostles for Children", "url": "https://store.ignatiusbookfairs.com/the-illustrated-acts-of-the-apostles-for-children/", "take": "Picks up where the Gospel leaves off: Pentecost, the first miracles, the early Church - all in vibrant comic-book style illustrations from St. Luke's Acts. A format that turns the apostles' adventures into something kids actually reach for."}, {"id": 883, "title": "The Illustrated Bible for Children", "url": "https://store.ignatiusbookfairs.com/the-illustrated-bible-for-children/", "take": "Old and New Testament episodes retold in graphic-strip style with simple text and full-color art - Abraham, Moses, David, Jesus, the Apostles. A smart pick for reluctant readers who would balk at a traditional children's Bible."}, {"id": 2529, "title": "The Illustrated Edgar Allan Poe", "url": "https://store.ignatiusbookfairs.com/the-illustrated-edgar-allan-poe/", "take": "Twenty-five Poe poems — The Raven, The Bells, and more — with full-color collage art, brief commentary, and helpful definitions. One of the most accessible and beautiful ways to introduce students to Poe. The advice given: enjoy the poems first."}, {"id": 1423, "title": "The Illustrated Gospel for Children", "url": "https://store.ignatiusbookfairs.com/the-illustrated-gospel-for-children/", "take": "The life, death, and resurrection of Jesus in a tasteful comic-book style - vibrant illustrations, simple text, and none of the Gospel's saving power lost in the telling. A smart format for reaching young readers."}, {"id": 1581, "title": "The Illustrated Miracles of Jesus for Children", "url": "https://store.ignatiusbookfairs.com/the-illustrated-miracles-of-jesus-for-children/", "take": "Selected miracles of Jesus from the Gospels, told in tasteful comic-book style with bright, bold illustrations and brief introductions setting each scene. An inviting format for kids to read alone or with family — and every miracle points to joy."}, {"id": 1965, "title": "The Innocents and Other Stories", "url": "https://store.ignatiusbookfairs.com/the-innocents-and-other-stories/", "take": "Four more Gertrud von le Fort novellas newly in English, including the poignant postwar family drama The Innocents. Ominous, page-turning historical fiction about war, suffering, and justice — a natural companion to The Wife of Pilate volume."}, {"id": 1463, "title": "The Invaders: Brotherband Chronicles Book 2", "url": "https://store.ignatiusbookfairs.com/the-invaders-brotherband-chronicles-book-2/", "take": "Hal's underdog crew won the Brotherband competition — then Skandia's most sacred artifact is stolen on their watch, and redemption means chasing the thief across stormy seas. Book two delivers the same propulsive adventure that made Ranger's Apprentice a phenomenon."}, {"id": 1915, "title": "The Jeweler's Shop", "url": "https://store.ignatiusbookfairs.com/the-jewelers-shop/", "take": "Pope John Paul II's three-act play about love and marriage, set outside a small-town jeweler's shop and inside the human heart, in the only English translation authorized by the Vatican. Spare, poetic, and surprisingly piercing for couples and drama lovers."}, {"id": 1564, "title": "The Joyful Beggar: A Novel about Saint Francis of Assisi", "url": "https://store.ignatiusbookfairs.com/the-joyful-beggar-a-novel-about-saint-francis-of-assisi/", "take": "Louis de Wohl at full narrative power: Francis Bernardone, the brash, pleasure-loving young officer of 13th-century Assisi who became the most beloved of saints. Action-packed and stirring, set against Italy and Egypt in a tempestuous age."}, {"id": 2799, "title": "The Kidnapped Prince", "url": "https://store.ignatiusbookfairs.com/the-kidnapped-prince-ibc-6kpp/", "take": "Two pardoned prisoners must find the missing prince whose birth freed them. Knights, castles, and honest-to-goodness adventure in a clean, satisfying package for middle readers."}, {"id": 1083, "title": "The Kids' Book of Chess and Starter Kit", "url": "https://store.ignatiusbookfairs.com/the-kids-book-of-chess-and-starter-kit/", "take": "A complete chess kit for ages 8-12: board, all 32 pieces, and a 96-page guide through openings, middle game, endgame, and winning strategies — with full-color fantasy art that makes the 900-year-old game feel like an adventure."}, {"id": 1074, "title": "The Kids' Building Workshop: 15 Woodworking Projects for Kids and Parents to Build Together", "url": "https://store.ignatiusbookfairs.com/the-kids-building-workshop-15-woodworking-projects-for-kids-and-parents-to-build-together/", "take": "Real carpentry for kids: driving a nail properly, drilling safely, measuring first — then fifteen parent-and-child builds from birdhouses to lemonade stands. The kind of book that produces skills, sawdust, and shared afternoons."}, {"id": 1004, "title": "The Kitchen Knight: A Tale of King Arthur", "url": "https://store.ignatiusbookfairs.com/the-kitchen-knight-a-tale-of-king-arthur/", "take": "From the creators of the Caldecott Medal-winning Saint George and the Dragon: young Sir Gareth serves humbly in King Arthur's kitchen before his true noble blood is revealed. Lush illustrations, honest chivalry."}, {"id": 2273, "title": "The Knight at Dawn: Magic Tree House - The Graphic Novel", "url": "https://store.ignatiusbookfairs.com/the-knight-at-dawn-magic-tree-house-the-graphic-novel/", "take": "Jack and Annie's castle adventure, retold in vibrant full-color graphic novel form. A perfect on-ramp for kids who love comics but aren't reaching for chapter books yet — and a nostalgic treat for Magic Tree House families."}, {"id": 1779, "title": "The Knight's Quest", "url": "https://store.ignatiusbookfairs.com/the-knights-quest/", "take": "Young squire Rodrigo must choose which lord to serve, and finds his answer with the great war hero Inigo of Loyola. A chivalric tale about discovering the goodness of God and the true desire of your own heart."}, {"id": 2187, "title": "The Lady of Guadalupe", "url": "https://store.ignatiusbookfairs.com/the-lady-of-guadalupe/", "take": "Tomie dePaola retells Juan Diego's 1531 encounter with Our Lady of Guadalupe, drawing on original sources, in his tender words and pictures. A beautiful bridge between cultures and generations, and a story every Catholic child should know."}, {"id": 1918, "title": "The Last Crusader: A Novel about Don Juan of Austria", "url": "https://store.ignatiusbookfairs.com/the-last-crusader-a-novel-about-don-juan-of-austria/", "take": "Louis de Wohl's opulent historical novel of Don Juan of Austria, the emperor's son raised in a peasant's hut who rose through a court of intrigue on intelligence, kindness, and devotion to the Church. Sweeping Catholic historical fiction done right."}, {"id": 2815, "title": "The Last Thing I Remember / Homelander 1", "url": "https://store.ignatiusbookfairs.com/the-last-thing-i-remember-homelander-1-ibc-1563/", "take": "Charlie West wakes up strapped to a chair, covered in bruises, with a year of his life missing - and a voice outside ordering his death. This teen thriller series opens at a sprint and doesn't let up."}, {"id": 1921, "title": "The Leaves Are Falling", "url": "https://store.ignatiusbookfairs.com/the-leaves-are-falling/", "take": "An elderly London bookseller, rescued from the ruins of Europe at sixteen, finds his father in a story about Weimar Germany and begins to tell his own. A quiet, memory-haunted novel of war's aftermath for thoughtful adult readers."}, {"id": 909, "title": "The Legend of the Indian Paintbrush", "url": "https://store.ignatiusbookfairs.com/the-legend-of-the-indian-paintbrush/", "take": "DePaola retells the old Indian legend of how the Indian Paintbrush got its name: a boy's Dream-Vision, a calling to paint, and colors as pure as sunset. A beautiful story about vocation and faithfulness to one's gift."}, {"id": 911, "title": "The Legend of the Poinsettia", "url": "https://store.ignatiusbookfairs.com/the-legend-of-the-poinsettia/", "take": "The Mexican legend of how the poinsettia came to bloom at Christmas, born of a little girl's unselfish gift to the Christ Child. DePaola's glorious paintings and evident love of Christmas make this a seasonal read-aloud worth keeping."}, {"id": 2244, "title": "The Library of Ever", "url": "https://store.ignatiusbookfairs.com/the-library-of-ever/", "take": "Bored Lenora finds a secret doorway into a mazelike library containing every book ever written and every fact ever known — and becomes a warrior for knowledge itself. A reality-bending middle grade adventure made for booklovers."}, {"id": 885, "title": "The Life of Jesus According to Saint Luke", "url": "https://store.ignatiusbookfairs.com/the-life-of-jesus-according-to-saint-luke/", "take": "The Gospel of Luke presented for children, with extra notes on each page explaining the Word of God and the world Jesus lived in. Lavishly illustrated, and built to start a friendship with Jesus rather than just recount events."}, {"id": 929, "title": "The Life of Jesus: Seek and Find Volume 1", "url": "https://store.ignatiusbookfairs.com/the-life-of-jesus-seek-and-find-volume-1/", "take": "A seek-and-find book built around twelve key events in the life of Jesus: children hunt for Sarah and Simon in busy, colorful scenes while absorbing the Gospel almost by accident. Interactive in the best sense."}, {"id": 878, "title": "The Life of St. Benedict", "url": "https://store.ignatiusbookfairs.com/the-life-of-st-benedict/", "take": "Told by a Benedictine monk living at Benedict's own birthplace and drawn from Pope St. Gregory the Great's biography, these stories of the saint's wisdom and miracles carry unusual authenticity. Rich family read-aloud material, with his twin sister Scholastica included."}, {"id": 1496, "title": "The Light at Tern Rock", "url": "https://store.ignatiusbookfairs.com/the-light-at-tern-rock/", "take": "A Newbery Honor story: Ronnie and his aunt tend the Tern Rock lighthouse for two December weeks — then the keeper doesn't return, and Christmas approaches at sea. Quiet, atmospheric, with an old-fashioned moral center that suits the season."}, {"id": 1927, "title": "The Lighthouse", "url": "https://store.ignatiusbookfairs.com/the-lighthouse/", "take": "A quiet, contemplative novel about a solitary lighthouse keeper on Cape Breton who cherishes his isolation yet aches under it. For readers who like slow, soul-searching fiction about duty, loneliness, and the question of what a life means."}, {"id": 2479, "title": "The Lion, the Witch and the Wardrobe ", "url": "https://store.ignatiusbookfairs.com/the-lion-the-witch-and-the-wardrobe/", "take": "The classic paperback of book two in the Chronicles of Narnia, with David Wiesner cover art and Pauline Baynes's original interior illustrations. If a child hasn't yet stepped through the wardrobe with the Pevensies, start here."}, {"id": 2469, "title": "The Lion, the Witch and the Wardrobe board book", "url": "https://store.ignatiusbookfairs.com/the-lion-the-witch-and-the-wardrobe-board-book/", "take": "C.S. Lewis's beloved classic, gently abridged as a board book with bright Joey Chou illustrations. A lovely way to plant Narnia in the very youngest hearts — and a genuinely sweet baby shower or first-library gift."}, {"id": 2168, "title": "The Little Engine That Could/La Pequena Locomotora que si Pudo", "url": "https://store.ignatiusbookfairs.com/the-little-engine-that-could-la-pequena-locomotora-que-si-pudo/", "take": "The classic little blue engine chugs uphill in Spanish, with all the original illustrations and the complete story. A natural for Spanish-speaking families and for children just learning the language. I think I can, en espanol."}, {"id": 903, "title": "The Little Friar Who Flew", "url": "https://store.ignatiusbookfairs.com/the-little-friar-who-flew/", "take": "The delightfully odd true story of St. Joseph of Cupertino, the clumsy friar who called himself Little Donkey - and who flew when overjoyed. Tomie dePaola's art and Patricia Lee Gauch's telling make humility genuinely funny and lovable."}, {"id": 1027, "title": "The Little House Collection (Books 1-5)", "url": "https://store.ignatiusbookfairs.com/the-little-house-collection-books-1-5/", "take": "The first five Little House books in a collector's set with Garth Williams' interior art in full color. Frontier history and family warmth in one package — a genuinely useful gift for a strong middle-grade reader."}, {"id": 1071, "title": "The Little House Cookbook: Frontier Food from Laura Ingalls Wilder's Classic Stories", "url": "https://store.ignatiusbookfairs.com/the-little-house-cookbook-frontier-food-from-laura-ingalls-wilders-classic-stories/", "take": "More than 100 recipes celebrating frontier cooking from the Little House stories — food you work for, prepare together, and give thanks over. A rich companion for families who have read the books and want to taste them."}, {"id": 1009, "title": "The Little Island", "url": "https://store.ignatiusbookfairs.com/the-little-island/", "take": "Margaret Wise Brown and Caldecott Medal-winner Leonard Weisgard follow a little island through the seasons, visited by one curious kitten. Winner of the 1947 Caldecott Medal, and still quietly magical."}, {"id": 1503, "title": "The Little Riders", "url": "https://store.ignatiusbookfairs.com/the-little-riders/", "take": "In a Dutch village during World War II, eleven-year-old Johanna guards the twelve metal riders of the ancient church clock — and one night risks her life for them. A short, moving wartime classic about courage at a child's scale."}, {"id": 875, "title": "The Little Way", "url": "https://store.ignatiusbookfairs.com/the-little-way/", "take": "A gentle hike up a steep mountain becomes a child-sized introduction to St. Therese of Lisieux. Henri's meeting with young Therese makes her \"little way\" of love and prayer genuinely graspable for young readers, not just quotable."}, {"id": 930, "title": "The Lives of the Saints: Seek and Find Volume 2", "url": "https://store.ignatiusbookfairs.com/the-lives-of-the-saints-seek-and-find-volume-2/", "take": "The seek-and-find formula applied to the saints: find Sara, Simon, two cats, and a goat while meeting Blandina, Genevieve, Hildegard, Francis, Catherine of Siena, John Bosco, Bernadette, and more. Busy, browsable fun with real substance underneath."}, {"id": 1643, "title": "The Living Wood:Saint Helena and the Emperor Constantine", "url": "https://store.ignatiusbookfairs.com/the-living-wood-saint-helena-and-the-emperor-constantine/", "take": "De Wohl's crisp, ironic, richly plotted novel of Helena, saintly mother of Constantine, and the quest for the True Cross across fifty tumultuous years of Roman history. Intrigue, romance, and power politics in the early Christian era — vintage de Wohl."}, {"id": 2822, "title": "The Long Way Home / Homelander 2", "url": "https://store.ignatiusbookfairs.com/the-long-way-home-homelander-2-ibc-1564/", "take": "Book two of Klavan's Homelanders: Charlie can't remember the year he supposedly murdered his best friend, so he goes home for answers. Bourne-style amnesia thriller momentum, written squarely for teen readers."}, {"id": 1611, "title": "The Long Way Westward", "url": "https://store.ignatiusbookfairs.com/the-long-way-westward/", "take": "In this lively sequel to The Long Way to a New Land, a Swedish immigrant family journeys from New York to a new home in Minnesota. Historically grounded and genuinely discussable — an early reader that earns classroom conversation."}, {"id": 1037, "title": "The Lord of the Rings: 50th Anniversary One-Volume", "url": "https://store.ignatiusbookfairs.com/the-lord-of-the-rings-50th-anniversary-one-volume/", "take": "All three volumes of Tolkien's epic in one handsome 50th anniversary tome, plus an extensive new index. For the reader ready to disappear into Middle-earth — or the family that reads big books together — this is the edition to own."}, {"id": 1861, "title": "The Lucky Baseball Bat", "url": "https://store.ignatiusbookfairs.com/the-lucky-baseball-bat/", "take": "Marvin's lucky bat vanishes just when he needs to prove himself to new teammates, and his game vanishes with it. A classic sports story about where confidence really comes from, and about friendship mattering more than talent."}, {"id": 2839, "title": "The Luminous Life of Lucy Landry", "url": "https://store.ignatiusbookfairs.com/the-luminous-life-of-lucy-landry-ibc-1632/", "take": "Lucy Landry, a spirited French-Ojibwe orphan afraid of the water, is sent to live with a lighthouse-keeping Anishinaabe family on Lake Superior - and hunts the legendary necklace her father sought. Atmospheric, big-hearted historical adventure."}, {"id": 1925, "title": "The Man Who Was Thursday", "url": "https://store.ignatiusbookfairs.com/the-man-who-was-thursday/", "take": "Chesterton's most famous novel, a metaphysical thriller about anarchists and the mysterious Sunday, here enriched with Martin Gardner's extensive footnotes and introductory essay on its allegory. The rare annotated edition that genuinely deepens the ride."}, {"id": 2234, "title": "The Martins: The Extraordinary Story of the Family of Saint Therese of Lisieux", "url": "https://store.ignatiusbookfairs.com/the-martins-the-extraordinary-story-of-the-family-of-saint-therese-of-lisieux/", "take": "Step inside the noisy, happy Martin household, where five daughters bicker, play tricks, and never forget love of God comes first. Lively anecdotes make Saint Therese of Lisieux's family feel wonderfully ordinary — and their faith extraordinary."}, {"id": 1906, "title": "The Merchant of Venice", "url": "https://store.ignatiusbookfairs.com/the-merchant-of-venice/", "take": "Probably Shakespeare's most controversial play and one of his least understood. Comedy or tragedy? Is Shylock villain or more sinned against than sinning? This critical edition gives students the scholarly footing to argue it out properly."}, {"id": 2154, "title": "The Merchant's Curse (Harwood Mysteries #4)", "url": "https://store.ignatiusbookfairs.com/the-merchants-curse-harwood-mysteries-4/", "take": "Xan is a merchant's apprentice in Lincoln now, and trouble finds the shop fast: a mysterious scarred woman, a deathly ill business partner, brutes lurking outside. Medieval mystery that keeps pages turning without losing its moral center."}, {"id": 1134, "title": "The Miracle of St. Nicholas", "url": "https://store.ignatiusbookfairs.com/the-miracle-of-st-nicholas/", "take": "In a Russian village where the soldiers closed the church sixty years ago, a boy asks his babushka why they cannot celebrate Christmas there tomorrow. A moving story of faith kept quietly alive, and of miracles."}, {"id": 1848, "title": "The Missing Maiden", "url": "https://store.ignatiusbookfairs.com/the-missing-maiden/", "take": "A missing Vestal maiden, puzzling clues, and three young friends sleuthing through ancient Rome, where being Christian meant living in the shadows. A mystery that smuggles in real lessons about freedom, duty, and devotion along the way."}, {"id": 1020, "title": "The Mitchells", "url": "https://store.ignatiusbookfairs.com/the-mitchells/", "take": "Daddy leaves for World War II with one instruction — no dogs — and the five Mitchell children form a club to help the war effort at home. Humorous, tender, and drawn from the author's own family."}, {"id": 2147, "title": "The Monster in the Hollows: The Wingfeather Saga #3", "url": "https://store.ignatiusbookfairs.com/the-monster-in-the-hollows-the-wingfeather-saga-3/", "take": "Hiding in the Green Hollows, the Igibys have a problem: the heir to Anniera has grown fur, fangs, and a tail. Book three trades chase scenes for something richer — belonging, suspicion, and brotherly loyalty."}, {"id": 927, "title": "The Mysterious Goblet", "url": "https://store.ignatiusbookfairs.com/the-mysterious-goblet/", "take": "Volume 3 of In the Shadows of Rome: an ordinary-looking goblet turns up in Titus' sack, and the questions - where from, put there by whom, and why - pull the three friends into danger again. Solid historical suspense for ages 10 and up."}, {"id": 2207, "title": "The Mythmakers", "url": "https://store.ignatiusbookfairs.com/the-mythmakers/", "take": "John Hendrix's graphic-novel biography of C.S. Lewis and J.R.R. Tolkien traces their childhoods, their friendship, and the creative fellowship behind their masterworks. A genuinely fresh way into two beloved authors, for teens and adults alike."}, {"id": 1121, "title": "The Napping House", "url": "https://store.ignatiusbookfairs.com/the-napping-house/", "take": "A snoring granny, a dreaming child, a dozing dog, a snoozing cat — and one wakeful flea. The classic cumulative bedtime tale that has young listeners predicting the topple and begging to read along."}, {"id": 1654, "title": "The Nature Connection: An Outdoor Workbook for Kids, Families, and Classrooms", "url": "https://store.ignatiusbookfairs.com/the-nature-connection-an-outdoor-workbook-for-kids-families-and-classrooms/", "take": "Clare Walker Leslie gets kids outside with all five senses — sketching wildlife, journaling weather, watching bird migrations — whether they live in the country or the city. A workbook that turns noticing into a lifelong habit."}, {"id": 2468, "title": "The Night Before Christmas: The Classic Edition", "url": "https://store.ignatiusbookfairs.com/the-night-before-christmas-the-classic-edition/", "take": "Clement C. Moore's beloved poem in a sturdy board book edition sized just right for toddlers. If you're carrying on a Christmas Eve reading tradition, or starting one, this classic version does the job beautifully."}, {"id": 1926, "title": "The Night Is Far Spent", "url": "https://store.ignatiusbookfairs.com/the-night-is-far-spent/", "take": "A career-spanning collection from Thomas Howard, the Evangelical college professor whose provocative questions led him through the Anglican Communion into the Catholic Church. Thought-provoking, respectful essays tracing one of the notable faith pilgrimages in recent memory."}, {"id": 908, "title": "The Night of Las Posadas", "url": "https://store.ignatiusbookfairs.com/the-night-of-las-posadas/", "take": "Las Posadas in Santa Fe, a snowstorm, two mysterious strangers who arrive just in time to play Mary and Joseph. DePaola's luminous paintings glow like farolitos in this lovely Christmas story rooted in a real Southwestern tradition."}, {"id": 1047, "title": "The Odyssey", "url": "https://store.ignatiusbookfairs.com/the-odyssey/", "take": "Odysseus's ten-year voyage home — Polyphemus, six-headed Scylla, the wrath of the gods — brilliantly retold for young readers by award-winning author Geraldine McCaughrean. A sturdy first door into the epic before students meet Homer straight."}, {"id": 2250, "title": "The Oldest Student", "url": "https://store.ignatiusbookfairs.com/the-oldest-student/", "take": "Born into slavery in 1848, Mary Walker worked her whole long life — and learned to read at 116, becoming the nation's oldest student. A true story that makes an unforgettable case that it is never too late."}, {"id": 1441, "title": "The Outcasts: Brotherband Chronicles Book 1", "url": "https://store.ignatiusbookfairs.com/the-outcasts-brotherband-chronicles-book-1/", "take": "From the author of Ranger's Apprentice: Hal, Stig, and the boys nobody wanted must outsail the Wolves and Sharks in a treacherous sea race. Underdog grit and brotherhood that hooks middle-grade adventure readers fast."}, {"id": 2827, "title": "The Outsider", "url": "https://store.ignatiusbookfairs.com/the-outsider-ibc-1610/", "take": "The book of Ruth, retold so faithfully and vividly that kids 8+ feel the hunger, danger, and rescue. Award-winning Bible engagement that doesn't water anything down."}, {"id": 2095, "title": "The Penderwicks at Last: Penderwicks #5", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-at-last-penderwicks-5/", "take": "The finale to Jeanne Birdsall's National Book Award-winning series brings everyone back to Arundel, where it all began, for Rosalind's wedding. Dogs, dances, and near-disasters included — a satisfying send-off for longtime Penderwick readers."}, {"id": 2150, "title": "The Penderwicks at Point Mouette.  Penderwicks #3", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-at-point-mouette-penderwicks-3/", "take": "Skye becomes Oldest Available Penderwick when the sisters summer in Maine with Aunt Claire and old friend Jeffrey. Jeanne Birdsall's warm, old-fashioned family storytelling, genuinely in the Streatfeild and Eager tradition, keeps winning over modern kids."}, {"id": 2151, "title": "The Penderwicks in Spring: Penderwicks #4", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-in-spring-penderwicks-4/", "take": "Springtime on Gardam Street brings a surprise for every Penderwick; some wonderful, like a neighbor home from war, some ridiculous, like Batty's new dog-walking venture. Birdsall's gentle family comedy remains a reliable read-aloud and hand-off for middle graders."}, {"id": 2145, "title": "The Penderwicks on Gardam Street: The Penderwicks #2", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-on-gardam-street-the-penderwicks-2/", "take": "The Penderwick sisters are home on Gardam Street when Aunt Claire decides it's time for their father to start dating — clearly a situation requiring intervention. Warm, funny family storytelling in the classic mold."}, {"id": 2758, "title": "The Penderwicks: A Summer Tale of Four Sisters, Two Rabbits, and a Very interesting Boy (#1)", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-a-summer-tale-of-four-sisters-two-rabbits-and-a-very-interesting-boy-1-ibc-1584/", "take": "Jeanne Birdsall's National Book Award-winning family story reads like a modern classic because it is one. Four sisters, a summer estate, gardens and attics to explore - old-fashioned charm that still wins over today's readers."}, {"id": 2142, "title": "The Penderwicks: A Summer Tale of Four Sisters, Two Rabbits, and a Very Interesting Boy, The Penderwicks #1", "url": "https://store.ignatiusbookfairs.com/the-penderwicks-a-summer-tale-of-four-sisters-two-rabbits-and-a-very-interesting-boy-the-penderwicks-1/", "take": "Four sisters, two rabbits, a very interesting boy, and one enchanted summer estate. Jeanne Birdsall's National Book Award-winning series opener has sold over a million copies by being exactly what it is: a modern classic of family charm."}, {"id": 1052, "title": "The Perilous Road", "url": "https://store.ignatiusbookfairs.com/the-perilous-road/", "take": "Chris hates the Yankees who stole his family's crops and horse — but his own brother joins the Union anyway. A Newbery Honor story set in the Tennessee mountains about the senseless waste of war and the harder kind of courage."}, {"id": 925, "title": "The Phantom of the Colosseum", "url": "https://store.ignatiusbookfairs.com/the-phantom-of-the-colosseum/", "take": "First in the six-book In the Shadows of Rome series for ages 10 and up: when Blandula's master is arrested for being a Christian, three unlikely boys come to her aid. Ancient-Rome danger and underground faith make a genuinely gripping combination."}, {"id": 1119, "title": "The Phantom Phoenix 1: First Fiery Issue", "url": "https://store.ignatiusbookfairs.com/the-phantom-phoenix-1-first-fiery-issue/", "take": "A wounded World War I fighter pilot turned homeless veteran rises from Chicago's 1920s streets to become the Phantom Phoenix. A superhero origin comic with an underdog heart and a Prohibition-era setting."}, {"id": 1120, "title": "The Phantom Phoenix 2", "url": "https://store.ignatiusbookfairs.com/the-phantom-phoenix-2/", "take": "Framed for a jewelry-store explosion and hunted by crooked cops and the nefarious Flambeau, the Phantom Phoenix must clear his name — while doubting his own tactics. Issue two raises the stakes for this virtuous vigilante nicely."}, {"id": 1622, "title": "The Pharaohs of Ancient Egypt", "url": "https://store.ignatiusbookfairs.com/the-pharaohs-of-ancient-egypt/", "take": "How do we know anything about ancient Egypt? This introduction follows archaeologists piecing together the pharaohs, the people, and the golden days of a 3,000-year civilization from what the sands preserved. Solid fuel for a kid's Egypt phase."}, {"id": 1866, "title": "The Picture of Dorian Gray", "url": "https://store.ignatiusbookfairs.com/the-picture-of-dorian-gray/", "take": "Wilde's Faustian tale of a young man who trades his soul for youth, and discovers the devil's bargain is no bargain. The moral lands hard and honestly. A gateway classic for older students drawn to dark, stylish fiction."}, {"id": 964, "title": "The Planets in Our Solar System", "url": "https://store.ignatiusbookfairs.com/the-planets-in-our-solar-system/", "take": "Where is it partly cloudy and 860 degrees? Venus. Written by a former Hayden Planetarium chairman and featuring real Voyager photographs, this classic gives young readers a trustworthy first tour of the eight planets."}, {"id": 1098, "title": "The Power of Silence", "url": "https://store.ignatiusbookfairs.com/the-power-of-silence/", "take": "Cardinal Robert Sarah, in a profound conversation with Nicolas Diat, on why silence has become both harder to find and more necessary — the indispensable doorway to the divine in a noisy age. Substantial spiritual reading for adults."}, {"id": 1454, "title": "The Precepts of the Church", "url": "https://store.ignatiusbookfairs.com/the-precepts-of-the-church/", "take": "Fr. Lovasik explains the seven precepts of the Church in short, child-sized language with full-color illustrations and a durable sewn binding. A dependable St. Joseph Picture Book for Catholic classrooms and homes — clear catechesis without fuss."}, {"id": 1033, "title": "The Princess and the Goblin", "url": "https://store.ignatiusbookfairs.com/the-princess-and-the-goblin/", "take": "A castle riddled with secret stairways, a princess with a protecting ring, and goblins scheming beneath the mountain. Classic fairy-tale adventure with real shivers and real courage — the kind of old-fashioned storytelling that still holds children fast."}, {"id": 1833, "title": "The Princesses of Heaven: The Flowers", "url": "https://store.ignatiusbookfairs.com/the-princesses-of-heaven-the-flowers/", "take": "Disney artist Fabiola Garza presents six saints — Joan of Arc, Josephine Bakhita, Kateri Tekakwitha, and more — as true princesses in heaven, shining crowns included. For girls ages 3-8 who love princesses, this redirects the obsession beautifully."}, {"id": 1631, "title": "The Quiet Light: A Novel about Saint Thomas Aquinas", "url": "https://store.ignatiusbookfairs.com/the-quiet-light-a-novel-about-saint-thomas-aquinas/", "take": "Louis de Wohl takes on Thomas Aquinas: the nobleman's son who defied his family's grand ambitions to take a vow of poverty and join the Dominicans, amid the Crusades and the ruthless Emperor Frederick II. History and holiness, expertly braided."}, {"id": 1049, "title": "The Railway Children", "url": "https://store.ignatiusbookfairs.com/the-railway-children/", "take": "A genuine classic from Edith Nesbit, first serialized in 1905 and adapted for the screen many times since — most famously in 1970. A dependable choice for families building a shelf of enduring English children's stories."}, {"id": 1106, "title": "The Read-Aloud Family", "url": "https://store.ignatiusbookfairs.com/the-read-aloud-family/", "take": "Practical strategies for making reading aloud a real family ritual — and a persuasive case that the shared stories and conversations become your family's legacy. Encouraging, realistic help for busy, technology-crowded households."}, {"id": 1868, "title": "The Red Badge of Courage", "url": "https://store.ignatiusbookfairs.com/the-red-badge-of-courage/", "take": "Crane called it a psychological portrait of fear, built from veterans' stories of the Civil War. Less about battles than about what happens inside a soldier who must kill or be killed. Short, intense, endlessly discussable."}, {"id": 1936, "title": "The Restless Flame", "url": "https://store.ignatiusbookfairs.com/the-restless-flame/", "take": "Louis de Wohl's stirring novel of St. Augustine traces the whole arc, vain and sensual youth to brilliant theologian, reverently but without sanding off the rough edges. Historical fiction that makes a towering saint feel human; adult and older teen readers."}, {"id": 2848, "title": "The Restorationists: Beneath the Swirling Sky", "url": "https://store.ignatiusbookfairs.com/the-restorationists-beneath-the-swirling-sky-ibc-1583/", "take": "Vincent's sister disappears into a famous painting, and the family secret comes out: they can travel through art. A fresh, imaginative adventure about beauty worth protecting — wonderful for 8-12s."}, {"id": 2203, "title": "The Rise and Fall of Mount Majestic", "url": "https://store.ignatiusbookfairs.com/the-rise-and-fall-of-mount-majestic/", "take": "Persimmony Smudge discovers the mountain at the center of her island is actually the belly of a sleeping giant, and someone must convince the quarreling islanders before it wakes. Whimsical, inventive fantasy with an adventure-hungry heroine."}, {"id": 1937, "title": "The Rising", "url": "https://store.ignatiusbookfairs.com/the-rising/", "take": "A gripping, thought-provoking Catholic novel about a boy whose prayer at a wake changes everything. Big questions about miracles, media, and faith under pressure — best for confident teen readers ready to wrestle with them."}, {"id": 1392, "title": "The Runaway Bunny (board book)", "url": "https://store.ignatiusbookfairs.com/the-runaway-bunny-board-book/", "take": "Margaret Wise Brown's steadfast mother bunny finds her little one every time, no matter where the game of hide-and-seek leads. In sturdy board-book form, it remains one of the most quietly comforting books ever written."}, {"id": 1938, "title": "The Sabbatical", "url": "https://store.ignatiusbookfairs.com/the-sabbatical/", "take": "An elderly Oxford historian plans a quiet sabbatical of gardening and an unpublishable book — and providence has other ideas. Michael O'Brien revisits a beloved character from The Father's Tale in this gentle, coincidence-haunted novel for grown-up readers."}, {"id": 1873, "title": "The Scarlet Letter", "url": "https://store.ignatiusbookfairs.com/the-scarlet-letter/", "take": "Hawthorne's classic meditation on sin, repentance, and redemption, presented with critical essays that take its Christian core seriously instead of explaining it away. An excellent edition for high schoolers meeting Hester Prynne for the first time."}, {"id": 2239, "title": "The Second Skater of the Apolcalypse", "url": "https://store.ignatiusbookfairs.com/the-second-skater-of-the-apolcalypse/", "take": "Six figure-skating siblings, one modern English family, and the COVID pandemic testing everyone's joy and resilience. Like its prequel, this warm, funny novel finds the humor and heart in family life's ups, downs, and hilarious mishaps."}, {"id": 975, "title": "The Secret Lives of Backyard Bugs", "url": "https://store.ignatiusbookfairs.com/the-secret-lives-of-backyard-bugs/", "take": "Hundreds of stunning close-up photographs turn any backyard into an expedition: spiders, beetles, dragonflies, aphids, all in their natural settings. The kind of book that sends kids straight outside to look."}, {"id": 1490, "title": "The Secret of the Mansion", "url": "https://store.ignatiusbookfairs.com/the-secret-of-the-mansion/", "take": "The first Trixie Belden mystery: a boring summer upended by a millionaire's daughter next door, a miser's hidden fortune, and a runaway hiding in Sleepyside. Vintage series-mystery fuel for middle-grade readers who inhale this sort of thing."}, {"id": 1847, "title": "The Secret Tomb", "url": "https://store.ignatiusbookfairs.com/the-secret-tomb/", "take": "Fifth in the In the Shadows of Rome series: Titus, sent to the police to be made a man of, finds himself hunting Christians — and the hidden body of Peter the Apostle. A tense premise that earns its page-turning."}, {"id": 2215, "title": "The Seven Habits of Highly Effective Teens", "url": "https://store.ignatiusbookfairs.com/the-seven-habits-of-highly-effective-teens/", "take": "Sean Covey adapts the famous 7 Habits framework for teenagers, updated for the digital age, with over 3 million copies sold. A practical roadmap for goals and habits, useful for the teen ready to hear it from someone besides a parent."}, {"id": 1578, "title": "The Shadow of his Wings: A Graphic Biography of Fr. Gereon Goldman", "url": "https://store.ignatiusbookfairs.com/the-shadow-of-his-wings-a-graphic-biography-of-fr-gereon-goldman/", "take": "The astonishing true story of Gereon Goldmann, a German seminarian drafted into Hitler's SS who — against all odds — completed his training, was ordained, and secretly ministered amid the horrors of war. Told here in gripping graphic-biography form."}, {"id": 948, "title": "The Shadow of His Wings: The True Story of Fr. Gereon Goldmann, OFM", "url": "https://store.ignatiusbookfairs.com/the-shadow-of-his-wings-the-true-story-of-fr-gereon-goldmann-ofm/", "take": "The astonishing true memoir of Gereon Goldmann, a German seminarian drafted into Hitler's SS who managed - against all odds - to be ordained and secretly minister amid the war. One of those true stories no novelist would dare invent."}, {"id": 2268, "title": "The Ship in the Window", "url": "https://store.ignatiusbookfairs.com/the-ship-in-the-window/", "take": "Mabel the mouse dreams of being a fearless sea captain, and the model ship in the window looks seaworthy to her. Caldecott Medalist Matthew Cordell and librarian Travis Jonker craft a timeless small-creature, big-adventure tale."}, {"id": 1774, "title": "The Side-by-Side Declaration of Independence", "url": "https://store.ignatiusbookfairs.com/the-side-by-side-declaration-of-independence/", "take": "The Declaration's original text on each left-hand page, a plain-English translation on the right — so kid patriots and their grown-ups can finally read what it actually says. A smart companion for civics and American history at home or school."}, {"id": 2865, "title": "The Silence Between Us", "url": "https://store.ignatiusbookfairs.com/the-silence-between-us/", "take": "Deaf teen Maya lands in a hearing school and refuses to shrink. An award-honored YA novel about Deaf culture, communication, and dreams — eye-opening, clean, and genuinely moving for teens."}, {"id": 1103, "title": "The Sleeping Witness", "url": "https://store.ignatiusbookfairs.com/the-sleeping-witness/", "take": "A refugee artist and war hero is murdered on abbey grounds, the doctor's frail wife lies in a coma beside him, and the police are sure it's a crime of passion. Fr. Gabriel disagrees. Atmospheric, unusual, absorbing."}, {"id": 2464, "title": "The Snowy Day", "url": "https://store.ignatiusbookfairs.com/the-snowy-day/", "take": "Ezra Jack Keats's Caldecott Medal winner still captures that hush of a first snowfall like nothing else. Peter's snowsuit walk has charmed readers since 1962, and it remains a genuine must-have for every child's shelf."}, {"id": 2256, "title": "The Snowy Day (Board book)", "url": "https://store.ignatiusbookfairs.com/the-snowy-day-board-book/", "take": "Peter steps into the first snowfall in his snowsuit and into generations of hearts — a Caldecott Medal winner and the New York Public Library's most checked-out book of all time, here in a sturdy board book for the littlest readers."}, {"id": 1944, "title": "The Song at the Scaffold", "url": "https://store.ignatiusbookfairs.com/the-song-at-the-scaffold/", "take": "Gertrud von le Fort's classic novella of the Carmelite nuns of Compiegne, who gave their lives during the French Revolution, told through the trembling young Blanche. Short, haunting, and unforgettable — a small book that stays with readers for years."}, {"id": 1396, "title": "The Spear: A Novel of the Crucifixion", "url": "https://store.ignatiusbookfairs.com/the-spear-a-novel-of-the-crucifixion/", "take": "Louis de Wohl's panoramic novel of the Crucifixion, told through the Roman soldier who thrust the spear. Sweeping from imperial Rome to Judea, it makes the last days of Christ feel immediate for older readers."}, {"id": 1129, "title": "The Spider Who Saved Christmas", "url": "https://store.ignatiusbookfairs.com/the-spider-who-saved-christmas/", "take": "Arroyo's faith-filled legend of Nephila, a cave spider with a part to play in the Christmas story - and the origin of tinsel besides. Gallegos's illustrations give this gentle tale real wonder for the season."}, {"id": 945, "title": "The Spirit of Hiawatha", "url": "https://store.ignatiusbookfairs.com/the-spirit-of-hiawatha/", "take": "Demi turns her vibrant mixed-media artwork - watercolor, ink, and more - to Hiawatha, the Iroquois peacemaker who united five nations and prepared the ground for the 17th-century Jesuit missions. An engaging, colorful bridge between legend and history."}, {"id": 1945, "title": "The Spirit of the Liturgy - - Commemorative Edition", "url": "https://store.ignatiusbookfairs.com/the-spirit-of-the-liturgy-commemorative-edition/", "take": "Joseph Ratzinger's landmark meditation on worship in a fortieth-anniversary edition, bound with the Romano Guardini classic of the same title that first inspired him. For serious adult readers who want to understand the beauty and depth of the liturgy."}, {"id": 1417, "title": "The Story of Easter", "url": "https://store.ignatiusbookfairs.com/the-story-of-easter/", "take": "The story of Jesus's death and resurrection alongside Easter celebrations from many cultures - plus egg-decorating instructions and a hot cross bun recipe. A nicely rounded holiday book, recommended for ages 9 to 12."}, {"id": 1135, "title": "The Story of Holly and Ivy", "url": "https://store.ignatiusbookfairs.com/the-story-of-holly-and-ivy/", "take": "An orphan wishing for a home, a doll wishing for a child, a couple wishing for someone to share Christmas - Rumer Godden braids three wishes together, with Barbara Cooney's luminous illustrations warming every page."}, {"id": 2844, "title": "The Story of King Arthur and his Knights", "url": "https://store.ignatiusbookfairs.com/the-story-of-king-arthur-and-his-knights-ibc-1551/", "take": "The sword, the stone, the Round Table, Merlin — all the Arthur essentials in one vibrant retelling. The right first Camelot for middle readers before they meet T.H. White."}, {"id": 2829, "title": "The Story Orchestra: The Nutcracker", "url": "https://store.ignatiusbookfairs.com/the-story-orchestra-the-nutcracker-ibc-1595/", "take": "A retelling of The Nutcracker with a button to press on each scene, playing the vivid sound of an orchestra performing Tchaikovsky's score. Story, art, and music in one sitting - a Christmas read-aloud that earns the word magical."}, {"id": 1641, "title": "The Surprising Power of Family Meals: How Eating Together Makes Us Smarter, Stronger, Healthier and Happier", "url": "https://store.ignatiusbookfairs.com/the-surprising-power-of-family-meals-how-eating-together-makes-us-smarter-stronger-healthier-and-happier/", "take": "A thoughtful case for the family dinner table: the first book to fully examine how a once-universal ritual quietly became a lifeline for connection. For parents and school communities wondering whether supper together really matters — this argues yes, persuasively."}, {"id": 2178, "title": "The Swiss Guard", "url": "https://store.ignatiusbookfairs.com/the-swiss-guard/", "take": "Follow Marc from first fascination to first assignment as a papal Swiss Guard, absorbing the history, training, and way of life of these elite soldiers along the way. Based on real events; catnip for kids drawn to honor and duty."}, {"id": 2253, "title": "The Tale of Peter Rabbit", "url": "https://store.ignatiusbookfairs.com/the-tale-of-peter-rabbit/", "take": "Peter squeezes under Mr. McGregor's gate and into 110-plus years of beloved trouble. This edition of Beatrix Potter's mischievous classic adds a colorful cover, special endpapers, and notes on the tale's history."}, {"id": 954, "title": "The Thanksgiving Story", "url": "https://store.ignatiusbookfairs.com/the-thanksgiving-story/", "take": "Alice Dalgliesh's Caldecott Honor-winning account of the first Thanksgiving, told through the Hopkins children aboard the crowded Mayflower - including baby Oceanus, born at sea. An honest, festive classic about hardship, courage, and gratitude."}, {"id": 1403, "title": "The Thief Who Stole Heaven", "url": "https://store.ignatiusbookfairs.com/the-thief-who-stole-heaven/", "take": "Arroyo follows The Spider Who Saved Christmas with the legend of the Good Thief, bridging Christmas and Easter in another cinematic holiday story built on ancient tradition. A dramatic Lenten read-aloud with real depth."}, {"id": 1951, "title": "The Time Before You Die", "url": "https://store.ignatiusbookfairs.com/the-time-before-you-die/", "take": "A beautifully written novel set amid Tudor England's religious upheaval, following lives shattered — especially among monks and nuns — as medieval Christendom broke apart. Sorrowful, serious historical fiction about loss, finding, and being found, for adult readers."}, {"id": 2213, "title": "The Tiny Seed", "url": "https://store.ignatiusbookfairs.com/the-tiny-seed/", "take": "Eric Carle's classic flower life cycle, told through one tiny seed's adventures, with an actual piece of plantable seed-embedded paper inside. Read the book, plant the paper, watch wildflowers grow. Science and wonder in one small package."}, {"id": 2825, "title": "The Treasure of Creation: Saint Francis", "url": "https://store.ignatiusbookfairs.com/the-treasure-of-creation-saint-francis-ibc-6toch/", "take": "A boy joins Saint Francis of Assisi on a treasure hunt, and the question quietly shifts from where treasure is to what treasure means. Simple Franciscan wisdom delivered through story - a lovely, unhurried faith read."}, {"id": 2236, "title": "The Tree Planted in the Sea: A Journey with the Apostle Paul", "url": "https://store.ignatiusbookfairs.com/the-tree-planted-in-the-sea-a-journey-with-the-apostle-paul/", "take": "Clement, a Roman centurion's slave, boards a ship to Rome and meets the prisoner Paul, who teaches him the true meaning of freedom. Drawing on Saint Paul's own words, this story brings the apostle's last journey vividly to life."}, {"id": 2777, "title": "The Truth of the Matter/ Homelander 3", "url": "https://store.ignatiusbookfairs.com/the-truth-of-the-matter-homelander-3-ibc-1620/", "take": "Third in Klavan's Homelanders series - Bourne Identity meets 24, for teens. Charlie West's memories are finally returning, and both the bad guys and the good guys want to capture him. Fast, clean thriller pacing."}, {"id": 2181, "title": "The Twelve Apostles: Seek and Find Volume 4", "url": "https://store.ignatiusbookfairs.com/the-twelve-apostles-seek-and-find-volume-4/", "take": "A seek-and-find that travels back to the time of the Twelve Apostles, hiding recurring characters, two cats, and a goat in every scene. Busy-eyed fun that sneaks in real apostolic history along the way."}, {"id": 2121, "title": "The Unbreakable Code: Book Scavenger #2", "url": "https://store.ignatiusbookfairs.com/the-unbreakable-code-book-scavenger-2/", "take": "Emily and James follow a trail of encrypted messages hidden in Mark Twain-penned books — and it may connect to an arsonist. The second Book Scavenger mystery keeps the codes coming for puzzle-loving middle graders."}, {"id": 2098, "title": "The Vanderbeekers and the Hidden Garden (The Vanderbeekers #2)", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-and-the-hidden-garden-the-vanderbeekers-2/", "take": "When catastrophe strikes their upstairs neighbors, the Vanderbeeker kids set out to build a healing garden in Harlem despite locked fences, thistles, and a developer's competing plans. A funny, warmhearted sequel about community made with your own hands."}, {"id": 2119, "title": "The Vanderbeekers Ever After (The Vanderbeekers #7)", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-ever-after-the-vanderbeekers-7/", "take": "The seventh Vanderbeekers book goes somewhere braver: a sibling's serious diagnosis trades wedding plans for hospital visits, with all of Harlem holding the family up. Honest about hard times, and still full of love and hope."}, {"id": 2106, "title": "The Vanderbeekers Lost and Found", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-lost-and-found/", "take": "Autumn brings marathon training with Mr. Beiderman — and a mystery: who is sleeping in the community garden? The fourth Vanderbeekers novel is a poignant one, threading real tenderness through the family's usual warmth."}, {"id": 2111, "title": "The Vanderbeekers Make a Wish", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-make-a-wish/", "take": "The siblings have spent months planning Papa's surprise 40th birthday — then he's called away and the distant grandparents land on the doorstep instead. A Vanderbeekers story about ruined plans, family friction, and making things right anyway."}, {"id": 2094, "title": "The Vanderbeekers of 141st Street (The Vanderbeekers #1)", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-of-141st-street-the-vanderbeekers-1/", "take": "Five siblings, one beloved Harlem brownstone, and eleven days to win over the curmudgeonly landlord who won't renew the lease. The series opener the New York Times called delightful and heartwarming — and families tend to agree."}, {"id": 2115, "title": "The Vanderbeekers On the Road", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-on-the-road/", "take": "The Vanderbeekers pile into the van to re-create the road trip Papa never got to take with his own father — while the younger siblings quietly scheme to keep the family from ever changing. A warm cross-country adventure."}, {"id": 2102, "title": "The Vanderbeekers to the Rescue (The Vanderbeekers #3)", "url": "https://store.ignatiusbookfairs.com/the-vanderbeekers-to-the-rescue-the-vanderbeekers-3/", "take": "Spring break on 141st Street goes sideways when the Vanderbeeker kids must race to save their mother's baking business from city closure. Book three keeps the series' warmth and busy, believable family energy fully intact."}, {"id": 1104, "title": "The Vanishing Woman", "url": "https://store.ignatiusbookfairs.com/the-vanishing-woman/", "take": "The most hated woman in town vanishes into thin air — witnessed only by her daughter, whom nobody believes. Father Gabriel takes up the riddle in this clever entry in the priest-detective series."}, {"id": 2196, "title": "The Velveteen Rabbit", "url": "https://store.ignatiusbookfairs.com/the-velveteen-rabbit/", "take": "The stuffed rabbit made real by a boy's love, in an oversized padded board book built for small hands. A century-old story of unconditional love that still lands, and a gentle heirloom-style gift for the youngest readers."}, {"id": 1981, "title": "The Very Hungry Caterpillar (Board book)", "url": "https://store.ignatiusbookfairs.com/the-very-hungry-caterpillar-board-book-yco0/", "take": "The all-time classic in its sturdy board-book form: die-cut pages little fingers love, plus painless lessons in counting and days of the week. A near-perfect first gift for new babies, baby showers, and birthdays."}, {"id": 1125, "title": "The Very Hungry Caterpillar board book", "url": "https://store.ignatiusbookfairs.com/the-very-hungry-caterpillar-board-book/", "take": "Eric Carle's hungry caterpillar munches his way through the week in this sturdy board-book edition sized for small hands. Bold collage art, simple counting, and that satisfying cocoon-to-butterfly ending have earned its classic status honestly."}, {"id": 942, "title": "The Virtue Chronicles Volume 1: The Saintly Outlaw", "url": "https://store.ignatiusbookfairs.com/the-virtue-chronicles-volume-1-the-saintly-outlaw/", "take": "History-loving Andrew Perry meets Eve Virtue, her family's mysterious Radiant Stone, and suddenly twelfth-century England - and Robin Hood, here a saintly outlaw. A time-travel series opener that makes the past an adventure rather than a homework assignment."}, {"id": 943, "title": "The Virtue Chronicles Volume 2: The Warrior Maiden", "url": "https://store.ignatiusbookfairs.com/the-virtue-chronicles-volume-2-the-warrior-maiden/", "take": "Book 2 strands Andrew and Eve in 15th-century France without the Radiant Stone that brought them there - which readers will recognize as Joan of Arc territory. The Warrior Maiden keeps the time-travel stakes high and the history vivid."}, {"id": 944, "title": "The Virtue Chronicles Volume 3: The Hidden Heroes", "url": "https://store.ignatiusbookfairs.com/the-virtue-chronicles-volume-3-the-hidden-heroes/", "take": "Book 3 drops Andrew and Eve into Elizabethan England, dodging priest-hunters while searching for a lost time traveler - and meeting Edmund Campion and the hidden Catholic heroes of that dangerous age. Real history, genuine suspense."}, {"id": 2149, "title": "The Warden and the Wolf King: Wingfeather Saga #4", "url": "https://store.ignatiusbookfairs.com/the-warden-and-the-wolf-king-wingfeather-saga-4/", "take": "The Wingfeather Saga reaches its long-promised battle: Fangs invading Ban Rona, three siblings scattered, and Kalmar carrying a terrible secret toward the Deeps of Throg. A finale with real stakes for readers who have loved these children since book one."}, {"id": 2197, "title": "The Wednesday Wars", "url": "https://store.ignatiusbookfairs.com/the-wednesday-wars/", "take": "Seventh grader Holling Hoodhood is stuck reading Shakespeare with the teacher he's sure hates his guts, while his image-obsessed father looms at home. Gary Schmidt's witty, big-hearted Newbery Honor novel is a middle school staple for good reason."}, {"id": 1498, "title": "The Week That Led to Easter (La Historia de Semana Santa)", "url": "https://store.ignatiusbookfairs.com/the-week-that-led-to-easter-la-historia-de-semana-santa/", "take": "Holy Week traced step by step to the cross and on to Easter joy, in Arch Books rhyme with English and Spanish together. A fine Lenten read-aloud for bilingual homes and classrooms, pitched at ages 5-9."}, {"id": 1599, "title": "The Westing Game", "url": "https://store.ignatiusbookfairs.com/the-westing-game/", "take": "A Newbery Medal winner and one of the all-time great puzzle mysteries: sixteen unlikely heirs gather for the reading of Samuel Westing's will, and the game begins. Confoundingly clever, very funny, and endlessly re-readable."}, {"id": 1466, "title": "The Whipping Boy", "url": "https://store.ignatiusbookfairs.com/the-whipping-boy/", "take": "Sid Fleischman's Newbery Medal winner: spoiled Prince Brat and his whipping boy trade places, fall in with dangerous outlaws, and learn — reluctantly — to trust each other. Broadly comic and deeply compassionate at once, a middle-grade tale that earns its medal."}, {"id": 1964, "title": "The Wife of Pilate and Other Stories", "url": "https://store.ignatiusbookfairs.com/the-wife-of-pilate-and-other-stories/", "take": "Three Gertrud von le Fort novellas newly translated into English, led by the imagined transformation of Pilate's wife from pagan aristocrat to Christian saint. Elegant historical fiction of ideas for adult readers who like their stories weighty."}, {"id": 2452, "title": "The Willpower Advantage", "url": "https://store.ignatiusbookfairs.com/the-willpower-advantage/", "take": "A practical Christian guide to the gap we all know: wanting holiness and happiness but struggling with the daily steps. The authors argue for renewing the mind and actively engaging the will, cooperating with God's grace rather than waiting passively."}, {"id": 1834, "title": "The Wind in the Willows", "url": "https://store.ignatiusbookfairs.com/the-wind-in-the-willows/", "take": "Rat, Mole, Toad, and Badger have charmed readers for nearly a century, and the riverbank magic has not dimmed. Born as bedtime stories for the author's own son, these tales of friendship amid the natural world remain genuinely timeless."}, {"id": 1022, "title": "The Winged Watchman", "url": "https://store.ignatiusbookfairs.com/the-winged-watchman/", "take": "Occupied Holland, a hidden Jewish child, a downed RAF pilot, and a family living in an old windmill. An acclaimed World War II story rich in suspense, character, and quiet spiritual truth."}, {"id": 1128, "title": "The Wise Men Who Found Christmas", "url": "https://store.ignatiusbookfairs.com/the-wise-men-who-found-christmas/", "take": "Raymond Arroyo retells the Magi's journey as a visual adventure, drawing on historical evidence to peel away the familiar assumptions - not three kings, not from Persia. A fresh, dramatic take on the seekers who followed the star."}, {"id": 2824, "title": "The Wishkeeper's Apprentice", "url": "https://store.ignatiusbookfairs.com/the-wishkeepers-apprentice-ibc-1548/", "take": "Felix discovers the town wishing fountain has a keeper — and becomes his apprentice. Imaginative and disarmingly tender about what people actually wish for. Lovely middle-grade magic."}, {"id": 2264, "title": "Theater Shoes", "url": "https://store.ignatiusbookfairs.com/theater-shoes/", "take": "Orphans Sorrel, Mark, and Holly are packed off to their actress grandmother and enrolled in the famous Children's Academy of Dancing and Stage Training. A beautiful gift edition of the beloved classic about music, theater, and finding your footing."}, {"id": 1711, "title": "Then Comes Baby: The Catholic Guide to Surviving and Thriving in the First Three Years of Parenthood", "url": "https://store.ignatiusbookfairs.com/then-comes-baby-the-catholic-guide-to-surviving-and-thriving-in-the-first-three-years-of-parenthood/", "take": "Greg and Lisa Popcak bring twenty-five years of marriage and family counseling to the first three years of parenthood — caring for baby, self, marriage, and spiritual life together. Reassuring, practical Catholic guidance for new parents."}, {"id": 1644, "title": "Theodore Boone: Kid Lawyer", "url": "https://store.ignatiusbookfairs.com/theodore-boone-kid-lawyer/", "take": "Theo Boone is thirteen, knows every judge and court clerk in Strattenburg, and dreams of the courtroom — then a perfect murder pulls him in sooner than expected. A legal thriller sized for middle graders, with real suspense."}, {"id": 1659, "title": "Theodore Boone: The Abduction", "url": "https://store.ignatiusbookfairs.com/theodore-boone-the-abduction/", "take": "John Grisham's thirteen-year-old lawyer-in-training returns, and this time the mystery is personal. Courtroom smarts meet kid-detective momentum — a solid hook for middle-grade readers who like their suspense grounded in the real world."}, {"id": 1960, "title": "Theophilos", "url": "https://store.ignatiusbookfairs.com/theophilos/", "take": "Who was the Theophilos St. Luke addressed? Michael O'Brien imagines him as Luke's skeptical Greek adoptive father, weighing his beloved son's startling account of the Christos. Rich, slow-burning biblical fiction for thoughtful adult readers."}, {"id": 1949, "title": "There and Back Again", "url": "https://store.ignatiusbookfairs.com/there-and-back-again/", "take": "Dwight Longenecker's conversion memoir travels from an Evangelical upbringing and Bob Jones University through Oxford, Anglican ministry, and finally to the Catholic Church. A winding, well-told spiritual road trip for readers who enjoy honest religious autobiography."}, {"id": 1508, "title": "Therese: The Little Flower of Lisieux", "url": "https://store.ignatiusbookfairs.com/therese-the-little-flower-of-lisieux/", "take": "From The Life of a Saint series: Therese of Lisieux, the young Carmelite whose confidence in God's love was the secret of her joy and perseverance. A tender introduction for young people to the Little Flower, Doctor of the Church."}, {"id": 1551, "title": "They Never Came Back", "url": "https://store.ignatiusbookfairs.com/they-never-came-back/", "take": "A cafeteria confrontation opens this teen mystery: a girl who looks exactly like a classmate's cousin, taken by social services after her parents fled an embezzlement scandal. Is it mistaken identity? A page-turning premise readers will chase to the end."}, {"id": 1533, "title": "Thimble Summer", "url": "https://store.ignatiusbookfairs.com/thimble-summer/", "take": "Nine-year-old Garnet finds a silver thimble in a dried-up riverbed, the rains finally come, and a farm summer turns quietly magical. Elizabeth Enright's warm story for readers who like their adventures sunny and small-town."}, {"id": 2458, "title": "Things to Pray for Your Kids", "url": "https://store.ignatiusbookfairs.com/things-to-pray-for-your-kids/", "take": "Melissa Kruger offers scripture-drawn prompts for praying over your children — deep, but genuinely easy to use. For Christian parents who know they should pray for their kids and honestly aren't sure where to start, this little guide helps."}, {"id": 2141, "title": "Things will Never be the Same: The 26 Fairmount Avenue Series #5", "url": "https://store.ignatiusbookfairs.com/things-will-never-be-the-same-the-26-fairmount-avenue-series-5/", "take": "Tomie gets a diary with a lock and key, a Flexible Flyer, and real art lessons at last — then Sunday radio news changes everything. dePaola handles a pivotal moment in history with a child's-eye tenderness."}, {"id": 1804, "title": "This is a Travel Journal", "url": "https://store.ignatiusbookfairs.com/this-is-a-travel-journal/", "take": "A guided travel journal for kids, with a panda prompting the way — pages for planning the trip, recording new foods and sights, and scrapbooking mementos. Turns a family vacation into a keepsake and a writing exercise in disguise."}, {"id": 2205, "title": "This is Me: a Girl's Journal", "url": "https://store.ignatiusbookfairs.com/this-is-me-a-girls-journal/", "take": "A guided journal for preteen girls from nurse and author Julie Metzger, with thoughtful questions, quotes, and encouraging advice for that tender in-between age. More substantial than a diary; a tool for sorting out feelings, hopes, and dreams."}, {"id": 1959, "title": "This Thing of Darkness", "url": "https://store.ignatiusbookfairs.com/this-thing-of-darkness/", "take": "Hollywood, 1956: a war-widowed journalist profiles a fading Bela Lugosi and is drawn into the Old World shadows behind Dracula and the twilight realm of horror films. Atmospheric, unusual fiction for adults who like their noir with deeper questions."}, {"id": 1948, "title": "Three Kings, Ten Mysteries", "url": "https://store.ignatiusbookfairs.com/three-kings-ten-mysteries/", "take": "Were the Magi historical figures or legend? Drawing on historians, scientists, and theologians, this Polish author's investigation digs into the Three Kings and the enduring meaning of Epiphany. Engaging reading that treats an old story with real curiosity."}, {"id": 907, "title": "Through the Year with Tomie de Paola", "url": "https://store.ignatiusbookfairs.com/through-the-year-with-tomie-de-paola/", "take": "A collection of dePaola's Art Mail - the feast-day and holiday illustrations he sent to family and friends - paired with short notes on each saint or season and Catholic customs worldwide. A charming book to keep by the family calendar all year."}, {"id": 1606, "title": "Tikki Tikki Tembo", "url": "https://store.ignatiusbookfairs.com/tikki-tikki-tembo/", "take": "Three decades of children have loved hearing about the boy with the very long name who fell down the well. Mosel and Lent's re-creation of the folktale is a read-aloud with rhythm to spare — the name alone becomes a chant."}, {"id": 2764, "title": "Time Kid Amazing Athletes", "url": "https://store.ignatiusbookfairs.com/time-kid-amazing-athletes-ibc-1585/", "take": "101 bite-size biographies of today's biggest sports stars, from Simone Biles to Caitlin Clark. Reliable TIME for Kids journalism in a format reluctant readers will actually pick up between games."}, {"id": 2871, "title": "To Best the Boys", "url": "https://store.ignatiusbookfairs.com/to-best-the-boys/", "take": "Every year the boys of Pinsbury Port compete in a deadly labyrinth for a coveted university scholarship. Rhen Tellur dons a disguise and enters anyway. A smart, spirited underdog tale about a girl determined to best the boys."}, {"id": 1962, "title": "To Know Christ Jesus", "url": "https://store.ignatiusbookfairs.com/to-know-christ-jesus/", "take": "Frank Sheed's modern spiritual classic walks slowly through the Gospels to meet Christ as he actually lived among us, from infancy to Passion. Back in print for a new generation — meaty, readable, and worth returning to often."}, {"id": 2491, "title": "To Mimi's House We Go", "url": "https://store.ignatiusbookfairs.com/to-mimis-house-we-go/", "take": "Susan Meissner's Christmas poem rides along with modern families — by all sorts of vehicles — to grandmother's house, whether she's a Mimi, Oma, Gigi, or Nana. A sweet seasonal read-aloud for ages 4 to 8."}, {"id": 1952, "title": "Tobit's Dog", "url": "https://store.ignatiusbookfairs.com/tobits-dog/", "take": "The story of Tobit reimagined in the Jim Crow South: a respected man struck blind and destitute, an affable traveling musician named Ace Redbone, and a son's fateful journey. A fresh, atmospheric retelling for teen and adult readers."}, {"id": 1950, "title": "Tolkien: Man and Myth", "url": "https://store.ignatiusbookfairs.com/tolkien-man-and-myth/", "take": "Tolkien topped Britain's greatest-book polls, yet remains widely misunderstood. This study of his life, character, and work confronts the myths, explores his closest literary friendships, and digs into the culture that shaped him. Rewarding for grown-up Middle-earth devotees."}, {"id": 1728, "title": "Tornado", "url": "https://store.ignatiusbookfairs.com/tornado/", "take": "Newbery Medalist Betsy Byars spins a storm-cellar tale: while a twister rages, farmhand Pete tells stories of Tornado, the card-trick-playing dog a storm once blew into his life. Sweet, short, and irresistible to dog lovers."}, {"id": 2846, "title": "Totally Kawaii Sticker and Activity Book", "url": "https://store.ignatiusbookfairs.com/totally-kawaii-sticker-and-activity-book-dont-order-yet-ibc-1596/", "take": "70+ kawaii coloring pages and 100+ stickers of maximum cuteness. Low-stakes, high-delight creative downtime for the cute-obsessed — and surprisingly calming for grown-ups too."}, {"id": 1820, "title": "Totus Tuus Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/totus-tuus-vinyl-sticker/", "take": "Totus tuus — Latin for \"totally yours\" — a beloved Marian motto rendered as a vinyl sticker. Two small words of serious devotion, sized for everyday view on a notebook or water bottle."}, {"id": 1100, "title": "Toward the Gleam", "url": "https://store.ignatiusbookfairs.com/toward-the-gleam/", "take": "Between the wars, a philologist shelters from a storm in a cave and finds an ancient manuscript in a language even he cannot place. An intriguing literary mystery for thoughtful adults — readers who know their Oxford philologists will smile early."}, {"id": 1688, "title": "Treasure Hunt Activity Book", "url": "https://store.ignatiusbookfairs.com/treasure-hunt-activity-book/", "take": "Fifty mazes, search-and-finds, and connect-the-dots strung along a jungle-to-castle treasure hunt, with snakes and crocodiles between the hunters and the gold. Solutions included — a solid rainy-day rescue."}, {"id": 1500, "title": "Trees", "url": "https://store.ignatiusbookfairs.com/trees/", "take": "A Fandex field guide to North American trees with four visual keys — die-cut leaf, bark, flower, seed — plus habitat notes and cultural history from White Oak to Redwood. Hand it over, take a walk, and identification becomes a game."}, {"id": 2003, "title": "Trinity Wooden Lacing Toy Set ", "url": "https://store.ignatiusbookfairs.com/trinity-wooden-lacing-toy-set/", "take": "Montessori-inspired wooden lacing shapes — including Trinity and decade-rosary forms — that build fine motor skills and hand-eye coordination through creative play. Thread the string, practice the fingers, and absorb a first bit of faith vocabulary along the way."}, {"id": 2204, "title": "Tristan Strong Punches a Hole in the Sky", "url": "https://store.ignatiusbookfairs.com/tristan-strong-punches-a-hole-in-the-sky/", "take": "Kwame Mbalia's epic fantasy drops seventh grader Tristan Strong into a richly imagined world of African American folk heroes and West African gods. A fast-paced, mythology-steeped series starter with real emotional weight to anchor the action."}, {"id": 1846, "title": "Troubled Waters", "url": "https://store.ignatiusbookfairs.com/troubled-waters/", "take": "Fourth in the In the Shadows of Rome series: Maximus uncovers a black market in Rome's stolen water, with suspicion pointing at the hidden Christians. Historical intrigue for readers 10 and up, with real stakes and real faith."}, {"id": 1955, "title": "True Friendship", "url": "https://store.ignatiusbookfairs.com/true-friendship/", "take": "Philosopher John Cuddeback draws on Scripture, Aristotle, and the saints to ask what friendship really is and where to find it. Clear, warm, and quietly challenging — excellent for older teens and adults who suspect they were made for more than acquaintances."}, {"id": 1976, "title": "True Rescue: A Storm Too Soon", "url": "https://store.ignatiusbookfairs.com/true-rescue-a-storm-too-soon/", "take": "Three expert sailors vanish into a Gulf Stream storm; four courageous coast guardsmen go after them. Part of the True Rescue chapter-book series — fast-paced, true, and uplifting, pitched just right for newly independent readers who crave real adventure."}, {"id": 1954, "title": "Trust", "url": "https://store.ignatiusbookfairs.com/trust/", "take": "A lavishly illustrated telling of St. Faustina's life and the Divine Mercy devotion she carried into the world despite steep obstacles. Part biography, part love story between God and a humble Polish nun — a handsome gift volume."}, {"id": 1786, "title": "Trust God Always Vinyl Sticker", "url": "https://store.ignatiusbookfairs.com/trust-god-always-vinyl-sticker/", "take": "A vinyl sticker with a three-word spiritual program: trust God always. The kind of small reminder that ends up on a binder or bottle and quietly does its work all school year long."}, {"id": 1011, "title": "Tuesday", "url": "https://store.ignatiusbookfairs.com/tuesday/", "take": "Frogs start floating on Tuesday evening, and David Wiesner's nearly wordless Caldecott Medal winner takes it from there. Whimsical, elegant, and endlessly fun to \"read\" — every child narrates it differently."}, {"id": 2183, "title": "Turn Toward God", "url": "https://store.ignatiusbookfairs.com/turn-toward-god/", "take": "The heart as a castle under assault, with God fighting at our side: this book gives children a simple, concrete method of spiritual combat so temptation and difficulty feel less frightening. Practical Catholic formation, not just another story."}, {"id": 2208, "title": "Twas the Night Before Christmas", "url": "https://store.ignatiusbookfairs.com/twas-the-night-before-christmas/", "take": "The beloved Christmas Eve poem in a handsome hardcover with an embossed cover and four-page foldout. Built for the read-aloud-by-the-tree tradition, and a fine way to start one if your family hasn't yet."}, {"id": 1958, "title": "Twelve Great Books", "url": "https://store.ignatiusbookfairs.com/twelve-great-books/", "take": "A guided tour through twelve of civilization's most important books, from Augustine to Shakespeare to the modern masterpieces, showing how great stories carry the greatest truths. A fine companion for homeschoolers, book clubs, and self-educating adults."}, {"id": 1401, "title": "Two Old Women", "url": "https://store.ignatiusbookfairs.com/two-old-women/", "take": "Velma Wallis retells an Athabascan legend of two elderly women abandoned by their tribe in a winter famine - and what they do next. Spare, shocking, and finally inspiring, for older readers."}, {"id": 2791, "title": "Ultimate Unofficial Encyclopedia for Minecrafters", "url": "https://store.ignatiusbookfairs.com/ultimate-unofficial-encyclopedia-for-minecrafters-ibc-1606/", "take": "Megan Miller's unofficial, full-color guide to Minecraft tricks and strategies - the kind of reference kids return to again and again. Honestly labeled as not affiliated with Mojang, but very much aligned with what your Minecrafter cares about."}, {"id": 2251, "title": "Unbroken:(The Young Adult Adaptation)  An Olympian's Journey from Airman to Castaway to Captive", "url": "https://store.ignatiusbookfairs.com/unbroken-the-young-adult-adaptation-an-olympians-journey-from-airman-to-castaway-to-captive/", "take": "Laura Hillenbrand's bestselling survival epic, adapted and lavishly illustrated for young adults: an Olympian's plane goes down in the Pacific in 1943, and courage, cunning, and fortitude carry him through. Thrilling, true, and hard to put down."}, {"id": 1882, "title": "Uncle Tom's Cabin", "url": "https://store.ignatiusbookfairs.com/uncle-toms-cabin/", "take": "The novel that claimed the hearts and politics of millions, painting plantation life with unflinching honesty. Stowe's questions about what slavery does to the human soul remain penetrating today. Essential, enthralling American reading for mature students."}, {"id": 2753, "title": "Unicorn Food", "url": "https://store.ignatiusbookfairs.com/unicorn-food-ibc-1601/", "take": "A rainbow-everything party cookbook that turns ordinary desserts into occasions. Great for baking with kids who love a little sparkle; expect requests to make the unicorn bark more than once."}, {"id": 2808, "title": "Unicorn Post", "url": "https://store.ignatiusbookfairs.com/unicorn-post-ibc-1546/", "take": "A little girl tries to find the right home for a lost unicorn, with lift-the-flap letters and a final surprise that lands sweetly. Gentle, whimsical, and lovely for ages 3-6."}, {"id": 1470, "title": "United States Coloring Book", "url": "https://store.ignatiusbookfairs.com/united-states-coloring-book/", "take": "A Dover coloring book of American history scenes, each with a detailed, informative caption. An easy way to slow kids down and get them looking closely at the past — works nicely alongside a history or literature unit. 56 pages."}, {"id": 1076, "title": "Unplugged Play: No Batteries. No Plugs. Pure Fun", "url": "https://store.ignatiusbookfairs.com/unplugged-play-no-batteries-no-plugs-pure-fun/", "take": "Hundreds of battery-free, screen-free games — an encyclopedia of glue-smearing, bubble-relay, imagination-stretching play. The parent-friendly answer to \"I'm bored\" that builds strong bodies and deep friendships instead of screen time."}, {"id": 1601, "title": "Up a Road Slowly", "url": "https://store.ignatiusbookfairs.com/up-a-road-slowly/", "take": "The Newbery Award-winning coming-of-age story from the beloved author of Across Five Aprils: Julie's growing-up years at Aunt Cordelia's, with rides in the woods, rainy-night singing, and precious solitude. Gentle, literary, and worth the unhurried pace."}, {"id": 1623, "title": "Vanished!", "url": "https://store.ignatiusbookfairs.com/vanished/", "take": "An Edgar Award winner for juvenile fiction: Florian Bates is back, juggling middle school and FBI casework at the same time. School Library Journal invokes Alex Rider and Sherlock Holmes, and mystery-loving middle graders will see why."}, {"id": 1966, "title": "Vatican Secret Archives", "url": "https://store.ignatiusbookfairs.com/vatican-secret-archives/", "take": "The Gorny and Rosikon investigative team gained access to the Vatican Secret Archives and returned with its turbulent history and remarkable documents, richly illustrated. Absorbing browsing for history lovers — a coffee-table book with genuine substance."}, {"id": 2209, "title": "Vincent", "url": "https://store.ignatiusbookfairs.com/vincent/", "take": "A wordless picture book about Vincent, a glum little pig whose mysterious gift fills his heart with love, then tests it. For ages 3 and up; wordless stories like this let pre-readers tell the tale themselves. Quietly lovely."}, {"id": 1696, "title": "Vincent De Paul Saint of Charity", "url": "https://store.ignatiusbookfairs.com/vincent-de-paul-saint-of-charity/", "take": "From shepherd boy to slavery in North Africa to priestly service among the poor and abandoned — this Vision book for ages 9-15 tells Vincent de Paul's dramatic story, including founding the Daughters of Charity. Genuinely adventurous hagiography."}, {"id": 2395, "title": "Vision of Beauty: The Story of Sarah Breedlove Walker", "url": "https://store.ignatiusbookfairs.com/vision-of-beauty-the-story-of-sarah-breedlove-walker/", "take": "An inspiring picture book biography of Sarah Breedlove Walker, born to sharecroppers in 1867, who rose through poverty and discrimination to remarkable success as a businesswoman and philanthropist. Starred-review nonfiction that earns its place."}, {"id": 1963, "title": "Voyage to Alpha Centauri", "url": "https://store.ignatiusbookfairs.com/voyage-to-alpha-centauri/", "take": "Eighty years from now, a Nobel-winning physicist boards the Kosmos, a flying city bound for Alpha Centauri, partly to escape Earth's seemingly benign totalitarian government. Big-idea science fiction with a soul, best for adult and older teen readers."}, {"id": 1593, "title": "Wagon Wheels", "url": "https://store.ignatiusbookfairs.com/wagon-wheels/", "take": "Based on a true story: after the Civil War, the formerly enslaved Muldie family homesteads to Nicodemus, Kansas, surviving a brutal winter with help from the Osage community. A powerful, often-overlooked chapter of American history for young readers."}, {"id": 1695, "title": "Washington, D.C.", "url": "https://store.ignatiusbookfairs.com/washington-d-c/", "take": "A Fandex tour of the capital, packed with history and trivia — the Smithsonian's mysterious founding bequest, Tokyo's gift of 3,000 cherry trees. A browsable format kids flip through happily before or after a D.C. trip."}, {"id": 1573, "title": "Watch Over Me, Little Angel", "url": "https://store.ignatiusbookfairs.com/watch-over-me-little-angel/", "take": "Every question a child might ask about their guardian angel, answered simply and warmly: God loves you so much he gave you an angel, close by since the day you were born. Delicate illustrations make it an easy bedtime favorite."}, {"id": 2026, "title": "Water Reveal: Children's Missal", "url": "https://store.ignatiusbookfairs.com/water-reveal-children-s-missal/", "take": "Pages start white; a wet brush wakes the colors. This reusable water-reveal board book walks little ones through the parts of the Mass — a genuinely clever addition to the Mass bag or Adoration tote."}, {"id": 2510, "title": "Water Reveal: Holy Family", "url": "https://store.ignatiusbookfairs.com/water-reveal-holy-family/", "take": "Brush water over the pages and the Holy Family's story appears in color — then dries and resets for next time. Four virtue-themed pages make this reusable board book a smart companion for Mass bags, Adoration, and car rides."}, {"id": 2536, "title": "Water Reveal: My First Prayers", "url": "https://store.ignatiusbookfairs.com/water-reveal-my-first-prayers/", "take": "Brush water over the pages and five beloved Catholic prayers — the Our Father, Hail Mary, Glory Be, and more — appear in color. Reusable, durable, and a genuinely gentle first introduction to prayer for little hands."}, {"id": 2870, "title": "Watership Down", "url": "https://store.ignatiusbookfairs.com/watership-down/", "take": "A band of rabbits flees the destruction of their warren toward the dream of a safer home in this stirring, beloved epic. A worldwide bestseller for decades, and one of those rare animal stories that grows with the reader."}, {"id": 2836, "title": "We Die Alone", "url": "https://store.ignatiusbookfairs.com/we-die-alone-by-david-howarth-ibc-1566/", "take": "The true story of Jan Baalsrud, sole survivor of a betrayed 1943 commando mission in Nazi-occupied Norway - frostbitten, snowblind, and hunted. One of World War II's great escape accounts, gripping from first page to last."}, {"id": 2752, "title": "We Play Soccer (bilingual)", "url": "https://store.ignatiusbookfairs.com/we-play-soccer-bilingual-ibc-1538/", "take": "Joe speaks English, Jose speaks Spanish, and they're on the same soccer team — now in board book form. Simple paired sentences in both languages, a shared win at the end. A genuinely useful bilingual first sports story."}, {"id": 1970, "title": "We'll Never Tell Them", "url": "https://store.ignatiusbookfairs.com/well-never-tell-them/", "take": "A modern London nurse fleeing a decision meets a dying patient in Jerusalem whose vivid storytelling carries her into his mother's life — colonial Malta, Edwardian England, the wards of World War I. Layered, absorbing fiction for adult readers."}, {"id": 1010, "title": "We're Going on a Bear Hunt", "url": "https://store.ignatiusbookfairs.com/were-going-on-a-bear-hunt/", "take": "Wavy grass, cold river, swampy mud — Rosen and Oxenbury's chantable classic has families marching along for over thirty years. One of the most reliable read-alouds in the picture-book canon."}, {"id": 1062, "title": "Welcome to the Symphony", "url": "https://store.ignatiusbookfairs.com/welcome-to-the-symphony/", "take": "Beethoven's Fifth with nineteen sound buttons — a picture-book ticket to the concert hall. An inviting, genuinely interactive first introduction to classical music for young children, and one they will press again and again."}, {"id": 2790, "title": "Whale of the Wild", "url": "https://store.ignatiusbookfairs.com/a-whale-of-the-wild-ibc-1559/", "take": "A young orca leads her brother through a changing sea to find their pod. Starred-review adventure that smuggles in real marine science; stunning illustrations throughout. For animal-story kids, 8-12."}, {"id": 2474, "title": "What are Hands for?", "url": "https://store.ignatiusbookfairs.com/what-are-hands-for/", "take": "A lift-the-flap board book that turns toddler discipline into gospel teaching: hands are for waving, clapping, praying, and helping, not snatching and hitting. Practical, playful help for parents pointing small children toward Christ-like behavior."}, {"id": 1661, "title": "What are the Three Branches of the Government? And Other Questions about the U.S. Constitution", "url": "https://store.ignatiusbookfairs.com/what-are-the-three-branches-of-the-government-and-other-questions-about-the-u-s-constitution/", "take": "Who wrote the Constitution, and how do the three branches actually work? Clear question-and-answer civics covering the Bill of Rights and how amendments happen — a handy companion for American government basics at school or home."}, {"id": 998, "title": "What Do You Say, Dear? Manners for All Occasions", "url": "https://store.ignatiusbookfairs.com/what-do-you-say-dear-manners-for-all-occasions/", "take": "What do you say when the Queen overfeeds you spaghetti or you bump into a crocodile downtown? Manners taught through gleeful absurdity — etiquette instruction children will actually request at bedtime."}, {"id": 1968, "title": "What Do You Seek? Encountering the Heart of the Gospel", "url": "https://store.ignatiusbookfairs.com/what-do-you-seek-encountering-the-heart-of-the-gospel/", "take": "A clear, warm walk through the kerygma, the core Gospel proclamation the Apostles first carried into the world. Ideal for adults who know the vocabulary of faith but want to encounter its beating heart again — or for the first time."}, {"id": 976, "title": "What Lives in a Shell?", "url": "https://store.ignatiusbookfairs.com/what-lives-in-a-shell/", "take": "A nest is home for a bird, a cave for a bear — and for snails, turtles, crabs, and clams, home is a shell. A clear, appealing early elementary introduction to the animals that carry their houses with them."}, {"id": 973, "title": "What the Moon is Like", "url": "https://store.ignatiusbookfairs.com/what-the-moon-is-like/", "take": "No air, nothing growing, towering mountains, deep craters — colder than the desert, then hotter. This one answers the question every stargazing child eventually asks, with facts that stay wonderful."}, {"id": 1718, "title": "What Was America's Deadliest War? And Other Questions About the Civil War", "url": "https://store.ignatiusbookfairs.com/what-was-americas-deadliest-war-and-other-questions-about-the-civil-war/", "take": "Who fired the first shots? How did one document free millions of slaves? Martin Sandler answers the must-know questions about America's deadliest war in an accessible question-and-answer format suited to reports and curious browsers alike."}, {"id": 1726, "title": "What Was Your Dream, Dr. King? And Other Questions about... Martin Luther King, Jr.", "url": "https://store.ignatiusbookfairs.com/what-was-your-dream-dr-king-and-other-questions-about-martin-luther-king-jr/", "take": "Why were schools and drinking fountains segregated? What was Dr. King's dream — and has it come true? An engaging question-and-answer introduction to the civil rights hero, well suited to classroom units and curious kids."}, {"id": 1971, "title": "What Would Socrates Say?", "url": "https://store.ignatiusbookfairs.com/what-would-socrates-say/", "take": "Peter Kreeft imagines Socrates on one end of a log and a bright modern beginner on the other, teaching philosophy the way he actually taught: by questions, not lectures. A playful, genuinely Socratic introduction for students and self-teaching adults."}, {"id": 1409, "title": "What's Inside a Flower", "url": "https://store.ignatiusbookfairs.com/whats-inside-a-flower/", "take": "From the creator of Women in Science, a stunning picture-book introduction to flowers from seed to root to bloom. Exactly the kind of nonfiction that grows backyard scientists out of curious kids."}, {"id": 1738, "title": "What's That Bird? Getting to Know the Birds Around You, Coast to Coast", "url": "https://store.ignatiusbookfairs.com/whats-that-bird-getting-to-know-the-birds-around-you-coast-to-coast/", "take": "Profiles of 30 North American birds — color, size, habitat, calls — plus bird anatomy, journal ideas, and nesting-box instructions. A welcoming first field guide that turns backyard noticing into actual birding."}, {"id": 2840, "title": "When the Earth Shook", "url": "https://store.ignatiusbookfairs.com/when-the-earth-shook-ibc-6wesp/", "take": "Mexico City, 1985: a book scavenged from a landfill sets off dangerous, almost miraculous events for two brothers as the earthquake looms. A dramatic story of wisdom, courage, and lives changed by what turns up in unlikely places."}, {"id": 1780, "title": "When You Open a Book", "url": "https://store.ignatiusbookfairs.com/when-you-open-a-book/", "take": "Two children dine with mermaids, swashbuckle with pirates, and ride a giant's shoulders in this celebration of reading's transportive power. The dreamlike, brightly colored illustrations make the case better than any lecture: open a book, enter a world."}, {"id": 1546, "title": "Where Is Jesus?", "url": "https://store.ignatiusbookfairs.com/where-is-jesus/", "take": "A tender lift-the-window book that takes a child's biggest question seriously: where is Jesus? On the cross, risen, in my heart. Faith, lovely illustrations, and poetry combine into a genuinely giftable little book for young children."}, {"id": 2263, "title": "Where the Red Fern Grows", "url": "https://store.ignatiusbookfairs.com/where-the-red-fern-grows/", "take": "Billy saves up for two hound pups, Old Dan and Little Ann, and together they roam the Ozarks as the finest hunting team in the valley. A beloved classic about devotion, grit, and a boy and his dogs. Have tissues ready."}, {"id": 1122, "title": "Where the Wild Things Are (paperback)", "url": "https://store.ignatiusbookfairs.com/where-the-wild-things-are-paperback/", "take": "Max sails off to where the wild things are, and children have followed for fifty years. This anniversary edition gives Sendak's Caldecott Medal-winning artwork faithful state-of-the-art reproductions — a worthy copy of a book every shelf needs."}, {"id": 2517, "title": "Wherever You Go, I Want You to Know...", "url": "https://store.ignatiusbookfairs.com/wherever-you-go-i-want-you-to-know/", "take": "A sweet rhyming keepsake that tells a child your biggest hope for them — that wherever life takes them, they'll love and follow Jesus. A go-to baptism, birthday, or just-because gift for ages 3-7."}, {"id": 2280, "title": "While Everyone is Sleeping", "url": "https://store.ignatiusbookfairs.com/while-everyone-is-sleeping/", "take": "Just before morning, a little shrew follows a mysterious fragrance into a moonlit garden of moonflowers, moths, and peepers keeping the beat. An award-winning, enchanting bedtime story for adventurous souls who love the natural world."}, {"id": 892, "title": "Who is Jesus?", "url": "https://store.ignatiusbookfairs.com/who-is-jesus/", "take": "A question-and-answer tour of Jesus' world: his grandparents, his house, what the disciples ate and wore, what the Temple looked like. The everyday details children actually wonder about, answered with charm and beautiful illustrations."}, {"id": 2801, "title": "Who is Lionel Messi?", "url": "https://store.ignatiusbookfairs.com/who-is-lionel-messi-ibc-1590/", "take": "From backyard games in Argentina to seven Ballon d'Ors. A current, well-told Who HQ biography for the soccer kids who know every stat but not the story."}, {"id": 1505, "title": "Wildflowers", "url": "https://store.ignatiusbookfairs.com/wildflowers/", "take": "North American wildflowers in die-cut Fandex form: true colors, lifelike shapes, vital stats on range and habitat, plus the lore — Columbine as love charm, wars fought over Wild Hyacinth. A field guide that works as porch-step browsing too."}, {"id": 939, "title": "Will Wilder 1: The Relic of Perilous Falls", "url": "https://store.ignatiusbookfairs.com/will-wilder-1-the-relic-of-perilous-falls/", "take": "A New York Times bestselling author's answer to Percy Jackson: mischievous twelve-year-old Will Wilder alone can see the creatures menacing Perilous Falls - and he has just borrowed the relic protecting the town. Rollicking supernatural adventure with a Catholic imagination."}, {"id": 940, "title": "Will Wilder 2: The Lost Staff of Wonders", "url": "https://store.ignatiusbookfairs.com/will-wilder-2-the-lost-staff-of-wonders/", "take": "Book 2 pits Will against the demon Amon when the Staff of Moses vanishes from the town museum - and Will is suspect number one. Booklist's \"shades of Indiana Jones and Percy Jackson\" is a fair description of the fun here."}, {"id": 941, "title": "Will Wilder 3: The Amulet of Power", "url": "https://store.ignatiusbookfairs.com/will-wilder-3-the-amulet-of-power/", "take": "Book 3 hands Will a talisman holding a lock of Samson's hair - suddenly the too-small kid can make the football team. But a new demon forces family secrets into the open. The series keeps raising the stakes."}, {"id": 2760, "title": "Winnie the Pooh", "url": "https://store.ignatiusbookfairs.com/winnie-the-pooh-ibc-1602/", "take": "The 1926 original, revitalized with full-color versions of E.H. Shepherd's illustrations. Pooh, Piglet, Eeyore, and Christopher Robin in the Hundred Acre Wood - a gift edition that earns its place on any family shelf."}, {"id": 993, "title": "Winter Days in the Big Woods", "url": "https://store.ignatiusbookfairs.com/winter-days-in-the-big-woods/", "take": "Winter chores, frost pictures on the windows — this My First Little House adaptation shows the season's small pleasures in the Big Woods. Renee Graef's illustrations honor Garth Williams' classic artwork."}, {"id": 1594, "title": "Winter on the Farm", "url": "https://store.ignatiusbookfairs.com/winter-on-the-farm/", "take": "A My First Little House book introducing Almanzo Wilder — barn chores, a hearty farm supper, and winter on the New York farm. A gentle, cozy on-ramp to the Little House world for readers too young for the novels."}, {"id": 1969, "title": "Witnesses to Mystery", "url": "https://store.ignatiusbookfairs.com/witnesses-to-mystery/", "take": "Gorny and Rosikon spent two years pursuing the evidence behind the relics of Christ's Passion, working with historians and scientists across museums, archives, and churches. A lavish, genuinely investigative coffee-table volume that takes questions as seriously as devotion."}, {"id": 2842, "title": "Wizard of Oz", "url": "https://store.ignatiusbookfairs.com/wizard-of-oz-ibc-1567/", "take": "L. Frank Baum's modern fairy tale in the Macmillan Collector's Library treatment: real cloth binding, gilt edges, ribbon marker, and Denslow's original illustrations in color. A pocket-sized keepsake edition made for giving."}, {"id": 1967, "title": "Women of the Church: What Every Catholic Should Know", "url": "https://store.ignatiusbookfairs.com/women-of-the-church-what-every-catholic-should-know/", "take": "Bronwen McShea's sweeping survey shows women not on the margins of Church history but at its heart, shaping traditions, institutions, and whole civilizations. An eye-opening corrective told accessibly — good for parish groups, teachers, and curious adults."}, {"id": 2002, "title": "Wooden Miracle of Life Puzzle", "url": "https://store.ignatiusbookfairs.com/wooden-miracle-of-life-puzzle/", "take": "A nine-piece reversible wooden puzzle, about nine inches across: images of fetal development on one side, weeks of growth on the other. A gentle, hands-on way for a big brother or sister to learn how the new baby is growing."}, {"id": 1886, "title": "Wuthering Heights", "url": "https://store.ignatiusbookfairs.com/wuthering-heights/", "take": "Bronte's dark masterpiece keeps its controversial status, and this critical edition leans into the arguments: who are the heroes, who are the villains, and what did Emily Bronte actually intend? A provocative edition for serious students."}, {"id": 893, "title": "You Are Loved", "url": "https://store.ignatiusbookfairs.com/you-are-loved/", "take": "A sweet, tender book that tells a child plainly what every child needs to hear: you are treasured by your family and loved beyond measure by God. Warm, simple, and well suited to reading aloud with the youngest listeners."}, {"id": 1455, "title": "You Can Understand the Bible: A Practical and Illuminating Guide to Each Book in the Bible", "url": "https://store.ignatiusbookfairs.com/you-can-understand-the-bible-a-practical-and-illuminating-guide-to-each-book-in-the-bible/", "take": "Peter Kreeft walks through every book of the Bible with wit and clarity, focusing on the core message of each. For teens and adults who find Scripture's sheer size intimidating, this best-selling road map makes the whole journey feel possible."}, {"id": 1060, "title": "You Never Heard of Willie Mays?!", "url": "https://store.ignatiusbookfairs.com/you-never-heard-of-willie-mays/", "take": "Willie Mays by the numbers — 660 home runs, a .302 lifetime average — and by the story: Birmingham, the Negro Leagues, the Majors. A fascinating picture book biography to hand young baseball fans."}, {"id": 2006, "title": "You Were Born to be a Saint", "url": "https://store.ignatiusbookfairs.com/you-were-born-to-be-a-saint/", "take": "A joyful A-to-Z tour of the saints — including Lidwina, patron of ice skating — with mini biographies for curious kids. A cheerful hardcover for ages 3-7 that plants the best idea early: sainthood is meant for you, too."}, {"id": 2202, "title": "You're the Greatest, Charlie Brown", "url": "https://store.ignatiusbookfairs.com/youre-the-greatest-charlie-brown/", "take": "A facsimile volume of classic Peanuts newspaper strips from 1963-64: Charlie Brown, Snoopy, Lucy, Linus, and the gang navigating school, baseball, and first crushes. Hand a new generation the comics their grandparents grew up on."}, {"id": 1723, "title": "YOUCAT", "url": "https://store.ignatiusbookfairs.com/youcat/", "take": "The Youth Catechism of the Catholic Church, written for high schoolers and young adults in an appealing question-and-answer format with Bible citations and quotable margins. An accessible, faithful reference teens will actually pick up."}, {"id": 897, "title": "YOUCAT Bible", "url": "https://store.ignatiusbookfairs.com/youcat-bible/", "take": "The YOUCAT treatment applied to Scripture: engaging photos, clever illustrations, sidebar quotes from saints and thinkers, and helpful introductions. Built to get teens and young adults actually reading the Bible rather than admiring it from a distance."}, {"id": 2018, "title": "YOUCAT Confirmation Leader's Handbook", "url": "https://store.ignatiusbookfairs.com/youcat-confirmation-leaders-handbook/", "take": "The teacher's companion to the YOUCAT Confirmation course: fully planned lessons for all twelve chapters, each with a theological overview, tiered activities, and ready-to-use resources. Exactly the prep-saver catechists and confirmation leaders ask us for."}, {"id": 1727, "title": "YOUCAT Confirmation: Student Book", "url": "https://store.ignatiusbookfairs.com/youcat-confirmation-student-book/", "take": "In-depth Confirmation preparation in the familiar YOUCAT format — lively text on spiritual themes, plus the real questions teens actually ask about God, Jesus, and the Church. A strong student book for junior high and high school candidates."}, {"id": 2020, "title": "YOUCAT Espanol", "url": "https://store.ignatiusbookfairs.com/youcat-espanol/", "take": "The Youth Catechism of the Catholic Church in Spanish — the same accessible question-and-answer format, lively graphics, and margin quotes from the saints, written for high schoolers and young adults. A real gift for bilingual parishes and families."}, {"id": 2019, "title": "YOUCAT for kids", "url": "https://store.ignatiusbookfairs.com/youcat-for-kids/", "take": "The bestselling YOUCAT approach, scaled for children: Creation, Creed, Sacraments, Commandments, prayer, and the life of Jesus in child-friendly language, with talking points so parents and teachers can explore the faith right alongside them."}, {"id": 1520, "title": "YOUCAT Study Guide", "url": "https://store.ignatiusbookfairs.com/youcat-study-guide/", "take": "The companion to the hugely popular YOUCAT youth catechism: 35 topics, each with background, comprehension questions, Scripture connections, and discussion starters. Built for youth groups and classrooms that want structure without deadening the conversation."}, {"id": 896, "title": "YOUCAT: Youth Prayer Book", "url": "https://store.ignatiusbookfairs.com/youcat-youth-prayer-book/", "take": "From the team behind the internationally best-selling YOUCAT catechism, a prayer book that speaks to teenagers in their own register - new prayers, traditional prayers, Scripture, and practical advice on how to actually build a habit of praying."}, {"id": 1635, "title": "Young Cam Jansen and the Dinosaur Game", "url": "https://store.ignatiusbookfairs.com/young-cam-jansen-and-the-dinosaur-game/", "take": "A jar of toy dinosaurs, musical chairs, and a telltale smudge of chocolate cake: Cam Jansen has a birthday-party puzzle to solve. Early-reader mystery at its most inviting — beginning readers get to play detective too."}, {"id": 1619, "title": "Young Cam Jansen and the Lost Tooth", "url": "https://store.ignatiusbookfairs.com/young-cam-jansen-and-the-lost-tooth/", "take": "Annie's tooth falls out and promptly disappears — a case for Cam Jansen and her photographic memory. These early-reader mysteries give beginning readers a real puzzle to solve alongside the sounding-out, which is exactly why kids devour them."}, {"id": 1651, "title": "Young Cam Jansen and the Missing Cookie", "url": "https://store.ignatiusbookfairs.com/young-cam-jansen-and-the-missing-cookie/", "take": "Jason's cookie has vanished from his lunch box, and Cam's amazing memory clicks into action. A friendly lunchroom mystery sized just right for brand-new readers who like solving the case alongside the detective."}, {"id": 1568, "title": "Young Fu of the Upper Yangtze", "url": "https://store.ignatiusbookfairs.com/young-fu-of-the-upper-yangtze/", "take": "One of the earliest Newbery Medal winners, first published in 1932: thirteen-year-old Young Fu arrives from a farming village into bustling 1920s Chungking, wide-eyed and ambitious. A city of wonders and dangers, and a boy determined to rise."}, {"id": 2180, "title": "Young Saints", "url": "https://store.ignatiusbookfairs.com/young-saints/", "take": "Fifteen young saints and blesseds, from Kateri Tekakwitha to Pier Giorgio Frassati to Chiara Badano, told through lively stories, comic strips, history, and prayers. Proof for kids that holiness isn't reserved for the old and gray."}, {"id": 2518, "title": "Your Magnificent Mouth: A Training Young Hearts rhyming book", "url": "https://store.ignatiusbookfairs.com/your-magnificent-mouth-a-training-young-hearts-rhyming-book/", "take": "A rhyming board book that gives kids ages 3 and up a theology of the mouth — words that reflect creation, fall, redemption, and grace. Practical gospel formation in language little ones actually enjoy hearing read aloud."}, {"id": 1605, "title": "Your Puppy, Your Dog: A Kid's Guide to Raising a Happy, Healthy Dog", "url": "https://store.ignatiusbookfairs.com/your-puppy-your-dog-a-kids-guide-to-raising-a-happy-healthy-dog/", "take": "Pat Storer's clear, kid-accessible guide to the whole job of dog ownership — choosing a breed, training, feeding, grooming, vet visits. Written for children and their parents together, it turns \"can we get a puppy\" into an actual plan."}, {"id": 1485, "title": "Your Questions, God's Answers", "url": "https://store.ignatiusbookfairs.com/your-questions-gods-answers/", "take": "Kreeft takes the questions young people actually ask — identity, failure, temptation, the mystery of God's love — and answers with Scripture itself. Direct and warm, and since adults ask the same questions, it travels well beyond the youth shelf."}, {"id": 2104, "title": "Zita the Spacegirl", "url": "https://store.ignatiusbookfairs.com/zita-the-spacegirl/", "take": "When her best friend is abducted by an alien doomsday cult, Zita leaps after him and becomes an accidental intergalactic hero. Humanoid chickens, neurotic robots, ancient prophecies — inventive, big-hearted adventure kids tear through."}, {"id": 1633, "title": "Zoo Animals Dot-to-Dot", "url": "https://store.ignatiusbookfairs.com/zoo-animals-dot-to-dot/", "take": "Forty-six connect-the-dot zoo animals — tiger, owl, panda, sea turtle, peacock, and more — each emerging in its habitat as the dots close. A pleasant, screen-free activity book that sneaks in a little animal recognition along the way."}];
